// Exercise library — extracted from the original single-file builder.
// Fields: id, cat, name, pos (starting position), sets, reps, hold, freq, instr
window.LIBRARY = [
// CERVICAL
{id:'c1',cat:'Cervical',name:'Cervical Retraction (Chin Tuck)',pos:'Seated or Supine',sets:3,reps:'10',hold:'5 sec',freq:'2x/day',instr:'Sit tall. Draw your chin straight back, making a "double chin." Hold, then relax. Keep eyes level. Do not tilt head up or down.'},
{id:'c2',cat:'Cervical',name:'Cervical Side Bend Stretch',pos:'Seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit tall. Tilt right ear toward right shoulder until a stretch is felt on the left side of the neck. Hold. Repeat on left side.'},
{id:'c3',cat:'Cervical',name:'Cervical Rotation',pos:'Seated',sets:3,reps:'10',hold:'2 sec',freq:'2x/day',instr:'Sit tall. Slowly turn head to the right as far as comfortable. Hold briefly. Return to center and rotate left. Stay in a pain-free range.'},
{id:'c4',cat:'Cervical',name:'Upper Trapezius Stretch',pos:'Seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit on your right hand. Use left hand to gently tilt head left and slightly forward. Feel a stretch at the right shoulder/neck. Hold, then switch sides.'},
{id:'c5',cat:'Cervical',name:'Levator Scapulae Stretch',pos:'Seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit on your right hand. Rotate head 45 degrees left, then tuck chin toward left armpit. Use left hand to gently add pressure. Feel a stretch behind the right shoulder blade. Switch sides.'},
{id:'c6',cat:'Cervical',name:'Deep Neck Flexor Endurance',pos:'Supine',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Lie on back, knees bent. Perform a chin tuck, then slowly lift head 1 inch off the surface. Hold without losing the tuck. Lower slowly.'},
{id:'c7',cat:'Cervical',name:'Cervical Extension ROM',pos:'Seated',sets:3,reps:'10',hold:'2 sec',freq:'2x/day',instr:'Sit tall. Slowly look up toward the ceiling as far as comfortable. Hold briefly. Return to neutral. Stop if pain or dizziness occurs.'},
// SHOULDER
{id:'s1',cat:'Shoulder',name:'Pendulum (Codman) Exercise',pos:'Standing, leaning forward',sets:3,reps:'20 circles',hold:'—',freq:'2x/day',instr:'Lean forward resting non-affected arm on a table. Let the affected arm hang freely. Use gentle body momentum (not shoulder muscles) to create small circles, then larger ones, clockwise and counterclockwise.'},
{id:'s2',cat:'Shoulder',name:'Cross-Body Adduction Stretch',pos:'Standing or seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Bring the affected arm across your chest. Use the opposite hand to pull the elbow further. Feel a stretch in the back of the shoulder. Keep shoulder down and do not shrug.'},
{id:'s3',cat:'Shoulder',name:'Sleeper Stretch (Posterior Capsule)',pos:'Side-lying',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on affected shoulder with elbow bent to 90 degrees. Use other hand to press the wrist toward the surface. Feel a stretch in the back of the shoulder. Do not allow trunk to rotate.'},
{id:'s4',cat:'Shoulder',name:'Scapular Retraction',pos:'Seated or standing',sets:3,reps:'15',hold:'5 sec',freq:'2x/day',instr:'Sit or stand tall. Squeeze shoulder blades together and down as if tucking them into your back pockets. Hold. Release. Do not shrug shoulders upward.'},
{id:'s5',cat:'Shoulder',name:'External Rotation with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a resistance band with elbow bent 90 degrees tucked at your side with a small towel roll. Rotate forearm outward (away from body) against resistance. Slowly return. Keep elbow at side throughout.'},
{id:'s6',cat:'Shoulder',name:'Internal Rotation with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold band anchored to one side with elbow at 90 degrees tucked at your side. Rotate forearm across body (inward) against resistance. Slowly return. Elbow stays at side.'},
{id:'s7',cat:'Shoulder',name:'Shoulder Abduction (Empty Can)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold light weight with thumb pointing down (as if emptying a can). Raise arm to shoulder height at 30 to 45 degrees in front of the body (scapular plane). Do not go above horizontal. Slowly lower.'},
{id:'s8',cat:'Shoulder',name:'Prone T / Y / W',pos:'Prone',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Lie face down. With thumbs up, lift arms to a T (horizontal), then Y (diagonal), then bend elbows to form a W. Squeeze shoulder blades down and back. Use light or no weight to start.'},
{id:'s9',cat:'Shoulder',name:'Wall Slides',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand with forearms on a smooth wall. Slide arms overhead while keeping forearms on the surface. Slide back down. Keep shoulder blades depressed and avoid shrugging.'},
{id:'s10',cat:'Shoulder',name:'Side-Lying External Rotation',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on non-affected side. Hold light weight in top hand with elbow bent 90 degrees tucked at waist. Rotate forearm upward toward the ceiling. Keep elbow at side. Slowly lower.'},
{id:'s11',cat:'Shoulder',name:'Shoulder Pulley - Flexion',pos:'Seated',sets:3,reps:'15',hold:'—',freq:'2x/day',instr:'Using an overhead pulley, hold one handle in each hand. Use the non-affected arm to lift the affected arm overhead. Lower slowly. Keep elbow relatively straight.'},
{id:'s23',cat:'Shoulder',name:'Shoulder Pulley - Abduction',pos:'Seated',sets:3,reps:'15',hold:'—',freq:'2x/day',instr:'Using an overhead pulley positioned to the side, hold one handle in each hand with arms resting at your sides. Use the non-affected arm to pull the affected arm out and up to the side. Lower slowly with control. Keep elbow relatively straight and avoid shrugging the shoulder.'},
{id:'s24',cat:'Shoulder',name:'Straight Arm Pulldown with Band (SAPD)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band overhead in front of you. Hold the handle with arm straight overhead. Keeping the elbow straight throughout, pull the arm down and back until it reaches your side. Slowly return to the overhead position with control. Strengthens the lats and helps depress the shoulder blade.'},
{id:'s25',cat:'Shoulder',name:'Dowel Shoulder Flexion (AAROM)',pos:'Supine or standing',sets:3,reps:'10',hold:'—',freq:'2x/day',instr:'Hold a dowel or stick with both hands, shoulder-width apart, palms down. Use the non-affected arm to assist raising both arms forward and overhead as far as comfortable. Lower slowly with control. Keep elbows straight throughout.'},
{id:'s26',cat:'Shoulder',name:'Dowel Shoulder External Rotation (AAROM)',pos:'Supine',sets:3,reps:'10',hold:'—',freq:'2x/day',instr:'Lie on your back with both elbows bent to 90 degrees and tucked at your sides, holding a dowel across both palms. Use the non-affected arm to push the dowel and rotate the affected arm outward. Return slowly. Keep the elbow tucked at your side throughout.'},
{id:'s27',cat:'Shoulder',name:'Table Slide - Shoulder Flexion',pos:'Seated at table',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Sit facing a table with your forearm resting on a towel or slide board. Slide your arm forward across the table surface, reaching as far as comfortable, then slide back. Keep the motion smooth and let the table support the weight of the arm.'},
{id:'s28',cat:'Shoulder',name:'Table Slide - Shoulder Abduction',pos:'Seated at table',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Sit beside a table with your forearm resting on a towel or slide board. Slide your arm out to the side across the table surface, then slide back in. Keep shoulder relaxed and let the table support the weight of the arm throughout.'},
{id:'s29',cat:'Shoulder',name:'Finger Ladder Wall Climb',pos:'Standing facing wall',sets:3,reps:'10 climbs',hold:'5 sec at top',freq:'Daily',instr:'Stand facing a finger ladder or wall. Use your fingers to walk your hand up the ladder as high as comfortable, going only into a mild stretch. Hold briefly at the top, then walk the fingers back down. Track your progress by noting the highest rung reached.'},
// ELBOW AND WRIST
{id:'e1',cat:'Elbow & Wrist',name:'Wrist Flexor Stretch',pos:'Standing or seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Extend affected arm in front with palm facing up. Use opposite hand to gently bend wrist downward (fingers toward floor). Keep elbow straight. Feel a stretch in the forearm.'},
{id:'e2',cat:'Elbow & Wrist',name:'Wrist Extensor Stretch',pos:'Standing or seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Extend affected arm in front with palm facing down. Use opposite hand to push wrist downward (fingers toward floor). Keep elbow straight. Feel a stretch on top of the forearm.'},
{id:'e3',cat:'Elbow & Wrist',name:'Wrist Curl - Flexion',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Rest forearm on table, palm up, wrist hanging off edge. Hold a light weight. Curl wrist upward. Slowly lower. Keep forearm flat on the table throughout.'},
{id:'e4',cat:'Elbow & Wrist',name:'Wrist Extension with Weight',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Rest forearm on table, palm down, wrist over edge. Hold light weight. Raise the back of the hand upward. Slowly lower. Keep forearm flat on the table.'},
{id:'e5',cat:'Elbow & Wrist',name:'Forearm Pronation and Supination',pos:'Seated, elbow at 90 degrees',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a light hammer or dowel vertically with elbow at 90 degrees. Rotate forearm so palm faces down (pronation), then up (supination). Slow and controlled. The weight increases resistance at end range.'},
{id:'e6',cat:'Elbow & Wrist',name:'Grip Strengthening with Putty',pos:'Seated',sets:3,reps:'20',hold:'3 sec',freq:'Daily',instr:'Hold therapy putty or a soft ball in the palm. Squeeze firmly with all fingers. Hold briefly and fully release. Vary grip by squeezing with only fingertips or performing pinch patterns.'},
{id:'e7',cat:'Elbow & Wrist',name:'Bicep Curl with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a resistance band with arm at side. Curl the forearm up toward the shoulder. Keep elbow tucked at your side. Slowly lower. Keep wrist neutral.'},
{id:'e8',cat:'Elbow & Wrist',name:'Triceps Extension with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor band overhead. Hold with elbow bent near your ear. Straighten elbow fully, pressing hand downward. Slowly return. Keep upper arm stationary.'},
// CORE AND LUMBAR
{id:'l1',cat:'Core & Lumbar',name:'Pelvic Tilts',pos:'Supine, knees bent',sets:3,reps:'15',hold:'5 sec',freq:'2x/day',instr:'Lie on back with knees bent, feet flat. Tighten abdominals to flatten low back against the surface. Hold. Relax. Do not hold your breath. This is a small, controlled motion.'},
{id:'l2',cat:'Core & Lumbar',name:'Dead Bug',pos:'Supine',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Lie on back, arms up toward ceiling, hips and knees at 90 degrees. Brace core. Lower one arm overhead while extending the opposite leg simultaneously. Keep low back flat. Return and repeat opposite side.'},
{id:'l3',cat:'Core & Lumbar',name:'Glute Bridge',pos:'Supine, knees bent',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Lie on back, knees bent, feet hip-width apart. Tighten core and squeeze glutes. Press through heels to raise hips until body forms a straight line shoulder to knees. Hold. Lower slowly.'},
{id:'l4',cat:'Core & Lumbar',name:'Single-Leg Bridge',pos:'Supine, knees bent',sets:3,reps:'12 each',hold:'3 sec',freq:'Daily',instr:'Perform a standard bridge, then extend one leg straight. Hold with hips level. Lower hips slowly and repeat. Switch legs each set. Progress to this only after mastering the standard bridge.'},
{id:'l5',cat:'Core & Lumbar',name:'Bird Dog',pos:'Quadruped',sets:3,reps:'10 each side',hold:'5 sec',freq:'Daily',instr:'Start on hands and knees with neutral spine. Brace core. Extend opposite arm and leg simultaneously until parallel to the floor. Hold. Return slowly. Avoid trunk rotation or arching the back.'},
{id:'l6',cat:'Core & Lumbar',name:'Cat-Camel Stretch',pos:'Quadruped',sets:3,reps:'10',hold:'3 sec each',freq:'2x/day',instr:'On hands and knees, arch your back upward toward the ceiling (cat). Hold. Then let the back sag downward (camel). Move slowly and fluidly. Focus on full spinal motion. Breathe deeply.'},
{id:'l7',cat:'Core & Lumbar',name:'Prone Hip Extension',pos:'Prone',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Lie face down. Tighten glutes and lift one leg with knee straight a few inches off the surface. Hold. Lower slowly. Keep pelvis in contact with the surface throughout.'},
{id:'l8',cat:'Core & Lumbar',name:'Modified Side Plank',pos:'Side-lying on knees',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Lie on your side propped on your forearm and knees. Lift hips off the surface to create a straight line from head to knees. Hold while breathing. Do not let hips sag. Progress to straight-leg version.'},
{id:'l9',cat:'Core & Lumbar',name:'Forearm Plank',pos:'Prone on forearms',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Prop up on forearms and knees (or toes for full plank). Keep body in a straight line. Do not let hips hike up or sag. Breathe steadily. Brace abdominals. Do not hold breath.'},
{id:'l10',cat:'Core & Lumbar',name:'Knees to Chest Stretch',pos:'Supine',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on your back, knees bent. Bring both knees to your chest using your hands. Gently pull knees closer. Feel a stretch in the low back and buttocks. Hold. Breathe and relax.'},
{id:'l11',cat:'Core & Lumbar',name:'Press-Up Extension',pos:'Prone',sets:3,reps:'10',hold:'2 sec',freq:'2x/day',instr:'Lie face down with hands under shoulders. Press through your hands to extend elbows, raising your chest while allowing the low back to arch. Keep hips relaxed on the surface. Only go as high as comfortable.'},
{id:'l12',cat:'Core & Lumbar',name:'Piriformis Stretch',pos:'Supine',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on back. Cross right ankle over left thigh. Clasp hands behind left thigh and gently pull both legs toward your chest. Feel a stretch deep in the right buttock. Hold. Switch sides.'},
// HIP
{id:'h1',cat:'Hip',name:'Supine Hip Abduction',pos:'Supine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with legs straight. Slide one leg out to the side while keeping the foot and kneecap pointing toward the ceiling. Slowly return. Keep pelvis flat on the surface.'},
{id:'h2',cat:'Hip',name:'Clamshell',pos:'Side-lying',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Lie on your side with knees bent to 45 degrees. Keep feet together. Rotate the top knee upward like a clamshell opening. Hold. Lower slowly. Do not let the pelvis roll backward.'},
{id:'h3',cat:'Hip',name:'Hip Flexor Stretch - Half Kneeling',pos:'Half kneeling',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Kneel on one knee (affected side down). Keep trunk upright. Shift weight forward until you feel a stretch at the front of the hip of the kneeling leg. Tuck pelvis slightly under to increase stretch.'},
{id:'h4',cat:'Hip',name:'Side-Lying Hip Abduction',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your side with body in a straight line. Lift the top leg to about 40 degrees. Keep the foot slightly toward the floor to target gluteus medius. Slowly lower. Do not let leg drift forward.'},
{id:'h5',cat:'Hip',name:'Hip Abduction with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand with a resistance band around both ankles. Holding a surface for balance, lift one leg out to the side against resistance. Keep standing knee slightly bent. Slowly return. Keep trunk upright.'},
{id:'h6',cat:'Hip',name:'Monster Walk with Band',pos:'Standing',sets:3,reps:'15 steps each way',hold:'—',freq:'Daily',instr:'Place resistance band around ankles. Stand in slight squat. Walk sideways in a controlled manner, maintaining tension in the band at all times. Keep toes forward. Do not allow knees to cave inward.'},
{id:'h7',cat:'Hip',name:'Standing Hip Extension with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand facing anchor with band around one ankle. Keeping trunk straight and core braced, kick affected leg straight back against resistance. Do not arch low back. Slowly return. Squeeze glute at top.'},
{id:'h8',cat:'Hip',name:'IT Band Stretch - Standing',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand near a wall for balance. Cross affected leg behind the other. Lean away from the wall, pushing your hip outward. Feel a stretch along the outside of the thigh and hip. Keep foot flat on floor.'},
{id:'h9',cat:'Hip',name:'Piriformis / External Rotator Stretch',pos:'Supine',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on back, both knees bent. Cross right ankle over left thigh. Pull the left thigh toward your chest. Feel a stretch deep in the right buttock and outer hip. Hold. Switch sides.'},
// KNEE
{id:'k1',cat:'Knee',name:'Quad Sets',pos:'Supine, leg straight',sets:3,reps:'15',hold:'10 sec',freq:'2x/day',instr:'Sit or lie with the leg straight. Press the back of your knee firmly down toward the surface, tightening the quadriceps. Hold. Relax fully. Feel the front of the thigh tighten. No knee pain should occur.'},
{id:'k2',cat:'Knee',name:'Straight Leg Raise (SLR)',pos:'Supine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on back. Bend the uninvolved knee to 90 degrees. Tighten the quad of the straight leg. Lift the straight leg to about 45 degrees. Hold briefly. Lower slowly.'},
{id:'k3',cat:'Knee',name:'Terminal Knee Extension with Band (TKE)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Place band behind the affected knee, anchored in front. With knee slightly bent, press knee back to full extension against resistance. Squeeze quad. Slowly return. Keep trunk upright.'},
{id:'k4',cat:'Knee',name:'Hamstring Curl with Band',pos:'Prone',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down with band anchored at the foot. Curl heel toward the buttock against resistance. Keep hips on the surface. Slowly straighten. Avoid substituting with hip movement.'},
{id:'k5',cat:'Knee',name:'Wall Slide - Mini Squat',pos:'Standing, back to wall',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Stand with back against a smooth wall, feet shoulder-width apart about 1 to 2 feet from the wall. Slide down until knees reach about 45 to 60 degrees. Hold. Push back up. Track knees over second toe.'},
{id:'k6',cat:'Knee',name:'Step-Ups',pos:'Standing at a step',sets:3,reps:'15 each',hold:'—',freq:'Daily',instr:'Stand in front of a 4 to 6 inch step. Step up with affected leg, straightening to full standing. Slowly lower opposite foot back to floor in a controlled manner. Keep knee aligned over second toe.'},
{id:'k7',cat:'Knee',name:'Standing Calf Raise',pos:'Standing',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Stand near a wall for balance. Rise up on tiptoes, lifting both heels as high as possible. Hold. Lower slowly all the way to the floor. Progress to single-leg when bilateral is too easy.'},
{id:'k8',cat:'Knee',name:'Prone Quad Stretch',pos:'Prone',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie face down. Bend affected knee, reaching back to hold the ankle with a strap or hand. Gently pull heel toward buttock. Keep hips flat on the surface. Feel a stretch in the front of the thigh.'},
{id:'k9',cat:'Knee',name:'Supine Hamstring Stretch',pos:'Supine',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on your back. Lift one leg and clasp behind the thigh. Slowly straighten the knee until a comfortable stretch is felt in the back of the thigh. Keep the other leg flat on the surface. Hold. Do not bounce.'},
{id:'k10',cat:'Knee',name:'VMO Squat - Sumo Stance',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand with feet wider than shoulder-width and toes turned out about 45 degrees. Squat slowly, tracking knees over toes. Keep chest up and weight in heels. Do not let knees cave in. Targets inner quad (VMO).'},
// ANKLE AND FOOT
{id:'a1',cat:'Ankle & Foot',name:'Ankle Alphabet',pos:'Seated or supine',sets:1,reps:'A-Z each foot',hold:'—',freq:'2x/day',instr:'Sit with leg elevated. Using only your ankle and foot (not the whole leg), draw every letter of the alphabet in the air. Promotes active range of motion in all directions. Go slowly and make letters as large as comfortable.'},
{id:'a2',cat:'Ankle & Foot',name:'Dorsiflexion Stretch - Wall',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand facing a wall. Place affected foot close to the wall with toes touching. Lean knee toward the wall over the foot while keeping heel flat. Feel a stretch in the calf and behind the ankle.'},
{id:'a3',cat:'Ankle & Foot',name:'Gastrocnemius Stretch',pos:'Standing at step',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand with toes of affected foot on the edge of a step. Lower the heel below step level with knee straight. Feel a stretch in the upper calf. Can also perform against a wall with knee straight.'},
{id:'a4',cat:'Ankle & Foot',name:'Soleus Stretch',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Perform a calf stretch against a wall, but keep the back knee slightly bent. This targets the soleus (lower calf) rather than the gastrocnemius. Keep heel flat on the ground.'},
{id:'a5',cat:'Ankle & Foot',name:'Ankle Eversion with Band',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit with affected leg extended. Loop band around the foot, anchored to the opposite side. Rotate the sole outward (eversion) against resistance. Slowly return. Targets peroneal muscles on the outer ankle.'},
{id:'a6',cat:'Ankle & Foot',name:'Ankle Inversion with Band',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit with affected leg extended. Loop band around the foot, anchored to the same side. Rotate the sole inward (inversion) against resistance. Slowly return. Targets the tibialis posterior.'},
{id:'a7',cat:'Ankle & Foot',name:'Single-Leg Balance',pos:'Standing',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand on affected leg with a slight knee bend. Hold balance for the time indicated. Progress to eyes closed, standing on foam, or adding arm movements as balance improves. Keep a surface nearby for safety.'},
{id:'a8',cat:'Ankle & Foot',name:'Single-Leg Calf Raise',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on the affected foot near a wall for safety. Rise up on tiptoe as high as possible. Hold. Lower slowly and fully (heel to floor). Critical for Achilles tendon and plantar fascia rehab. Control the eccentric lowering phase.'},
{id:'a9',cat:'Ankle & Foot',name:'Towel Toe Curls',pos:'Seated, bare foot on towel',sets:3,reps:'20',hold:'—',freq:'Daily',instr:'Place a small towel on the floor. Use only the toes to scrunch the towel toward you. Spread toes wide and repeat. Strengthens intrinsic foot muscles. Helpful for plantar fasciitis.'},
{id:'a10',cat:'Ankle & Foot',name:'Ankle Pumps',pos:'Supine or elevated',sets:3,reps:'20',hold:'—',freq:'Every 1-2 hrs',instr:'Flex the foot (pull toes toward you) then point the foot (push toes away) in a pumping motion. Promotes circulation and reduces swelling. Often prescribed early post-op or during periods of limited mobility.'},
// BALANCE AND FUNCTIONAL
{id:'b1',cat:'Balance & Functional',name:'Tandem Stance',pos:'Standing',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand with one foot directly in front of the other, heel touching toe (tightrope stance). Hold position. Keep a chair or wall nearby for safety. Progress to eyes closed or on foam. Switch which foot is in front.'},
{id:'b2',cat:'Balance & Functional',name:'Lateral Step-Overs',pos:'Standing',sets:3,reps:'10 each way',hold:'—',freq:'Daily',instr:'Set up 2 to 3 small cones or objects in a row. Step sideways over each obstacle with a controlled motion. Keep trunk upright and avoid excessive trunk lean. Focus on hip abductor control.'},
{id:'b3',cat:'Balance & Functional',name:'Sit to Stand',pos:'Chair, seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Sit at the front edge of a chair with feet hip-width apart. Lean slightly forward, then press through feet to stand fully. Lower back to seated slowly. Progress to using arms less, then no arms.'},
{id:'b4',cat:'Balance & Functional',name:'Stair Training',pos:'Staircase',sets:3,reps:'5 trips up and down',hold:'—',freq:'Daily',instr:'Ascend stairs leading with the stronger leg. Descend leading with the weaker leg. Progress from step-to-step to step-over-step. Use handrail initially for safety.'},
{id:'b5',cat:'Balance & Functional',name:'Foam Pad Balance',pos:'Standing on foam',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand on a foam pad or folded exercise mat on one or both feet. Maintain balance while keeping trunk upright and gaze fixed on a target. Progress by closing eyes, adding arm movements, or a light ball toss.'},
// MORE CERVICAL
{id:'c8',cat:'Cervical',name:'Cervical Flexion ROM',pos:'Seated',sets:3,reps:'10',hold:'2 sec',freq:'2x/day',instr:'Sit tall. Slowly lower your chin toward your chest as far as comfortable. Hold briefly. Return to neutral. Move slowly and stay within a pain-free range.'},
{id:'c9',cat:'Cervical',name:'Isometric Neck Flexion',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Place your palm on your forehead. Gently push your head forward into your hand without allowing the head to actually move. Hold, then relax. This builds strength without moving the neck.'},
{id:'c10',cat:'Cervical',name:'Isometric Neck Extension',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Place both palms behind your head. Gently push your head backward into your hands without allowing the head to move. Hold, then relax.'},
{id:'c11',cat:'Cervical',name:'Isometric Neck Side Bend',pos:'Seated',sets:3,reps:'10 each side',hold:'5 sec',freq:'Daily',instr:'Place your palm against the side of your head. Gently push your head sideways into your hand without allowing movement. Hold, then relax. Repeat on the other side.'},
{id:'c12',cat:'Cervical',name:'Scalene Stretch',pos:'Seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit tall. Tilt your head back slightly and to one side, looking toward the ceiling on that same side. You should feel a stretch along the front-side of the neck. Hold, then switch sides.'},
{id:'c13',cat:'Cervical',name:'Suboccipital Release Stretch',pos:'Supine',sets:3,reps:'3',hold:'30-45 sec',freq:'Daily',instr:'Lie on your back. Place a small towel roll or your fingers at the base of your skull. Gently nod your chin as if saying "yes" in small motions, allowing the upper neck to release. Breathe and relax.'},
{id:'c14',cat:'Cervical',name:'Standing Wall Chin Tuck',pos:'Standing against wall',sets:3,reps:'10',hold:'5 sec',freq:'2x/day',instr:'Stand with your back, shoulders, and head against a wall. Draw your chin straight back to touch the wall behind your head while keeping eyes level. Hold, then relax. Maintains posture awareness throughout the day.'},
// THORACIC
{id:'t1',cat:'Thoracic',name:'Thoracic Extension Over Foam Roller',pos:'Supine over roller',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Lie with a foam roller placed horizontally under your shoulder blades, knees bent, hands supporting your head. Gently arch backward over the roller. Hold briefly. Return to start. Move the roller to target different segments.'},
{id:'t2',cat:'Thoracic',name:'Open Book Stretch',pos:'Side-lying',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'Lie on your side with knees bent and arms together in front at shoulder height. Rotate your top arm up and across your body, opening your chest toward the ceiling, following with your eyes. Return slowly. Switch sides.'},
{id:'t3',cat:'Thoracic',name:'Quadruped Thoracic Rotation',pos:'Quadruped',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'On hands and knees, place one hand behind your head. Rotate your elbow up toward the ceiling, then back down under your body toward the opposite arm. Keep hips stable. Switch sides.'},
{id:'t4',cat:'Thoracic',name:'Seated Thoracic Rotation',pos:'Seated',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Sit tall with arms crossed over your chest. Rotate your upper trunk to one side as far as comfortable, keeping hips facing forward. Return to center. Rotate to the other side.'},
{id:'t5',cat:'Thoracic',name:'Doorway Pec Stretch',pos:'Standing in doorway',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand in a doorway with your forearm against the frame, elbow at shoulder height. Gently lean your body forward through the doorway. Feel a stretch across the chest. Hold. Repeat with arm at a different height.'},
{id:'t6',cat:'Thoracic',name:'Foam Roller Thoracic Extension (Active)',pos:'Supine over roller',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Lie over a foam roller placed under the mid-back, hands behind head for support. Extend your upper back over the roller, then curl back up. Move slowly and avoid arching the low back.'},
{id:'t7',cat:'Thoracic',name:'Prone I-Y-T Raise',pos:'Prone',sets:3,reps:'10 each position',hold:'2 sec',freq:'Daily',instr:'Lie face down with arms by your sides. Lift arms overhead in line with the body (I), then to a diagonal (Y), then out to the sides (T), squeezing shoulder blades each time. Keep chest lifted slightly off the surface.'},
// MORE SHOULDER
{id:'s13',cat:'Shoulder',name:'Standing Shoulder Flexion with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a resistance band holding both ends. Raise straight arms forward and up to shoulder height against resistance. Slowly lower. Keep core engaged and avoid arching your back.'},
{id:'s14',cat:'Shoulder',name:'Scapular Punches',pos:'Supine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back holding light weights with arms straight up toward the ceiling. Punch upward, allowing the shoulder blade to protract off the surface. Lower slowly. Targets serratus anterior.'},
{id:'s15',cat:'Shoulder',name:'Standing Row with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band at chest height in front of you. Pull both handles toward your ribs, squeezing shoulder blades together. Slowly return. Keep elbows close to your body.'},
{id:'s16',cat:'Shoulder',name:'Bear Hug Stretch',pos:'Standing',sets:3,reps:'3',hold:'20 sec',freq:'2x/day',instr:'Wrap both arms around yourself like a hug, reaching hands toward the opposite shoulder blades. Round your upper back slightly. Feel a stretch between the shoulder blades. Hold and breathe.'},
{id:'s17',cat:'Shoulder',name:'Shoulder Flexion AAROM with Cane',pos:'Supine or seated',sets:3,reps:'10',hold:'—',freq:'2x/day',instr:'Hold a cane or stick with both hands shoulder-width apart. Use the non-affected arm to assist raising both arms overhead. Lower slowly with control. Keep elbows straight throughout.'},
{id:'s18',cat:'Shoulder',name:'AC Joint Cross-Body Press',pos:'Standing',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Gently bring the affected arm across the body at chest height. With the opposite hand, apply light pressure just above the elbow to add a deeper stretch through the front of the shoulder. Avoid forcing if sharp pain occurs.'},
{id:'s19',cat:'Shoulder',name:'Standing Shoulder Extension with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band in front at shoulder height. Hold the handle with arm straight, then pull the arm backward past your hip against resistance. Slowly return. Keep trunk stable, avoid leaning back.'},
{id:'s20',cat:'Shoulder',name:'Towel Slide Wall Wash',pos:'Standing facing wall',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Place a small towel against a wall under your hand. Slide your hand in large circles or up-and-down patterns, simulating washing a window. Keep shoulder relaxed and motion smooth and pain-free.'},
// MORE ELBOW AND WRIST + HAND
{id:'e9',cat:'Elbow & Wrist',name:'Tennis Elbow Eccentric Wrist Extension',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Rest forearm on a table, palm down, wrist over the edge. Use the other hand to lift the wrist up, then slowly lower it down against gravity over a count of 4. This eccentric-focused motion is key for tendon healing.'},
{id:'e10',cat:'Elbow & Wrist',name:'Golfers Elbow Eccentric Wrist Flexion',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Rest forearm on a table, palm up, wrist over the edge holding a light weight. Use the other hand to lift the wrist, then slowly lower it down against gravity over a count of 4.'},
{id:'e11',cat:'Elbow & Wrist',name:'Radial / Ulnar Deviation with Band',pos:'Seated, elbow supported',sets:3,reps:'15 each direction',hold:'2 sec',freq:'Daily',instr:'Hold a light band or hammer with elbow supported on a table, thumb up. Move the wrist side to side (toward thumb, then toward pinky) against resistance. Keep the forearm still throughout.'},
{id:'e12',cat:'Elbow & Wrist',name:'Finger Tendon Glides',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Start with fingers straight. Make a hook fist, then a full fist, then a straight fist, returning to start between each position. This glides the tendons through their full range and helps reduce stiffness.'},
{id:'e13',cat:'Elbow & Wrist',name:'Thumb Opposition',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Touch the tip of your thumb to the tip of each finger one at a time, forming an "O" shape. Hold briefly at each finger. This improves fine motor control and thumb mobility.'},
{id:'e14',cat:'Elbow & Wrist',name:'Rubber Band Finger Extension',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Place a rubber band around all fingers and thumb. Spread fingers apart against the resistance of the band. Slowly return. Strengthens finger extensors, often weak after hand injury.'},
{id:'e15',cat:'Elbow & Wrist',name:'Wrist Circles',pos:'Seated',sets:2,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Make a loose fist and slowly rotate the wrist in a circular motion, first clockwise then counterclockwise. Keep the motion controlled and pain-free. Promotes general wrist mobility.'},
{id:'e16',cat:'Elbow & Wrist',name:'Carpal Tunnel (CTS) Median Nerve Glide',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'2x/day',instr:'Make a fist, then straighten fingers with wrist neutral, then extend wrist back with fingers straight, then add thumb stretch back. Move through this sequence slowly and stop if tingling increases.'},
{id:'e17',cat:'Elbow & Wrist',name:'Elbow Extension Stretch',pos:'Standing or seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Extend the affected arm straight in front of you. Use the opposite hand to gently apply pressure just above the wrist, encouraging the elbow to straighten fully. Hold a comfortable stretch.'},
{id:'e18',cat:'Elbow & Wrist',name:'Elbow Flexion Stretch',pos:'Standing or seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Use the opposite hand to gently assist bending the affected elbow as far as comfortable, bringing the hand toward the shoulder. Hold a comfortable stretch in the back of the upper arm.'},
// MORE CORE AND LUMBAR
{id:'l13',cat:'Core & Lumbar',name:'Standing Pelvic Tilts',pos:'Standing',sets:3,reps:'15',hold:'3 sec',freq:'2x/day',instr:'Stand with knees slightly bent. Tighten your abdominals and tuck your pelvis under (posterior tilt), then release into a gentle arch (anterior tilt). Move slowly between the two positions, building body awareness.'},
{id:'l14',cat:'Core & Lumbar',name:'Quadruped Rock Back',pos:'Quadruped',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'On hands and knees, slowly shift your hips backward toward your heels while keeping your back flat, then return forward. Movement should be smooth and pain-free. Helps restore lumbar flexion tolerance.'},
{id:'l15',cat:'Core & Lumbar',name:'Standing Lumbar Extension',pos:'Standing',sets:3,reps:'10',hold:'2 sec',freq:'2x/day',instr:'Stand with hands on your low back for support. Gently lean backward, extending through the low back as far as comfortable. Hold briefly. Return to standing. Useful for directional preference low back pain.'},
{id:'l16',cat:'Core & Lumbar',name:'Supine March',pos:'Supine, knees bent',sets:3,reps:'10 each leg',hold:'2 sec',freq:'Daily',instr:'Lie on your back with knees bent, feet flat. Brace your core and lift one knee toward your chest without the low back arching or rocking. Lower slowly. Alternate legs.'},
{id:'l17',cat:'Core & Lumbar',name:'Standing Trunk Rotation',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Stand with feet shoulder-width apart, arms crossed over chest. Rotate your trunk to one side, then the other, in a controlled, pain-free motion. Keep hips relatively still and let the motion come from the trunk.'},
{id:'l18',cat:'Core & Lumbar',name:'Plank with Shoulder Taps',pos:'Forearm or hand plank',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Hold a plank position on your hands. Lift one hand to tap the opposite shoulder, then return it to the floor. Keep hips as still as possible throughout, resisting the urge to rotate.'},
{id:'l19',cat:'Core & Lumbar',name:'Stir the Pot (Stability Ball Plank)',pos:'Forearms on stability ball',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'In a forearm plank position with forearms resting on a stability ball, make small circular motions with the ball while keeping the trunk stable and hips level. An advanced core stability exercise.'},
{id:'l20',cat:'Core & Lumbar',name:'McKenzie Press-Up Progression',pos:'Prone',sets:1,reps:'10',hold:'2 sec',freq:'Every 2 hrs',instr:'Lie face down, hands under shoulders. Press up slowly, allowing the low back to extend while keeping hips on the surface. Progress depth gradually over multiple sessions per the McKenzie method, only as tolerated.'},
{id:'l21',cat:'Core & Lumbar',name:'Standing Hamstring Curl (Bodyweight)',pos:'Standing, holding support',sets:3,reps:'15 each leg',hold:'—',freq:'Daily',instr:'Stand holding a support for balance. Bend one knee, bringing the heel up toward the buttock against the resistance of gravity alone. Lower slowly. Good early-stage hamstring activation exercise.'},
{id:'l22',cat:'Core & Lumbar',name:'Bridge with Hip Abduction',pos:'Supine, knees bent',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Perform a glute bridge, then while holding the bridge position, open and close your knees against a light resistance band placed around the thighs. Combines glute bridge and hip abductor activation.'},
// MORE HIP
{id:'h10',cat:'Hip',name:'Standing Hip Circumduction',pos:'Standing, holding support',sets:2,reps:'10 each direction, each leg',hold:'—',freq:'Daily',instr:'Stand holding a support. Lift one leg slightly and draw large, slow circles with the foot, moving from the hip. Repeat in both directions, then switch legs. Promotes hip joint mobility.'},
{id:'h11',cat:'Hip',name:'Frog Stretch',pos:'Quadruped',sets:3,reps:'3',hold:'30-45 sec',freq:'Daily',instr:'On hands and knees, slowly widen your knees apart while keeping ankles in line with knees. Rock hips backward slightly to deepen the stretch through the inner hips and groin. Stop if any sharp pinching occurs.'},
{id:'h12',cat:'Hip',name:'Supine Figure-4 Stretch',pos:'Supine',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on your back, knees bent. Cross one ankle over the opposite knee, forming a "4" shape. Gently push down on the crossed knee while keeping the back flat. Feel a stretch in the outer hip. Switch sides.'},
{id:'h13',cat:'Hip',name:'Standing Hip Flexion with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band around the ankle, anchored behind you. Lift the knee straight up toward the chest against resistance. Hold briefly. Slowly lower. Keep trunk upright, avoid leaning backward.'},
{id:'h14',cat:'Hip',name:'Lateral Band Walk (Squat Position)',pos:'Standing in mini-squat',sets:3,reps:'10 steps each way',hold:'—',freq:'Daily',instr:'Place a band around the ankles or above the knees. Hold a shallow squat position throughout. Step sideways in a controlled manner, maintaining band tension and knee alignment over the toes.'},
{id:'h15',cat:'Hip',name:'Hip Hike',pos:'Standing on step',sets:3,reps:'15 each side',hold:'2 sec',freq:'Daily',instr:'Stand on a small step or block with one foot, allowing the other foot to hang off the edge. Hike the hanging hip up using only the standing-side hip muscles, then lower it below neutral. Strengthens hip abductors.'},
{id:'h16',cat:'Hip',name:'Quadruped Hip Extension (Donkey Kick)',pos:'Quadruped',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'On hands and knees, keep one knee bent at 90 degrees and lift that leg straight up behind you, leading with the heel toward the ceiling. Keep the back flat throughout. Lower slowly. Switch legs.'},
{id:'h17',cat:'Hip',name:'Adductor Squeeze (Ball Between Knees)',pos:'Supine, knees bent',sets:3,reps:'10',hold:'5-10 sec',freq:'Daily',instr:'Lie on your back, knees bent, with a small ball or rolled towel placed between your knees. Squeeze your knees together against the ball. Hold, then relax. Strengthens the inner thigh (adductor) muscles.'},
{id:'h18',cat:'Hip',name:'Standing Hip Adduction with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band at ankle height to the side. Loop the other end around the affected ankle. Pull the leg across the body against resistance. Slowly return. Keep trunk upright and stable.'},
// MORE KNEE
{id:'k11',cat:'Knee',name:'Seated Knee Extension with Band',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with a band anchored behind you and looped around your ankle. Straighten the knee fully against resistance. Slowly return. Keep the thigh stationary on the chair.'},
{id:'k12',cat:'Knee',name:'Short Arc Quad (SAQ)',pos:'Supine, small bolster under knee',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Lie on your back with a small rolled towel or bolster under your knee. Straighten the knee fully by lifting the foot, keeping the back of the knee on the bolster. Hold, then lower slowly. Good early post-op exercise.'},
{id:'k13',cat:'Knee',name:'Heel Slides',pos:'Supine',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Lie on your back with legs straight. Slowly slide one heel toward your buttock, bending the knee as far as comfortable. Hold briefly. Slide back down with control. Improves knee flexion range of motion.'},
{id:'k14',cat:'Knee',name:'Standing Hamstring Curl with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band low in front of you and loop it around your ankle. Curl the heel up toward the buttock against resistance while standing. Slowly return. Hold a support for balance if needed.'},
{id:'k15',cat:'Knee',name:'Lateral Lunge',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Stand with feet together. Step out to one side into a side lunge, bending the stepping knee while keeping the other leg straight. Push back to standing. Keep the bending knee aligned over the foot.'},
{id:'k16',cat:'Knee',name:'Forward Lunge',pos:'Standing',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand tall. Step forward into a lunge, lowering the back knee toward the floor while keeping the front knee aligned over the ankle. Push back to standing. Keep trunk upright throughout.'},
{id:'k17',cat:'Knee',name:'Single-Leg Squat (Mini)',pos:'Standing, near support',sets:3,reps:'10 each leg',hold:'2 sec',freq:'Daily',instr:'Stand on one leg near a support for safety. Perform a small squat on the standing leg, keeping the knee aligned over the toes. Return to standing. Progress depth gradually as control improves.'},
{id:'k18',cat:'Knee',name:'Box Step-Downs',pos:'Standing on box or step',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on a low step or box with one leg. Slowly lower the opposite foot to tap the floor with control, then return to standing on the box. Keep the standing knee tracking over the toes without caving in.'},
{id:'k19',cat:'Knee',name:'Patellar Mobilization',pos:'Supine, leg straight',sets:1,reps:'10 each direction',hold:'5 sec',freq:'Daily',instr:'With the knee relaxed and straight, use your fingers to gently glide the kneecap up, down, and side to side. This can help reduce stiffness, especially after surgery or immobilization. Move slowly and gently.'},
{id:'k20',cat:'Knee',name:'Knee Extension Stretch (Towel)',pos:'Supine',sets:3,reps:'3',hold:'1-2 min',freq:'2-3x/day',instr:'Lie on your back with a small towel roll placed under the ankle so the heel is elevated, allowing the knee to relax into a straightened position using gravity. Hold for an extended duration to improve extension range.'},
// MORE ANKLE AND FOOT
{id:'a11',cat:'Ankle & Foot',name:'Resisted Dorsiflexion with Band',pos:'Seated, leg extended',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit with leg extended and a band anchored in front, looped around the top of the foot. Pull the foot up toward the shin against resistance. Slowly return. Strengthens the tibialis anterior, important for foot drop or ankle sprains.'},
{id:'a12',cat:'Ankle & Foot',name:'Resisted Plantarflexion with Band',pos:'Seated, leg extended',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit with leg extended and a band looped around the ball of the foot, held in both hands. Point the foot downward against resistance, then slowly return. Strengthens the calf and supports push-off during walking.'},
{id:'a13',cat:'Ankle & Foot',name:'Star Excursion Balance Reach',pos:'Standing',sets:2,reps:'8 directions each leg',hold:'—',freq:'Daily',instr:'Stand on one leg. Reach the opposite foot out in different directions (forward, side, back) as far as possible while maintaining balance on the standing leg, then return to center. An advanced dynamic balance challenge.'},
{id:'a14',cat:'Ankle & Foot',name:'Plantar Fascia Stretch with Ball',pos:'Seated or standing',sets:1,reps:'2 min',hold:'—',freq:'Daily',instr:'Place a tennis ball or massage ball under the arch of your foot. Roll the foot back and forth over the ball with light to moderate pressure. Helpful for plantar fasciitis and general foot tightness.'},
{id:'a15',cat:'Ankle & Foot',name:'Heel Walks',pos:'Standing',sets:2,reps:'10-15 steps',hold:'—',freq:'Daily',instr:'Walk forward on your heels only, keeping your toes lifted off the ground the entire time. This strengthens the muscles on the front of the shin (dorsiflexors). Use support nearby if balance is a concern.'},
{id:'a16',cat:'Ankle & Foot',name:'Toe Walks',pos:'Standing',sets:2,reps:'10-15 steps',hold:'—',freq:'Daily',instr:'Walk forward on your toes only, keeping your heels lifted off the ground throughout. Strengthens the calf muscles. Use support nearby if balance is a concern.'},
{id:'a17',cat:'Ankle & Foot',name:'Seated Marble Pickup',pos:'Seated, bare foot',sets:1,reps:'10-15 marbles',hold:'—',freq:'Daily',instr:'Place small marbles or objects on the floor. Using only your toes, pick each one up and place it into a small bowl. Strengthens the small intrinsic muscles of the foot.'},
// BALANCE AND FUNCTIONAL EXTRA
{id:'b6',cat:'Balance & Functional',name:'Standing Marching in Place',pos:'Standing',sets:3,reps:'20 total (10 each leg)',hold:'—',freq:'Daily',instr:'Stand tall, holding support if needed. Lift one knee up toward your chest, then lower and switch to the other leg in a slow marching pattern. Keeps balance reactions sharp while building hip strength.'},
{id:'b7',cat:'Balance & Functional',name:'Functional Reach Test Practice',pos:'Standing',sets:3,reps:'5 each direction',hold:'—',freq:'Daily',instr:'Stand near a support. Reach one arm forward as far as possible without losing balance or stepping, then return. Practice in forward, side, and diagonal directions to build dynamic balance confidence.'},
{id:'b8',cat:'Balance & Functional',name:'Tandem Walk',pos:'Standing, walking',sets:3,reps:'10 steps',hold:'—',freq:'Daily',instr:'Walk in a straight line placing the heel of one foot directly in front of the toes of the other with each step, as if walking a tightrope. Use a hallway with a wall nearby for safety.'},
{id:'b9',cat:'Balance & Functional',name:'Single-Leg Stance with Head Turns',pos:'Standing',sets:3,reps:'10 turns',hold:'—',freq:'Daily',instr:'Stand on one leg near a support. Slowly turn your head side to side while maintaining balance. This challenges the vestibular and visual systems together with balance control. Switch legs.'},
{id:'b10',cat:'Balance & Functional',name:'Sit-to-Stand with Weight Shift',pos:'Chair, seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Sit at the edge of a chair. Shift your weight forward over your feet before standing up fully, focusing on controlled, even weight distribution between both legs throughout the movement.'},
{id:'b11',cat:'Balance & Functional',name:'Clock Reach (Single-Leg)',pos:'Standing',sets:2,reps:'12 positions each leg',hold:'—',freq:'Daily',instr:'Stand on one leg, imagining a clock face on the floor around you. Tap your opposite foot lightly to different "clock numbers" around your standing leg, returning to center each time. Builds dynamic single-leg balance.'},
// POST-OP / GENERAL MOBILITY
{id:'p1',cat:'Post-Op & General',name:'Bed Mobility - Log Roll',pos:'Supine in bed',sets:3,reps:'5 each direction',hold:'—',freq:'Daily',instr:'Bend both knees up. Keeping shoulders and hips aligned, roll your entire body as one unit to the side like a log, using your arms and legs together. Avoid twisting the spine. Useful after spine or hip surgery.'},
{id:'p2',cat:'Post-Op & General',name:'Sit-to-Stand with Assistive Device',pos:'Chair, seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Using a walker or cane for support, scoot to the edge of the chair, lean forward, and push through your hands and legs to stand. Pause to find balance before walking. Reverse the steps slowly to sit back down.'},
{id:'p3',cat:'Post-Op & General',name:'Deep Breathing Exercises',pos:'Seated or semi-reclined',sets:3,reps:'10 breaths',hold:'3 sec',freq:'Every 1-2 hrs',instr:'Breathe in slowly and deeply through your nose, expanding your belly and ribs. Hold briefly, then exhale slowly through your mouth. Helps prevent post-surgical lung complications and reduces stress.'},
{id:'p4',cat:'Post-Op & General',name:'Incentive Spirometer Use',pos:'Seated upright',sets:5,reps:'10 breaths',hold:'3-5 sec',freq:'Every 1-2 hrs',instr:'Seal your lips around the mouthpiece. Breathe in slowly and steadily to raise the indicator as high as possible. Hold briefly, then remove and exhale normally. Commonly prescribed after chest or abdominal surgery.'},
{id:'p5',cat:'Post-Op & General',name:'Assisted Walking with Walker',pos:'Standing',sets:3,reps:'Distance as tolerated',hold:'—',freq:'Daily',instr:'Advance the walker a short distance, then step forward with the affected leg followed by the other leg, keeping weight evenly distributed through the walker. Increase distance gradually as strength and confidence improve.'},
{id:'p6',cat:'Post-Op & General',name:'Gentle Active Range of Motion - General',pos:'As appropriate to joint',sets:2,reps:'10',hold:'—',freq:'Daily',instr:'Move the involved joint slowly through its available pain-free range in all directions without forcing or bouncing. Used broadly early after surgery or injury to maintain mobility before progressing to strengthening.'},
{id:'p7',cat:'Post-Op & General',name:'Edema Pumping Exercises',pos:'Supine, limb elevated',sets:3,reps:'20',hold:'—',freq:'Every 1-2 hrs',instr:'With the affected limb elevated above heart level, perform repeated pumping motions (e.g., ankle pumps for the leg, fist clenches for the arm) to promote circulation and reduce post-surgical swelling.'},
{id:'p8',cat:'Post-Op & General',name:'Scar Mobilization',pos:'Seated',sets:1,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Once the incision is fully healed and cleared by your surgeon, use your fingers to gently massage the scar in small circles and side-to-side motions. Helps prevent adhesions and improve tissue mobility.'},
{id:'p9',cat:'Post-Op & General',name:'Transfer Training - Bed to Chair',pos:'Seated at bedside',sets:3,reps:'3-5',hold:'—',freq:'Daily',instr:'Practice moving safely from the bed to a chair using a pivot or stand-pivot technique as instructed by your therapist. Always lock wheels and brakes on any equipment before transferring. Use assistive devices as directed.'},
{id:'p10',cat:'Post-Op & General',name:'Active-Assisted Range of Motion with Pulley',pos:'Seated',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Using an overhead pulley system, use the uninvolved limb to gently assist moving the involved limb through a greater range of motion than it could achieve alone. Move slowly and stop at any sharp pain.'},
// EXTRA COMMON CLINIC STAPLES
{id:'s21',cat:'Shoulder',name:'Standing Shoulder Shrugs',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand tall with arms relaxed at your sides. Lift both shoulders straight up toward your ears, hold briefly, then let them drop fully down. Repeat slowly with full relaxation between reps.'},
{id:'s22',cat:'Shoulder',name:'Resisted Shoulder Diagonal (D2 Flexion PNF Pattern)',pos:'Standing',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Anchor a band low at your opposite hip. Pull the band diagonally up and across the body to end above the opposite shoulder, rotating the forearm as you go. Return slowly along the same diagonal path. A functional, multi-plane pattern.'},
{id:'k21',cat:'Knee',name:'Leg Press (Light Resistance)',pos:'Seated leg press machine',sets:3,reps:'15',hold:'—',freq:'2-3x/week',instr:'Sit in the leg press machine with feet shoulder-width apart on the platform. Press the platform away by straightening the knees, then return with control, avoiding locking the knees out forcefully at the top.'},
{id:'k22',cat:'Knee',name:'Stationary Bike (Low Resistance)',pos:'Seated on bike',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Pedal at a comfortable, low-resistance pace on a stationary bike. Adjust the seat height so the knee is nearly straight at the bottom of the pedal stroke. Great low-impact option for early knee rehab.'},
{id:'k23',cat:'Knee',name:'Knee Extension Machine',pos:'Seated on machine',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Sit in the leg extension machine with the pad positioned just above the ankle and knees bent at the starting position. Straighten the knee against the resistance, hold briefly at the top, then lower with control. Avoid locking the knee out forcefully.'},
{id:'k24',cat:'Knee',name:'Knee Flexion Machine',pos:'Prone or seated on machine',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Position yourself in the leg curl machine with the pad against the back of the ankle or lower leg, depending on machine type. Bend the knee, curling the pad toward the buttock against resistance. Slowly return to the starting position with control.'},
{id:'h19',cat:'Hip',name:'Standing Hip External Rotation with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band at ankle height to the side. With knee slightly bent, rotate the leg outward from the hip against resistance, keeping the foot planted. Slowly return. Use a support for balance if needed.'},
{id:'h20',cat:'Hip',name:'Supine Hip Internal/External Rotation (Windshield Wipers)',pos:'Supine',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Lie on your back with knees bent and feet flat, knees together. Rotate both knees to one side, then the other, like windshield wipers, keeping feet planted. Move within a comfortable, pain-free range.'},
{id:'l23',cat:'Core & Lumbar',name:'Standing Wall Sit',pos:'Standing against wall',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Stand with your back against a wall, feet shoulder-width apart. Slide down into a seated position with knees at about 90 degrees. Hold, keeping weight even through both legs. Slide back up to standing.'},
{id:'l24',cat:'Core & Lumbar',name:'Dying Bug (Modified Dead Bug)',pos:'Supine',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'Lie on your back with knees bent at 90 degrees and arms reaching toward the ceiling. Slowly lower one arm and the opposite leg toward the floor without arching the low back. Return and switch sides.'},
{id:'a18',cat:'Ankle & Foot',name:'Seated Ankle Resistance Band 4-Way',pos:'Seated',sets:3,reps:'15 each direction',hold:'2 sec',freq:'Daily',instr:'With a band looped around the foot, perform dorsiflexion, plantarflexion, inversion, and eversion movements against resistance in sequence. A complete strengthening circuit for full ankle stability.'},
{id:'a19',cat:'Ankle & Foot',name:'Standing Heel-to-Toe Rock',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand with feet flat. Rock your weight back onto your heels lifting your toes, then forward onto your toes lifting your heels. Move slowly and with control, holding a support if balance is a concern.'},
{id:'c15',cat:'Cervical',name:'Cervical Retraction with Overpressure',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'2x/day',instr:'Perform a chin tuck, then use your hand on your chin to apply a gentle additional pressure backward at the end range. Hold, then release. Use light pressure only and stop with any increase in symptoms.'},
{id:'t8',cat:'Thoracic',name:'Cat-Cow for Thoracic Mobility',pos:'Quadruped',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'On hands and knees, focus the motion specifically through the mid-back (between the shoulder blades) as you arch and round, rather than the low back. Move slowly, breathing with the motion.'},
{id:'e19',cat:'Elbow & Wrist',name:'Reverse Wrist Curl Over Knee',pos:'Seated',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Rest the forearm on your thigh, palm down, wrist hanging just past the knee. Holding a light weight, lift the back of the hand upward, then lower slowly. Keep the forearm still on the thigh throughout.'},
{id:'e20',cat:'Elbow & Wrist',name:'Hammer Curl',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand holding a light weight in each hand with palms facing your body (thumbs up). Curl the weights up toward the shoulders, keeping elbows tucked at your sides. Lower slowly with control.'},
{id:'p11',cat:'Post-Op & General',name:'Ankle Pumps for DVT Prevention',pos:'Supine or seated',sets:5,reps:'15',hold:'—',freq:'Every hour while awake',instr:'Point your toes up toward your shin, then down away from you, in a slow pumping motion. Performed frequently after surgery to promote blood flow in the legs and reduce blood clot risk.'},
{id:'p12',cat:'Post-Op & General',name:'Quad Sets for Post-Surgical Knee',pos:'Supine, leg straight',sets:3,reps:'10',hold:'10 sec',freq:'Every 1-2 hrs',instr:'With the leg straight, tighten the thigh muscle to press the back of the knee down into the surface. Hold, then relax fully. Frequently prescribed in the very early days following knee surgery.'},
// CERVICAL (c16-c25, 10 more)
{id:'c16',cat:'Cervical',name:'Cervical Lateral Glide',pos:'Seated',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Sit tall with chin level. Without tilting or rotating, glide your head straight sideways as if sliding along a shelf. Hold briefly, return to center, then glide the other direction. A subtle motion used for nerve mobility.'},
{id:'c17',cat:'Cervical',name:'Cervical Flexion-Rotation',pos:'Seated',sets:3,reps:'5 each side',hold:'3 sec',freq:'Daily',instr:'Tuck your chin slightly, then rotate your head to one side as far as comfortable while maintaining the tuck. Hold, return to center, repeat on the other side. Often used to assess and treat upper cervical restriction.'},
{id:'c18',cat:'Cervical',name:'Resisted Cervical Rotation with Band',pos:'Seated',sets:3,reps:'12 each side',hold:'2 sec',freq:'Daily',instr:'Anchor a band to the side at head height. Place the band around the back of your head. Rotate your head against the resistance toward the anchor side, then return slowly. Switch the anchor side to work the other direction.'},
{id:'c19',cat:'Cervical',name:'Prone Cervical Extension (Gentle)',pos:'Prone on elbows',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Lie face down propped on your forearms. Gently lift your head to look forward, extending through the neck. Hold briefly, then lower. Keep the motion small and pain-free.'},
{id:'c20',cat:'Cervical',name:'Cervical Isometric Diagonal',pos:'Seated',sets:3,reps:'8 each diagonal',hold:'5 sec',freq:'Daily',instr:'Place your hand on your forehead at a diagonal angle. Gently push your head into your hand without movement, working the diagonal muscle line. Hold, relax, then repeat on the opposite diagonal.'},
{id:'c21',cat:'Cervical',name:'Neck Flexor Endurance Test Position',pos:'Supine',sets:1,reps:'1',hold:'As tolerated, up to 60 sec',freq:'Weekly to track progress',instr:'Lie on your back, perform a chin tuck, then lift your head slightly off the surface holding the tuck. Hold as long as you can with good form. Used both as an exercise and a way to track endurance improvements over time.'},
{id:'c22',cat:'Cervical',name:'Seated Thoracic-Cervical Combined Extension',pos:'Seated',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Sit tall. Gently arch your upper back while lifting your chin slightly, extending through both the neck and upper back together. Hold briefly, then return to neutral. Helps counter forward head and rounded shoulder posture.'},
{id:'c23',cat:'Cervical',name:'Cervical Traction (Self, Towel)',pos:'Supine',sets:1,reps:'—',hold:'5-10 min',freq:'Daily',instr:'Lie on your back. Loop a towel under the base of your skull and hold both ends. Gently pull upward along the length of your body, creating a light traction force on the neck. Use light force only and stop with any tingling or sharp pain.'},
{id:'c24',cat:'Cervical',name:'Standing Posture Reset (Wall Angels for Neck)',pos:'Standing against wall',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Stand with your back against a wall, arms in a goalpost position against the wall. Slide arms up and down while maintaining contact with the wall, keeping the chin gently tucked throughout. Combines postural and cervical retraining.'},
{id:'c25',cat:'Cervical',name:'Cervical Rotation with Eyes Fixed (VOR)',pos:'Seated',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Hold a target (like your thumb) at arm\\u2019s length and keep your eyes fixed on it while rotating your head side to side. This challenges the vestibulo-ocular reflex and is often used for dizziness related to neck dysfunction.'},
// THORACIC (t9-t15, 7 more)
{id:'t9',cat:'Thoracic',name:'Standing Thoracic Extension Against Wall',pos:'Standing',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Stand with a foam roller or rolled towel vertically against the wall behind your upper back. Gently lean back into it and arch slightly through the mid-back. Hold, then return to neutral.'},
{id:'t10',cat:'Thoracic',name:'Child\\u2019s Pose Reach',pos:'Quadruped to kneeling',sets:3,reps:'5',hold:'15-30 sec',freq:'Daily',instr:'From hands and knees, sit your hips back toward your heels while reaching your arms forward along the floor, lowering your chest down. Hold and breathe, feeling a stretch through the upper back and shoulders.'},
{id:'t11',cat:'Thoracic',name:'Thread the Needle',pos:'Quadruped',sets:3,reps:'8 each side',hold:'3 sec',freq:'Daily',instr:'From hands and knees, slide one arm underneath your body and across, rotating your trunk and resting your shoulder toward the floor. Hold briefly, then return and repeat on the other side.'},
{id:'t12',cat:'Thoracic',name:'Standing Reach and Rotate',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Stand with feet shoulder-width apart. Reach both arms forward, then rotate your trunk to one side while opening your arms out, following with your eyes. Return to center and repeat on the other side.'},
{id:'t13',cat:'Thoracic',name:'Foam Roller Angels',pos:'Supine over roller',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Lie along the length of a foam roller placed under your spine, knees bent, feet flat. With arms at your sides, slowly slide them up overhead along the floor and back down, like making a snow angel. Keep low back relaxed.'},
{id:'t14',cat:'Thoracic',name:'Seated Thoracic Extension with Arms Overhead',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Sit tall, interlace your fingers and reach your arms overhead. Gently arch your upper back as you reach up and slightly back. Hold, then return to neutral. Keep the motion through the mid-back rather than the low back.'},
{id:'t15',cat:'Thoracic',name:'Sphinx Pose',pos:'Prone on forearms',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Lie face down and prop yourself up on your forearms with elbows under shoulders. Gently lift your chest, extending through the upper and mid back while keeping the hips on the floor. Hold and breathe.'},
// SHOULDER (s30-s42, 13 more)
{id:'s30',cat:'Shoulder',name:'Standing Shoulder Horizontal Abduction with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band in front at chest height. Hold both handles with arms extended forward. Pull arms out to the sides, squeezing the shoulder blades together. Slowly return. Keep elbows slightly bent throughout.'},
{id:'s31',cat:'Shoulder',name:'Lawnmower Pull',pos:'Standing, band underfoot',sets:3,reps:'12 each side',hold:'2 sec',freq:'Daily',instr:'Stand on a band with one foot, holding the other end in the opposite hand, starting in a slight forward bend. Pull the band diagonally up and back as if starting a lawnmower, rotating the trunk slightly. Return slowly. Switch sides.'},
{id:'s32',cat:'Shoulder',name:'High-to-Low Row with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band overhead. Holding the handle, pull down and back toward your hip, squeezing the shoulder blade down and in. Slowly return to start. Keep your trunk stable throughout.'},
{id:'s33',cat:'Shoulder',name:'Low-to-High Row with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band low in front of you. Pull the handle up and out to the side at shoulder height, leading with the elbow. Slowly return to start. Strengthens the upper back and rotator cuff together.'},
{id:'s34',cat:'Shoulder',name:'Standing Shoulder Press with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a band with handles at shoulder height. Press both arms straight overhead against resistance. Lower slowly with control. Keep core engaged and avoid arching the low back.'},
{id:'s35',cat:'Shoulder',name:'Supine Shoulder Flexion AROM',pos:'Supine',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Lie on your back. Slowly raise your straight arm overhead toward the floor behind you as far as comfortable, then lower back down. The supine position offers gravity-assisted support for early-stage shoulder mobility.'},
{id:'s36',cat:'Shoulder',name:'Standing Shoulder Abduction to 90 with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a band holding the handle in one hand. Raise the straight arm out to the side up to shoulder height against resistance. Lower slowly. Avoid shrugging the shoulder up toward the ear.'},
{id:'s37',cat:'Shoulder',name:'Resisted Shoulder Diagonal (D1 Extension PNF Pattern)',pos:'Standing',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Anchor a band high to one side. Starting with the arm up and across the body, pull the band diagonally down and across to the opposite hip, rotating the forearm as you go. Return slowly along the same path.'},
{id:'s38',cat:'Shoulder',name:'Standing Arm Circles',pos:'Standing',sets:2,reps:'15 each direction',hold:'—',freq:'Daily',instr:'Stand with arms extended out to the sides at shoulder height. Make small to medium circles with your arms, first forward, then backward. Keep the motion controlled and within a pain-free range.'},
{id:'s39',cat:'Shoulder',name:'Seated Scapular Clock',pos:'Seated',sets:1,reps:'1 full circuit',hold:'3 sec each position',freq:'Daily',instr:'Sit tall. Move your shoulder blade through different "clock" positions: up, down, in, out, and the diagonals between, holding briefly at each position. Builds awareness and control of scapular movement.'},
{id:'s40',cat:'Shoulder',name:'Resisted Shoulder Extension (Standing Band Row Variant)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band in front at shoulder height. With your arm straight, pull it backward and down past your hip against resistance, like a swimming stroke. Slowly return to start.'},
{id:'s41',cat:'Shoulder',name:'Towel Behind Back Stretch',pos:'Standing',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Hold a towel behind your back with one hand over the shoulder and the other behind your low back. Gently pull the towel to stretch the top arm into more external rotation or the bottom arm into more internal rotation. Switch hand positions to stretch the other side.'},
{id:'s42',cat:'Shoulder',name:'Standing Resisted Internal Rotation at 90 Abduction',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band at shoulder height. With your arm out to the side at 90 degrees and elbow bent 90 degrees, rotate the forearm forward against resistance. Slowly return. Often used in advanced overhead athlete rehab.'},
// ELBOW & WRIST (e21-e32, 12 more)
{id:'e21',cat:'Elbow & Wrist',name:'Wrist Flexion with Band',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest forearm on a table, palm up, with a band looped under the foot and held in hand. Curl the wrist upward against resistance. Slowly lower. Keep the forearm flat on the table throughout.'},
{id:'e22',cat:'Elbow & Wrist',name:'Wrist Extension with Band',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest forearm on a table, palm down, with a band looped under the foot and held in hand. Lift the back of the hand upward against resistance. Slowly lower. Keep the forearm flat on the table throughout.'},
{id:'e23',cat:'Elbow & Wrist',name:'Reverse Bicep Curl',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand holding light weights with palms facing down (pronated grip). Curl the weights up toward the shoulders, keeping wrists straight and elbows tucked at your sides. Lower slowly. Targets the forearm extensors along with the biceps.'},
{id:'e24',cat:'Elbow & Wrist',name:'Overhead Triceps Stretch',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Raise one arm overhead and bend the elbow so your hand reaches toward the opposite shoulder blade. Use the other hand to gently push on the elbow for a deeper stretch in the back of the upper arm. Hold, then switch sides.'},
{id:'e25',cat:'Elbow & Wrist',name:'Wrist Flexion/Extension Stretch Combo',pos:'Seated',sets:3,reps:'5 each direction',hold:'15 sec',freq:'2x/day',instr:'Extend the arm in front, palm up, and gently pull the fingers down with the other hand for a flexor stretch. Then flip the palm down and gently pull fingers down again for an extensor stretch. Alternate between the two.'},
{id:'e26',cat:'Elbow & Wrist',name:'Putty Pinch Strengthening',pos:'Seated',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Pinch a small piece of therapy putty between your thumb and each finger one at a time, flattening it. Hold briefly, then release. Strengthens fine pinch grip used in many daily tasks.'},
{id:'e27',cat:'Elbow & Wrist',name:'Wrist Ulnar/Radial Deviation Stretch',pos:'Seated',sets:3,reps:'3 each direction',hold:'20 sec',freq:'2x/day',instr:'Extend the arm with the wrist relaxed. Use the other hand to gently bend the wrist toward the thumb side, hold, then toward the pinky side, hold. A gentle stretch for the sides of the wrist.'},
{id:'e28',cat:'Elbow & Wrist',name:'Wall Push-Up (Wrist Loading)',pos:'Standing facing wall',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand facing a wall with hands flat against it at shoulder height. Bend the elbows to bring your chest toward the wall, then push back to start. This gently loads the wrists in a weight-bearing position to build tolerance.'},
{id:'e29',cat:'Elbow & Wrist',name:'Forearm Supination Stretch',pos:'Seated',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Hold the affected forearm with the other hand and gently rotate it so the palm faces further upward than it can go actively. Keep the elbow bent at 90 degrees and tucked at your side throughout.'},
{id:'e30',cat:'Elbow & Wrist',name:'Forearm Pronation Stretch',pos:'Seated',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Hold the affected forearm with the other hand and gently rotate it so the palm faces further downward than it can go actively. Keep the elbow bent at 90 degrees and tucked at your side throughout.'},
{id:'e31',cat:'Elbow & Wrist',name:'Resisted Finger Abduction',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Place a rubber band around the thumb and index finger, or all fingers. Spread the fingers apart against the resistance of the band. Slowly bring them back together. Strengthens the small intrinsic hand muscles.'},
{id:'e32',cat:'Elbow & Wrist',name:'Wrist Extensor Eccentric Lowering (Tyler Twist style)',pos:'Standing, holding light bar or hammer',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Hold a light bar or hammer with the affected wrist extended. Use the other hand to help twist or position it, then slowly lower the wrist into flexion under control over a 4-second count. Often used for stubborn tennis elbow.'},
// CORE & LUMBAR (l25-l38, 14 more)
{id:'l25',cat:'Core & Lumbar',name:'Standing Core Brace',pos:'Standing',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Stand tall. Gently draw your belly button in toward your spine without holding your breath, as if bracing for a light punch to the stomach. Hold, then relax. Builds basic core awareness used in many other exercises.'},
{id:'l26',cat:'Core & Lumbar',name:'Quadruped Alternating Toe Taps',pos:'Quadruped',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'On hands and knees, lift one knee slightly off the ground and tap your toe out to the side, then return. Keep your back flat and core engaged throughout. Alternate sides.'},
{id:'l27',cat:'Core & Lumbar',name:'Standing Side Bend',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Stand with feet shoulder-width apart, arms at your sides. Slide one hand down the side of your leg, bending sideways at the waist, then return to upright. Repeat on the other side. Keep the motion controlled and pain-free.'},
{id:'l28',cat:'Core & Lumbar',name:'Supine Double Knee to Chest',pos:'Supine',sets:3,reps:'1',hold:'30-60 sec',freq:'2x/day',instr:'Lie on your back and bring both knees up to your chest at the same time, holding behind the thighs. Gently pull them closer for a stretch through the entire low back. Hold and breathe deeply.'},
{id:'l29',cat:'Core & Lumbar',name:'Standing Lumbar Flexion Stretch',pos:'Standing',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Stand with feet shoulder-width apart. Slowly bend forward at the hips, reaching toward the floor as far as comfortable, letting the low back round. Hold, then slowly roll back up to standing.'},
{id:'l30',cat:'Core & Lumbar',name:'Bridge with March',pos:'Supine, knees bent',sets:3,reps:'10 each leg',hold:'2 sec',freq:'Daily',instr:'Lift into a bridge position and hold it. While holding, lift one knee toward your chest, then lower it and switch legs, all without letting your hips drop. A more advanced core and glute stability challenge.'},
{id:'l31',cat:'Core & Lumbar',name:'Standing Anti-Rotation Press (Band)',pos:'Standing',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'Hold a band anchored to the side at chest height, pulling it straight out in front of you. Resist the band\\u2019s pull to rotate your trunk, keeping your hips and shoulders square. Hold, then return. Switch sides to face the other anchor direction.'},
{id:'l32',cat:'Core & Lumbar',name:'Curl-Up (Modified)',pos:'Supine, knees bent',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Lie on your back with knees bent. Tuck your chin slightly and lift only your head and shoulders a few inches off the floor, keeping the low back flat. Lower slowly. A gentler alternative to a full sit-up.'},
{id:'l33',cat:'Core & Lumbar',name:'Standing Hip Hinge Pattern',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand with feet hip-width apart and a slight bend in the knees. Push your hips backward while keeping your back flat, lowering your trunk forward, then return to standing by driving your hips forward. Practices safe bending mechanics for daily activities.'},
{id:'l34',cat:'Core & Lumbar',name:'Side-Lying Hip Hike (Quadratus Lumborum)',pos:'Side-lying or standing on step',sets:3,reps:'15 each side',hold:'2 sec',freq:'Daily',instr:'Lie on your side or stand on a small step with the affected side hanging off. Hike that hip up toward your ribs, then lower below neutral. Targets the muscles along the side of the low back and pelvis.'},
{id:'l35',cat:'Core & Lumbar',name:'Standing March with Trunk Stability',pos:'Standing',sets:3,reps:'10 each leg',hold:'2 sec',freq:'Daily',instr:'Stand tall. Lift one knee up to hip height while keeping the trunk upright and stable without leaning back. Hold briefly, then lower and switch legs. Builds the core control needed for walking and stairs.'},
{id:'l36',cat:'Core & Lumbar',name:'Prone Press-Up with Rotation',pos:'Prone',sets:3,reps:'8 each side',hold:'2 sec',freq:'Daily',instr:'From a prone press-up position with hands under shoulders, push up and rotate to one side, looking over your shoulder. Return to center, lower, then repeat rotating to the other side on the next rep.'},
{id:'l37',cat:'Core & Lumbar',name:'Seated Pelvic Clock',pos:'Seated on ball or chair',sets:1,reps:'1 full circuit',hold:'—',freq:'Daily',instr:'Sit on a stability ball or chair. Imagine a clock under your pelvis and slowly tilt and shift your pelvis to touch each "hour" around the clock face in sequence. Builds pelvic and lumbar movement awareness.'},
{id:'l38',cat:'Core & Lumbar',name:'Standing Pallof Press',pos:'Standing',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'Stand sideways to a band anchored at chest height. Hold the handle at your chest with both hands, then press it straight out in front of you, resisting the rotational pull of the band. Hold, then return. Switch to face the other direction.'},
// HIP (h21-h32, 12 more)
{id:'h21',cat:'Hip',name:'Standing Hip Extension (No Band)',pos:'Standing, holding support',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Stand holding a support for balance. Keeping the knee straight, lift one leg straight back behind you using the glute muscles. Avoid leaning the trunk forward to compensate. Lower slowly. Switch legs.'},
{id:'h22',cat:'Hip',name:'Seated Hip External Rotation Stretch (Pretzel)',pos:'Seated in chair',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit in a chair and cross one ankle over the opposite knee. Gently lean forward from the hips, keeping your back straight, until you feel a stretch in the outer hip of the crossed leg. Hold, then switch sides.'},
{id:'h23',cat:'Hip',name:'Standing Hip Flexor Stretch (No Kneel)',pos:'Standing, staggered stance',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand in a staggered stance with one foot well behind the other, both knees slightly bent. Tuck your pelvis under and shift your weight forward until you feel a stretch in the front of the back hip. Hold, then switch sides.'},
{id:'h24',cat:'Hip',name:'Resisted Hip Flexion in Sitting',pos:'Seated',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with a band looped around one thigh and anchored under the opposite foot. Lift the knee up against the resistance, then lower slowly. Good option when standing hip flexion is too difficult.'},
{id:'h25',cat:'Hip',name:'Supine Hip Abduction with Band',pos:'Supine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with a band looped around both ankles, legs straight. Slide one leg out to the side against resistance, keeping the kneecap pointed toward the ceiling. Slowly return. Switch legs.'},
{id:'h26',cat:'Hip',name:'Standing Single-Leg Hip Hinge',pos:'Standing',sets:3,reps:'10 each leg',hold:'2 sec',freq:'Daily',instr:'Stand on one leg with a slight knee bend. Hinge forward at the hip, extending the other leg straight back behind you for balance, like a kickstand deadlift. Return to standing. Builds single-leg hip and balance control together.'},
{id:'h27',cat:'Hip',name:'Hip Flexor Isometric Hold',pos:'Seated',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Sit in a chair and lift one knee a few inches off the seat. Hold the position without movement, then lower. A gentle, joint-friendly way to begin activating the hip flexors after injury or surgery.'},
{id:'h28',cat:'Hip',name:'Side-Lying Hip Abduction with Internal Rotation',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your side with the top leg slightly rotated inward (toes pointed down toward the floor). Lift the leg up to about 40 degrees, then lower slowly. The inward rotation increases emphasis on the gluteus medius.'},
{id:'h29',cat:'Hip',name:'Standing Resisted Hip Abduction (Cable or Band, Standing Leg Opposite)',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Anchor a band low to the side. Stand with the band around the far ankle and lift that leg out to the side against resistance, away from the anchor. Slowly return. Switch which leg you are working by turning around.'},
{id:'h30',cat:'Hip',name:'Hip 90-90 Stretch',pos:'Seated on floor',sets:3,reps:'3',hold:'30 sec',freq:'Daily',instr:'Sit on the floor with the front leg bent 90 degrees in front of you and the back leg bent 90 degrees out to the side behind you. Lean your trunk forward over the front leg for a deeper stretch. Hold, then switch leg positions.'},
{id:'h31',cat:'Hip',name:'Banded Hip Distraction (Self)',pos:'Standing, band around upper thigh',sets:1,reps:'—',hold:'1-2 min',freq:'Before exercise',instr:'Loop a heavy band around the top of the thigh, anchored to a stable point to the side. Step away from the anchor to create gentle tension distracting the hip joint, then gently move the hip through ranges of motion. Often used before mobility work.'},
{id:'h32',cat:'Hip',name:'Standing Resisted Hip Extension (Hip Hinge Pattern with Band)',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Anchor a band low in front of you, looped around one ankle. Hinging slightly at the hip, extend the leg straight back against resistance, squeezing the glute. Slowly return. Keep the standing leg slightly bent for stability.'},
// KNEE (k25-k34, 10 more)
{id:'k25',cat:'Knee',name:'Seated Knee Flexion AROM',pos:'Seated, leg hanging',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit on the edge of a table or chair with the leg hanging freely. Bend and straighten the knee through its available range using just the muscles of the leg, without assistance. Improves active range of motion.'},
{id:'k26',cat:'Knee',name:'Standing Terminal Knee Extension (No Band)',pos:'Standing',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Stand with a slight bend in the knee. Tighten the quad to fully straighten the knee, holding the contraction at the very end of the motion. Slowly allow a slight bend again and repeat. Useful when bands are not available.'},
{id:'k27',cat:'Knee',name:'Eccentric Step-Down',pos:'Standing on step',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on a step with one leg. Slowly lower the opposite leg toward the floor over a count of 4-5 seconds, controlling the descent with the standing leg, then step back up. Often used for patellar tendon rehab.'},
{id:'k28',cat:'Knee',name:'Standing Knee Hyperextension Block Stretch',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Place a small towel roll under the heel while standing with the knee straight, allowing gravity to gently encourage full extension of the knee. Hold and relax into the position. Useful after periods of restricted extension.'},
{id:'k29',cat:'Knee',name:'Quad Set with Hip Adduction (Ball Squeeze)',pos:'Supine',sets:3,reps:'15',hold:'5-10 sec',freq:'Daily',instr:'Lie on your back with a small ball between the knees and legs straight. Tighten the quad while simultaneously squeezing the ball between the knees. Hold, then relax. Combines two common early post-op activations.'},
{id:'k30',cat:'Knee',name:'Standing Mini Squat with Heel Raise',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Perform a shallow squat, then as you stand back up, continue into a calf raise onto your toes before lowering back down. Combines lower body strength and balance in one fluid motion.'},
{id:'k31',cat:'Knee',name:'Backward Walking',pos:'Standing, walking',sets:1,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Walk slowly backward in a straight, clear path, taking controlled, even steps. This activates the quadriceps differently than forward walking and is commonly used in knee rehabilitation programs.'},
{id:'k32',cat:'Knee',name:'Seated Knee Extension with Ankle Weight',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with an ankle weight secured around the lower leg. Straighten the knee fully against the weight, then lower slowly with control. A simple alternative to bands or machines for quad strengthening.'},
{id:'k33',cat:'Knee',name:'Lateral Box Step-Up',pos:'Standing beside box or step',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand beside a low step or box. Step sideways up onto it with one leg, bringing the other leg up to meet it, then step back down to the side. Strengthens the knee and hip in a side-to-side movement pattern.'},
{id:'k34',cat:'Knee',name:'Knee Flexion Stretch (Towel Assisted)',pos:'Supine',sets:3,reps:'3',hold:'30-60 sec',freq:'2x/day',instr:'Lie on your back. Loop a towel around your foot and gently pull the heel toward your buttock to increase knee bending range, keeping the motion gentle and pain-free. Hold and relax into the stretch.'},
// ANKLE & FOOT (a20-a30, 11 more)
{id:'a20',cat:'Ankle & Foot',name:'Seated Ankle Pumps with Resistance Band',pos:'Seated',sets:3,reps:'20',hold:'—',freq:'Daily',instr:'Sit with a light band looped around the foot, held loosely in both hands. Pump the ankle up and down through its full range against the light resistance of the band. Combines circulation benefits with light strengthening.'},
{id:'a21',cat:'Ankle & Foot',name:'Standing Calf Stretch with Strap',pos:'Seated, leg extended',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit with the leg extended and loop a strap or towel around the ball of the foot. Gently pull the foot toward you, keeping the knee straight, to stretch the calf. Hold, then relax.'},
{id:'a22',cat:'Ankle & Foot',name:'Standing Single-Leg Calf Raise on Step (Eccentric)',pos:'Standing on step edge',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand on the edge of a step with the heel hanging off. Rise up onto your toes using both legs for assistance, then shift to standing on the affected leg only and slowly lower the heel below the step level over a 3-4 second count.'},
{id:'a23',cat:'Ankle & Foot',name:'Ankle Resistance Band Figure-8s',pos:'Seated',sets:2,reps:'10 each direction',hold:'—',freq:'Daily',instr:'With a light band around the foot held in both hands, move the foot in a figure-8 pattern, combining multiple directions of motion against light resistance. Builds dynamic ankle control.'},
{id:'a24',cat:'Ankle & Foot',name:'Standing Heel Raises on Uneven Surface',pos:'Standing on pillow or foam',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a pillow or foam pad. Rise up onto your toes, hold briefly, then lower with control. The unstable surface adds a balance challenge to the standard calf raise.'},
{id:'a25',cat:'Ankle & Foot',name:'Big Toe (Hallux) Extension Stretch',pos:'Seated',sets:3,reps:'3',hold:'20 sec',freq:'2x/day',instr:'Sit and use your hand to gently pull the big toe upward and back, stretching the bottom of the foot near the toe joint. Useful for plantar fasciitis or limited big toe motion affecting push-off during walking.'},
{id:'a26',cat:'Ankle & Foot',name:'Resisted Toe Flexion (Towel Scrunch Variant)',pos:'Seated',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Place a small resistance band or towel under the toes. Curl the toes downward against the resistance, then release. Strengthens the small muscles that support the arch of the foot.'},
{id:'a27',cat:'Ankle & Foot',name:'Standing Ankle Circles',pos:'Standing on one leg',sets:2,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Stand on one leg holding a support. Lift the other foot slightly and draw circles with the ankle in both directions. Combines ankle mobility with single-leg balance demand.'},
{id:'a28',cat:'Ankle & Foot',name:'Seated Resisted Ankle Eversion/Inversion Combo',pos:'Seated',sets:3,reps:'15 each direction',hold:'2 sec',freq:'Daily',instr:'Sit with a band looped around the foot anchored to each side in turn. Rotate the sole outward against resistance, then switch the anchor and rotate inward. Strengthens both sides of the ankle for stability.'},
{id:'a29',cat:'Ankle & Foot',name:'Single-Leg Balance on Foam with Ball Toss',pos:'Standing on foam',sets:3,reps:'15 tosses',hold:'—',freq:'Daily',instr:'Stand on one leg on a foam pad. Toss a small ball against a wall or to a partner and catch it while maintaining balance. An advanced dynamic balance and proprioception challenge.'},
{id:'a30',cat:'Ankle & Foot',name:'Walking Lunges with Ankle Focus',pos:'Standing, walking',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Take a controlled lunge step forward, focusing on a stable, flat foot placement and controlled ankle motion through the step. Push off through the front foot to bring the back leg forward into the next lunge.'},
// BALANCE & FUNCTIONAL (b12-b22, 11 more)
{id:'b12',cat:'Balance & Functional',name:'Standing Eyes-Closed Balance',pos:'Standing',sets:3,reps:'—',hold:'15-30 sec',freq:'Daily',instr:'Stand with feet together or in a tandem position and close your eyes, removing visual input to challenge balance. Keep a support nearby for safety. Open eyes immediately if you feel unsteady.'},
{id:'b13',cat:'Balance & Functional',name:'Standing on Pillow',pos:'Standing on pillow',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand with both feet on a soft pillow or cushion. Maintain an upright posture and steady balance on the unstable surface. Progress to one leg as tolerated.'},
{id:'b14',cat:'Balance & Functional',name:'Multi-Directional Lunges',pos:'Standing',sets:3,reps:'8 each direction',hold:'—',freq:'Daily',instr:'From standing, lunge forward, then return to center. Lunge to the side, return. Lunge backward, return. This builds dynamic balance and strength through multiple movement planes used in daily life.'},
{id:'b15',cat:'Balance & Functional',name:'Standing Reach to Floor (Hip Hinge Balance)',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand on both feet or progress to one leg. Hinge at the hips to reach down toward the floor with control, then return to standing. Builds the balance and strength needed for picking objects up safely.'},
{id:'b16',cat:'Balance & Functional',name:'Treadmill Walking (Supervised)',pos:'Standing on treadmill',sets:1,reps:'5-15 min',hold:'—',freq:'Daily',instr:'Walk on a treadmill at a slow, comfortable, and safe speed, holding the rails as needed for balance. Gradually progress speed and duration as tolerated, always with appropriate supervision and safety precautions.'},
{id:'b17',cat:'Balance & Functional',name:'Sit-to-Stand to Walk Transition',pos:'Chair to standing to walking',sets:3,reps:'5 cycles',hold:'—',freq:'Daily',instr:'Stand up from a chair with control, pause to find your balance, then walk a short distance before returning and sitting back down. Practices the full functional sequence used many times throughout a normal day.'},
{id:'b18',cat:'Balance & Functional',name:'Standing Weight Shifts',pos:'Standing',sets:3,reps:'15 each direction',hold:'3 sec',freq:'Daily',instr:'Stand with feet shoulder-width apart. Slowly shift your weight onto one leg, hold briefly, then shift to the other leg. Also practice shifting forward and backward. Builds the foundational control needed for more advanced balance work.'},
{id:'b19',cat:'Balance & Functional',name:'Obstacle Course Stepping',pos:'Standing, walking',sets:2,reps:'1-2 laps',hold:'—',freq:'Daily',instr:'Set up several low objects (books, cones, pillows) in a path. Walk through, stepping carefully over each obstacle with control. Simulates navigating cluttered or uneven real-world environments safely.'},
{id:'b20',cat:'Balance & Functional',name:'Single-Leg Stance on Stairs (Supervised)',pos:'Standing on a stair step',sets:3,reps:'—',hold:'15-20 sec',freq:'Daily',instr:'With supervision and a handrail nearby, stand on one leg on a stair step. Hold the position, building confidence and control for the demands of real stair navigation.'},
{id:'b21',cat:'Balance & Functional',name:'Dual-Task Standing Balance (Counting Backward)',pos:'Standing',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand in a stable position and count backward from 100 by 7s (or another mental task) while maintaining your balance. Practices the divided attention needed for safe walking and standing in daily life.'},
{id:'b22',cat:'Balance & Functional',name:'Standing Reach Across Midline',pos:'Standing on one leg',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Stand on one leg. Reach the opposite hand across your body toward the floor on the standing-leg side, then return upright. Challenges rotational balance control on a single leg.'},
// POST-OP & GENERAL (p13-p20, 8 more)
{id:'p13',cat:'Post-Op & General',name:'Cervical Collar Removal ROM Check',pos:'Seated',sets:1,reps:'5 each direction',hold:'—',freq:'As directed by surgeon',instr:'Once cleared by your surgeon to remove a cervical collar temporarily, gently move the neck through small, pain-free ranges in all directions to begin reintroducing motion. Always follow your surgeon\\u2019s specific clearance and restrictions.'},
{id:'p14',cat:'Post-Op & General',name:'Total Hip Precautions Practice - Sit to Stand',pos:'Chair, seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Practice standing up from a chair while following your surgeon\\u2019s hip precautions (commonly avoiding excessive bending, crossing legs, or twisting). Use an elevated seat if needed and assistive devices as directed.'},
{id:'p15',cat:'Post-Op & General',name:'Total Knee Replacement Early ROM',pos:'Seated, leg supported',sets:3,reps:'10',hold:'5 sec',freq:'Every 1-2 hrs',instr:'In sitting with the leg supported, gently bend and straighten the knee through the available pain-free range. Frequent, gentle motion in the early post-operative period helps prevent stiffness.'},
{id:'p16',cat:'Post-Op & General',name:'Compression Stocking Application Practice',pos:'Seated',sets:1,reps:'1-2',hold:'—',freq:'Daily',instr:'Practice the technique of rolling and applying a compression stocking smoothly over the foot and up the leg without bunching, as instructed, to support circulation and reduce post-surgical swelling.'},
{id:'p17',cat:'Post-Op & General',name:'Cane or Walker Fitting Check',pos:'Standing',sets:1,reps:'—',hold:'—',freq:'Once, then periodically',instr:'Stand upright with arms relaxed at your sides. The top of the cane or walker handle should align with the crease of your wrist, with your elbow bent slightly when gripping the handle. Adjust the device height as needed.'},
{id:'p18',cat:'Post-Op & General',name:'Stair Negotiation with Device',pos:'Standing at stairs',sets:3,reps:'1 flight',hold:'—',freq:'Daily',instr:'Using your prescribed assistive device and following the "up with the good, down with the bad" principle, practice ascending and descending a flight of stairs slowly and safely with supervision as needed.'},
{id:'p19',cat:'Post-Op & General',name:'Postural Drainage Positioning (As Directed)',pos:'As directed by therapist',sets:1,reps:'—',hold:'5-15 min',freq:'As prescribed',instr:'Position yourself as specifically instructed by your therapist to help mobilize and drain secretions from a particular area of the lungs following surgery or with a respiratory condition. Always follow individualized positioning guidance.'},
{id:'p20',cat:'Post-Op & General',name:'Energy Conservation Technique (ECT) Practice',pos:'Varies by task',sets:1,reps:'—',hold:'—',freq:'Throughout the day',instr:'Practice breaking down daily tasks into smaller steps with rest breaks in between, sitting when possible instead of standing, and organizing your space to reduce unnecessary movement. Helps manage fatigue during recovery.'},
// NEURO & VESTIBULAR (n1-n12, new category, 12)
{id:'n1',cat:'Neuro & Vestibular',name:'Gaze Stabilization - Horizontal (VOR x1)',pos:'Seated',sets:3,reps:'30 sec',hold:'—',freq:'2-3x/day',instr:'Hold a target card at arm\\u2019s length. Keeping the target in clear focus, turn your head side to side while keeping your eyes fixed on the target. Start slowly and increase speed as tolerated, stopping if symptoms increase significantly.'},
{id:'n2',cat:'Neuro & Vestibular',name:'Gaze Stabilization - Vertical (VOR x1)',pos:'Seated',sets:3,reps:'30 sec',hold:'—',freq:'2-3x/day',instr:'Hold a target card at arm\\u2019s length. Keeping the target in clear focus, move your head up and down while keeping your eyes fixed on the target. Start slowly and progress speed gradually.'},
{id:'n3',cat:'Neuro & Vestibular',name:'Smooth Pursuit Eye Exercise',pos:'Seated',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Hold a target at arm\\u2019s length and move it slowly side to side, then up and down, while keeping your head still and only your eyes tracking the target smoothly.'},
{id:'n4',cat:'Neuro & Vestibular',name:'Saccadic Eye Movements',pos:'Seated',sets:3,reps:'15 each direction',hold:'—',freq:'Daily',instr:'Hold two targets a comfortable distance apart. Quickly shift your gaze from one target to the other and back, keeping your head still. This trains fast, accurate eye movement control.'},
{id:'n5',cat:'Neuro & Vestibular',name:'Standing Balance with Head Turns',pos:'Standing',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Stand in a stable position near a support. Turn your head side to side while maintaining your balance. Progress by narrowing your stance or standing on a softer surface as tolerated.'},
{id:'n6',cat:'Neuro & Vestibular',name:'Habituation Exercise - Brandt-Daroff',pos:'Seated to side-lying',sets:5,reps:'1 cycle each side',hold:'30 sec each position',freq:'3x/day',instr:'Sit on the edge of a bed. Quickly lie down on one side with your head turned slightly upward. Hold until any dizziness settles, then return to sitting. Repeat lying on the other side. Used for certain types of positional dizziness under guidance.'},
{id:'n7',cat:'Neuro & Vestibular',name:'Static Standing Balance Progression (Narrow Base)',pos:'Standing',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Progress your standing balance challenge by narrowing your foot stance over time: feet apart, feet together, then a tandem (heel-to-toe) stance. Hold each position as tolerated with appropriate safety support nearby.'},
{id:'n8',cat:'Neuro & Vestibular',name:'Functional Mobility with Cognitive Task',pos:'Walking',sets:3,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Walk at a comfortable pace while performing a simple cognitive task, such as naming words that start with a certain letter. Builds the ability to walk safely while attention is divided, as it often is in daily life.'},
{id:'n9',cat:'Neuro & Vestibular',name:'Mirror Therapy for Affected Limb',pos:'Seated at table with mirror',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Place a mirror so the unaffected limb\\u2019s reflection appears in the position of the affected limb. Move the unaffected limb while watching its reflection, which can help retrain motor pathways for the affected side.'},
{id:'n10',cat:'Neuro & Vestibular',name:'Weight Bearing Through Affected Upper Limb',pos:'Seated or standing at table',sets:3,reps:'—',hold:'15-30 sec',freq:'Daily',instr:'Place the affected hand flat on a table or stable surface and gently lean weight through it as tolerated. Helps build proprioceptive input and tone regulation following neurological injury.'},
{id:'n11',cat:'Neuro & Vestibular',name:'Standing Hip Strategy Practice',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand with a support nearby. Practice small, quick weight shifts at the hips in response to a light, expected nudge or perturbation from a partner or therapist, training a fast balance-correcting strategy.'},
{id:'n12',cat:'Neuro & Vestibular',name:'Sit-to-Stand with Visual Target Tracking',pos:'Chair to standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand up from a chair while keeping your eyes on a fixed target across the room, rather than looking down at your feet. Combines a functional movement with gaze and balance control.'},
// TMJ (j1-j10, new category, 10)
{id:'j1',cat:'TMJ',name:'TMJ Rest Position Awareness',pos:'Seated',sets:1,reps:'—',hold:'Ongoing awareness',freq:'Throughout the day',instr:'Rest your tongue gently on the roof of your mouth with teeth slightly apart and lips closed. This is the relaxed resting position for the jaw and helps reduce clenching habits throughout the day.'},
{id:'j2',cat:'TMJ',name:'Controlled Jaw Opening',pos:'Seated, in front of mirror',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'In front of a mirror, slowly open your mouth in a straight line without deviating to either side. Hold briefly at a comfortable opening, then close slowly. Use the mirror to monitor for any side-to-side shifting.'},
{id:'j3',cat:'TMJ',name:'Resisted Jaw Opening',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Place your thumb gently under your chin. Slowly open your mouth against the light resistance of your thumb. Hold, then close. Strengthens the jaw-opening muscles in a controlled way.'},
{id:'j4',cat:'TMJ',name:'Resisted Jaw Closing',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Place your index fingers on your chin. Gently try to close your mouth against the light resistance of your fingers holding it slightly open. Hold, then relax.'},
{id:'j5',cat:'TMJ',name:'Lateral Jaw Movement',pos:'Seated, in front of mirror',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'With your mouth slightly open, slide your lower jaw sideways toward one shoulder, then the other, in a controlled motion. Use a mirror to check for smooth, symmetrical movement.'},
{id:'j6',cat:'TMJ',name:'Jaw Protrusion/Retrusion',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Slide your lower jaw forward (protrusion) as far as comfortable, hold, then pull it back (retrusion). Move slowly and stop with any sharp pain or clicking that causes discomfort.'},
{id:'j7',cat:'TMJ',name:'TMJ Self-Massage',pos:'Seated',sets:1,reps:'1-2 min each side',hold:'—',freq:'Daily',instr:'Use your fingers to gently massage in small circles over the jaw joint just in front of your ear, and along the muscles of the cheek and temple. Helps reduce muscle tension contributing to jaw pain.'},
{id:'j8',cat:'TMJ',name:'Tongue-Up Jaw Opening',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Place your tongue on the roof of your mouth and keep it there while slowly opening your mouth as far as you can without the tongue lifting off. This encourages a more controlled, midline opening pattern.'},
{id:'j9',cat:'TMJ',name:'Cervical Posture for TMJ',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Perform a gentle chin tuck while sitting tall. Forward head posture often contributes to jaw muscle strain, so improving neck alignment can help reduce TMJ symptoms over time.'},
{id:'j10',cat:'TMJ',name:'Warm Compress for Jaw',pos:'Seated or reclined',sets:1,reps:'—',hold:'10-15 min',freq:'Before exercises',instr:'Apply a warm, moist compress to the jaw and temple area for 10-15 minutes before performing jaw exercises. Heat can help relax tight muscles and improve comfort during movement.'},
// PEDIATRIC (peds1-peds10, new category, 10)
{id:'peds1',cat:'Pediatric',name:'Tummy Time',pos:'Prone on floor',sets:1,reps:'—',hold:'5-15 min total per day',freq:'Several times daily',instr:'Place the infant on their tummy on a firm, supervised surface for short periods throughout the day. Encourages early head control, neck strength, and upper body development. Always supervise closely and never during sleep.'},
{id:'peds2',cat:'Pediatric',name:'Assisted Rolling Practice',pos:'Supine on mat',sets:3,reps:'5 each direction',hold:'—',freq:'Daily',instr:'Gently guide the child\\u2019s hip and shoulder to assist rolling from back to side to tummy, encouraging them to complete more of the motion independently over time. Use toys or your voice to motivate movement toward a direction.'},
{id:'peds3',cat:'Pediatric',name:'Supported Sitting Practice',pos:'Seated, supported',sets:1,reps:'—',hold:'5-10 min',freq:'Several times daily',instr:'Support the child in a seated position, gradually reducing the amount of support provided as their trunk control improves. Use toys at eye level to encourage active head and trunk control while seated.'},
{id:'peds4',cat:'Pediatric',name:'Crawling Encouragement',pos:'Quadruped on floor',sets:1,reps:'—',hold:'5-10 min',freq:'Daily',instr:'Place a favorite toy slightly out of reach in front of the child while they are in a hands-and-knees position, encouraging them to crawl forward to reach it. Builds coordination, strength, and the cross-body patterns important for later motor skills.'},
{id:'peds5',cat:'Pediatric',name:'Assisted Standing at Support Surface',pos:'Standing, holding furniture',sets:3,reps:'—',hold:'1-3 min',freq:'Several times daily',instr:'Help the child pull to stand at a stable, low piece of furniture, encouraging them to hold on and bear weight through both legs. Always ensure the surface is stable and cannot tip.'},
{id:'peds6',cat:'Pediatric',name:'Cruising Along Furniture',pos:'Standing, holding furniture',sets:1,reps:'—',hold:'—',freq:'Daily',instr:'Encourage the child to take sideways steps while holding onto a couch or low table, moving along its length to reach a toy. This builds the leg strength and balance leading toward independent walking.'},
{id:'peds7',cat:'Pediatric',name:'Squat to Stand Play',pos:'Standing',sets:1,reps:'10',hold:'—',freq:'Daily',instr:'Encourage the child to squat down to pick up a toy from the floor and stand back up repeatedly during play. Builds functional leg strength in a way that feels like a game rather than exercise.'},
{id:'peds8',cat:'Pediatric',name:'Ball Kicking',pos:'Standing',sets:1,reps:'10 kicks',hold:'—',freq:'Daily',instr:'Roll a soft ball toward the child and encourage them to kick it back. Builds single-leg balance, coordination, and motor planning in a playful format.'},
{id:'peds9',cat:'Pediatric',name:'Animal Walks',pos:'Floor, varies',sets:1,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Encourage the child to move like different animals (bear walk on hands and feet, crab walk, bunny hops). A fun way to build overall strength, coordination, and motor planning across the whole body.'},
{id:'peds10',cat:'Pediatric',name:'Obstacle Course Play',pos:'Floor, varied setup',sets:1,reps:'1-2 laps',hold:'—',freq:'Daily',instr:'Set up a simple, safe obstacle course with pillows to climb over, a tunnel to crawl through, and a line to walk along. Builds gross motor skills, coordination, and motor planning through play.'},
// CERVICAL (c26-c35, 10)
{id:'c26',cat:'Cervical',name:'Cervical Stabilization in Quadruped',pos:'Quadruped',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'On hands and knees with a neutral spine, hold the head and neck steady and level while gently rocking the body forward and back. Trains the deep neck stabilizers under light dynamic load.'},
{id:'c27',cat:'Cervical',name:'Resisted Cervical Extension with Band',pos:'Seated',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Anchor a band in front at head height. Place the band across your forehead. Press your head backward against the resistance, then slowly return. Strengthens the neck extensors.'},
{id:'c28',cat:'Cervical',name:'Resisted Cervical Flexion with Band',pos:'Seated',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Anchor a band behind you at head height. Place the band across the back of your head. Press your head forward against the resistance into a chin tuck, then slowly return.'},
{id:'c29',cat:'Cervical',name:'Seated Cervical Side Glide with Overpressure',pos:'Seated',sets:3,reps:'5 each side',hold:'10 sec',freq:'Daily',instr:'Tilt your head to one side, then use your hand to apply a light additional stretch at the end range. Hold, then return to neutral and repeat on the other side. Use gentle pressure only.'},
{id:'c30',cat:'Cervical',name:'Cervical Retraction in Standing with Wall',pos:'Standing against wall',sets:3,reps:'10',hold:'5 sec',freq:'2x/day',instr:'Stand with your upper back against a wall. Draw your chin straight back until the back of your head approaches the wall, keeping your gaze level. Hold, then relax. Builds postural awareness in a functional standing position.'},
{id:'c31',cat:'Cervical',name:'Cervical Rotation Stretch with Towel Assist',pos:'Seated',sets:3,reps:'3 each side',hold:'20 sec',freq:'2x/day',instr:'Hold a towel with both hands and place it behind your head. Use the towel to gently guide your head into more rotation than you could achieve actively. Hold a comfortable stretch, then switch sides.'},
{id:'c32',cat:'Cervical',name:'Cervical Endurance Hold - Side',pos:'Side-lying',sets:3,reps:'—',hold:'10-20 sec',freq:'Daily',instr:'Lie on your side and lift your head a small amount off the surface, keeping it level, working the side neck muscles. Hold, then lower slowly. Switch sides.'},
{id:'c33',cat:'Cervical',name:'Cervical Active Range of Motion Full Circuit',pos:'Seated',sets:1,reps:'1 full circuit',hold:'2 sec each',freq:'2x/day',instr:'Move slowly through flexion, extension, rotation both ways, and side bending both ways in sequence, pausing briefly at each end range. A complete warm-up for cervical mobility.'},
{id:'c34',cat:'Cervical',name:'Cervical Flexion Stretch with Hands',pos:'Seated',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Sit tall and clasp both hands behind your head. Gently use your hands to guide your chin further toward your chest, feeling a stretch through the back of the neck. Use light pressure only.'},
{id:'c35',cat:'Cervical',name:'Functional Head Turns for Driving Prep',pos:'Seated, as if driving',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Sit as if in a car seat. Practice turning your head to check over each shoulder as you would when checking blind spots while driving. Builds functional rotation range needed for safe driving.'},
// THORACIC (t16-t25, 10)
{id:'t16',cat:'Thoracic',name:'Standing Thoracic Rotation with Band',pos:'Standing',sets:3,reps:'12 each side',hold:'—',freq:'Daily',instr:'Anchor a band at chest height to the side. Hold the handle with both hands extended in front. Rotate your trunk away from the anchor against resistance, then return. Switch direction to work the other side.'},
{id:'t17',cat:'Thoracic',name:'Prone Thoracic Extension with Arms at Sides',pos:'Prone',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Lie face down with arms resting at your sides, palms down. Lift your chest slightly off the floor, squeezing the shoulder blades together. Lower slowly. A gentler alternative to the prone press-up for thoracic extension.'},
{id:'t18',cat:'Thoracic',name:'Seated Cat-Cow Variation',pos:'Seated on chair',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Sit tall in a chair. Round your upper back forward (like cat), then arch it backward, lifting your chest (like cow). Move slowly through the available range, focusing on the mid-back rather than the low back.'},
{id:'t19',cat:'Thoracic',name:'Standing Doorway Thoracic Extension',pos:'Standing in doorway',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Stand in a doorway holding both sides of the frame at shoulder height. Gently lean your chest forward through the doorway while arching slightly through the upper back. Hold, then return.'},
{id:'t20',cat:'Thoracic',name:'Foam Roller Cross-Body Reach',pos:'Side-lying over roller',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Lie on your side with a foam roller supporting your trunk. Reach your top arm across your body and down toward the floor, rotating through the mid-back, then reach it back up and open. Switch sides.'},
{id:'t21',cat:'Thoracic',name:'Standing Overhead Reach with Wall Contact',pos:'Standing facing wall',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Stand facing a wall with one hand placed on it at shoulder height. Reach the other arm up and overhead, rotating your trunk slightly to look up at your hand. Return and repeat.'},
{id:'t22',cat:'Thoracic',name:'Resisted Thoracic Extension (Band Row Variant)',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band in front at chest height. Sit tall and pull both handles back toward your ribs while extending slightly through the upper back. Slowly return. Focuses the row motion through the thoracic spine.'},
{id:'t23',cat:'Thoracic',name:'Quadruped Thread the Needle with Reach',pos:'Quadruped',sets:3,reps:'8 each side',hold:'3 sec',freq:'Daily',instr:'From hands and knees, thread one arm under your body, then reverse the motion and reach that same arm up toward the ceiling, rotating through the trunk to follow it with your eyes. Return and repeat on the other side.'},
{id:'t24',cat:'Thoracic',name:'Standing Wall Angel with Rotation',pos:'Standing against wall',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand against a wall in a goalpost arm position. Slide your arms up and down while keeping contact with the wall, then add a gentle trunk rotation at the top of the movement before returning.'},
{id:'t25',cat:'Thoracic',name:'Seated Thoracic Side Bend',pos:'Seated',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Sit tall with one arm reaching overhead. Side bend your trunk away from that arm, feeling a stretch along the side of the rib cage. Return to upright and repeat on the other side.'},
// SHOULDER (s43-s58, 16)
{id:'s43',cat:'Shoulder',name:'Standing Resisted External Rotation at 90 Abduction',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band low to the side. With your arm out to the side at 90 degrees and elbow bent 90 degrees, rotate the forearm backward against resistance. Slowly return. Common in advanced throwing-athlete rehab.'},
{id:'s44',cat:'Shoulder',name:'Plyometric Wall Dribble',pos:'Standing facing wall',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand facing a wall holding a small weighted ball. Throw the ball against the wall and catch it as it bounces back, absorbing the force through the shoulder. An advanced exercise for return to sport.'},
{id:'s45',cat:'Shoulder',name:'Rhythmic Stabilization',pos:'Standing, arm supported',sets:3,reps:'30 sec',hold:'—',freq:'Daily',instr:'With your arm held out in front or to the side by a partner or therapist, resist small, alternating pushes in different directions without letting the arm move. Builds dynamic shoulder stability and joint control.'},
{id:'s46',cat:'Shoulder',name:'Quadruped Shoulder Tap',pos:'Quadruped',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'From hands and knees, lift one hand and tap the opposite shoulder, then return it to the floor. Keep hips and trunk as stable as possible. Builds shoulder stability through the closed-chain position.'},
{id:'s47',cat:'Shoulder',name:'Standing Plyometric Ball Toss (Chest Pass)',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Hold a light medicine ball at chest height. Push and throw the ball to a partner or against a wall, then catch the return throw, absorbing the impact through the chest and shoulders. Builds power for return to sport.'},
{id:'s48',cat:'Shoulder',name:'Standing Shoulder Flexion to Wall with Slide',pos:'Standing facing wall',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand facing a wall with your hand against it. Slide your hand up the wall as far as comfortable, then slide back down. The wall provides support and feedback for controlled shoulder flexion.'},
{id:'s49',cat:'Shoulder',name:'Resisted Scapular Protraction (Push-Up Plus)',pos:'Prone or wall',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'From a push-up or wall push-up position with arms straight, push your upper back upward slightly further at the top of the motion, protracting the shoulder blades. Hold briefly, then return. Strengthens the serratus anterior.'},
{id:'s50',cat:'Shoulder',name:'Standing Resisted Shoulder Flexion to 180',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a band holding the handle in one hand. Raise the straight arm forward and up overhead against resistance through the full available range. Lower slowly with control.'},
{id:'s51',cat:'Shoulder',name:'Resisted Shoulder External Rotation at Neutral with Towel',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a small rolled towel between your elbow and side. With the elbow bent 90 degrees, rotate the forearm outward against a light band anchored to the side. The towel cues you to keep the elbow tucked properly.'},
{id:'s52',cat:'Shoulder',name:'Overhead Athlete Sleeper Stretch with Towel',pos:'Side-lying',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on the affected shoulder with the elbow bent 90 degrees. Use a towel looped around the wrist, held by the other hand, to gently rotate the arm further into internal rotation than you could manage alone. Use light, controlled pressure only.'},
{id:'s53',cat:'Shoulder',name:'Standing Resisted Shoulder Adduction',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band overhead to the side. Hold the handle with your arm out to the side and pull it down and across your body against resistance. Slowly return. Strengthens the shoulder adductors and lat.'},
{id:'s54',cat:'Shoulder',name:'Push-Up to Plank Walkout',pos:'Standing to plank',sets:3,reps:'8',hold:'—',freq:'Daily',instr:'From standing, hinge forward and walk your hands out to a plank position, then walk them back to your feet and stand up. Builds shoulder stability and overall body control as part of return-to-activity training.'},
{id:'s55',cat:'Shoulder',name:'Resisted Horizontal Adduction (Standing Chest Press with Band)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band behind you at chest height. Hold both handles and press your arms forward and together in front of your chest against resistance. Slowly return. Strengthens the chest and front shoulder muscles.'},
{id:'s56',cat:'Shoulder',name:'Standing Single-Arm Carry',pos:'Standing, walking',sets:3,reps:'1-2 min',hold:'—',freq:'Daily',instr:'Hold a moderate weight in one hand at your side and walk a short distance while keeping your trunk upright and shoulders level, resisting the urge to lean to one side. Switch hands and repeat.'},
{id:'s57',cat:'Shoulder',name:'Standing Y-T-W Raises with Band',pos:'Standing on band',sets:3,reps:'10 each position',hold:'2 sec',freq:'Daily',instr:'Stand on a band holding both handles. Raise your arms to a Y position, then a T position, then a W position against resistance, squeezing the shoulder blades with each. Lower slowly between each.'},
{id:'s58',cat:'Shoulder',name:'Resisted Internal Rotation at 0 Degrees with Towel Roll',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band to the side at waist height. With a small towel roll tucked under your arm and elbow bent 90 degrees, rotate your forearm across your body against resistance. Slowly return, keeping the towel roll in place.'},
// ELBOW & WRIST (e33-e44, 12)
{id:'e33',cat:'Elbow & Wrist',name:'Resisted Forearm Pronation with Band',pos:'Seated, elbow at 90',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a band anchored to the side with elbow bent 90 degrees and tucked at your waist. Rotate the forearm so the palm turns downward against resistance, then return slowly. Keep the elbow stable throughout.'},
{id:'e34',cat:'Elbow & Wrist',name:'Resisted Forearm Supination with Band',pos:'Seated, elbow at 90',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a band anchored to the side with elbow bent 90 degrees and tucked at your waist. Rotate the forearm so the palm turns upward against resistance, then return slowly. Keep the elbow stable throughout.'},
{id:'e35',cat:'Elbow & Wrist',name:'Wrist Extensor Strengthening with Dumbbell (Pronated)',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest the forearm on a table, palm fully down, wrist hanging off the edge holding a light dumbbell. Lift the back of the hand up against gravity, then lower slowly with control.'},
{id:'e36',cat:'Elbow & Wrist',name:'Towel Twist (Wringing)',pos:'Standing or seated',sets:3,reps:'10 each direction',hold:'3 sec',freq:'Daily',instr:'Hold a rolled towel with both hands. Twist it in opposite directions as if wringing out water, alternating which hand twists which way. Builds combined grip and forearm rotational strength.'},
{id:'e37',cat:'Elbow & Wrist',name:'Resisted Thumb Extension',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Loop a small rubber band around your thumb and fingers. Extend the thumb away from the fingers against the resistance of the band, then return slowly. Useful after thumb or hand injuries.'},
{id:'e38',cat:'Elbow & Wrist',name:'Resisted Finger Flexion (Grip Squeeze with Dynamometer or Putty)',pos:'Seated',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Squeeze a grip strengthener, stress ball, or therapy putty firmly with your whole hand. Hold the contraction, then release fully. Track your progress over time if using a measurable grip device.'},
{id:'e39',cat:'Elbow & Wrist',name:'Elbow Flexion/Extension AAROM with Towel',pos:'Seated',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Hold a towel with both hands, one above and one below the affected elbow. Use the unaffected arm to gently assist bending and straightening the affected elbow through a greater range than it could move alone.'},
{id:'e40',cat:'Elbow & Wrist',name:'Standing Resisted Elbow Extension (Overhead Triceps with Band)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band under your foot. Hold the handle with your elbow bent overhead, hand behind your head. Straighten the elbow fully against resistance, then return slowly. Keep your upper arm stationary.'},
{id:'e41',cat:'Elbow & Wrist',name:'Wrist Flexion Stretch in Quadruped',pos:'Quadruped',sets:3,reps:'3',hold:'15-20 sec',freq:'Daily',instr:'On hands and knees with fingers pointing forward, gently shift your weight backward toward your heels while keeping your palms flat, stretching the wrist flexors and forearm. A functional, weight-bearing wrist stretch.'},
{id:'e42',cat:'Elbow & Wrist',name:'Wrist Extension Stretch in Quadruped (Reverse)',pos:'Quadruped',sets:3,reps:'3',hold:'15-20 sec',freq:'Daily',instr:'On hands and knees, turn your hands so fingers point backward toward your knees with palms flat. Gently shift weight backward, stretching the top of the wrist and forearm. Adjust the amount of weight shifted as tolerated.'},
{id:'e43',cat:'Elbow & Wrist',name:'Resisted Wrist Circumduction',pos:'Seated, forearm supported',sets:2,reps:'10 each direction',hold:'—',freq:'Daily',instr:'With forearm supported on a table and holding a light weight or hammer, move the wrist in a controlled circular pattern, working through all directions against gravity and the weight\\u2019s resistance.'},
{id:'e44',cat:'Elbow & Wrist',name:'Functional Jar Opening Simulation',pos:'Seated or standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Practice gripping and twisting a jar lid or similar object (empty or lightly resisted) to simulate the grip and rotational strength needed for this common daily task. Progress resistance as grip strength improves.'},
// CORE & LUMBAR (l39-l54, 16)
{id:'l39',cat:'Core & Lumbar',name:'Standing Resisted Trunk Rotation (Cable or Band, High to Low)',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Anchor a band high to one side. Hold the handle with both hands and pull it diagonally down and across your body, rotating the trunk and hips together. Return slowly along the same path. Switch sides.'},
{id:'l40',cat:'Core & Lumbar',name:'Standing Resisted Trunk Rotation (Low to High)',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Anchor a band low to one side. Hold the handle with both hands and pull it diagonally up and across your body, rotating the trunk and hips together. Return slowly along the same path. Switch sides.'},
{id:'l41',cat:'Core & Lumbar',name:'Side Plank with Hip Abduction',pos:'Side-lying plank',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Hold a side plank position, then lift the top leg up and down while maintaining the plank, keeping hips stable and stacked. An advanced combined core and hip exercise.'},
{id:'l42',cat:'Core & Lumbar',name:'Standing Core Brace with Arm Raise',pos:'Standing',sets:3,reps:'10 each arm',hold:'3 sec',freq:'Daily',instr:'Stand tall and gently brace your core. While maintaining the brace, slowly raise one arm overhead, then lower it. Repeat with the other arm. Trains core stability during upper body movement.'},
{id:'l43',cat:'Core & Lumbar',name:'Quadruped Bird Dog with Hold and March',pos:'Quadruped',sets:3,reps:'8 each side',hold:'5 sec',freq:'Daily',instr:'From the standard bird dog position with opposite arm and leg extended, hold steady, then bring the knee and elbow to touch gently underneath the body before extending back out. Return and switch sides.'},
{id:'l44',cat:'Core & Lumbar',name:'Standing Resisted Lateral Flexion',pos:'Standing',sets:3,reps:'12 each side',hold:'2 sec',freq:'Daily',instr:'Anchor a band overhead to one side. Hold the handle and resist the pull by bending sideways away from the anchor, engaging the obliques on the opposite side. Return to upright. Switch sides.'},
{id:'l45',cat:'Core & Lumbar',name:'Supine Bicycle Crunch (Modified)',pos:'Supine',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Lie on your back with hands behind your head, knees bent. Bring one knee toward your chest while rotating your opposite elbow toward it, then switch sides in a slow, controlled pedaling motion. Keep the low back from arching.'},
{id:'l46',cat:'Core & Lumbar',name:'Standing Farmer\\u2019s Carry',pos:'Standing, walking',sets:3,reps:'1-2 min',hold:'—',freq:'Daily',instr:'Hold a moderate weight in each hand at your sides and walk a controlled distance, keeping your trunk upright and core engaged without leaning to either side. Builds total-body core stability under load.'},
{id:'l47',cat:'Core & Lumbar',name:'Prone Superman Hold',pos:'Prone',sets:3,reps:'—',hold:'10-20 sec',freq:'Daily',instr:'Lie face down with arms extended overhead. Simultaneously lift your arms, chest, and legs slightly off the floor, holding the position like flying. Lower slowly. An advanced exercise for the entire posterior chain.'},
{id:'l48',cat:'Core & Lumbar',name:'Standing Cable Chop (High to Low)',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Anchor a band high to one side. Hold both hands together and pull the band diagonally down across your body in a chopping motion, rotating through the trunk. Return slowly. Switch the anchor side to work the other direction.'},
{id:'l49',cat:'Core & Lumbar',name:'Standing Cable Lift (Low to High)',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Anchor a band low to one side. Hold both hands together and pull the band diagonally up and across your body in a lifting motion, rotating through the trunk. Return slowly. Switch the anchor side to work the other direction.'},
{id:'l50',cat:'Core & Lumbar',name:'Stability Ball Bridge',pos:'Supine, heels on ball',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with your heels resting on a stability ball, knees bent. Lift your hips into a bridge while keeping the ball steady, then lower slowly. The unstable surface increases the core and hamstring demand.'},
{id:'l51',cat:'Core & Lumbar',name:'Standing Wood Chop with Lunge',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Combine a diagonal chopping motion with a band or light weight while stepping into a lunge with the same side leg. Return to standing as you bring the weight back up. A dynamic, functional full-body core exercise.'},
{id:'l52',cat:'Core & Lumbar',name:'Seated Trunk Flexion-Extension on Ball',pos:'Seated on stability ball',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Sit on a stability ball with feet flat. Gently lean your trunk forward and back in a controlled motion while maintaining your balance on the ball. Builds dynamic core control in a seated, low-impact position.'},
{id:'l53',cat:'Core & Lumbar',name:'Standing Resisted Anti-Extension (Band Pull-Down)',pos:'Standing',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Anchor a band overhead in front of you. Pull the handle down toward your waist while resisting the urge to arch your low back, keeping your core braced and ribs down throughout the motion. Hold, then return slowly.'},
{id:'l54',cat:'Core & Lumbar',name:'Prone Plank with Alternating Leg Lift',pos:'Forearm plank',sets:3,reps:'10 each leg',hold:'2 sec',freq:'Daily',instr:'Hold a forearm plank position. Lift one leg a few inches off the floor without letting the hips rotate or sag, hold briefly, then lower and switch legs.'},
// HIP (h33-h44, 12)
{id:'h33',cat:'Hip',name:'Resisted Hip External Rotation in Sitting',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with a band looped around both ankles, knees together. Rotate one foot outward against the resistance, keeping the knee in place. Slowly return. Switch legs.'},
{id:'h34',cat:'Hip',name:'Resisted Hip Internal Rotation in Sitting',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with a band looped around both ankles, knees together. Rotate one foot inward against the resistance, keeping the knee in place. Slowly return. Switch legs.'},
{id:'h35',cat:'Hip',name:'Single-Leg Romanian Deadlift',pos:'Standing',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on one leg holding a light weight in the opposite hand. Hinge forward at the hip, extending the free leg straight back for balance, lowering the weight toward the floor, then return to standing. An advanced hip and balance exercise.'},
{id:'h36',cat:'Hip',name:'Banded Lateral Walks in Athletic Stance',pos:'Standing in semi-squat',sets:3,reps:'15 steps each way',hold:'—',freq:'Daily',instr:'With a band around the ankles and knees bent in an athletic stance, take controlled lateral steps while keeping tension on the band and knees tracking over the toes. Commonly used in return-to-sport hip programs.'},
{id:'h37',cat:'Hip',name:'Standing Resisted Hip Flexion with High Knee',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Anchor a band low behind you, looped around one ankle. Drive the knee up high toward the chest against resistance, then lower slowly. Mimics a running-type motion for athletes returning to sport.'},
{id:'h38',cat:'Hip',name:'Copenhagen Plank (Adductor)',pos:'Side-lying, top foot supported',sets:3,reps:'—',hold:'10-20 sec',freq:'Daily',instr:'Lie on your side with your top foot supported on a bench or chair. Lift your body into a side plank using the inner thigh of the top leg for support. An advanced groin/adductor strengthening exercise used in sports rehab.'},
{id:'h39',cat:'Hip',name:'Standing Hip Flexor March with Resistance',pos:'Standing',sets:3,reps:'15 each leg',hold:'—',freq:'Daily',instr:'Stand holding a light ankle weight or band resistance. March in place, driving the knee up to hip height with control, then lower with control rather than letting it drop. Alternate legs.'},
{id:'h40',cat:'Hip',name:'Lateral Hop and Hold (Hip Stability)',pos:'Standing',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'Stand on one leg, hop sideways to the other leg, and hold the landing steady for a few seconds before hopping back. An advanced plyometric exercise for hip and ankle stability used in late-stage rehab and sport prep.'},
{id:'h41',cat:'Hip',name:'Standing Resisted Hip Abduction with Trunk Lean Control',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Stand holding a support, with a band around the working ankle. Lift the leg out to the side against resistance while specifically focusing on keeping your trunk upright rather than leaning away, a common compensation pattern.'},
{id:'h42',cat:'Hip',name:'Hip Adductor Stretch (Standing Wide Stance)',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand with feet wide apart. Shift your weight to one side, bending that knee while keeping the other leg straight, feeling a stretch along the inner thigh of the straight leg. Hold, then shift to the other side.'},
{id:'h43',cat:'Hip',name:'Standing Single-Leg Balance with Hip Hike Pattern',pos:'Standing',sets:3,reps:'10 each leg',hold:'2 sec',freq:'Daily',instr:'Stand on one leg. Hike the opposite hip up and down repeatedly while maintaining balance on the standing leg. Combines hip strengthening with single-leg balance demand.'},
{id:'h44',cat:'Hip',name:'Resisted Hip Extension in Quadruped with Band',pos:'Quadruped',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'On hands and knees with a band looped around one foot and anchored under the opposite knee, extend the banded leg straight back against resistance. Slowly return. Keep the back flat throughout.'},
// KNEE (k35-k44, 10)
{id:'k35',cat:'Knee',name:'Single-Leg Romanian Deadlift for Knee Control',pos:'Standing',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on one leg and hinge forward at the hip, keeping the knee soft and stable while the other leg extends back for balance. Focuses on knee alignment and control rather than just hip strength.'},
{id:'k36',cat:'Knee',name:'Lateral Step-Down',pos:'Standing on step',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on a step with one leg, allowing the other foot to lower toward the floor to the side with control. Focus on keeping the standing knee aligned over the foot without caving inward. Step back up and repeat.'},
{id:'k37',cat:'Knee',name:'Resisted Knee Extension in Standing (Band Behind Knee)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand with a band looped behind the knee, anchored behind you. With a slight knee bend, press the knee forward into full extension against the resistance, then return slowly. Used for terminal extension control.'},
{id:'k38',cat:'Knee',name:'Plyometric Box Jump (Low)',pos:'Standing',sets:3,reps:'8',hold:'—',freq:'2-3x/week',instr:'Stand in front of a low, stable box. Jump up onto the box landing softly with both feet, then step back down. Used in later-stage rehab to build power and confidence for return to sport, only when cleared.'},
{id:'k39',cat:'Knee',name:'Single-Leg Landing Practice',pos:'Standing on a step',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Step off a low step and land softly on one leg, absorbing the impact with a slight knee bend while keeping the knee aligned over the foot. Practices safe landing mechanics important for sports and daily activities.'},
{id:'k40',cat:'Knee',name:'Resisted Knee Flexion in Standing (Band, Hip Extended)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band low behind you, looped around your ankle. Keeping the hip extended, bend the knee to bring the heel toward the buttock against resistance. Slowly return. Isolates the hamstring at the knee.'},
{id:'k41',cat:'Knee',name:'Lateral Bound (Skater Hop)',pos:'Standing',sets:3,reps:'10 each direction',hold:'2 sec',freq:'2-3x/week',instr:'Push off one leg and hop sideways onto the other leg, holding the landing steady before repeating in the same direction or alternating back and forth. An advanced plyometric exercise for return to sport, only when cleared.'},
{id:'k42',cat:'Knee',name:'Standing Knee Extension Wall Press',pos:'Standing against wall',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Stand with your back against a wall, knees slightly bent. Press the back of your knees into the wall, tightening the quads, then relax. A simple way to build quad activation using the wall for feedback.'},
{id:'k43',cat:'Knee',name:'Single-Leg Squat to Box',pos:'Standing in front of low box',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on one leg in front of a low box or chair. Slowly lower to lightly tap the box with your buttock, then push back up to standing. The box provides a safe depth target for single-leg squat practice.'},
{id:'k44',cat:'Knee',name:'Resisted Terminal Knee Extension in Lunge Position',pos:'Standing lunge position',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Get into a split lunge stance with a band around the front knee, anchored in front. Press the front knee back to full extension against resistance while maintaining the lunge position, then return.'},
// ANKLE & FOOT (a31-a40, 10)
{id:'a31',cat:'Ankle & Foot',name:'Single-Leg Hop in Place',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'Stand on one leg and perform small, controlled hops in place, landing softly each time. An introductory plyometric exercise for ankle strength and confidence before progressing to more advanced hopping drills.'},
{id:'a32',cat:'Ankle & Foot',name:'Forward Hop and Hold',pos:'Standing',sets:3,reps:'10',hold:'3 sec',freq:'2-3x/week',instr:'Stand on one leg and hop forward a short distance, landing softly on the same leg and holding the position steady for a few seconds before resetting. Builds single-leg landing control.'},
{id:'a33',cat:'Ankle & Foot',name:'Resisted Ankle Dorsiflexion in Standing',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band low in front of you, looped over the top of the foot. Lift the foot up toward the shin against resistance while standing, then return slowly. A standing variation of seated dorsiflexion work.'},
{id:'a34',cat:'Ankle & Foot',name:'Single-Leg Balance Reaching to Cones',pos:'Standing',sets:3,reps:'8 directions',hold:'—',freq:'Daily',instr:'Stand on one leg with small cones or markers placed around you. Reach the opposite foot to tap each cone in turn while maintaining balance on the standing leg, then return to center between each reach.'},
{id:'a35',cat:'Ankle & Foot',name:'Ankle Mobility with Knee-to-Wall',pos:'Standing facing wall',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Stand facing a wall in a half-kneeling or staggered position with the front foot a measured distance from the wall. Drive the front knee toward the wall while keeping the heel down, then return. Track distance from the wall to monitor ankle mobility progress.'},
{id:'a36',cat:'Ankle & Foot',name:'Resisted Ankle Plantarflexion in Standing (Heel Raise with Band)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a band looped under the foot, holding the handles. Rise onto your toes against the added resistance of the band, then lower slowly. Adds extra resistance beyond simple bodyweight calf raises.'},
{id:'a37',cat:'Ankle & Foot',name:'Standing Calf Raise on Step (Bilateral)',pos:'Standing on step edge',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Stand on the edge of a step with both heels hanging off. Rise up onto your toes as high as possible, then lower the heels below the level of the step for an extended range calf raise. Hold a railing for balance if needed.'},
{id:'a38',cat:'Ankle & Foot',name:'Ankle Inversion Sprain Proprioception Drill',pos:'Standing on wobble board',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand on a wobble board or balance disc with the affected ankle, working to keep the board as level as possible. A key exercise after ankle sprains to retrain the joint\\u2019s position sense and reduce reinjury risk.'},
{id:'a39',cat:'Ankle & Foot',name:'Side-to-Side Ankle Hops',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'2-3x/week',instr:'Hop side to side over an imaginary or taped line on the floor, landing softly and quickly resetting for the next hop. Builds reactive ankle strength and confidence for cutting and pivoting movements.'},
{id:'a40',cat:'Ankle & Foot',name:'Standing Toe Raises (Anterior Tibialis Focus)',pos:'Standing',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Stand with feet flat. Lift just your toes and the front of your foot upward while keeping your heels on the ground, then lower. Strengthens the muscles along the front of the shin.'},
// BALANCE & FUNCTIONAL (b23-b32, 10)
{id:'b23',cat:'Balance & Functional',name:'Standing Balance on BOSU (Dome Side Up)',pos:'Standing on BOSU',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand with both feet on a BOSU ball with the dome side facing up. Maintain a stable, upright posture on the unstable surface. Progress to a single leg as tolerated, with a support nearby for safety.'},
{id:'b24',cat:'Balance & Functional',name:'Standing Balance on BOSU (Platform Side Up)',pos:'Standing on BOSU, flat side up',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand with the BOSU ball flipped so the flat platform faces up, providing a slightly different and often more challenging type of instability. Maintain your balance with a support nearby.'},
{id:'b25',cat:'Balance & Functional',name:'Single-Leg Stance with Ball Toss to Partner',pos:'Standing',sets:3,reps:'15 tosses',hold:'—',freq:'Daily',instr:'Stand on one leg and toss a ball back and forth with a partner or therapist while maintaining your balance. Adds an unpredictable, reactive element to single-leg balance training.'},
{id:'b26',cat:'Balance & Functional',name:'Walking with Head Turns',pos:'Standing, walking',sets:3,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Walk at a comfortable, supervised pace while turning your head side to side periodically. Combines functional walking with the dynamic balance demands of looking around, as you would in a busy environment.'},
{id:'b27',cat:'Balance & Functional',name:'Standing Reactive Balance (Light Perturbation)',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand in a stable position while a partner or therapist provides light, unexpected nudges from different directions. React to regain balance each time. Always performed with appropriate safety precautions.'},
{id:'b28',cat:'Balance & Functional',name:'Carrying Object While Walking',pos:'Standing, walking',sets:3,reps:'1-2 min',hold:'—',freq:'Daily',instr:'Walk a supervised distance while carrying a light object such as a small basket or tray, practicing the divided attention and balance control needed for many everyday tasks.'},
{id:'b29',cat:'Balance & Functional',name:'Standing on One Leg While Brushing Teeth (Home Practice)',pos:'Standing',sets:1,reps:'2 min',hold:'—',freq:'Daily during routine task',instr:'Practice standing on one leg near the bathroom counter while brushing your teeth, switching legs halfway through. A simple way to build balance practice naturally into your daily routine.'},
{id:'b30',cat:'Balance & Functional',name:'Step-Up with Knee Drive and Balance Hold',pos:'Standing at step',sets:3,reps:'10 each leg',hold:'3 sec',freq:'Daily',instr:'Step up onto a step with one leg, then drive the opposite knee up toward the chest and hold your balance briefly at the top before stepping back down. Combines strength and single-leg balance in one motion.'},
{id:'b31',cat:'Balance & Functional',name:'Standing Balance with Resisted Arm Movement',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand on one or both legs while performing arm exercises with a band or light weights, such as shoulder raises. Challenges balance and upper body strength together.'},
{id:'b32',cat:'Balance & Functional',name:'Community Ambulation Simulation',pos:'Standing, walking',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Practice walking varied distances over different surfaces (carpet, tile, a slight incline if available) while navigating around simple obstacles, simulating the demands of walking in the community.'},
{id:'b33',cat:'Balance & Functional',name:'Toe Taps',pos:'Standing',sets:3,reps:'15 each leg',hold:'—',freq:'Daily',instr:'Stand holding a support for balance. Lift one foot and lightly tap the toe in front of you, then return to standing. Focus on controlled, small movements with the hip and knee. Progress by tapping to the side and back as well. Builds dynamic balance and lower extremity control.'},
{id:'b34',cat:'Balance & Functional',name:'Posterior Lateral Toe Taps',pos:'Standing',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Stand on one leg with a slight knee bend. Reach the opposite foot diagonally backward and to the side, lightly tapping the toe on the floor, then return to center. Targets the posterior and lateral balance strategies while challenging single-leg stance on the standing leg. Progress by increasing speed or reducing support.'},
// POST-OP & GENERAL (p21-p28, 8)
{id:'p21',cat:'Post-Op & General',name:'Sternal Precautions Arm Use',pos:'Seated or standing',sets:1,reps:'—',hold:'—',freq:'As directed post cardiac surgery',instr:'Following sternal precautions after heart surgery, avoid pushing, pulling, or lifting more than the weight specified by your surgical team, and avoid reaching both arms overhead at once. Always follow individualized restrictions from your surgeon.'},
{id:'p22',cat:'Post-Op & General',name:'Logrolling Technique for Spine Precautions',pos:'Supine in bed',sets:3,reps:'5',hold:'—',freq:'Daily',instr:'Keeping your spine in a neutral, aligned position throughout, roll your entire body as one unit from back to side using your arms and legs together rather than twisting through the trunk. Used for spinal surgery precautions.'},
{id:'p23',cat:'Post-Op & General',name:'Abdominal Splinting for Cough or Sneeze',pos:'Seated or standing',sets:1,reps:'As needed',hold:'—',freq:'As needed after abdominal surgery',instr:'Place a pillow or your hands firmly across your abdominal incision before coughing, sneezing, or laughing to provide support and reduce strain and discomfort at the surgical site.'},
{id:'p24',cat:'Post-Op & General',name:'Early Mobilization Walking (Post-Surgical)',pos:'Standing, walking',sets:3,reps:'Short distances as tolerated',hold:'—',freq:'Several times daily',instr:'Begin walking short, supervised distances as early as cleared after surgery, gradually increasing distance and frequency each day. Early mobilization helps reduce many post-surgical complications.'},
{id:'p25',cat:'Post-Op & General',name:'Incision Site Protection During Exercise',pos:'Varies',sets:1,reps:'—',hold:'—',freq:'Ongoing during healing',instr:'Be mindful to avoid direct pressure or excessive stretching across a healing incision during exercise until cleared by your surgeon. Modify positions or exercises as needed to protect the area.'},
{id:'p26',cat:'Post-Op & General',name:'Lymphedema Self-Massage (As Trained)',pos:'Seated or supine',sets:1,reps:'—',hold:'10-15 min',freq:'Daily',instr:'Following specific training from a certified lymphedema therapist, perform the prescribed gentle massage strokes in the correct sequence and direction to help promote lymphatic drainage in the affected limb.'},
{id:'p27',cat:'Post-Op & General',name:'Graded Activity Pacing',pos:'Varies',sets:1,reps:'—',hold:'—',freq:'Throughout recovery',instr:'Gradually increase the duration or intensity of daily activities in small, planned increments rather than pushing through fatigue or pain, helping build tolerance steadily during recovery from surgery or chronic conditions.'},
{id:'p28',cat:'Post-Op & General',name:'Functional Reach for ADLs (Activities of Daily Living)',pos:'Standing or seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Practice reaching for items on shelves at different heights using safe body mechanics and any prescribed precautions, simulating the demands of dressing, grooming, and other daily activities during recovery.'},
// NEURO & VESTIBULAR (n13-n20, 8)
{id:'n13',cat:'Neuro & Vestibular',name:'Standing Romberg Test Practice',pos:'Standing',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand with feet together, arms at your sides, first with eyes open and then with eyes closed, noting any difference in steadiness. Often used both to assess and to train balance and proprioception.'},
{id:'n14',cat:'Neuro & Vestibular',name:'Optokinetic Stimulation Exercise (Moving Visual Background)',pos:'Seated',sets:3,reps:'2-3 min',hold:'—',freq:'Daily',instr:'While seated safely, watch a moving visual pattern (such as a scrolling screen or rotating drum, as directed by your therapist) to help the visual system adapt and reduce sensitivity to motion. Stop if symptoms increase significantly.'},
{id:'n15',cat:'Neuro & Vestibular',name:'Sit-to-Stand with Eyes Closed (Supervised)',pos:'Chair to standing',sets:3,reps:'5',hold:'—',freq:'Daily',instr:'With close supervision and a support nearby, practice standing up from a chair with your eyes closed, relying on proprioceptive and vestibular input rather than vision to maintain balance.'},
{id:'n16',cat:'Neuro & Vestibular',name:'Standing Balance on Compliant Surface with Head Movement',pos:'Standing on foam',sets:3,reps:'10 head turns',hold:'—',freq:'Daily',instr:'Stand on a foam pad while turning your head side to side, combining surface instability with vestibular and visual challenge together. A more advanced balance and vestibular integration exercise.'},
{id:'n17',cat:'Neuro & Vestibular',name:'Functional Reaching Outside Base of Support',pos:'Standing',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Stand with a support nearby and practice reaching just beyond your comfortable base of support in different directions, gradually increasing the reach distance as confidence and control improve.'},
{id:'n18',cat:'Neuro & Vestibular',name:'Seated Trunk Control Reaching',pos:'Seated, unsupported',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Sit without back support and practice reaching in different directions with one arm while maintaining trunk control and balance in sitting. Useful following neurological injury affecting trunk control.'},
{id:'n19',cat:'Neuro & Vestibular',name:'Standing Weight Shift with Visual Feedback',pos:'Standing on balance device',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Stand on a balance device that provides visual feedback (such as a balance board connected to a screen, if available) and practice shifting your weight to hit displayed targets, training controlled balance responses.'},
{id:'n20',cat:'Neuro & Vestibular',name:'Multi-Sensory Standing Balance Progression',pos:'Standing',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Systematically vary the surface (firm to foam), vision (eyes open to closed), and head position while standing to progressively challenge and retrain the systems involved in maintaining balance.'},
// TMJ (j11-j15, 5)
{id:'j11',cat:'TMJ',name:'TMJ Isometric Holds in Multiple Positions',pos:'Seated',sets:3,reps:'8 each direction',hold:'5 sec',freq:'Daily',instr:'Apply gentle resistance with your hand against the jaw in opening, closing, and both side directions in sequence, holding each briefly without allowing movement. Builds balanced strength around the jaw joint.'},
{id:'j12',cat:'TMJ',name:'Jaw Relaxation Breathing',pos:'Seated or reclined',sets:1,reps:'10 breaths',hold:'—',freq:'Several times daily',instr:'Let your jaw hang loosely open with your tongue resting gently on the roof of your mouth. Take slow, deep breaths while consciously relaxing the jaw and facial muscles further with each exhale.'},
{id:'j13',cat:'TMJ',name:'Resisted Lateral Jaw Movement',pos:'Seated',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'Place your fingers against the side of your chin. Gently move your jaw sideways into your fingers, providing light resistance. Hold briefly, then relax. Switch to the other side.'},
{id:'j14',cat:'TMJ',name:'Chewing Awareness Retraining',pos:'Seated, during meals',sets:1,reps:'—',hold:'—',freq:'During meals',instr:'Practice chewing evenly on both sides of the mouth rather than favoring one side, and take smaller bites of softer foods if needed during a flare. Helps reduce uneven loading on the jaw joint over time.'},
{id:'j15',cat:'TMJ',name:'TMJ Distraction Self-Technique',pos:'Seated',sets:1,reps:'5',hold:'5-10 sec',freq:'Daily',instr:'Place your thumb inside your mouth on the lower back molars on one side. Gently press downward and slightly forward to create a light distraction force at the jaw joint, as specifically instructed by your therapist. Use very light pressure only.'},
// PEDIATRIC (peds11-peds15, 5)
{id:'peds11',cat:'Pediatric',name:'Wheelbarrow Walking',pos:'Prone, hands on floor',sets:1,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Hold the child\\u2019s legs gently while they walk forward on their hands like a wheelbarrow. Builds significant upper body and core strength in a fun, game-like format. Adjust the amount of support based on the child\\u2019s ability.'},
{id:'peds12',cat:'Pediatric',name:'Therapy Ball Prone Extension Play',pos:'Prone over therapy ball',sets:1,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Position the child face down over a large therapy ball, supporting at the hips, and gently rock to encourage them to lift their head and reach for toys placed in front of them. Builds neck and back extensor strength.'},
{id:'peds13',cat:'Pediatric',name:'Jumping on Trampoline (Supervised)',pos:'Standing on mini trampoline',sets:1,reps:'2-3 min',hold:'—',freq:'Daily',instr:'With close supervision and appropriate safety measures, encourage the child to jump on a small, stable trampoline. Builds leg strength, balance, and motor planning in a highly motivating activity.'},
{id:'peds14',cat:'Pediatric',name:'Therapy Swing Vestibular Play',pos:'Seated or prone in swing',sets:1,reps:'5-10 min',hold:'—',freq:'As tolerated',instr:'Using a therapy swing under appropriate supervision, provide gentle, controlled swinging motion to support vestibular and sensory processing development. Always follow specific guidance on speed and duration from a trained therapist.'},
{id:'peds15',cat:'Pediatric',name:'Hopscotch or Single-Leg Hopping Play',pos:'Standing',sets:1,reps:'10 hops each leg',hold:'—',freq:'Daily',instr:'Encourage the child to hop on one foot, then the other, as part of a hopscotch game or simple hopping activity. Builds single-leg balance, strength, and coordination in a playful, motivating way.'},
// SPORT-SPECIFIC & PLYOMETRIC (sp1-sp14, new category, 14)
{id:'sp1',cat:'Sport-Specific & Plyometric',name:'Pogo Hops',pos:'Standing',sets:3,reps:'20',hold:'—',freq:'2-3x/week',instr:'Stand tall and perform small, quick hops in place using mostly your ankles, keeping your knees relatively straight. Builds reactive strength and prepares the lower leg for higher-level plyometric work.'},
{id:'sp2',cat:'Sport-Specific & Plyometric',name:'Broad Jump',pos:'Standing',sets:3,reps:'8',hold:'—',freq:'2-3x/week',instr:'From a standing position, swing your arms and jump forward as far as possible, landing softly with both feet and absorbing the impact through a slight squat. Used in later-stage rehab to build power.'},
{id:'sp3',cat:'Sport-Specific & Plyometric',name:'Tuck Jump',pos:'Standing',sets:3,reps:'8',hold:'—',freq:'2-3x/week',instr:'Jump straight up, drawing both knees up toward your chest at the peak of the jump, then land softly with control. An advanced plyometric exercise typically introduced in later-stage return-to-sport programs.'},
{id:'sp4',cat:'Sport-Specific & Plyometric',name:'Lateral Bound with Stick',pos:'Standing',sets:3,reps:'10 each direction',hold:'2 sec',freq:'2-3x/week',instr:'Push off one leg and bound sideways onto the other leg, "sticking" the landing with a brief stable hold before bounding back in the other direction. Builds lateral power and landing control.'},
{id:'sp5',cat:'Sport-Specific & Plyometric',name:'Depth Jump',pos:'Standing on low box',sets:3,reps:'8',hold:'—',freq:'2-3x/week',instr:'Step off a low, stable box and immediately jump upward as soon as your feet touch the ground, minimizing ground contact time. A high-level plyometric exercise only used in advanced, cleared rehab stages.'},
{id:'sp6',cat:'Sport-Specific & Plyometric',name:'Agility Ladder Drills',pos:'Standing, floor ladder',sets:3,reps:'2-3 passes',hold:'—',freq:'2-3x/week',instr:'Using an agility ladder laid on the floor, perform quick, controlled footwork patterns through the rungs as instructed (such as quick steps or lateral shuffles). Builds foot speed and coordination for sport.'},
{id:'sp7',cat:'Sport-Specific & Plyometric',name:'Cutting Drill (45-Degree Plant and Cut)',pos:'Standing, running approach',sets:3,reps:'8 each direction',hold:'—',freq:'2-3x/week',instr:'Jog forward, then plant one foot and quickly cut to change direction at roughly a 45-degree angle, decelerating and accelerating with control. A key drill for athletes returning to cutting sports, only when cleared.'},
{id:'sp8',cat:'Sport-Specific & Plyometric',name:'Sprint Starts (Acceleration Drill)',pos:'Standing or staggered stance',sets:3,reps:'5 starts',hold:'—',freq:'2-3x/week',instr:'From a staggered or standing start position, accelerate forward over a short, supervised distance, focusing on a strong, controlled push-off and gradual increase in speed. Used in late-stage return-to-running programs.'},
{id:'sp9',cat:'Sport-Specific & Plyometric',name:'Single-Leg Hop for Distance',pos:'Standing',sets:3,reps:'5 each leg',hold:'—',freq:'Weekly to track progress',instr:'Stand on one leg and hop forward as far as possible, landing and holding the landing on the same leg. Often used as both an exercise and a measurement of single-leg power compared between sides.'},
{id:'sp10',cat:'Sport-Specific & Plyometric',name:'Triple Hop for Distance',pos:'Standing',sets:3,reps:'3 each leg',hold:'—',freq:'Weekly to track progress',instr:'Stand on one leg and perform three consecutive hops forward on the same leg, covering as much distance as possible while maintaining control, then stick the final landing. A standard return-to-sport hop test.'},
{id:'sp11',cat:'Sport-Specific & Plyometric',name:'Medicine Ball Rotational Throw',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Stand sideways to a wall holding a medicine ball at your hip. Rotate your trunk explosively and throw the ball against the wall, then catch the return and repeat. Builds rotational power used in many sports.'},
{id:'sp12',cat:'Sport-Specific & Plyometric',name:'Resisted Sprint with Band',pos:'Standing, running',sets:3,reps:'20-30 yards',hold:'—',freq:'2-3x/week',instr:'With a band anchored behind you around your waist, run forward against the resistance over a short, supervised distance, focusing on strong leg drive. Used in advanced sport-specific conditioning.'},
{id:'sp13',cat:'Sport-Specific & Plyometric',name:'Shuttle Run',pos:'Standing, running',sets:3,reps:'4-6 lengths',hold:'—',freq:'2-3x/week',instr:'Run back and forth between two markers set a measured distance apart, touching the line at each end before changing direction. Builds the change-of-direction conditioning needed for most field and court sports.'},
{id:'sp14',cat:'Sport-Specific & Plyometric',name:'Plyometric Push-Up (Clap Push-Up)',pos:'Prone',sets:3,reps:'8',hold:'—',freq:'2-3x/week',instr:'From a push-up position, lower down then push up explosively enough to briefly leave the ground, clapping your hands together before landing softly back into the next push-up. An advanced upper body power exercise.'},
// PELVIC FLOOR & WOMEN'S HEALTH (pf1-pf12, new category, 12)
{id:'pf1',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Contraction (Kegel)',pos:'Seated or supine',sets:3,reps:'10',hold:'5-10 sec',freq:'Daily',instr:'Gently contract the muscles you would use to stop the flow of urine or hold back gas, without tightening the buttocks, thighs, or abdomen. Hold, then fully relax. Build hold time gradually as control improves.'},
{id:'pf2',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Quick Flicks',pos:'Seated or supine',sets:3,reps:'10',hold:'1 sec',freq:'Daily',instr:'Perform quick, brief pelvic floor contractions and releases in rapid succession, training the fast-twitch component of the pelvic floor muscles used during coughing, sneezing, or sudden movement.'},
{id:'pf3',cat:'Pelvic Floor & Womens Health',name:'Diaphragmatic Breathing with Pelvic Floor Relaxation',pos:'Supine, knees bent',sets:3,reps:'10 breaths',hold:'—',freq:'Daily',instr:'Lie comfortably with knees bent. Breathe in deeply, allowing the belly and pelvic floor to gently relax and expand, then exhale slowly. Helps build coordination between breathing and pelvic floor relaxation.'},
{id:'pf4',cat:'Pelvic Floor & Womens Health',name:'The Knack (Pre-Contraction Before Cough)',pos:'Standing or seated',sets:3,reps:'5',hold:'—',freq:'Daily and as needed',instr:'Practice gently contracting the pelvic floor just before and during a cough or sneeze. This pre-emptive timing strategy can help reduce leakage with sudden increases in abdominal pressure.'},
{id:'pf5',cat:'Pelvic Floor & Womens Health',name:'Bridge with Pelvic Floor Activation',pos:'Supine, knees bent',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Gently contract the pelvic floor, then lift into a bridge while maintaining the contraction throughout the movement. Lower slowly while still holding the contraction, then fully relax at the bottom.'},
{id:'pf6',cat:'Pelvic Floor & Womens Health',name:'Standing Pelvic Floor Activation with Functional Task',pos:'Standing',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Practice gently contracting the pelvic floor while performing a simple functional task, such as lifting a light object or standing up from a chair, to build coordination for real daily activities.'},
{id:'pf7',cat:'Pelvic Floor & Womens Health',name:'Deep Squat Hold for Pelvic Mobility',pos:'Standing to deep squat',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Lower into a comfortable deep squat position, using a support for balance if needed, and hold while breathing deeply. Can help with pelvic floor relaxation and mobility when appropriate for the individual.'},
{id:'pf8',cat:'Pelvic Floor & Womens Health',name:'Transverse Abdominis Activation (Postpartum)',pos:'Supine, knees bent',sets:3,reps:'10',hold:'5-10 sec',freq:'Daily',instr:'Gently draw your lower belly in and slightly up, as if zipping up tight pants, without holding your breath or tightening the upper abdominals strongly. Hold, then relax. A foundational postpartum core exercise.'},
{id:'pf9',cat:'Pelvic Floor & Womens Health',name:'Heel Slides with Core Activation (Postpartum)',pos:'Supine, knees bent',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Lie on your back with a gentle core brace engaged. Slowly slide one heel away from you along the floor, keeping the low back still and stable, then slide it back. Switch legs.'},
{id:'pf10',cat:'Pelvic Floor & Womens Health',name:'Standing Pelvic Tilts for Pregnancy Comfort',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand with knees slightly bent. Gently tilt the pelvis forward and back in a slow, controlled motion to help relieve low back discomfort commonly experienced during pregnancy.'},
{id:'pf11',cat:'Pelvic Floor & Womens Health',name:'Side-Lying Pelvic Floor Activation with Hip Abduction',pos:'Side-lying',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Lie on your side with knees bent. Gently contract the pelvic floor, then lift the top knee while maintaining the contraction. Lower slowly while still holding, then fully relax.'},
{id:'pf12',cat:'Pelvic Floor & Womens Health',name:'Diastasis Recti Safe Curl-Up Check',pos:'Supine, knees bent',sets:1,reps:'1-3',hold:'—',freq:'As directed',instr:'Lie on your back and gently lift your head while feeling along the midline of your abdomen for any doming or significant gap, as taught by your therapist, to monitor abdominal wall healing postpartum. Stop the activity if doming occurs and modify as instructed.'},
// AMPUTEE & PROSTHETIC (amp1-amp9, new category, 9)
{id:'amp1',cat:'Amputee & Prosthetic',name:'Residual Limb Desensitization',pos:'Seated',sets:1,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Gently rub the residual limb with different textures of fabric (soft to slightly rougher), gradually increasing the firmness of contact to help reduce sensitivity and improve tolerance for prosthetic wear.'},
{id:'amp2',cat:'Amputee & Prosthetic',name:'Residual Limb Strengthening - Hip Extension',pos:'Prone or standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'For a lower limb amputation, extend the residual limb backward against light resistance or gravity, focusing on hip extensor strength important for prosthetic gait and stance phase control.'},
{id:'amp3',cat:'Amputee & Prosthetic',name:'Prosthetic Donning and Doffing Practice',pos:'Seated',sets:1,reps:'3-5 repetitions',hold:'—',freq:'Daily',instr:'Practice the full sequence of putting on and taking off the prosthetic limb and any liners or socks involved, working toward an efficient, independent technique as instructed by your prosthetist and therapist.'},
{id:'amp4',cat:'Amputee & Prosthetic',name:'Standing Weight Shift Onto Prosthesis',pos:'Standing between bars or rails',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Standing between parallel bars or a stable support, practice shifting your weight onto the prosthetic side and holding briefly before shifting back. Builds confidence and tolerance for weight bearing through the prosthesis.'},
{id:'amp5',cat:'Amputee & Prosthetic',name:'Prosthetic Gait Training - Step Length Symmetry',pos:'Standing, walking',sets:1,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Walk with focus on taking even step lengths with both the prosthetic and intact limb, often practiced with floor markers or tape to provide visual feedback on symmetry.'},
{id:'amp6',cat:'Amputee & Prosthetic',name:'Residual Limb Range of Motion - Hip',pos:'Supine or seated',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Move the hip of the residual limb through all available directions (flexion, extension, abduction) to maintain full joint mobility, which is critical for proper prosthetic fit and function.'},
{id:'amp7',cat:'Amputee & Prosthetic',name:'Phantom Limb Sensation Management Exercise',pos:'Seated, using mirror',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Using a mirror to reflect the intact limb in the position of the amputated limb, perform movements with the intact limb while visualizing the movement occurring in the missing limb, which can help manage phantom limb sensations.'},
{id:'amp8',cat:'Amputee & Prosthetic',name:'Standing Balance with Prosthesis',pos:'Standing',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Stand with even weight distribution between the prosthetic and intact limb, working on steady balance with a support nearby. Progress to reduced support and added challenges as confidence builds.'},
{id:'amp9',cat:'Amputee & Prosthetic',name:'Stump Shrinker or Wrap Application Practice',pos:'Seated',sets:1,reps:'1-2',hold:'—',freq:'Daily',instr:'Practice applying a compression shrinker sock or wrap to the residual limb in the technique taught by your therapist, helping manage swelling and shape the limb appropriately for prosthetic fitting.'},
// EXTRA SHOULDER (s59-s62, 4)
{id:'s59',cat:'Shoulder',name:'Resisted Shoulder Shrug with Band',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a band holding the handles at your sides. Shrug your shoulders straight up against the resistance, then lower slowly with control.'},
{id:'s60',cat:'Shoulder',name:'Standing Resisted Scapular Depression',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold onto handles anchored overhead. Pull your shoulder blades down and together, depressing the shoulders away from your ears against resistance. Slowly return.'},
{id:'s61',cat:'Shoulder',name:'Quadruped Plus Position Hold',pos:'Quadruped',sets:3,reps:'—',hold:'15-20 sec',freq:'Daily',instr:'From hands and knees, gently round your upper back slightly while pressing your hands into the floor, protracting the shoulder blades. Hold this "plus" position, then relax.'},
{id:'s62',cat:'Shoulder',name:'Standing Resisted Shoulder Circles',pos:'Standing',sets:2,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Hold light weights or bands in each hand. Make slow, controlled circles with both arms extended out to the sides, first forward then backward, against the light resistance.'},
{id:'s63',cat:'Shoulder',name:'Mid Row with Band',pos:'Seated or standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band at chest or mid-torso height in front of you. Hold both handles with arms extended forward, palms facing each other or down. Pull the handles back toward your lower ribcage, squeezing the shoulder blades together and keeping elbows close to the body. Slowly return to start. Targets the mid trapezius and rhomboids.'},
{id:'s64',cat:'Shoulder',name:'Low Row with Band',pos:'Seated or standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band low in front of you at floor or shin height. Hold both handles and pull them back and upward toward your hips, driving the elbows back and squeezing the shoulder blades down and together. Slowly return. The low anchor emphasizes the lower trapezius and promotes scapular depression — important for shoulder stability and posture.'},
// EXTRA HIP (h45-h47, 3)
{id:'h45',cat:'Hip',name:'Standing Resisted Hip Circumduction with Band',pos:'Standing',sets:2,reps:'8 each direction, each leg',hold:'—',freq:'Daily',instr:'Anchor a band around one ankle. Lift the leg slightly and draw slow circles against the resistance, moving from the hip. Repeat in both directions, then switch legs.'},
{id:'h46',cat:'Hip',name:'Standing Hip 4-Way with Band (Circuit)',pos:'Standing',sets:1,reps:'15 each direction',hold:'2 sec',freq:'Daily',instr:'With a band around one ankle anchored appropriately, perform hip flexion, extension, abduction, and adduction against resistance in sequence as a complete strengthening circuit for the entire hip.'},
{id:'h47',cat:'Hip',name:'Seated Figure-4 Stretch with Forward Lean',pos:'Seated in chair',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit in a chair and cross one ankle over the opposite knee. Keeping your back straight, lean your trunk forward from the hips until you feel a stretch in the outer hip and buttock of the crossed leg. Hold, then switch sides.'},
{id:'h48',cat:'Hip',name:'4-Way Hip with Band',pos:'Standing',sets:3,reps:'15 each direction',hold:'2 sec',freq:'Daily',instr:'Anchor a resistance band at ankle height. With the band around one ankle, perform hip flexion (kick forward), extension (kick back), abduction (lift out to side), and adduction (pull across body) against resistance in sequence. Complete all four directions on one leg before switching. Use a support for balance.'},
{id:'h49',cat:'Hip',name:'3-Way Hip with Band',pos:'Standing',sets:3,reps:'15 each direction',hold:'2 sec',freq:'Daily',instr:'Anchor a resistance band at ankle height. Perform three directions against resistance: hip flexion (kick forward), abduction (lift out to side), and extension (kick back). Complete all three on one leg then switch. A focused hip stability circuit commonly used in knee and hip rehab.'},
{id:'h50',cat:'Hip',name:'Side Steps with Band',pos:'Standing',sets:3,reps:'15 steps each way',hold:'—',freq:'Daily',instr:'Place a resistance band around both ankles. Stand with feet hip-width apart and a slight bend in the knees. Step sideways in a controlled manner, maintaining tension in the band at all times and keeping toes pointed forward. Take the prescribed number of steps in one direction then return. Avoid letting the feet come together completely.'},
// EXTRA CORE (l55-l56, 2)
{id:'l55',cat:'Core & Lumbar',name:'Standing Resisted Trunk Extension',pos:'Standing',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Anchor a band low behind you. Hold the handles at your shoulders and gently extend your trunk backward against resistance in a small, controlled motion, then return to upright.'},
{id:'l56',cat:'Core & Lumbar',name:'Quadruped Diagonal Reach (No Lift)',pos:'Quadruped',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'From hands and knees, reach one hand forward and diagonally while keeping it on the floor, sliding it out to challenge the core without fully lifting the limb. A gentler progression toward the full bird dog exercise.'},
{id:'l57',cat:'Core & Lumbar',name:'Bridge with Ball Squeeze',pos:'Supine, knees bent',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Lie on your back with knees bent and a small ball or rolled towel placed between your knees. Squeeze the ball gently to activate the inner thighs, then press through your heels to lift your hips into a bridge. Hold at the top while maintaining the squeeze, then lower slowly. The ball cue helps activate the adductors and provides feedback for hip alignment.'},
// EXTRA KNEE (k45-k46, 2)
{id:'k45',cat:'Knee',name:'Standing Resisted Knee Flexion (Single Leg, No Band)',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Stand holding a support. Bend one knee, bringing the heel toward the buttock using just the resistance of gravity and the hamstring muscle. Lower slowly with control. Switch legs.'},
{id:'k46',cat:'Knee',name:'Seated Knee Extension Isometric Hold',pos:'Seated',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Sit with the leg extended straight out in front. Tighten the quad fully and hold the straight-leg position steady against gravity for the prescribed time, then relax.'},
{id:'k47',cat:'Knee',name:'Long Arc Quad',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with your back supported. Starting with the knee bent at 90 degrees, straighten the knee fully until the leg is parallel to the floor. Hold briefly at the top, then lower slowly back to the start. Keep the motion smooth and controlled throughout.'},
{id:'k48',cat:'Knee',name:'Mini Squat',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand with feet shoulder-width apart and a light hand on a support for balance if needed. Bend the knees to approximately 30-45 degrees, keeping the knees aligned over the toes and the chest upright. Return to standing. This is a controlled, shallow squat used early in knee rehab.'},
{id:'a41',cat:'Ankle & Foot',name:'Standing Resisted Ankle Dorsiflexion (Single Leg, No Band)',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Stand on one leg holding a support. Lift your toes upward toward your shin as far as comfortable using just the muscles of the shin, hold briefly, then lower with control. Switch legs.'},
// CERVICAL (c36-c50, 15)
{id:'c36',cat:'Cervical',name:'Cervical Proprioception Retraining',pos:'Seated',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Place a laser pointer or sticker on your forehead. Fix your gaze on a target on the wall, close your eyes, slowly rotate your head, then return to neutral and open your eyes to check accuracy. Retrains the cervical joint position sense often disrupted after whiplash or chronic neck pain.'},
{id:'c37',cat:'Cervical',name:'Cervical Unilateral PA Mobilization Self-Technique',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Place your thumb on the side of a specific neck vertebra as directed by your therapist. Apply a gentle, oscillating forward pressure while keeping the neck relaxed. A self-mobilization technique to restore segmental cervical motion.'},
{id:'c38',cat:'Cervical',name:'Shoulder Blade Squeeze for Neck Posture',pos:'Seated or standing',sets:3,reps:'15',hold:'5 sec',freq:'2x/day',instr:'Sit or stand tall. Gently draw both shoulder blades back and down together, as if trying to hold a pencil between them. Hold, then relax. Directly addresses the forward head and rounded shoulder posture commonly contributing to neck pain.'},
{id:'c39',cat:'Cervical',name:'Neck Rotation with Overpressure (Unilateral)',pos:'Seated',sets:3,reps:'5 each side',hold:'10 sec',freq:'Daily',instr:'Rotate your head to one side as far as comfortable. Place your hand on your chin and gently add a small additional rotational overpressure. Hold, then return to neutral. Use light pressure only. Switch sides.'},
{id:'c40',cat:'Cervical',name:'Upper Cervical Flexion (Nodding)',pos:'Supine',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Lie on your back with a small pillow under your head. Gently nod your chin toward your chest in a small motion, as if saying yes very slightly. Hold, then relax. Targets the upper cervical flexors (C0-C2) specifically.'},
{id:'c41',cat:'Cervical',name:'Cervical Traction in Flexion (Self)',pos:'Supine',sets:1,reps:'—',hold:'5-10 min',freq:'Daily',instr:'Lie on your back with a rolled towel under your neck. Gently tuck your chin and allow your head to rest in a slightly flexed position, creating a gentle stretch through the posterior cervical structures. Often used for facet-related neck pain.'},
{id:'c42',cat:'Cervical',name:'Cervical SNAG Self-Technique (Sustained Natural Apophyseal Glide)',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Using a towel or strap placed around a specific cervical level, apply a gentle forward glide at that level while performing the painful or restricted movement. Based on the Mulligan concept. Only perform as specifically directed by your therapist for your level.'},
{id:'c43',cat:'Cervical',name:'Postural Taping Awareness Exercise',pos:'Standing',sets:1,reps:'—',hold:'Throughout the day',freq:'Daily',instr:'With postural taping applied by your therapist, practice holding the taped corrected posture throughout the day. The tape provides sensory feedback when posture deviates. Focus on chin tuck and shoulder blade retraction.'},
{id:'c44',cat:'Cervical',name:'Cervical Rotation Strengthening (Isometric Against Towel)',pos:'Seated',sets:3,reps:'10 each side',hold:'5 sec',freq:'Daily',instr:'Loop a towel around the back of your head and hold both ends in front. Gently attempt to rotate your head to one side against the resistance of the towel without allowing movement. Hold, relax. Repeat to the other side.'},
{id:'c45',cat:'Cervical',name:'Cervical Lateral Flexion Strengthening (Isometric Against Towel)',pos:'Seated',sets:3,reps:'10 each side',hold:'5 sec',freq:'Daily',instr:'Loop a towel around the side of your head and hold the ends to that same side. Gently attempt to side bend your head toward the towel against its resistance without allowing movement. Hold, relax. Repeat on the other side.'},
{id:'c46',cat:'Cervical',name:'Thoracic Inlet Stretch',pos:'Seated or standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Tilt your head to one side then look toward the ceiling slightly, feeling a stretch along the front of the neck and into the chest. A useful stretch for the scalene muscles and thoracic outlet region, often used in thoracic outlet syndrome management.'},
{id:'c47',cat:'Cervical',name:'Standing Shoulder Retraction and Chin Tuck Combined',pos:'Standing',sets:3,reps:'15',hold:'5 sec',freq:'2x/day',instr:'Stand tall. Simultaneously draw your chin back in a chin tuck while squeezing your shoulder blades together and down. Hold both positions at the same time. A combined postural correction commonly prescribed for forward head posture with rounded shoulders.'},
{id:'c48',cat:'Cervical',name:'Cervical Flexion Endurance in Sitting',pos:'Seated',sets:3,reps:'—',hold:'15-30 sec',freq:'Daily',instr:'Sit tall without back support. Gently perform a chin tuck and hold the corrected cervical neutral position as long as possible without allowing the head to drift forward. A functional endurance exercise for sustained head control during seated tasks.'},
{id:'c49',cat:'Cervical',name:'First Rib Mobilization Stretch',pos:'Seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit on your hand on the affected side. Tilt your head away and slightly forward, adding gentle overpressure with the other hand, to stretch the scalene muscles and mobilize the first rib. Used for thoracic outlet syndrome and rib hypomobility. Follow specific guidance from your therapist.'},
{id:'c50',cat:'Cervical',name:'Cervical Rotation with Gaze (VOR Combined)',pos:'Seated',sets:3,reps:'20',hold:'—',freq:'Daily',instr:'Hold a target card at arm\'s length. Rotate your head and eyes together in one direction while keeping the target card in view by moving it in the opposite direction. A combined cervical and vestibulo-ocular exercise often used for post-concussion or whiplash vestibular rehabilitation.'},
// SHOULDER (s65-s82, 18)
{id:'s65',cat:'Shoulder',name:'Closed Kinetic Chain Shoulder Exercise (Wall)',pos:'Standing facing wall',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand facing a wall with your hand flat against it at shoulder height. Perform small push-up motions with the arm straight, keeping the shoulder blade stable throughout. Weight-bearing through the arm builds co-contraction stability, useful early after rotator cuff or labral surgery.'},
{id:'s66',cat:'Shoulder',name:'Shoulder Distraction Stretch',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Hold a light weight in the affected hand and let the arm hang relaxed at your side. Lean slightly away to allow the weight to gently distract the shoulder joint downward. Hold and breathe. Used for shoulder impingement and adhesive capsulitis to improve inferior capsule mobility.'},
{id:'s67',cat:'Shoulder',name:'Inferior Capsule Stretch (Sleeper Position)',pos:'Side-lying',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on the affected side with the shoulder forward and elbow bent 90 degrees. Use the top hand to gently press the wrist downward toward the floor, stretching the posterior and inferior capsule. Used for GIRD and internal rotation deficit in overhead athletes.'},
{id:'s68',cat:'Shoulder',name:'Theraband ER with Pivot (90/90 Position)',pos:'Standing',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Stand with the arm abducted to 90 degrees and elbow bent 90 degrees, holding a band. Rotate the forearm backward so the hand moves upward, then return. This 90/90 position is specific to overhead athletes returning to throwing or serving. Only use when cleared for this load.'},
{id:'s69',cat:'Shoulder',name:'Posterior Shoulder Capsule Stretch (Corner Stretch)',pos:'Standing in corner',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand facing a corner with forearms on each wall at shoulder height. Lean your chest forward into the corner, feeling a stretch across the chest and front of both shoulders. Adjust arm height for a different portion of the pec minor and anterior capsule.'},
{id:'s70',cat:'Shoulder',name:'Scapular Winging Correction Exercise',pos:'Quadruped or wall',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'From hands and knees or a wall push-up position, focus on preventing the shoulder blade from winging off the ribcage at the end of the movement. At the top of the push-up, perform the "plus" protraction to fully seat the blade. Addresses serratus anterior weakness causing scapular winging.'},
{id:'s71',cat:'Shoulder',name:'Rotator Cuff Interval Training',pos:'Standing',sets:1,reps:'As prescribed',hold:'—',freq:'As directed',instr:'Perform your prescribed rotator cuff exercises in intervals of increasing duration and resistance, following a specific interval progression chart provided by your therapist. Used for systematic loading in tendinopathy rehabilitation.'},
{id:'s72',cat:'Shoulder',name:'Shoulder IR Stretch (Behind Back)',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Reach your affected arm behind your back as if tucking in a shirt. Use a towel or strap held by the other hand over the shoulder to gently pull the affected arm further upward. Feel a stretch in the front of the shoulder and biceps. Improves internal rotation range of motion.'},
{id:'s73',cat:'Shoulder',name:'Weighted Pendulum',pos:'Standing, leaning forward',sets:3,reps:'20 circles each direction',hold:'—',freq:'Daily',instr:'Hold a light weight in the affected hand. Lean forward with the other arm resting on a support. Allow the weighted arm to hang and use body momentum to create gentle circles, first small then larger. The weight provides gentle inferior distraction while gravity assists mobility.'},
{id:'s74',cat:'Shoulder',name:'Sidelying Shoulder ER Stretch',pos:'Side-lying',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Lie on the unaffected side. Hold the affected arm with elbow bent 90 degrees and the elbow at shoulder height. Use the other hand to gently press the wrist forward and downward, stretching into external rotation. Used for posterior capsule tightness.'},
{id:'s75',cat:'Shoulder',name:'Inferior Glide Mobilization (Self)',pos:'Supine',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Lie on your back. Place a strap around the upper arm just below the shoulder. Anchor the strap low and gently traction the arm in an inferior direction while relaxing the shoulder. Improves inferior capsule mobility limited in adhesive capsulitis.'},
{id:'s76',cat:'Shoulder',name:'Shoulder Circumduction Active',pos:'Standing',sets:2,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Stand with the arm hanging loosely. Make large, slow, controlled circles with the entire arm, first forward then backward. Keep the motion pain-free and gradually increase the size of the circles as range of motion improves.'},
{id:'s77',cat:'Shoulder',name:'Prone Serratus Punch',pos:'Prone on bench',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down on a bench with the arm hanging. Raise the arm to 90 degrees of flexion (thumbs up), then at the top further protrude the shoulder forward off the bench, seating the blade. Hold, then lower slowly. A challenging serratus and lower trap combined exercise.'},
{id:'s78',cat:'Shoulder',name:'Posterior Capsule Self-Mobilization (Cross-Arm)',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Bring the affected arm across your chest with elbow at shoulder height. Use the opposite hand to apply an additional horizontal force at the elbow, gliding the humeral head posteriorly. Hold briefly. Used in Mulligan and Maitland approaches for posterior capsule hypomobility.'},
{id:'s79',cat:'Shoulder',name:'Rhythmic Stabilization at 90 Degrees Flexion',pos:'Supine or standing, arm held at 90',sets:3,reps:'30 sec',hold:'—',freq:'Daily',instr:'Hold the arm at 90 degrees of flexion with the elbow straight. A partner or therapist applies alternating perturbations (forward/back, left/right, rotations) while you resist without moving. Builds neuromuscular co-contraction stability in the functional position for many daily activities.'},
{id:'s80',cat:'Shoulder',name:'Subscapularis Stretch (Hand Behind Back Progression)',pos:'Standing',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Place the back of the affected hand against the small of your back. Gently move the hand upward along the spine as far as comfortable without pain. Use the other hand or a towel to assist lifting. Targets subscapularis and anterior capsule specifically.'},
{id:'s81',cat:'Shoulder',name:'AC Joint Protection Exercise',pos:'Seated or standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Focus on keeping the shoulder blade depressed and retracted while performing arm movements within the prescribed range. Avoid crossing the arm past neutral horizontal adduction. Used to protect the acromioclavicular joint following AC joint injury or separation.'},
{id:'s82',cat:'Shoulder',name:'Overhead Throwing Program Phase 1 (Short Toss)',pos:'Standing',sets:1,reps:'As per program schedule',hold:'—',freq:'As prescribed',instr:'Perform the initial phase of an interval throwing program as directed by your therapist, typically starting at 30-45 feet with a gentle, flat throw. Progress through each phase only when pain-free and as cleared by your therapist and physician.'},
// ELBOW & WRIST (e45-e60, 16)
{id:'e45',cat:'Elbow & Wrist',name:'Lateral Epicondyle Friction Massage (Self)',pos:'Seated',sets:1,reps:'3-5 min',hold:'—',freq:'Daily',instr:'Using your thumb or fingers, apply firm cross-friction massage directly across the lateral epicondyle and proximal wrist extensor tendons, perpendicular to the fiber direction. Used alongside eccentric exercises for lateral epicondylalgia (tennis elbow). Expect mild discomfort during the technique.'},
{id:'e46',cat:'Elbow & Wrist',name:'Medial Epicondyle Friction Massage (Self)',pos:'Seated',sets:1,reps:'3-5 min',hold:'—',freq:'Daily',instr:'Apply cross-friction massage to the medial epicondyle and proximal wrist flexor tendons. Used alongside eccentric exercises for medial epicondylalgia (golfers elbow). Apply firm, controlled pressure perpendicular to the tendon fibers.'},
{id:'e47',cat:'Elbow & Wrist',name:'Elbow Valgus Stress Control Exercise',pos:'Seated or standing',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Using a light dumbbell or band, perform controlled wrist flexion while keeping the elbow in slight flexion, working the UCL-supporting musculature (wrist flexors and pronators). Used in rehabilitation of UCL injury in overhead athletes.'},
{id:'e48',cat:'Elbow & Wrist',name:'Supination Strengthening with Hammer',pos:'Seated, elbow at 90',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a hammer at the base of the handle with your elbow bent to 90 degrees and your arm resting on a table, thumb facing up. Rotate the hammer so the head moves upward (supination). Slowly return. The offset weight of the hammer increases resistance at end range.'},
{id:'e49',cat:'Elbow & Wrist',name:'Pronation Strengthening with Hammer',pos:'Seated, elbow at 90',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a hammer at the base of the handle with your elbow bent to 90 degrees and your arm resting on a table, thumb facing up. Rotate the hammer so the head moves downward (pronation). Slowly return. The offset weight of the hammer provides progressive resistance at end range.'},
{id:'e50',cat:'Elbow & Wrist',name:'Elbow Flexion Stretch (Table)',pos:'Standing at table',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand at a table with your arm extended and the back of the wrist resting on the table surface. Gently lean away to encourage the elbow into further extension, feeling a stretch in the front of the elbow. Used to restore elbow extension after fracture or surgery.'},
{id:'e51',cat:'Elbow & Wrist',name:'Cubital Tunnel Nerve Glide (Ulnar Nerve)',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Sit with your arm at your side. Start with the elbow straight and wrist extended. Slowly bend the elbow fully while simultaneously flexing the wrist and fingers, then return. This glides the ulnar nerve through the cubital tunnel. Stop if symptoms spread significantly. Used for cubital tunnel syndrome.'},
{id:'e52',cat:'Elbow & Wrist',name:'Radial Tunnel Nerve Glide',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Sit with the arm at your side. Straighten the elbow, pronate the forearm, flex the wrist, and tilt the head away from the arm simultaneously. Hold, then return. Mobilizes the radial nerve through the radial tunnel. Used for lateral forearm pain and radial tunnel syndrome.'},
{id:'e53',cat:'Elbow & Wrist',name:'Wrist Extension Strengthening with Soup Can',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest the forearm on a table, palm down, holding a soup can or similar light weight. Raise the back of the hand upward against gravity. Lower slowly. A convenient home exercise for wrist extensor strengthening using common household items.'},
{id:'e54',cat:'Elbow & Wrist',name:'Three-Jaw Chuck Pinch Strengthening',pos:'Seated',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Pinch therapy putty or a small object between the pad of the thumb and the pads of both the index and middle fingers simultaneously (three-jaw chuck or tripod pinch). Hold the pinch and then release fully. A critical pinch pattern for many functional hand activities.'},
{id:'e55',cat:'Elbow & Wrist',name:'Lateral Pinch Strengthening',pos:'Seated',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Pinch therapy putty between the thumb pad and the side of the index finger (key pinch or lateral pinch). Hold firmly and release. This is the pinch pattern used for turning a key, opening a jar lid, or holding a card.'},
{id:'e56',cat:'Elbow & Wrist',name:'Hook Fist Exercise',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Begin with fingers fully extended. Bend only the middle and tip joints of your fingers downward while keeping the knuckles straight, forming a hook shape. Hold, then fully extend. Specifically glides the flexor digitorum superficialis tendon relative to the profundus. Used after hand surgery or tendon repair.'},
{id:'e57',cat:'Elbow & Wrist',name:'Intrinsic Plus Position Hold',pos:'Seated',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Hold the fingers with the knuckles (MCP joints) fully bent and the finger joints (IP joints) fully straight simultaneously. This is the intrinsic plus or safe position. Maintaining this position during immobilization prevents intrinsic tightness. Also used as an active exercise for intrinsic muscle strengthening.'},
{id:'e58',cat:'Elbow & Wrist',name:'Extensor Tendon Glide',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Start with fingers straight. Move through a sequence of positions: tabletop (MCP bent, IP straight), straight fist (all joints bent, fingernails touching palm), full fist (fingers fully curled), then hook fist (MCP straight, IP bent). Each position glides a different portion of the extensor mechanism.'},
{id:'e59',cat:'Elbow & Wrist',name:'Wrist Mobilization (Radiocarpal Glide Self)',pos:'Seated',sets:3,reps:'10 each direction',hold:'3 sec',freq:'Daily',instr:'Stabilize the forearm with one hand. Use the other hand to gently glide the entire wrist forward (volar), backward (dorsal), and sideways in a slow, oscillating motion. Used to restore wrist range of motion after fracture, sprain, or prolonged immobilization.'},
{id:'e60',cat:'Elbow & Wrist',name:'Shoulder-Elbow-Wrist Integrated Nerve Glide (Median)',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Sit with the arm at your side. Sequentially straighten the elbow while externally rotating the shoulder, extending the wrist and fingers, then tilt the head away. Hold, then reverse. A full upper extremity median nerve mobilization technique. Used for carpal tunnel, pronator syndrome, and cervical radiculopathy.'},
// CORE & LUMBAR (l58-l72, 15)
{id:'l58',cat:'Core & Lumbar',name:'McKenzie Repeated Extension in Prone (DP Exercise)',pos:'Prone',sets:1,reps:'10',hold:'—',freq:'Every 2 hrs',instr:'Lie face down with hands under shoulders. Press up slowly and fully into extension, allowing the low back to arch and the hips to remain on the surface. Return completely to flat after each repetition. Used as a directional preference exercise for patients who benefit from extension loading.'},
{id:'l59',cat:'Core & Lumbar',name:'McKenzie Repeated Flexion in Standing',pos:'Standing',sets:1,reps:'10',hold:'—',freq:'Every 2 hrs',instr:'Stand with feet shoulder-width apart. Bend forward at the waist as far as comfortable, reaching hands toward the floor. Return to standing. Used as a directional preference exercise for patients who respond to flexion loading. Only perform if prescribed specifically for your presentation.'},
{id:'l60',cat:'Core & Lumbar',name:'Lumbar Lateral Shift Correction',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Every 2 hrs',instr:'Stand with feet shoulder-width apart. If you have a lateral shift (your trunk leans to one side), gently push your hips in the opposite direction to correct the shift, then hold the corrected posture. Often performed alongside repeated extension exercises. Follow your therapist\'s specific guidance for your shift direction.'},
{id:'l61',cat:'Core & Lumbar',name:'Prone Lumbar Decompression (Press-Up with Belt)',pos:'Prone',sets:3,reps:'—',hold:'5-10 min',freq:'Daily',instr:'Lie face down and prop up on forearms. Place a traction belt or strap around the pelvis, anchored to something stable at the foot of the bed, to provide gentle lumbar traction in the prone extended position. A self-traction technique for lumbar disc decompression.'},
{id:'l62',cat:'Core & Lumbar',name:'Hip Flexor Strengthening in Standing',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Stand holding a support. Lift one knee up toward hip height against a light resistance band anchored below, or simply against gravity. Lower slowly. Hip flexor weakness is commonly seen with lumbar instability and after hip surgery or prolonged sitting.'},
{id:'l63',cat:'Core & Lumbar',name:'Trunk Side Bridge (Full)',pos:'Side-lying, straight body',sets:3,reps:'—',hold:'15-30 sec',freq:'Daily',instr:'Lie on your side fully supported on one forearm and the side of one foot, with the body forming a straight line. Hold the position without letting the hips sag or rise. A more demanding version of the modified side plank used in later-stage core stabilization programs.'},
{id:'l64',cat:'Core & Lumbar',name:'Standing Extension with Theraband',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band overhead in front of you. Pull both handles down to your waist while extending through the lower back and squeezing the glutes at the bottom. Slowly return. Combines lumbar extension with lat and glute activation in a functional standing position.'},
{id:'l65',cat:'Core & Lumbar',name:'Lumbar Stabilization with Perturbation',pos:'Supine, knees bent',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Lie on your back with knees bent and core braced. A partner gently and unexpectedly pushes one knee or the pelvis, and you resist the perturbation without losing your neutral spine position. Trains reactive core stability.'},
{id:'l66',cat:'Core & Lumbar',name:'Quadruped Thoracolumbar Control (No Movement)',pos:'Quadruped',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Hold a hands-and-knees position with the spine perfectly neutral, neither arching nor rounding. Focus on the deep breathing while maintaining this neutral position. A fundamental prerequisite for all quadruped exercises, often skipped but important for patients with lumbar instability.'},
{id:'l67',cat:'Core & Lumbar',name:'Supine Lumbar Rotation Stretch',pos:'Supine, knees bent',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Lie on your back with knees bent and feet flat. Let both knees fall slowly to one side while keeping both shoulders on the floor. Hold the stretch in the low back and hip. Return and repeat to the other side. A gentle lumbar rotation stretch often prescribed for lumbar stiffness.'},
{id:'l68',cat:'Core & Lumbar',name:'Sit-Up with Trunk Rotation',pos:'Supine, knees bent',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Lie on your back with knees bent and hands behind your head. Perform a partial sit-up, rotating one elbow toward the opposite knee at the top. Lower slowly. Targets the oblique abdominals. Only use when appropriate for the patient\'s diagnosis.'},
{id:'l69',cat:'Core & Lumbar',name:'Roman Chair Back Extension',pos:'Prone on back extension bench',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Position yourself face down on a back extension bench with hips at the edge and feet secured. Cross arms over chest or place hands behind head. Lower your trunk downward, then lift it back to horizontal. Do not hyperextend past parallel. Strengthens the lumbar extensors and glutes under load.'},
{id:'l70',cat:'Core & Lumbar',name:'Good Morning Exercise (Bodyweight)',pos:'Standing',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Stand with feet shoulder-width apart and hands behind your head. With a slight knee bend and a neutral spine, hinge forward at the hips until your trunk is roughly parallel to the floor, then return to upright. Teaches the hip hinge pattern and strengthens the lumbar and hip extensors together.'},
{id:'l71',cat:'Core & Lumbar',name:'Quadratus Lumborum Strengthening (Side Plank Variant)',pos:'Side-lying',sets:3,reps:'—',hold:'15-30 sec each side',freq:'Daily',instr:'Lie on your side with knees bent. Lift your hips off the floor to form a straight line from head to knees. Focus on contracting the muscles along the side of the low back (quadratus lumborum) rather than just the hip abductors. Hold, then lower.'},
{id:'l72',cat:'Core & Lumbar',name:'Lumbar SNAG in Flexion (Self with Belt)',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Place a belt or strap around a specific lumbar segment. Apply a forward glide force at that level while bending forward to perform the restricted movement. Based on the Mulligan SNAG technique. Only perform at the specific level and direction directed by your therapist.'},
// HIP (h51-h63, 13)
{id:'h51',cat:'Hip',name:'Hip Labral Loading Exercise',pos:'Standing',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Stand on one leg with a slight forward lean of the trunk. Hold briefly, focusing on deep hip stability without gripping or excessive muscle activation. Progress from bilateral to unilateral and add light perturbations. Used in labral tear rehabilitation to load the hip in a controlled manner.'},
{id:'h52',cat:'Hip',name:'Hip Scour Test Position Stretch',pos:'Supine',sets:3,reps:'3',hold:'20-30 sec',freq:'Daily',instr:'Lie on your back. Bring one knee to the chest, then direct it toward the opposite shoulder and gently add a compressive force through the knee. Circle the hip in a figure-8 pattern. Used both diagnostically and therapeutically for hip joint mobility.'},
{id:'h53',cat:'Hip',name:'Thomas Stretch (Hip Flexor)',pos:'Supine at edge of table',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on your back at the edge of a bed or table with both knees pulled to your chest. Lower one leg downward off the edge, letting it hang. Feel a stretch at the front of the hip of the lowered leg. Hold, then raise it back. A classic hip flexor stretch isolating the iliopsoas.'},
{id:'h54',cat:'Hip',name:'Hip Abductor Isometric Against Wall',pos:'Side-lying against wall',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Lie on your side with the affected leg on top, pressing the top foot firmly into a wall. Push upward against the wall without moving. Hold, then relax. A low-load isometric for early-stage gluteus medius activation when dynamic exercises are too painful or demanding.'},
{id:'h55',cat:'Hip',name:'Standing Hip Abductor Wall Press',pos:'Standing beside wall',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Stand sideways next to a wall with the outside of the affected leg against it. Press the leg outward into the wall without moving. Hold, then relax. A functional standing isometric for the hip abductors useful when dynamic lateral movements are restricted.'},
{id:'h56',cat:'Hip',name:'Piriformis Strengthening',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your side with hips at 60 degrees flexion and knees slightly bent. Rotate the top hip externally (lifting the foot away from the other foot) against light resistance, keeping the knees together. A specific exercise targeting the piriformis as a hip external rotator.'},
{id:'h57',cat:'Hip',name:'Hip Flexor Eccentric Lowering',pos:'Standing at step',sets:3,reps:'12 each leg',hold:'—',freq:'Daily',instr:'Stand on a step. Use both legs to lift the knee up, then lower it slowly back down over a count of 4 seconds on the affected leg only. The slow eccentric lowering specifically loads the hip flexor tendon. Used for psoas tendinopathy.'},
{id:'h58',cat:'Hip',name:'Lateral Band Walk with Forward Lean',pos:'Standing in forward lean',sets:3,reps:'15 steps each direction',hold:'—',freq:'Daily',instr:'Place a band around the ankles. Adopt a slight forward lean at the hips (athletic position). Walk laterally in a controlled manner, maintaining the forward lean and band tension. The lean shifts emphasis from the gluteus medius to the posterior fibers and gluteus maximus.'},
{id:'h59',cat:'Hip',name:'Hip Extension with Knee Flexion (Kickback)',pos:'Standing or quadruped',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand holding a support or position on hands and knees. Extend the hip while simultaneously bending the knee to 90 degrees, lifting the heel toward the ceiling. This position targets the gluteus maximus in relative isolation from the hamstrings, since the hamstrings are shortened at the knee.'},
{id:'h60',cat:'Hip',name:'Hip Thrust (Weighted)',pos:'Supine, upper back on bench',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Rest your upper back across a bench or elevated surface. Drive through both heels to lift the hips into full extension, squeezing the glutes at the top. Hold, then lower slowly. Add resistance as tolerated. A high-load glute exercise commonly used in late-stage hip and knee rehab.'},
{id:'h61',cat:'Hip',name:'Hip IR Stretch (Prone)',pos:'Prone, knee bent 90',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie face down with one knee bent to 90 degrees. Let the foot fall outward away from the body, rotating the hip inward. Gently press the foot further outward for a deeper internal rotation stretch. Used for reduced hip IR range, often seen with hip impingement or osteoarthritis.'},
{id:'h62',cat:'Hip',name:'Hip ER Stretch (Prone)',pos:'Prone, knee bent 90',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie face down with one knee bent to 90 degrees. Let the foot fall inward across the body, rotating the hip outward. Gently press the foot further inward for a deeper external rotation stretch. Used for hip ER restriction.'},
{id:'h63',cat:'Hip',name:'Gluteal Amnesia Re-Activation (McGill)',pos:'Standing',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Stand with feet hip-width apart and knees slightly bent. Without moving the hip, squeeze the glutes as hard as possible. Hold. Relax completely. This isolated squeeze technique, described by Dr. Stuart McGill, is used to re-engage inhibited glutes in patients with chronic low back pain.'},
// KNEE (k49-k62, 14)
{id:'k49',cat:'Knee',name:'Patellar Tendon Isometric Load',pos:'Seated, knee at 60 degrees',sets:5,reps:'1',hold:'45 sec',freq:'Daily',instr:'Sit with the knee bent to approximately 60 degrees. Press the shin against a fixed surface and hold a strong quad contraction at that angle for 45 seconds. Research supports isometric loading at this angle for immediate pain relief in patellar tendinopathy. Use 70-80% of maximum effort.'},
{id:'k50',cat:'Knee',name:'Patellar Tendon Heavy-Slow Resistance (Leg Press Variant)',pos:'Leg press machine',sets:4,reps:'8-15',hold:'3 sec',freq:'3x/week',instr:'Perform slow leg press repetitions over a 3-second concentric and 3-second eccentric count. Use a load that makes the prescribed reps challenging. Heavy-slow resistance has the strongest evidence base for patellar tendinopathy loading in PT practice.'},
{id:'k51',cat:'Knee',name:'Patellofemoral Taping for Exercise',pos:'Supine or standing',sets:1,reps:'—',hold:'During exercise',freq:'Daily',instr:'Apply patellofemoral taping as specifically directed by your therapist (McConnell technique), medially gliding and tilting the patella before exercise. The tape reduces patellofemoral pain during exercise and allows higher-quality loading in patellofemoral pain syndrome.'},
{id:'k52',cat:'Knee',name:'Knee OA Land-Based Exercise Program',pos:'Varies',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Perform your prescribed program of quadriceps strengthening, hip strengthening, balance, and aerobic exercise as directed, following the guidelines for knee osteoarthritis. Land-based exercise is a Grade A recommended treatment for knee OA.'},
{id:'k53',cat:'Knee',name:'Blood Flow Restriction Quad Strengthening (BFR)',pos:'Seated or supine',sets:4,reps:'30/15/15/15',hold:'—',freq:'2-3x/week',instr:'With a cuff applied proximal to the knee at the prescribed restriction pressure, perform leg extensions or quad sets at 20-30% of your maximum effort in the prescribed rep scheme (typically 30 reps, rest 30 sec, then three sets of 15). BFR allows muscle strengthening with very light loads, used post-surgically. Only under therapist supervision.'},
{id:'k54',cat:'Knee',name:'Seated Knee Flexion PROM with Gravity',pos:'Seated, leg hanging',sets:3,reps:'—',hold:'1-2 min',freq:'Several times daily',instr:'Sit on the edge of a table with the leg hanging freely. Allow gravity to gently increase knee flexion as the muscles relax, or use the other foot to gently press the ankle further. Hold for a prolonged stretch to improve knee flexion range. Often used immediately post-op.'},
{id:'k55',cat:'Knee',name:'Prone Hang for Knee Extension',pos:'Prone, leg hanging off table edge',sets:3,reps:'—',hold:'5-10 min',freq:'2-3x/day',instr:'Lie face down with the knee hanging off the edge of a table. Allow gravity to gradually extend the knee. Add a small ankle weight to increase the gentle stretch into extension. Used to restore knee extension range after ACL reconstruction or total knee replacement.'},
{id:'k56',cat:'Knee',name:'Stair Master or Step Mill Walking',pos:'Standing on stair machine',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Walk on a stair climbing machine at a comfortable, low pace. Stair training in a controlled manner builds quad and glute strength functionally, improves endurance, and is commonly used in the mid to late stages of knee rehabilitation.'},
{id:'k57',cat:'Knee',name:'Slide Board Lateral Slides',pos:'Standing on slide board',sets:3,reps:'1-2 min',hold:'—',freq:'Daily',instr:'Stand on a slide board with socks or booties. Push off one foot to slide to the other end, then push back. Maintains a slight squat position throughout. Builds lateral quad strength, hip stability, and aerobic conditioning in a low-impact sliding motion.'},
{id:'k58',cat:'Knee',name:'Pool Walking (Aquatic Therapy)',pos:'Standing in pool',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Walk forward, backward, and sideways in chest- or waist-deep water, allowing the buoyancy to reduce joint loading while still providing resistance for strengthening. A mainstay of early-stage knee rehabilitation when land-based loading is too painful.'},
{id:'k59',cat:'Knee',name:'T-Test Agility Drill',pos:'Standing, open space',sets:3,reps:'3 trials',hold:'—',freq:'2-3x/week',instr:'Set up four cones in a T-shape. Sprint forward to the center cone, shuffle left to the far cone, shuffle right across to the other far cone, shuffle back to center, then backpedal to the start. A standard return-to-sport agility assessment and drill for the knee.'},
{id:'k60',cat:'Knee',name:'ACL Return to Sport Hop Battery',pos:'Standing',sets:1,reps:'3 each test',hold:'—',freq:'Weekly to assess',instr:'Perform the four-hop test battery: single-leg hop for distance, triple hop, crossover triple hop, and 6-meter timed hop. Compare the affected to the unaffected leg to calculate a limb symmetry index. Used to guide return-to-sport decisions after ACL reconstruction.'},
{id:'k61',cat:'Knee',name:'Knee Flexion Isometric Wall Hold',pos:'Standing against wall',sets:5,reps:'—',hold:'30-45 sec',freq:'Daily',instr:'Stand with your back against a wall and feet about 18 inches out. Slide down to a position where the knee is at the prescribed angle (often 60-90 degrees) and hold, squeezing the quad. An isometric quad strengthening technique commonly used for knee pain management.'},
{id:'k62',cat:'Knee',name:'TKE with Hip Abduction Combined',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band behind the knee while also placing a band around both ankles. Perform a terminal knee extension while simultaneously abducting the hip slightly against the ankle band. Combines quad activation with hip abductor co-contraction, used for patellofemoral and ACL rehab.'},
// ANKLE & FOOT (a42-a54, 13)
{id:'a42',cat:'Ankle & Foot',name:'Achilles Tendon Heavy-Slow Resistance',pos:'Standing on step',sets:4,reps:'15',hold:'3 sec each phase',freq:'3x/week',instr:'Perform a double or single-leg calf raise using a 3-second concentric (rise) and 3-second eccentric (lower) tempo over the full range. Use a step to achieve the bottom range. Heavy-slow resistance is the leading evidence-based approach for Achilles tendinopathy loading.'},
{id:'a43',cat:'Ankle & Foot',name:'Achilles Tendon Isometric Calf Press',pos:'Standing',sets:5,reps:'—',hold:'45 sec',freq:'Daily',instr:'Stand and press both heels firmly into the floor or against a fixed surface at approximately 20-30 degrees of plantarflexion. Hold a strong isometric calf contraction. Isometric loading at this angle has shown immediate pain-reducing effects for Achilles tendinopathy.'},
{id:'a44',cat:'Ankle & Foot',name:'Plantar Fascia Night Stretch (Towel)',pos:'Supine, in bed',sets:1,reps:'1-2',hold:'5-10 min',freq:'Each morning before first steps',instr:'Before taking your first steps in the morning, loop a towel around the foot and pull the toes toward the shin, holding the plantar fascia on stretch. This prevents the shock of load after overnight shortening of the fascia, the primary cause of first-step morning pain in plantar fasciitis.'},
{id:'a45',cat:'Ankle & Foot',name:'Intrinsic Foot Doming (Short Foot Exercise - SFE)',pos:'Seated or standing',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Sit with the foot flat. Without curling the toes, shorten the foot by drawing the ball of the foot toward the heel, creating an arch dome. Hold, then relax. Specifically activates the intrinsic foot muscles (abductor hallucis, flexor digitorum brevis) that support the arch. A key exercise for flat foot and plantar fasciitis.'},
{id:'a46',cat:'Ankle & Foot',name:'Ankle Sprain Protocol - Phase 1 RICE and Pumps',pos:'Supine, elevated',sets:1,reps:'Ongoing',hold:'—',freq:'Continuously',instr:'In the acute phase following ankle sprain: rest the ankle, apply ice for 15-20 minutes every 2-3 hours, use compression with an ACE wrap or brace, and elevate the limb above heart level. Perform gentle ankle pumps hourly to reduce swelling.'},
{id:'a47',cat:'Ankle & Foot',name:'Ankle Inversion Sprain Phase 2 - BAPS Board',pos:'Standing on BAPS board',sets:3,reps:'20 circles each direction',hold:'—',freq:'Daily',instr:'Stand on a biomechanical ankle platform system (BAPS board). Perform controlled circles with the ankle in all directions, using the foot to guide the board. Progresses proprioception and controlled range of motion after ankle sprain. Begin with seated and progress to standing.'},
{id:'a48',cat:'Ankle & Foot',name:'Fibularis Longus Strengthening (Peroneal)',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit with a band anchored to the same side, looped around the outside of the foot. Evert and plantarflex the foot simultaneously against resistance, mimicking the primary function of fibularis longus. Critical muscle for lateral ankle stability after inversion sprain.'},
{id:'a49',cat:'Ankle & Foot',name:'Tibialis Posterior Strengthening',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit with a band looped around the inside of the foot and anchored to the opposite side. Invert and plantarflex the foot simultaneously against resistance. Targets the tibialis posterior specifically, a key muscle for medial arch support and prevention of flat foot progression.'},
{id:'a50',cat:'Ankle & Foot',name:'Windlass Mechanism Exercise',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on the affected foot with the big toe extended upward. Rise onto your toes while keeping the big toe extended. This activates the windlass mechanism of the plantar fascia, which tensions the arch. Used in plantar fasciitis and flat foot rehabilitation.'},
{id:'a51',cat:'Ankle & Foot',name:'Single-Leg Balance with Perturbations',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand on one leg while a partner provides unexpected light perturbations to the body from different directions. Resist each perturbation while maintaining single-leg stance. An advanced reactive balance exercise for ankle sprain and ankle instability rehabilitation.'},
{id:'a52',cat:'Ankle & Foot',name:'Aquatic Running (Pool Running)',pos:'Deep water with flotation belt',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Wearing a flotation belt, perform a running motion in deep water where feet do not touch the bottom. Maintains cardiovascular fitness and movement patterns during non-weight-bearing periods of lower extremity rehabilitation.'},
{id:'a53',cat:'Ankle & Foot',name:'Tibialis Anterior Eccentric Training',pos:'Standing on step edge',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand on a step with just the toes on the edge, heels hanging off. Rise onto tiptoes with both feet, then transfer to the affected foot only and slowly lower the foot below the step level, controlling the dorsiflexion eccentrically over a 4-second count. Targets tibialis anterior for shin splints and foot drop.'},
{id:'a54',cat:'Ankle & Foot',name:'Ankle Proprioception - Cone Picks with Single Leg',pos:'Standing',sets:3,reps:'8 each leg',hold:'—',freq:'Daily',instr:'Stand on one leg. Bend down and pick up a small cone from the floor in front of you, then place it to one side, then behind you, maintaining single-leg balance throughout. An advanced dynamic balance and proprioception exercise mimicking functional activities.'},
// BALANCE & FUNCTIONAL (b35-b43, 9)
{id:'b35',cat:'Balance & Functional',name:'Perturbation Training on Rocker Board',pos:'Standing on rocker board',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand on a rocker or wobble board. Practice maintaining balance as the board tips, actively resisting perturbations and correcting your position. Progress from bilateral to unilateral stance and from expected to unexpected perturbations.'},
{id:'b36',cat:'Balance & Functional',name:'Standing Hip Strategy Practice with Eyes Closed',pos:'Standing',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Stand with feet together and eyes closed. When balance is challenged, practice using primarily the hips (lateral sway of the trunk) rather than the ankles to recover balance. The hip strategy is used for larger perturbations and becomes important when ankle range or strength is limited.'},
{id:'b37',cat:'Balance & Functional',name:'Weight Bearing Symmetry Training (Dual Scale)',pos:'Standing on two scales',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand with one foot on each bathroom scale. Practice distributing your weight evenly between both feet, achieving 50/50 body weight on each scale. Used post-surgically or after injury when patients habitually avoid loading the affected limb.'},
{id:'b38',cat:'Balance & Functional',name:'Four Square Step Test',pos:'Standing in four-square formation',sets:3,reps:'2 trials',hold:'—',freq:'Weekly to track progress',instr:'Step clockwise then counterclockwise through four squares marked on the floor (or taped grid). Count the time to complete. A validated clinical balance assessment and training drill used particularly in fall prevention programs.'},
{id:'b39',cat:'Balance & Functional',name:'Timed Up and Go Practice (TUG)',pos:'Seated in chair',sets:3,reps:'3 trials',hold:'—',freq:'Daily',instr:'Sit in a standard chair. On the command, stand up, walk 3 meters at a comfortable pace, turn around, walk back, and sit down. Time the trial. TUG is a key clinical outcome measure for functional mobility and fall risk. Practice to improve performance.'},
{id:'b40',cat:'Balance & Functional',name:'Step Over Obstacles with Single-Leg Stance',pos:'Standing',sets:3,reps:'10 steps',hold:'2 sec',freq:'Daily',instr:'Walk through a course of small obstacles arranged in a line. As you step over each obstacle, pause briefly in single-leg stance before placing the foot down on the other side. Builds dynamic balance and controlled weight transfer.'},
{id:'b41',cat:'Balance & Functional',name:'Narrow Walking with Head Turns',pos:'Standing, walking in narrow corridor',sets:3,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Walk in a narrow hallway or along a taped line on the floor while turning your head from side to side every few steps. Challenges divided attention and gaze stability during functional walking, a common scenario that falls often occur.'},
{id:'b42',cat:'Balance & Functional',name:'Floor Descent and Return (Get Up from Floor)',pos:'Standing to floor to standing',sets:3,reps:'3',hold:'—',freq:'Daily',instr:'Practice safely lowering yourself to the floor using controlled steps and hands for support, then returning to standing independently. A critical functional skill for older adults or post-surgical patients, directly addressing a common fear after a fall or surgery.'},
{id:'b43',cat:'Balance & Functional',name:'Vestibular Rehabilitation Walking Program',pos:'Walking',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Walk in progressively challenging environments: first in a quiet hallway, then with head turns, then in a more visually stimulating or crowded environment. A graduated vestibular and balance rehabilitation walking progression for dizziness and imbalance.'},
// THORACIC (t26-t35, 10)
{id:'t26',cat:'Thoracic',name:'Thoracic Mobility Spine Roll',pos:'Supine on floor',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Lie on your back with knees bent. Systematically roll onto one side and back, allowing the thoracic spine to mobilize segment by segment. A gentle global thoracic mobility exercise often used as a warm-up.'},
{id:'t27',cat:'Thoracic',name:'Rib Expansion Breathing (3D)',pos:'Seated or standing',sets:3,reps:'10',hold:'3 sec',freq:'2x/day',instr:'Take a deep breath in, consciously expanding your ribcage in all three dimensions: upward, sideways, and into the back. Hold at full expansion, then slowly exhale. This three-dimensional breathing mobilizes the costovertebral joints and is used for thoracic stiffness and post-surgical respiratory care.'},
{id:'t28',cat:'Thoracic',name:'Thoracic Extension Over Chair Back',pos:'Seated in chair',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Sit in a chair and place a folded towel over the top of the chair back. Lean back so that the chair back contacts your mid-thoracic spine. Extend backward over the chair back. Hold, then return upright. An accessible way to mobilize the thoracic spine without equipment.'},
{id:'t29',cat:'Thoracic',name:'Thoracic SNAG in Extension (Self)',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Using a towel or belt placed horizontally around a specific thoracic level, apply a forward glide at that segment while performing thoracic extension. Based on the Mulligan SNAG technique applied to the thoracic spine. Follow your therapist\'s specific level guidance.'},
{id:'t30',cat:'Thoracic',name:'Intercostal Muscle Stretch',pos:'Seated or standing',sets:3,reps:'3 each side',hold:'30 sec',freq:'Daily',instr:'Reach one arm fully overhead, then side bend your trunk away from that arm while taking a deep breath. Feel a stretch along the entire side of the ribcage between the ribs. Used for rib mobility restrictions, post-surgical thoracic stiffness, or musculoskeletal chest pain.'},
{id:'t31',cat:'Thoracic',name:'Prone Cobra',pos:'Prone',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down with arms at your sides. Lift your head, chest, and arms off the floor simultaneously while drawing the shoulder blades down and together. Your palms face inward or backward and your thumbs point upward. Hold briefly, then lower slowly. Strengthens the thoracic extensors and lower trapezius together.'},
{id:'t32',cat:'Thoracic',name:'Band Pull Apart',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a resistance band or dowel in front of you at shoulder height with both hands shoulder-width apart. Pull the band or rod apart, moving both hands outward and backward until the band touches your chest. Squeeze the shoulder blades together at end range. An excellent upper thoracic and scapular retractor exercise.'},
{id:'t33',cat:'Thoracic',name:'Sidelying Thoracic Rotation with Arm Reach',pos:'Side-lying',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'Lie on your side with hips and knees bent to 90 degrees and arms stacked in front of you at shoulder height. Rotate only the top arm up and back toward the floor, rotating through the mid-back and following your hand with your gaze. Return slowly. Switch sides.'},
{id:'t34',cat:'Thoracic',name:'Quadruped Thoracic Segmental Extension',pos:'Quadruped',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'On hands and knees, focus extension at one specific thoracic level rather than the whole spine. Create a hump at that level, then extend specifically at that segment. A controlled, segmental thoracic mobility technique used when global mobility exercises are insufficient.'},
{id:'t35',cat:'Thoracic',name:'Serratus Anterior Punches in Supine',pos:'Supine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with both arms pointing straight up toward the ceiling. Punch one arm further upward by protracting the shoulder blade off the mat while keeping the elbow straight. Alternate sides. Targets serratus anterior in a gravity-assisted position, useful when push-up variations are too difficult.'},
// POST-OP & GENERAL (p29-p38, 10)
{id:'p29',cat:'Post-Op & General',name:'CPM Machine Use (Continuous Passive Motion)',pos:'Supine in machine',sets:1,reps:'—',hold:'1-6 hrs/day as prescribed',freq:'Daily post-surgically',instr:'Position the limb in the continuous passive motion machine as instructed by your therapist. Set the range of motion and speed as prescribed. The machine moves the joint through a controlled arc passively, maintaining mobility and reducing adhesion formation in the early post-surgical period.'},
{id:'p30',cat:'Post-Op & General',name:'Non-Weight Bearing Ambulation with Crutches',pos:'Standing with crutches',sets:1,reps:'As tolerated',hold:'—',freq:'Daily',instr:'Bear no weight on the affected limb as instructed. Position crutches to the side and slightly forward. Push down through both crutches simultaneously as you swing the body forward. Keep the affected foot off the ground throughout. Use stairs with "up with the good, down with the crutch" guidance.'},
{id:'p31',cat:'Post-Op & General',name:'Toe Touch Weight Bearing Progression',pos:'Standing with assistive device',sets:1,reps:'—',hold:'—',freq:'Daily',instr:'Lightly touch the toes or foot of the affected limb to the floor for balance only, bearing the equivalent of about 10-15 pounds of body weight (roughly the weight of the limb itself). Progress as directed by your surgeon toward partial then full weight bearing.'},
{id:'p32',cat:'Post-Op & General',name:'Post-Surgical Edema Elevation Protocol',pos:'Supine',sets:1,reps:'—',hold:'As much as possible when resting',freq:'Throughout day',instr:'Keep the surgical limb elevated above the level of the heart whenever resting, using pillows or an elevated support surface. Maintain neutral alignment of the limb. Do not place a pillow directly under the knee if knee extension is a goal, as this can create a flexion contracture.'},
{id:'p33',cat:'Post-Op & General',name:'TENS Unit Application for Pain Management',pos:'Supine or seated',sets:1,reps:'—',hold:'20-30 min',freq:'As needed for pain',instr:'Place the TENS electrode pads at the sites directed by your therapist (around the painful area or at dermatome-appropriate locations). Set the frequency and intensity to the comfortable tingling sensation without pain or muscle contraction. Do not use on broken skin, near the heart, or during pregnancy without clearance.'},
{id:'p34',cat:'Post-Op & General',name:'Ultrasound Therapy (Supervised)',pos:'As positioned by therapist',sets:1,reps:'—',hold:'5-10 min',freq:'As prescribed',instr:'Therapeutic ultrasound is applied by your therapist to the target tissue using a sound head moved in slow circular strokes over a coupling gel. Used for tissue healing acceleration, scar tissue management, and pain modulation. Follow your therapist\'s specific protocol.'},
{id:'p35',cat:'Post-Op & General',name:'Electrical Muscle Stimulation (EMS) for Quad',pos:'Supine or seated',sets:3,reps:'10',hold:'10 sec on, 10 sec off',freq:'Daily',instr:'Electrodes are placed over the quadriceps muscle belly. The EMS device delivers a current that causes an involuntary quad contraction. Used to prevent or treat quad atrophy after surgery. Often combined with a voluntary quad contraction attempt (volitional overlay).'},
{id:'p36',cat:'Post-Op & General',name:'Wound Care and Dressing Change Preparation',pos:'Supine or seated',sets:1,reps:'Daily',hold:'—',freq:'Daily',instr:'Follow your surgeon\'s and therapist\'s specific instructions for surgical wound care. Typically involves gentle cleansing with appropriate solutions, monitoring for signs of infection (increased redness, warmth, swelling, discharge, or fever), and proper redressing. Report any concerns to your healthcare team promptly.'},
{id:'p37',cat:'Post-Op & General',name:'Post-Surgical Shoulder Pendulum (Phase 1)',pos:'Standing, leaning forward',sets:3,reps:'20 circles each direction',hold:'—',freq:'3-5x/day',instr:'Lean forward with the non-surgical arm supported on a table. Allow the surgical arm to hang completely relaxed. Use small body movements to create gentle pendulum circles in both directions. The arm moves by momentum only, not shoulder muscle contraction. Usually the first exercise after shoulder surgery.'},
{id:'p38',cat:'Post-Op & General',name:'Sling Weaning Protocol',pos:'Seated or standing',sets:1,reps:'—',hold:'Increasing time out of sling',freq:'Daily progress',instr:'Following your therapist\'s and surgeon\'s schedule, gradually increase the amount of time the affected arm spends out of the sling each day, allowing it to rest comfortably at the side. Never use the sling to substitute for exercises. Progress to full-time out of sling when tolerated.'},
// NEURO & VESTIBULAR (n21-n30, 10)
{id:'n21',cat:'Neuro & Vestibular',name:'Canalith Repositioning (Epley Maneuver - Self)',pos:'Seated then supine',sets:1,reps:'1-3 per session',hold:'30 sec each position',freq:'As directed',instr:'Sit on a bed. Turn your head 45 degrees toward the affected ear. Quickly lie back with the head hanging off the bed at 45 degrees. Hold 30 seconds. Turn the head 90 degrees to the other side without raising it. Hold 30 seconds. Roll onto the same side the head is turned, then return to sitting. A self-Epley maneuver for BPPV of the posterior canal. Only perform as directed by your therapist after proper diagnosis.'},
{id:'n22',cat:'Neuro & Vestibular',name:'Half Somersault Maneuver (Foster)',pos:'Kneeling to supine',sets:1,reps:'1-3 per session',hold:'30 sec each position',freq:'As directed',instr:'Kneel and quickly tilt your head back to look at the ceiling. Bring your head nose-down toward the floor, then turn 45 degrees toward the affected ear. With the head in this position, roll it upward toward the ceiling quickly. Slowly return to kneeling. An alternative to the Epley for posterior canal BPPV that some patients find easier to self-perform.'},
{id:'n23',cat:'Neuro & Vestibular',name:'Horizontal Canal BPPV Roll Test Exercise',pos:'Supine',sets:1,reps:'As directed',hold:'Until nystagmus stops',freq:'As directed',instr:'Lie flat on your back. Turn your head 90 degrees to one side and hold until any dizziness settles, then turn 90 degrees to the other side. Continue in a barrel-roll fashion until dizziness resolves. Used for horizontal canal BPPV when correctly diagnosed.'},
{id:'n24',cat:'Neuro & Vestibular',name:'Walking Tandem with Head Turns',pos:'Walking in tandem',sets:3,reps:'10 steps',hold:'—',freq:'Daily',instr:'Walk in a tandem heel-to-toe line while simultaneously turning your head from side to side every two steps. Combines the balance challenge of tandem walking with active vestibular-visual integration, used in intermediate vestibular rehabilitation.'},
{id:'n25',cat:'Neuro & Vestibular',name:'Sensory Organization Training',pos:'Standing on varied surfaces',sets:3,reps:'—',hold:'30 sec each condition',freq:'Daily',instr:'Systematically vary three sensory conditions: surface (firm to foam) and vision (eyes open, eyes closed, or visual conflict dome). Work through all six Sensory Organization Test conditions systematically. This isolates and trains each sensory system contributing to balance.'},
{id:'n26',cat:'Neuro & Vestibular',name:'Constraint-Induced Movement Therapy (CIMT) Tasks',pos:'Seated at table',sets:1,reps:'2-6 hrs/day as prescribed',hold:'—',freq:'Daily',instr:'With the unaffected arm constrained in a mitt or sling, perform intensive functional tasks using only the affected upper extremity as directed by your therapist. Used for arm rehabilitation following stroke. Tasks are progressed in difficulty using shaping techniques.'},
{id:'n27',cat:'Neuro & Vestibular',name:'Task-Specific Walking with Obstacles (Post-Stroke)',pos:'Walking',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Walk through a course of varied obstacles, surfaces, and directions, simulating real-world walking challenges. Task-specific, high-repetition walking practice is the most evidence-supported intervention for improving walking speed and independence after stroke.'},
{id:'n28',cat:'Neuro & Vestibular',name:'Functional Electrical Stimulation (FES) for Drop Foot',pos:'Walking with FES device',sets:1,reps:'During walking sessions',hold:'—',freq:'Daily',instr:'Wear the FES device with electrodes over the common peroneal nerve or the tibialis anterior. The device triggers dorsiflexion during the swing phase of walking via a heel sensor. Used for foot drop following stroke, spinal cord injury, or multiple sclerosis to normalize gait.'},
{id:'n29',cat:'Neuro & Vestibular',name:'Dual-Task Treadmill Walking (Post-Neurological)',pos:'Standing on treadmill',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Walk on a treadmill at a slow, safe speed while simultaneously performing a cognitive task such as counting backward, naming words by category, or answering questions. Improves the ability to walk safely while engaging in conversations or other real-world cognitive demands.'},
{id:'n30',cat:'Neuro & Vestibular',name:'Body Weight Supported Treadmill Training (BWSTT)',pos:'Standing in treadmill harness',sets:1,reps:'20-30 min',hold:'—',freq:'Daily',instr:'With a percentage of body weight supported by an overhead harness, walk on a treadmill at a functional pace with therapist-assisted stepping as needed. Allows high-repetition stepping practice before independent weight bearing is possible. Used in spinal cord injury, stroke, and severe neurological conditions.'},
// SPORT-SPECIFIC & PLYOMETRIC (sp15-sp25, 11)
{id:'sp15',cat:'Sport-Specific & Plyometric',name:'Lateral Shuffle',pos:'Standing',sets:3,reps:'20 sec',hold:'—',freq:'2-3x/week',instr:'In an athletic low position with knees bent and weight forward, shuffle rapidly side to side over a short distance without crossing feet. Builds lateral quickness and the hip abductor-knee alignment control needed for court and field sports.'},
{id:'sp16',cat:'Sport-Specific & Plyometric',name:'Cone Drill - 5-10-5 (Pro Agility)',pos:'Standing',sets:3,reps:'3 each direction',hold:'—',freq:'2-3x/week',instr:'Place three cones five yards apart in a line. Start at the middle cone. Sprint five yards to one side, touch the cone, sprint ten yards to the far side, touch, then sprint five yards back through the start. Time the drill to track improvement. A standard return-to-sport agility benchmark.'},
{id:'sp17',cat:'Sport-Specific & Plyometric',name:'Plyometric Lateral Barrier Jumps',pos:'Standing beside low barrier',sets:3,reps:'12 each direction',hold:'—',freq:'2-3x/week',instr:'Stand beside a low hurdle or line on the floor. Jump laterally over the barrier, land softly, immediately rebound back to the starting side. Minimize ground contact time. Builds lateral explosive power and reactive landing mechanics.'},
{id:'sp18',cat:'Sport-Specific & Plyometric',name:'Single-Leg Lateral Hop',pos:'Standing',sets:3,reps:'10 each leg',hold:'2 sec land',freq:'2-3x/week',instr:'Stand on one leg. Hop sideways onto the same leg, landing with a slight knee bend and controlled balance. Hold the landing briefly, then hop back. Builds single-leg lateral power and is a key late-stage ACL and ankle rehab exercise.'},
{id:'sp19',cat:'Sport-Specific & Plyometric',name:'Medicine Ball Chest Pass with Step',pos:'Standing',sets:3,reps:'12 each side',hold:'—',freq:'2-3x/week',instr:'Hold a medicine ball at chest height. Step toward a wall or partner with one foot and explosively push the ball forward. Catch the return and repeat on the other side. Builds upper extremity power in a functional stepping pattern used in throwing and racket sports.'},
{id:'sp20',cat:'Sport-Specific & Plyometric',name:'Overhead Medicine Ball Slam',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'Hold a medicine ball overhead with both hands. Forcefully slam it into the floor, following through with the whole body. Catch or retrieve the ball and repeat. Builds total-body power and is used for upper extremity and core strength in late-stage sports rehab.'},
{id:'sp21',cat:'Sport-Specific & Plyometric',name:'Running Mechanics Drills - High Knees',pos:'Standing, running',sets:3,reps:'20 meters',hold:'—',freq:'2-3x/week',instr:'Run forward driving the knees up to hip height with each step, maintaining a tall posture and quick arm swing. Focus on the quality of each knee drive rather than maximum speed. A fundamental drill used in return-to-running programs to reinforce proper mechanics.'},
{id:'sp22',cat:'Sport-Specific & Plyometric',name:'Running Mechanics Drills - Butt Kicks',pos:'Standing, running',sets:3,reps:'20 meters',hold:'—',freq:'2-3x/week',instr:'Run forward flexing the knee rapidly to bring the heel to the buttock with each step, maintaining an upright posture. Trains hamstring flexibility and cycling mechanics used in distance running gait. A standard return-to-running drill.'},
{id:'sp23',cat:'Sport-Specific & Plyometric',name:'Return to Running Walk-Jog Intervals',pos:'Walking and jogging',sets:1,reps:'As per schedule',hold:'—',freq:'As prescribed',instr:'Follow your prescribed return-to-running interval program, typically starting with a walk-jog ratio such as 1 minute jog, 1 minute walk for 20 minutes, and progressively reducing the walking intervals as tolerated. Only progress when the current level is consistently pain-free.'},
{id:'sp24',cat:'Sport-Specific & Plyometric',name:'Y-Balance Test (YBT) Training',pos:'Standing on one leg',sets:3,reps:'4 each direction',hold:'—',freq:'Daily',instr:'Stand on one leg. Reach the opposite foot as far as possible in three directions: anterior, posteromedial, and posterolateral. Touch the foot lightly and return to center after each reach without losing balance. Used both as a functional movement screen and a dynamic balance training exercise.'},
{id:'sp25',cat:'Sport-Specific & Plyometric',name:'Plyometric Push-Up Progression',pos:'Prone',sets:3,reps:'8',hold:'—',freq:'2-3x/week',instr:'Starting from a standard push-up, progress through variations: incline push-up, floor push-up, push-up with clap, push-up with two claps. Each level increases the power demand on the upper extremity. Used in return-to-sport programs for sports involving upper extremity weight-bearing and throwing.'},
// PELVIC FLOOR & WOMEN'S HEALTH (pf13-pf20, 8)
{id:'pf13',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Drop and Release',pos:'Seated',sets:3,reps:'10',hold:'5 sec release',freq:'Daily',instr:'Sit comfortably and focus on consciously releasing and letting the pelvic floor muscles drop downward, like opening a flower. Hold the released position for several seconds before gently returning to neutral. Important for hypertonic pelvic floor conditions or pelvic pain where relaxation is the goal rather than contraction.'},
{id:'pf14',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Strengthening in Standing',pos:'Standing',sets:3,reps:'10',hold:'5-10 sec',freq:'Daily',instr:'Stand with feet hip-width apart. Perform pelvic floor contractions (Kegels) in the standing position, which more closely simulates the functional demand of standing activities. A progression from supine or seated Kegel exercises.'},
{id:'pf15',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Strengthening During Activity (Functional Kegel)',pos:'Varies',sets:1,reps:'Throughout activity',hold:'—',freq:'During at-risk activities',instr:'Practice contracting the pelvic floor during activities that challenge it, such as coughing, lifting, or transitioning from sit to stand. This trains the timing and coordination of the pelvic floor response needed for continence during real functional demands.'},
{id:'pf16',cat:'Pelvic Floor & Womens Health',name:'Postpartum Pelvic Floor Progressive Loading',pos:'Supine progressing to standing',sets:3,reps:'10',hold:'Increasing duration',freq:'Daily',instr:'Begin with gentle resting tone contractions in supine. Progress over 6-12 weeks through increasingly loaded positions: supine, seated, standing, during walking, and during impact activity. A structured postpartum pelvic floor rehabilitation progression.'},
{id:'pf17',cat:'Pelvic Floor & Womens Health',name:'Hip External Rotator Strengthening for Pelvic Floor',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your side with hips slightly flexed. Perform clamshell exercises focusing on hip external rotation. The hip external rotators share fascial connections with the pelvic floor and are commonly addressed together in pelvic floor rehabilitation.'},
{id:'pf18',cat:'Pelvic Floor & Womens Health',name:'Supine Core Activation with Pelvic Floor (Abdominal Draw)',pos:'Supine, knees bent',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Lie on your back with knees bent. Simultaneously perform a gentle pelvic floor contraction and a gentle lower abdominal drawing-in maneuver (hollowing). Hold the combined contraction while breathing normally. Trains the co-activation of the pelvic floor and transverse abdominis commonly disrupted after childbirth.'},
{id:'pf19',cat:'Pelvic Floor & Womens Health',name:'Return to Running Post-Partum Checklist',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Pre-running clearance',instr:'Before returning to running after childbirth, confirm ability to: walk 30 minutes without pain or leakage, jog in place for 1 minute without symptoms, hop on each leg 10 times without symptoms, and perform 10 single-leg bridges each side. Use this functional checklist as a minimum standard before resuming impact activity.'},
{id:'pf20',cat:'Pelvic Floor & Womens Health',name:'Pelvic Girdle Pain Exercise Program',pos:'Supine and standing',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Perform your prescribed program of inner unit activation (pelvic floor, transverse abdominis), gentle hip strengthening, and pain-free walking. Avoid activities that cause asymmetrical pelvic loading such as single-leg stance for extended periods, stair climbing one step at a time, or asymmetrical sitting. Pelvic girdle pain is common during and after pregnancy.'},
// AMPUTEE & PROSTHETIC (amp10-amp16, 7)
{id:'amp10',cat:'Amputee & Prosthetic',name:'Prosthetic Gait Training - Heel Strike Pattern',pos:'Standing, walking',sets:1,reps:'2-5 min',hold:'—',freq:'Daily',instr:'Focus specifically on making contact with the prosthetic heel first during each step, rather than the foot flat or toe. Practice with slow, deliberate steps in a controlled environment with a therapist present. The heel-strike pattern is a key component of a normal prosthetic gait pattern.'},
{id:'amp11',cat:'Amputee & Prosthetic',name:'Prosthetic Stance Phase Control Drill',pos:'Standing',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand with weight fully on the prosthetic side. Hold steady balance on the prosthesis while the intact limb performs small controlled movements. Builds confidence and balance control during the stance phase of gait.'},
{id:'amp12',cat:'Amputee & Prosthetic',name:'Prosthetic Stair Negotiation',pos:'Standing at staircase',sets:3,reps:'1 flight',hold:'—',freq:'Daily',instr:'Practice ascending and descending stairs with the prosthesis under therapist supervision. Begin step-over-step as tolerance and prosthetic control develop. Use the handrail initially for safety.'},
{id:'amp13',cat:'Amputee & Prosthetic',name:'Prosthetic Running and Sport Preparation',pos:'Open space',sets:1,reps:'As tolerated',hold:'—',freq:'As directed',instr:'Under therapist guidance, progress through walking to jogging to running activities with the appropriate running prosthesis. Follow a structured progression that allows the residual limb to adapt to the increased impact demands of running prosthetics.'},
{id:'amp14',cat:'Amputee & Prosthetic',name:'Upper Extremity Prosthetic Terminal Device Training',pos:'Seated at table',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Practice opening and closing the terminal device (hook or hand) to grasp, hold, release, and manipulate objects of varied sizes and weights, as directed by your therapist. Builds the myoelectric or body-powered prosthetic control needed for functional hand use.'},
{id:'amp15',cat:'Amputee & Prosthetic',name:'Residual Limb Core Strengthening (Transtibial)',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'For a below-knee amputation, focus on knee flexion and extension strengthening of the residual limb through its available range. Strong knee musculature is critical for controlling the prosthesis and for absorbing gait forces.'},
{id:'amp16',cat:'Amputee & Prosthetic',name:'Myoelectric Signal Training (EMG Biofeedback)',pos:'Seated with biofeedback device',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Using a biofeedback device on the residual limb muscles, practice generating and controlling the myoelectric signals that will control a myoelectric prosthesis. Isolated, graded muscle activations of the target muscles are trained using visual or auditory feedback.'},
// PEDIATRIC (peds16-peds23, 8)
{id:'peds16',cat:'Pediatric',name:'Strengthening Through Play - Wall Pushes',pos:'Standing facing wall',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Have the child stand facing a wall and practice pushing against it with both hands, playing a game of "pushing the wall down." Builds upper extremity and core strength in a fun, non-threatening way that doesn\'t feel like exercise.'},
{id:'peds17',cat:'Pediatric',name:'Pediatric Balance Board Game',pos:'Standing on balance board',sets:1,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Have the child stand on a wobble board and play a catching or tossing game with a ball while maintaining balance. Combines balance challenge with a motivating play activity that maintains engagement.'},
{id:'peds18',cat:'Pediatric',name:'Scooter Board Prone Propulsion',pos:'Prone on scooter board',sets:1,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Have the child lie face down on a scooter board and propel themselves using both hands on the floor. Builds shoulder girdle and core extensor strength, proprioception, and bilateral coordination in an engaging play activity.'},
{id:'peds19',cat:'Pediatric',name:'Pediatric Torticollis Stretching',pos:'Supine',sets:3,reps:'10-20',hold:'10-30 sec',freq:'3-5x/day',instr:'Gently rotate the infant\'s head toward the tight side and tilt it away from the tight side to stretch the shortened sternocleidomastoid. Perform slowly and hold as tolerated. The frequency and specific technique should be taught directly by a trained pediatric physical therapist and must be adapted to the child\'s age and tolerance.'},
{id:'peds20',cat:'Pediatric',name:'Pediatric Gait Training with Reverse Walker',pos:'Standing, walking',sets:1,reps:'5-20 min',hold:'—',freq:'Daily',instr:'Have the child use a posterior (reverse) walker for upright gait training. The posterior walker promotes a more upright trunk posture than an anterior walker and is commonly used in pediatric CP, MMC, and other pediatric gait disorders.'},
{id:'peds21',cat:'Pediatric',name:'Pediatric Hippotherapy (Horse-Back Exercise) Preparation',pos:'Seated',sets:1,reps:'5-10 min',hold:'—',freq:'As prescribed',instr:'Practice the seated position and weight shifts on a therapy barrel or bolster in preparation for hippotherapy. The rhythmic movement of a horse closely replicates the pelvic motion of human walking and is used for tone management, posture, and core strengthening in pediatric populations.'},
{id:'peds22',cat:'Pediatric',name:'Pediatric Aquatic Therapy',pos:'In pool',sets:1,reps:'30-45 min',hold:'—',freq:'As prescribed',instr:'Perform prescribed water-based activities including floating, kicking, ball games, and walking in water under close therapist supervision. Buoyancy reduces the demands of gravitational loading, allowing movement practice in children who cannot perform equivalent activities on land.'},
{id:'peds23',cat:'Pediatric',name:'Pediatric Proprioceptive Training (Jumping on Trampoline)',pos:'Standing on mini trampoline',sets:1,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Have the child perform controlled bouncing and jumping activities on a small supervised trampoline. Builds joint proprioception, vestibular processing, and lower extremity strength while providing strong sensory input that many children with developmental conditions respond well to.'},
// TMJ (j16-j20, 5)
{id:'j16',cat:'TMJ',name:'Jaw Stabilization Exercise (Resistance)',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Perform gentle resisted jaw opening, closing, and lateral movements simultaneously while stabilizing the jaw with your hand, as directed by your therapist. Builds coordinated strength around the temporomandibular joint from multiple directions.'},
{id:'j17',cat:'TMJ',name:'Mandibular Repositioning Training',pos:'Seated, in front of mirror',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Using a mirror for feedback, practice moving the mandible to a specific resting position prescribed by your dentist or therapist that reduces joint loading. Hold the position, then relax. Used when bite position contributes to TMJ symptoms.'},
{id:'j18',cat:'TMJ',name:'Hyoid Bone Mobilization',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Gently grasp the hyoid bone (the U-shaped bone in the throat) between the thumb and fingers and perform very gentle side-to-side mobilizations. Used for restricted or painful swallowing related to cervical and jaw dysfunction. Only perform if specifically instructed by your therapist.'},
{id:'j19',cat:'TMJ',name:'Masticatory Muscle Stretching',pos:'Seated',sets:3,reps:'3',hold:'20-30 sec',freq:'Daily',instr:'Gently open the mouth as wide as comfortable. Use the thumb inside the upper teeth and the fingers under the lower teeth to very gently add a small additional opening stretch. Hold. Used for limited mouth opening due to masticatory muscle tightness (trismus).'},
{id:'j20',cat:'TMJ',name:'Diaphragmatic Breathing for TMJ Relaxation',pos:'Supine or seated',sets:3,reps:'10 breaths',hold:'—',freq:'Daily and during stress',instr:'Practice slow, deep belly breathing while consciously releasing jaw clenching and facial muscle tension with each exhale. Jaw clenching is closely associated with stress and altered breathing patterns. This exercise directly addresses the systemic tension that drives many TMJ symptoms.'},
// CERVICAL (c51-c58, 8)
{id:'c51',cat:'Cervical',name:'Cervical Flexion with Chin Tuck on Foam Roll',pos:'Supine over foam roll',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Lie on your back with a foam roll placed horizontally under the thoracic spine. Allow the head to rest backward gently. Perform chin tucks in this position, which opens the posterior cervical spine in a gravity-assisted way. A gentle cervical and upper thoracic stretch combined.'},
{id:'c52',cat:'Cervical',name:'Craniocervical Flexion Exercise (Stage 1)',pos:'Supine',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Lie on your back. Gently perform a small nodding motion (upper cervical flexion only), as if saying yes with only the very top of your neck. Hold without recruiting the superficial neck muscles. A foundational exercise for deep cervical flexor activation, the first stage of the CCF protocol.'},
{id:'c53',cat:'Cervical',name:'Cervical Nerve Tension Test Self-Mobilization',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Sit tall and side-bend your head away from the symptomatic arm. Simultaneously move the symptomatic arm downward and flex the elbow and wrist to slacken the nerve, then straighten the elbow. This flossing movement mobilizes the cervical nerve roots. Use only as directed by your therapist.'},
{id:'c54',cat:'Cervical',name:'Thoracic Outlet Self-Stretch (Pec Minor)',pos:'Standing in doorway',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand in a doorway with the forearm against the door frame at 90 degrees of shoulder abduction. Step forward through the doorway until you feel a stretch across the front of the chest and into the shoulder. Used for thoracic outlet syndrome and pec minor shortening contributing to neck and shoulder symptoms.'},
{id:'c55',cat:'Cervical',name:'Cervical Extension Strengthening (Prone)',pos:'Prone on forearms',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Lie face down propped on forearms. Lift your head against gravity into extension, keeping the movement controlled and the neck long rather than compressing. Hold, then lower slowly. Directly strengthens the cervical extensor muscles, often undertrained compared to flexors.'},
{id:'c56',cat:'Cervical',name:'Cervical Rotation AROM in Supine',pos:'Supine',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Lie on your back without a pillow or with a very thin one. Rotate your head from side to side slowly through the full available range. Gravity-assisted rotation in supine is often more comfortable than seated for patients with acute neck pain or post-surgical restrictions.'},
{id:'c57',cat:'Cervical',name:'Cervical Side Bend Strengthening (Sidelying)',pos:'Side-lying',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Lie on your side with the head resting on the arm. Lift your head away from the surface by side-bending the neck against gravity. Lower slowly. Strengthens the lateral cervical flexors and scalenes in a functional position.'},
{id:'c58',cat:'Cervical',name:'Posterior Cervical Soft Tissue Mobilization (Self)',pos:'Supine',sets:1,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Lie on your back with a tennis ball or massage ball placed under a specific area of the posterior cervical musculature. Allow gravity to create pressure into the muscle. Breathe and allow the muscle to release over 60-90 seconds before moving to the next spot. A self-myofascial release technique for posterior neck tension.'},
// SHOULDER (s83-s92, 10)
{id:'s83',cat:'Shoulder',name:'Codman Pendulum Progression (Active)',pos:'Standing, leaning forward',sets:3,reps:'20 each direction',hold:'—',freq:'Daily',instr:'Progress from passive pendulum to an active version where you initiate small shoulder circles under control using the rotator cuff muscles. Keep the movement small and controlled. Marks the transition from passive to active shoulder mobility work.'},
{id:'s84',cat:'Shoulder',name:'Shoulder ER/IR ROM at 90 Abduction (Full Arc)',pos:'Supine',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Lie on your back with the arm abducted to 90 degrees and elbow bent 90 degrees, resting on a surface. Lower the forearm toward the floor (ER) then raise it past vertical into IR. Move through the full available rotation arc slowly and without compensation.'},
{id:'s85',cat:'Shoulder',name:'Overhead Stretch with PNF Contract-Relax',pos:'Supine',sets:3,reps:'5',hold:'10 sec contract, 20 sec stretch',freq:'Daily',instr:'Lie on your back and reach the arm overhead as far as comfortable. Hold a gentle 5-second isometric contraction at end range against your own other hand, then relax and try to reach further overhead. The post-contraction relaxation often gains additional range. A PNF technique for overhead mobility restriction.'},
{id:'s86',cat:'Shoulder',name:'Shoulder Flexion Active-Assisted with Stick',pos:'Supine',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Lie on your back holding a stick with both hands. Use the non-affected arm to assist the affected arm in moving through shoulder flexion (overhead) as tolerated. Lower slowly under the affected arm\'s own control. A standard early AAROM technique after shoulder surgery or immobilization.'},
{id:'s87',cat:'Shoulder',name:'Rotator Cuff Eccentric Strengthening (ER)',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Hold a light band with the elbow bent at 90 degrees and externally rotated to start. Use both hands to return to the internally rotated starting position, then remove the assisting hand and control the return to ER with only the affected arm, slowing the motion over 3-4 seconds. Eccentric loading is particularly useful for rotator cuff tendinopathy.'},
{id:'s88',cat:'Shoulder',name:'Side-Lying Horizontal Abduction',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on the non-affected side. Hold a light weight in the top hand with the arm resting in front of the body at 90 degrees of flexion. Raise the arm upward and backward into horizontal abduction and slight extension. Hold at the top, then lower slowly. Targets the posterior deltoid and external rotators.'},
{id:'s89',cat:'Shoulder',name:'Prone Shoulder External Rotation at 90 (Low Load)',pos:'Prone, arm hanging off table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down on a table with the arm hanging off the edge, elbow bent 90 degrees. Rotate the forearm upward toward the ceiling (ER) against gravity. Hold briefly. Lower slowly. A gravity-resisted ER exercise requiring no equipment beyond a table.'},
{id:'s90',cat:'Shoulder',name:'Scapular Plane Elevation (Scaption)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand with the arm at your side. Raise the arm forward and outward at a 30-45 degree angle (the scapular plane), keeping the thumb pointing upward. Elevate to shoulder height only initially, then progress to overhead as tolerated. Movement in the scapular plane is more comfortable and functional than pure flexion or abduction.'},
{id:'s91',cat:'Shoulder',name:'Shoulder Horizontal Adduction Stretch',pos:'Seated',sets:3,reps:'3',hold:'20-30 sec',freq:'2x/day',instr:'Sit tall. Bring the arm across the chest at shoulder height and hold it in place with the other hand just above the elbow. Add a gentle pull to increase the stretch in the posterior shoulder and posterior capsule. A standard posterior shoulder flexibility exercise.'},
{id:'s92',cat:'Shoulder',name:'Standing Wall Slide to Overhead',pos:'Standing facing wall',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand facing a wall with both hands on the surface at shoulder height. Slowly slide both hands up the wall as high as possible while keeping them flat against the surface. Slide back down. The wall assists with controlling the movement and provides feedback for compensation.'},
// ELBOW & WRIST (e61-e68, 8)
{id:'e61',cat:'Elbow & Wrist',name:'Elbow Flexion Isometric at Multiple Angles',pos:'Seated',sets:3,reps:'5 per angle',hold:'10 sec',freq:'Daily',instr:'Perform an isometric biceps contraction with the elbow at 30, 60, 90, and 120 degrees of flexion. Hold at each angle, then relax. Working through multiple angles provides comprehensive strengthening of the biceps and brachialis at all points in the range.'},
{id:'e62',cat:'Elbow & Wrist',name:'Elbow Extension Isometric at Multiple Angles',pos:'Seated',sets:3,reps:'5 per angle',hold:'10 sec',freq:'Daily',instr:'Perform an isometric triceps contraction against a fixed surface at 30, 60, 90, and 120 degrees of elbow flexion. Hold at each angle, then relax. Provides comprehensive triceps strengthening through the range.'},
{id:'e63',cat:'Elbow & Wrist',name:'Wrist Proprioception Retraining',pos:'Seated, forearm supported',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'With eyes closed, move the wrist to a specific position called out by your therapist, then open your eyes to check accuracy. Alternatively, attempt to match the wrist angle of the other hand without looking. Trains wrist joint position sense after sprain or injury.'},
{id:'e64',cat:'Elbow & Wrist',name:'Extensor Carpi Radialis Longus Strengthening',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest the forearm on a table, palm down. Extend and radially deviate the wrist simultaneously against light resistance or gravity, targeting the ECRL. Used specifically for lateral epicondylar rehabilitation where this muscle\'s tendon is primarily involved.'},
{id:'e65',cat:'Elbow & Wrist',name:'Flexor Carpi Ulnaris Strengthening',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest forearm on table, palm up. Flex and ulnar-deviate the wrist simultaneously against light resistance. Targets the FCU specifically, used in medial epicondylalgia rehabilitation.'},
{id:'e66',cat:'Elbow & Wrist',name:'Opponens Pollicis Strengthening',pos:'Seated',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Pinch the tip of the thumb to the tip of the little finger, creating a circle with maximum force. Hold, then release fully. Targets the opponens pollicis, thenar eminence musculature. Used after carpal tunnel release, basal joint arthritis, or thumb injuries.'},
{id:'e67',cat:'Elbow & Wrist',name:'Wrist Traction Self-Mobilization',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Stabilize the forearm with one hand. With the other hand, grasp around the wrist bones and apply a gentle longitudinal traction (pull away from the forearm). Hold briefly, then release. A self-mobilization technique for wrist joint restriction following fracture or immobilization.'},
{id:'e68',cat:'Elbow & Wrist',name:'Scaphoid Wrist Stability Drills',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Hold the wrist with the thumb of the other hand providing firm stabilizing pressure over the scaphoid. Perform gentle controlled wrist motions against this stabilizing pressure. Used in scaphoid fracture rehabilitation to load the bone progressively while controlling motion.'},
// CORE & LUMBAR (l73-l84, 12)
{id:'l73',cat:'Core & Lumbar',name:'Standing Hip Flexor Activation Against Band',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Stand with a band anchored behind you at ankle height and loop the other end around one ankle. Drive the knee upward against the resistance of the band, maintaining an upright trunk. A standing hip flexor strengthening exercise that closely mirrors the hip flexion demands of walking and running.'},
{id:'l74',cat:'Core & Lumbar',name:'Multifidus Isometric Re-Activation',pos:'Prone',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Lie face down and gently tighten the small muscles along the side of the spine by attempting to bulge them outward at a specific spinal level, without contracting the glutes or hamstrings. An isolation technique for the lumbar multifidus, a deep spinal stabilizer that becomes inhibited following low back injury.'},
{id:'l75',cat:'Core & Lumbar',name:'Lateral Trunk Stability with Arm Swing',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Stand on one leg and swing the opposite arm forward and back in a walking motion, maintaining a level pelvis and upright trunk. Trains the lateral trunk stabilizers under a functional dynamic load, mimicking demands placed on the core during single-leg stance in walking.'},
{id:'l76',cat:'Core & Lumbar',name:'Prone Hip Extension with Knee Bent (Prone Kickback with Resistance)',pos:'Prone with ankle weight or band',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Lie face down. With an ankle weight or band around the ankle, bend the knee to 90 degrees and lift the entire thigh off the surface by extending at the hip. Hold, then lower. The bent knee position shortens the hamstrings, isolating the gluteus maximus more effectively.'},
{id:'l77',cat:'Core & Lumbar',name:'Lumbopelvic Dissociation in Standing',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand with hands on the hips. Practice anteriorly and posteriorly tilting the pelvis independently without moving the thorax or knees, then practice lateral pelvic tilts. Builds the motor control to move the pelvis independently from the spine, often limited after prolonged pain or altered movement patterns.'},
{id:'l78',cat:'Core & Lumbar',name:'Supine Leg Press Against Wall (90-90)',pos:'Supine, feet on wall',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with the hips and knees both at approximately 90 degrees and both feet flat against a wall. Press through both feet into the wall, engaging the glutes and hamstrings without extending the knees. A closed-chain lower extremity and core exercise requiring no equipment.'},
{id:'l79',cat:'Core & Lumbar',name:'Seated Spinal Extension at Desk (McKenzie Posture)',pos:'Seated',sets:1,reps:'Every 30-45 min',hold:'—',freq:'Throughout work day',instr:'If you spend prolonged time seated, sit on the edge of the chair with an exaggerated lumbar lordosis and upright posture for 30-60 seconds every 30-45 minutes, then perform 3-5 standing lumbar extensions. This McKenzie postural correction program is designed to counteract the sustained flexion loading of prolonged desk sitting.'},
{id:'l80',cat:'Core & Lumbar',name:'Seated Lumbar Stabilization on Balance Disc',pos:'Seated on disc',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Sit on an inflated balance disc or wobble cushion without back support. Maintain a neutral spine and balanced sitting posture on the unstable surface. Builds dynamic lumbar and core control in a functional sitting position.'},
{id:'l81',cat:'Core & Lumbar',name:'Standing Deadlift (Romanian, Light)',pos:'Standing',sets:3,reps:'12',hold:'—',freq:'2-3x/week',instr:'Stand with feet hip-width apart holding light weights. With a slight knee bend and neutral spine, hinge at the hips pushing them backward, lowering the weights toward the floor. Return by driving the hips forward. The Romanian deadlift trains the entire posterior chain in a fundamental hip hinge pattern used in daily lifting.'},
{id:'l82',cat:'Core & Lumbar',name:'Functional Squat Pattern Drill',pos:'Standing',sets:3,reps:'12',hold:'2 sec at bottom',freq:'Daily',instr:'Stand with feet shoulder-width apart. Sit back into a squat keeping the chest upright, weight in the heels, and knees tracking over the toes. Pause briefly at the bottom, then push back to standing. Rehearses the fundamental squat movement pattern used in occupational and recreational tasks.'},
{id:'l83',cat:'Core & Lumbar',name:'Supine Marching with Lumbar Control (Progression)',pos:'Supine, knees bent',sets:3,reps:'20 total',hold:'—',freq:'Daily',instr:'Lie on your back with knees bent. Brace your core. Alternately lift each knee toward the chest with a 90/90 position, moving only the hip and not allowing the lumbar spine to move at all. A more demanding version of supine marching used as a progression when the basic version is mastered.'},
{id:'l84',cat:'Core & Lumbar',name:'Cable Woodchop Variations',pos:'Standing',sets:3,reps:'12 each direction',hold:'—',freq:'2-3x/week',instr:'Using a cable machine or resistance band, perform diagonal chopping motions (high to low and low to high) through the trunk. Progress from two hands to single leg stance. Functional trunk rotation and strength used in return to sport and occupational rehabilitation.'},
// HIP (h64-h73, 10)
{id:'h64',cat:'Hip',name:'Supine Hip ER Isometric with Band',pos:'Supine, knees bent',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Lie on your back with knees bent and a band looped around both thighs just above the knees. Press the knees outward against the band resistance without allowing the feet to move. A low-load hip external rotator isometric often used in early hip rehabilitation or with patients who have pain with dynamic movements.'},
{id:'h65',cat:'Hip',name:'Seated Resisted Hip IR with Band',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with feet flat on the floor. Place a band around both ankles crossing between the legs. Rotate the affected foot and knee inward against the band resistance. Slowly return. Targets hip internal rotators, often weak after hip replacement or in hip impingement.'},
{id:'h66',cat:'Hip',name:'Hip Adductor Isometric (Ball Squeeze) in Bridge',pos:'Supine in bridge',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Get into a bridge position and place a small ball between your knees. Squeeze the ball firmly while holding the bridge. This combines glute and adductor activation and is used for groin rehabilitation, hip stability, and knee alignment training.'},
{id:'h67',cat:'Hip',name:'Nordic Hamstring Curl - NHC (Eccentric)',pos:'Kneeling, feet held',sets:3,reps:'5-8',hold:'—',freq:'2-3x/week',instr:'Kneel on a soft surface with feet secured by a partner or anchored object. With the body rigid and straight, slowly lower your trunk toward the floor by allowing the knees to extend, controlling the lowering eccentrically with the hamstrings as long as possible before catching yourself. An advanced eccentric hamstring exercise with strong evidence for hamstring strain prevention.'},
{id:'h68',cat:'Hip',name:'Standing Y-Balance Reach for Hip',pos:'Standing on one leg',sets:3,reps:'5 each direction',hold:'—',freq:'Daily',instr:'Stand on the affected leg. Reach the opposite foot as far as possible in the anterior, posteromedial, and posterolateral directions in sequence, touching lightly each time. Measures and trains dynamic hip and ankle balance control together.'},
{id:'h69',cat:'Hip',name:'Hip Abductor Strengthening in Sidelying (Weighted)',pos:'Side-lying',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Lie on your side with an ankle weight on the top leg. Lift the leg to about 45 degrees while keeping the foot parallel to the floor or slightly internally rotated. Hold briefly and lower with control. A progression from unweighted side-lying abduction for hip abductor strength.'},
{id:'h70',cat:'Hip',name:'Reverse Nordic Hamstring Curl',pos:'Kneeling on soft surface',sets:3,reps:'8-10',hold:'—',freq:'2-3x/week',instr:'Kneel upright on a padded surface with ankles secured. Lean back slowly, lowering the trunk away from the vertical while maintaining a rigid body position. Return to upright. Focuses on hip flexor and quadriceps eccentric loading, the anterior counterpart to the Nordic curl.'},
{id:'h71',cat:'Hip',name:'Hip Extension Bias with Contralateral Reach',pos:'Standing',sets:3,reps:'10 each',hold:'2 sec',freq:'Daily',instr:'Stand on one leg and reach the opposite arm forward as you hinge at the hip, extending the free leg back behind you. Both the arm reach and leg extension counterbalance each other. Specifically targets the hip extensors while building proprioception and trunk stability together.'},
{id:'h72',cat:'Hip',name:'Sidelying Hip Internal Rotation Strengthening',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your side with the top leg positioned with the knee bent. Internally rotate the hip by moving the foot away from the other foot while keeping the knee still. Add a resistance band around the ankle for progression. Used for hip IR weakness in FAI, snapping hip, and hip osteoarthritis rehab.'},
{id:'h73',cat:'Hip',name:'Hip Strength and Power - Jump Squat',pos:'Standing',sets:3,reps:'8',hold:'—',freq:'2-3x/week',instr:'Stand with feet shoulder-width apart. Perform a partial squat then explosively jump upward, extending at the hips, knees, and ankles simultaneously. Land softly with knees bent. A power-developing exercise used in late-stage hip and knee rehab for athletes and active patients.'},
// KNEE (k63-k72, 10)
{id:'k63',cat:'Knee',name:'Knee Extension Wall Slide',pos:'Standing against wall',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Stand with your back against a smooth wall. Slide down slightly into a mini squat position. Hold at this angle, engaging the quads, then slide back up to standing. A controlled bodyweight quad exercise using the wall for support and feedback.'},
{id:'k64',cat:'Knee',name:'Lunge with Trunk Rotation',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Step into a forward lunge. At the bottom of the lunge, rotate your trunk toward the front leg while keeping the pelvis stable. Return to standing. Adds a rotational demand to the lunge, used in sports rehabilitation for rotational sports.'},
{id:'k65',cat:'Knee',name:'Leg Press Single Limb Eccentric',pos:'Leg press machine',sets:3,reps:'12 each leg',hold:'—',freq:'2-3x/week',instr:'Use both legs to press the weight up, then remove one foot and slowly lower the weight with the single affected leg over a 3-4 second count. Return to two legs for the pressing phase. Eccentric single-leg loading for late-stage ACL, patellar tendon, and knee OA rehabilitation.'},
{id:'k66',cat:'Knee',name:'Knee Flexion Active Range in Prone',pos:'Prone',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down with legs straight. Bend one knee actively toward the buttock against gravity, hold briefly, then lower slowly. No band or weight needed. Good early active knee flexion exercise following surgery or immobilization.'},
{id:'k67',cat:'Knee',name:'Resisted Knee Extension Arc (30-0 Degrees)',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit with the knee bent to 30 degrees. Straighten the knee fully against a band anchored below and hold briefly. This final 30 degree arc of extension is where the VMO is most active and is a specific focus in patellar tracking and patellofemoral pain management.'},
{id:'k68',cat:'Knee',name:'Step Down with Perturbation',pos:'Standing on step',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Perform a controlled step-down from a step while a partner provides unexpected perturbations to the stance side. Resist each perturbation while maintaining controlled lowering. An advanced reactive neuromuscular training exercise for knee stability.'},
{id:'k69',cat:'Knee',name:'Squatting with Valgus Collapse Correction',pos:'Standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Perform a squat while placing a band around the thighs just above the knees to provide feedback for maintaining knee alignment. Actively push outward against the band throughout the movement, preventing the knees from caving inward. Specifically trains knee alignment during functional loading.'},
{id:'k70',cat:'Knee',name:'Knee OA Cycling Program',pos:'Seated on bike',sets:1,reps:'20-40 min',hold:'—',freq:'Daily',instr:'Cycle at a moderate resistance and comfortable cadence for the prescribed duration. Cycling provides aerobic fitness and knee mobility with minimal impact loading. A core component of knee osteoarthritis management programs showing strong evidence for pain reduction and function improvement.'},
{id:'k71',cat:'Knee',name:'Resisted Calf Raises (Post ACL)',pos:'Standing',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Stand on a slight incline if available. Perform double-leg then progressing to single-leg calf raises. Calf strengthening is often overlooked in ACL protocols but is important for absorbing landing forces and reducing tibial translation loads.'},
{id:'k72',cat:'Knee',name:'Knee Replacement Scar Massage',pos:'Seated',sets:1,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Once the incision is fully healed, use your fingers to gently massage the scar in small circles and across the scar line. Mobilizing the scar prevents adhesion formation that can restrict knee flexion range following total knee replacement. Report any unusual changes in the wound to your healthcare team.'},
// ANKLE & FOOT (a55-a64, 10)
{id:'a55',cat:'Ankle & Foot',name:'Ankle Dorsiflexion with Knee Drive (Mobility)',pos:'Standing facing wall',sets:3,reps:'10 each',hold:'2 sec',freq:'Daily',instr:'Stand with the foot against the base of a wall, measured distance from the wall. Drive the knee toward the wall while keeping the heel flat, then return. This controlled mobility drill progressively improves ankle dorsiflexion range in a weight-bearing position. Track the maximum distance that allows the knee to touch the wall.'},
{id:'a56',cat:'Ankle & Foot',name:'Foot Strengthening - Doming with Band Assistance',pos:'Seated',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Loop a band around the toes and the arch to provide light assistance for the arching motion. Attempt to dome the foot (create an arch by drawing the ball of the foot toward the heel) with band assistance, then progress to no assistance. Used early when intrinsic foot strength is very limited.'},
{id:'a57',cat:'Ankle & Foot',name:'Heel Drop (Achilles Eccentric) on Decline Board',pos:'Standing on inclined surface, heel raised',sets:3,reps:'15',hold:'—',freq:'2x/day',instr:'Stand on a slightly inclined surface or decline board with the heel raised. Rise onto both toes, then shift to the affected leg only and slowly lower the heel below the starting position over a 4-second count. The decline loading position specifically targets the soleus portion of the Achilles, which is the site of insertional Achilles tendinopathy. Use as directed only.'},
{id:'a58',cat:'Ankle & Foot',name:'Subtalar Joint Mobilization (Self)',pos:'Seated',sets:3,reps:'10 each direction',hold:'3 sec',freq:'Daily',instr:'Stabilize the lower leg above the ankle with one hand. With the other hand, grasp the heel bone (calcaneus) and perform gentle eversion and inversion tilts of the heel independently from the leg. Mobilizes the subtalar joint, often restricted after ankle fractures, sprains, or prolonged immobilization.'},
{id:'a59',cat:'Ankle & Foot',name:'Midfoot Mobilization for Plantar Fasciitis',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Stabilize the heel with one hand. With the other hand, grasp the midfoot and gently mobilize the bones up and down relative to the heel. Addresses midfoot stiffness that transfers excessive load to the plantar fascia during walking. Perform as directed by your therapist.'},
{id:'a60',cat:'Ankle & Foot',name:'Functional Walking with Corrected Foot Mechanics',pos:'Standing, walking',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Walk while consciously applying your prescribed gait correction, such as avoiding toe-in or toe-out gait, using proper heel-toe pattern, or loading through the proper arch. Gait retraining with conscious corrections in early stages of rehabilitation progressively improves automatic movement patterns.'},
{id:'a61',cat:'Ankle & Foot',name:'Orthotics Accommodation Exercise',pos:'Standing, walking with orthotics',sets:1,reps:'Progressive time',hold:'—',freq:'Daily',instr:'Follow your prescribed schedule for breaking in new orthotic inserts, gradually increasing wear time each day to allow adaptation of the foot and lower limb. Report any areas of new pressure or discomfort to your therapist or orthotist for adjustment.'},
{id:'a62',cat:'Ankle & Foot',name:'Ankle Plantarflexion Stretch (Kneeling)',pos:'Kneeling',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Kneel with toes tucked under (pointing forward). Sit your weight back toward your heels, feeling a stretch along the top of the foot and ankle. Used for restricted plantarflexion range, often limited after immobilization or in patients who wear high heels regularly.'},
{id:'a63',cat:'Ankle & Foot',name:'MTP Joint Mobilization (Metatarsophalangeal)',pos:'Seated',sets:3,reps:'10 each direction',hold:'3 sec',freq:'Daily',instr:'Stabilize the metatarsal shaft with one hand. With the other, grasp the base of a toe and gently mobilize the MTP joint in dorsal and plantar glide directions. Used for restricted big toe extension limiting push-off, and after midfoot or toe injuries or surgeries.'},
{id:'a64',cat:'Ankle & Foot',name:'Sesamoid Offloading and Strengthening',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Using a specific offloading pad placed under the first metatarsal head as directed by your therapist, perform toe curls and gentle great toe extension exercises to maintain mobility and strength around the sesamoid bones without direct compression. Used in sesamoiditis management.'},
// BALANCE & FUNCTIONAL (b44-b52, 9)
{id:'b44',cat:'Balance & Functional',name:'Limits of Stability Training',pos:'Standing on balance device',sets:3,reps:'10 each direction',hold:'2 sec',freq:'Daily',instr:'Stand on a balance device and practice leaning as far as possible in each direction (forward, backward, each side, and diagonals) without losing balance or taking a step. Learning to explore the full limits of your stability envelope is a core component of fall prevention programs.'},
{id:'b45',cat:'Balance & Functional',name:'Berg Balance Scale Practice (BBS)',pos:'Various positions',sets:1,reps:'Full test',hold:'—',freq:'Weekly to track',instr:'Practice the 14 tasks of the Berg Balance Scale with your therapist: sitting without support, transfers, standing unsupported, eyes closed, feet together, reaching forward, retrieving from floor, turning to look behind, turning 360 degrees, stepping, and single-leg stance. A gold standard functional balance assessment.'},
{id:'b46',cat:'Balance & Functional',name:'Dynamic Gait Index Practice (DGI)',pos:'Walking course',sets:1,reps:'Full assessment tasks',hold:'—',freq:'Weekly to track',instr:'Walk at your comfortable speed, then modify speed, turn your head horizontally, turn your head vertically, step over obstacles, step around cones, and turn. Your therapist scores each task. The DGI is a standard functional walking assessment used for vestibular, neurological, and older adult populations.'},
{id:'b47',cat:'Balance & Functional',name:'Step-Up and Over (Functional Obstacle Crossing)',pos:'Standing beside step or platform',sets:3,reps:'5 each leg',hold:'—',freq:'Daily',instr:'Step up onto a low platform, pause briefly to balance on both feet, then step down on the other side. Turn around and repeat in the opposite direction. Mimics the stair-like demands of stepping over curbs, thresholds, and uneven surfaces in daily life.'},
{id:'b48',cat:'Balance & Functional',name:'Multidirectional Stepping Practice',pos:'Standing',sets:3,reps:'10 steps in each direction',hold:'—',freq:'Daily',instr:'Practice taking deliberate, controlled steps in all directions: forward, backward, to each side, and diagonally. Pause briefly between each step to establish balance before taking the next one. A foundational exercise for fall prevention and gait retraining.'},
{id:'b49',cat:'Balance & Functional',name:'Reactive Stepping Practice',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand in a stable position near a support. A therapist or partner provides unexpected light pushes from different directions and you take a recovery step as needed to regain balance. Practices the automatic stepping reactions used to prevent falls. Always performed with appropriate supervision.'},
{id:'b50',cat:'Balance & Functional',name:'Floor to Standing (Functional Transfer)',pos:'Floor to standing',sets:3,reps:'3',hold:'—',freq:'Daily',instr:'From sitting on the floor, practice transitioning to standing using the most efficient sequence: roll to side, push to hands and knees, assume half-kneeling, then rise to standing. Practice both with and without using furniture assistance, building the confidence and strength needed to get up independently after a fall.'},
{id:'b51',cat:'Balance & Functional',name:'Carry and Walk (Dual Task)',pos:'Standing, walking',sets:3,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Carry an object of graduated weight and size (starting with a light bag or tray, progressing to heavier items) while walking at a comfortable pace, simulating grocery carrying or common daily tasks requiring carrying and walking simultaneously.'},
{id:'b52',cat:'Balance & Functional',name:'Stepping Over Moving Obstacles',pos:'Walking',sets:3,reps:'10 steps',hold:'—',freq:'Daily',instr:'Practice stepping over objects that are moving or unpredictably placed, simulating real-world demands like stepping over pets, children, or moving objects. Requires quick visual processing and reactive motor control, key skills for fall prevention in community-dwelling older adults.'},
// POST-OP & GENERAL (p39-p46, 8)
{id:'p39',cat:'Post-Op & General',name:'Instrument-Assisted Soft Tissue Mobilization (IASTM)',pos:'Supine or seated',sets:1,reps:'3-5 min',hold:'—',freq:'As prescribed',instr:'Your therapist uses a specialized tool to apply controlled pressure and strokes along the involved tissue. You should feel firm pressure and moderate discomfort but not sharp pain. IASTM is used for scar tissue, chronic muscle tension, and tendinopathy. Some post-treatment soreness is normal and expected.'},
{id:'p40',cat:'Post-Op & General',name:'Dry Needling Aftercare Exercise',pos:'Various',sets:1,reps:'As directed',hold:'—',freq:'Same day and day after treatment',instr:'Following dry needling treatment, perform gentle, active movement of the treated area through its full range of motion to encourage blood flow and tissue response. Continue your prescribed home exercise program. Expect some local soreness for 24-48 hours after treatment.'},
{id:'p41',cat:'Post-Op & General',name:'Functional Capacity Evaluation Practice Task',pos:'Varies',sets:1,reps:'3-5 min',hold:'—',freq:'As prescribed',instr:'Practice the specific work tasks identified in your functional capacity evaluation (FCE) as a target for rehabilitation, such as controlled lifting, carrying, pushing, pulling, or sustained postures. Progress capacity in each task systematically in preparation for return to work.'},
{id:'p42',cat:'Post-Op & General',name:'Progressive Resistive Exercise (PRE) Protocol',pos:'Varies by muscle group',sets:3,reps:'8-12',hold:'—',freq:'Every other day',instr:'Determine the maximum weight you can lift 10 times (10-rep max). Perform sets at 50%, 75%, and 100% of that weight. Reassess and progress the 10RM weekly. The DeLorme PRE protocol is a foundational strength-building method used throughout PT for muscle strengthening.'},
{id:'p43',cat:'Post-Op & General',name:'Nordic Hamstring Curl (NHC) for Injury Prevention',pos:'Kneeling',sets:3,reps:'6-10',hold:'—',freq:'2-3x/week',instr:'As a preventive exercise: kneel with feet secured. With a controlled body position, slowly lower toward the floor eccentrically. A partner catches you before you touch the floor, then assists you back to upright. One of the most evidence-supported exercises for hamstring injury prevention in athletes.'},
{id:'p44',cat:'Post-Op & General',name:'Tai Chi Balance Series',pos:'Standing',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Follow the prescribed Tai Chi movement sequence of slow, deliberate weight shifts and arm movements. Multiple high-quality RCTs support Tai Chi as one of the most effective exercise interventions for fall prevention in older adults. Often incorporated into PT fall prevention programs.'},
{id:'p45',cat:'Post-Op & General',name:'Aquatic Therapy Pool Exercise Program',pos:'In pool',sets:1,reps:'30-45 min',hold:'—',freq:'2-3x/week',instr:'Perform your prescribed aquatic exercise program including walking, leg raises, step-ups on pool stairs, and swimming activities as directed. Buoyancy reduces loading by up to 90% (at shoulder depth), allowing movement and strengthening when land-based exercise is too painful or restricted.'},
{id:'p46',cat:'Post-Op & General',name:'Return to Work Simulation Exercise',pos:'Work station setup',sets:1,reps:'Progressive work duration',hold:'—',freq:'Daily',instr:'Gradually increase the amount of time performing simulated work tasks (computer work, lifting, driving posture, overhead reaching) that match your occupational demands. Progress duration and intensity systematically toward full work capacity while monitoring symptoms.'},
// NEURO & VESTIBULAR (n31-n38, 8)
{id:'n31',cat:'Neuro & Vestibular',name:'Otolith Rehabilitation Exercises (Linear Motion)',pos:'Seated or standing',sets:3,reps:'20',hold:'—',freq:'2x/day',instr:'Move the head up and down (nodding) or tilt side to side slowly while maintaining focus on a target. These motions stimulate the otolith organs (utricle and saccule) which sense linear head acceleration and gravity. Used in otolith dysfunction and unilateral vestibular hypofunction.'},
{id:'n32',cat:'Neuro & Vestibular',name:'Imagined Movement Therapy',pos:'Supine or seated',sets:3,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Vividly mentally rehearse the movement of the affected body part through its full range, imagining the sensation of the movement in detail without physically moving. Used after neurological injury, complex regional pain syndrome, or severe pain limiting active movement. Motor imagery activates many of the same neural pathways as actual movement.'},
{id:'n33',cat:'Neuro & Vestibular',name:'Graded Motor Imagery (GMI) Phase 1 - Laterality',pos:'Seated at screen or with cards',sets:3,reps:'5-10 min',hold:'—',freq:'Daily',instr:'View a series of photographs of hands or feet and identify as quickly and accurately as possible whether they are the left or right limb. This task activates the motor representation of the limb in the brain without triggering the pain response. Used in complex regional pain syndrome and chronic pain rehabilitation.'},
{id:'n34',cat:'Neuro & Vestibular',name:'Graded Motor Imagery Phase 2 - Imagined Movements',pos:'Seated',sets:3,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Mentally rehearse progressively complex movements of the affected limb beginning with simple motions and advancing to multi-joint movements. Continue only while the exercises remain comfortable and do not provoke symptoms. Part of the three-stage GMI protocol for CRPS and chronic pain.'},
{id:'n35',cat:'Neuro & Vestibular',name:'Graded Motor Imagery Phase 3 - Mirror Therapy',pos:'Seated at table with mirror',sets:3,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Position a mirror vertically between your two limbs. Move the unaffected limb while watching its reflection in the mirror, which appears to be the affected limb moving normally. Practice progressively complex movements. The final stage of the GMI protocol for CRPS and phantom limb pain.'},
{id:'n36',cat:'Neuro & Vestibular',name:'Spasticity Management Stretching Program',pos:'Supine or assisted position',sets:3,reps:'5 each muscle group',hold:'30-60 sec',freq:'Daily',instr:'Perform slow, sustained stretching of spastic muscle groups as directed, holding each stretch at least 30 seconds to allow the spastic response to diminish. Avoid fast or ballistic movements that trigger the stretch reflex. Often combined with positioning, splinting, and thermal agents in neurological spasticity management.'},
{id:'n37',cat:'Neuro & Vestibular',name:'Unilateral Vestibular Hypofunction Compensation Program',pos:'Various',sets:1,reps:'Per prescribed protocol',hold:'—',freq:'Multiple times daily',instr:'Follow your individually prescribed program of gaze stabilization, habituation, and balance exercises designed to promote central compensation for unilateral vestibular loss. Consistent, frequent practice is the key driver of vestibular compensation and symptoms should gradually reduce over weeks to months.'},
{id:'n38',cat:'Neuro & Vestibular',name:'Meclizine-Free Vestibular Rehabilitation',pos:'Various',sets:1,reps:'Per protocol',hold:'—',freq:'Multiple times daily',instr:'Continue your vestibular rehabilitation exercises as prescribed without relying on vestibular suppressant medications such as meclizine during exercise sessions, as these medications slow the central compensation process. Medications should only be used for severe acute episodes if absolutely necessary as directed by your physician.'},
// SPORT-SPECIFIC & PLYOMETRIC (sp26-sp35, 10)
{id:'sp26',cat:'Sport-Specific & Plyometric',name:'Interval Sprinting Program',pos:'Track or open field',sets:1,reps:'Per interval schedule',hold:'—',freq:'2-3x/week',instr:'Perform your prescribed interval running schedule, beginning with short work intervals (10-20 seconds) at submaximal speed with adequate rest periods. Progressively increase the speed, duration, and number of intervals over weeks. Used in the later stages of lower extremity return-to-sport programs.'},
{id:'sp27',cat:'Sport-Specific & Plyometric',name:'Figure-8 Running Drill',pos:'Open space with cones',sets:3,reps:'4 laps',hold:'—',freq:'2-3x/week',instr:'Set up two cones 5-10 yards apart. Run in a continuous figure-8 pattern around the cones, which requires repeated cutting and direction changes in both directions. A fundamental return-to-sport drill for field and court sport athletes after lower extremity injury.'},
{id:'sp28',cat:'Sport-Specific & Plyometric',name:'Jump Rope',pos:'Standing, open space',sets:3,reps:'1-3 min',hold:'—',freq:'Daily',instr:'Jump rope at a comfortable pace, beginning with slow single bounces and progressing to faster rhythms and more complex footwork patterns. An excellent cardiovascular, coordination, and calf/ankle conditioning exercise commonly used in PT sports rehabilitation programs.'},
{id:'sp29',cat:'Sport-Specific & Plyometric',name:'Defensive Slide with Resistance',pos:'Standing, athletic stance',sets:3,reps:'20 sec',hold:'—',freq:'2-3x/week',instr:'Assume a low defensive athletic stance with a resistance band around the ankles. Slide laterally with quick, small steps, maintaining the low position and never letting the feet come together. Mimics the defensive positioning of basketball, tennis, and soccer.'},
{id:'sp30',cat:'Sport-Specific & Plyometric',name:'Overhead Athlete Return to Throwing - Phase 2',pos:'Standing, throwing distance',sets:1,reps:'Per interval throwing schedule',hold:'—',freq:'As prescribed',instr:'Progress your interval throwing program to longer distances and increased velocity as cleared by your therapist and physician. Never skip phases. Any return of elbow or shoulder pain during throwing mandates returning to the previous phase or ceasing activity until reassessed.'},
{id:'sp31',cat:'Sport-Specific & Plyometric',name:'Drop-Catch Reactive Exercise',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'Have a partner hold a ball or object at shoulder height and drop it without warning. React and catch it as quickly as possible. Builds upper extremity reactive strength and visual-motor reaction time used in many sports.'},
{id:'sp32',cat:'Sport-Specific & Plyometric',name:'Sport-Specific Cutting Drill (45 and 90 degree)',pos:'Open space with cones',sets:3,reps:'8 each direction',hold:'—',freq:'2-3x/week',instr:'Set up cones for your specific sport direction-change angles. Jog forward, plant and cut at the designated angle using controlled deceleration and acceleration. Perform 45-degree cuts first, progressing to 90-degree cuts as neuromuscular control improves. A critical step in sport-specific return-to-play after lower extremity injury.'},
{id:'sp33',cat:'Sport-Specific & Plyometric',name:'Reactive Jump with Direction Change',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'A partner calls out a direction (left, right, forward, back) immediately before or at the moment of takeoff. Jump in the called direction and land softly. Trains reactive decision-making and multi-directional landing mechanics needed in sport contexts.'},
{id:'sp34',cat:'Sport-Specific & Plyometric',name:'Single-Leg Plyometric Progression',pos:'Standing',sets:3,reps:'8 each leg',hold:'—',freq:'2-3x/week',instr:'Progress single-leg plyometrics in this order: single-leg hop in place, single-leg hop for distance, single-leg hop for height, single-leg lateral hop, and reactive single-leg hops. Progress only when each level can be performed with controlled, symmetrical landing mechanics.'},
{id:'sp35',cat:'Sport-Specific & Plyometric',name:'Medicine Ball Side Throw',pos:'Standing sideways to wall',sets:3,reps:'12 each side',hold:'—',freq:'2-3x/week',instr:'Stand sideways to a solid wall holding a medicine ball at hip level. Rotate explosively through the trunk, releasing the ball against the wall, then catch the rebound and immediately repeat. Builds the rotational power and reactive arm strength used in throwing, batting, and racket sports.'},
// PELVIC FLOOR & WOMEN'S HEALTH (pf21-pf27, 7)
{id:'pf21',cat:'Pelvic Floor & Womens Health',name:'Pessary Care Exercise Program',pos:'Seated or standing',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Perform pelvic floor strengthening exercises as directed alongside proper pessary use and care. A pessary is a support device for pelvic organ prolapse and must be properly fitted by a healthcare provider. Pelvic floor exercises are recommended alongside pessary use for optimal prolapse management.'},
{id:'pf22',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Strengthening Post-Menopause',pos:'Seated or standing',sets:3,reps:'10-15',hold:'5-10 sec',freq:'Daily',instr:'Perform pelvic floor contractions with adequate hold time to build endurance, as postmenopausal changes in tissue quality and hormones require more deliberate strength training focus. Estrogen changes affect the pelvic floor tissues and the exercises may need to be adjusted for optimal effect.'},
{id:'pf23',cat:'Pelvic Floor & Womens Health',name:'Urge Suppression Technique Practice',pos:'Any position',sets:1,reps:'As needed',hold:'—',freq:'When urge occurs',instr:'At the first sensation of urge to urinate, immediately contract the pelvic floor firmly (a strong Kegel), relax the body, breathe, and distract yourself mentally until the urge passes. Delay voiding by 5-10 minutes initially, gradually extending the delay. Used for urgency urinary incontinence and overactive bladder.'},
{id:'pf24',cat:'Pelvic Floor & Womens Health',name:'Bladder Diary Guided Exercise Timing',pos:'Varies',sets:1,reps:'—',hold:'—',freq:'As per diary protocol',instr:'Use your bladder diary records to identify patterns in voiding frequency and urgency. Time your pelvic floor exercises to coincide with periods of highest urge or highest activity. Work with your therapist to refine the exercise timing based on your diary data.'},
{id:'pf25',cat:'Pelvic Floor & Womens Health',name:'Chronic Pelvic Pain Relaxation Sequence',pos:'Supine',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Perform a progressive body relaxation sequence beginning with diaphragmatic breathing, then systematically releasing tension from each muscle group of the body working from the feet to the head, ending with a sustained pelvic floor drop and release. Used for hypertonicity and chronic pelvic pain.'},
{id:'pf26',cat:'Pelvic Floor & Womens Health',name:'Perineal Massage Technique Preparation',pos:'Supine',sets:1,reps:'5-10 min',hold:'—',freq:'Daily, last 4-6 weeks of pregnancy',instr:'In the last weeks of pregnancy, perineal massage can be performed to stretch the tissues in preparation for delivery. Your therapist will instruct you in the specific technique, pressure, and stretching direction. Evidence supports perineal massage for reducing perineal trauma during childbirth in first-time mothers.'},
{id:'pf27',cat:'Pelvic Floor & Womens Health',name:'Interstitial Cystitis Pelvic Floor Program',pos:'Supine or seated',sets:3,reps:'10',hold:'5-10 sec relax, 5 sec contract',freq:'Daily',instr:'For interstitial cystitis with pelvic floor involvement, alternate between sustained pelvic floor relaxation holds and gentle contractions as directed by your therapist. The program emphasis on relaxation versus strengthening depends on whether the floor is hypertonic or hypotonic in your specific case.'},
// AMPUTEE & PROSTHETIC (amp17-amp21, 5)
{id:'amp17',cat:'Amputee & Prosthetic',name:'Transfemoral Residual Limb Hip Extension Strengthening',pos:'Prone',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'For an above-knee amputation, lie face down and lift the residual limb off the surface using only the hip extensors. Hold briefly. The gluteus maximus is the primary stance and push-off muscle for above-knee prosthetic gait and must be specifically strengthened.'},
{id:'amp18',cat:'Amputee & Prosthetic',name:'Transfemoral Residual Limb Hip Abductor Strengthening',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'For an above-knee amputation, lie on the non-affected side and lift the residual limb upward using the hip abductors. The hip abductors are critical for controlling pelvic drop (Trendelenburg) during the stance phase on the prosthetic side.'},
{id:'amp19',cat:'Amputee & Prosthetic',name:'Bilateral Residual Limb Strengthening (Upper Extremity)',pos:'Standing or seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'For bilateral lower extremity amputees, focus on upper extremity strengthening (push-ups on knees, wheelchair pushes, overhead presses) to maintain the arm strength needed for effective transfers, wheelchair propulsion, and assistive device use.'},
{id:'amp20',cat:'Amputee & Prosthetic',name:'Prosthetic Energy Return Optimization',pos:'Walking',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Work with your therapist and prosthetist to optimize the alignment and component selection of your energy-return prosthetic foot for your walking speed and activity level. Practice walking at varied speeds and on varied surfaces to adapt to and maximize the energy return characteristics of the prosthesis.'},
{id:'amp21',cat:'Amputee & Prosthetic',name:'Upper Extremity Prosthetic Bilateral Hand Activities',pos:'Seated at table',sets:1,reps:'15-20 min',hold:'—',freq:'Daily',instr:'Practice bilateral hand activities using both the prosthetic terminal device and the intact hand together, such as fastening buttons, tying shoes, opening containers, and using utensils. Bilateral functional integration is the ultimate goal of upper extremity prosthetic rehabilitation.'},
// PEDIATRIC (peds24-peds29, 6)
{id:'peds24',cat:'Pediatric',name:'Pediatric Gait Training - Bodyweight Supported',pos:'Walking in support harness or gait trainer',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'With the child supported in a posterior gait trainer or overhead harness system, practice walking with therapist-assisted stepping as needed. Allows early gait training before independent weight bearing is possible in children with neurological conditions or severe weakness.'},
{id:'peds25',cat:'Pediatric',name:'Pediatric Constraint Therapy (mCIMT)',pos:'Play activities',sets:1,reps:'2-6 hrs/day',hold:'—',freq:'Daily as prescribed',instr:'With a modified constraint (soft mitt or sling) on the non-affected arm, engage the child in fun, age-appropriate play activities that require using the affected arm. Modified CIMT for children is adapted with shorter constraint times and play-based activities compared to the adult protocol.'},
{id:'peds26',cat:'Pediatric',name:'Flat Foot (Pes Planus) Exercise Program',pos:'Seated and standing',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Perform the short foot exercise (foot doming), toe curls, calf raises, and single-leg balance activities as prescribed. Pediatric flat foot exercises focus on building the intrinsic foot muscles and extrinsic supports to improve dynamic arch control during walking and running activities.'},
{id:'peds27',cat:'Pediatric',name:'In-Toeing Gait Correction Exercises',pos:'Standing and walking',sets:3,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Walk forward while consciously tracking your feet straight ahead or placing them in the prescribed corrected position. Use floor markers, a treadmill with a line, or video feedback to guide foot placement correction. Combined with hip strengthening and external rotation stretching as directed.'},
{id:'peds28',cat:'Pediatric',name:'Pediatric Scoliosis Exercise (SEAS or Schroth)',pos:'Varies by curve',sets:1,reps:'20-30 min',hold:'—',freq:'Daily',instr:'Perform your individually prescribed scoliosis-specific exercise program (SEAS, Schroth, or similar method) as directed by your therapist. These programs use three-dimensional corrective movement patterns specific to your curve type and are significantly more effective than general exercise for scoliosis management.'},
{id:'peds29',cat:'Pediatric',name:'Pediatric Developmental Milestone Play Facilitation',pos:'Floor play',sets:1,reps:'30-60 min total throughout day',hold:'—',freq:'Throughout day',instr:'Embed therapeutic movements into daily play activities that facilitate the next developmental milestone, such as facilitating transitions from sitting to standing, encouraging bilateral hand use, or practicing controlled walking over varied surfaces. Parents and caregivers are trained to incorporate these activities throughout the child\'s day rather than only in formal therapy sessions.'},
// TMJ (j21-j25, 5)
{id:'j21',cat:'TMJ',name:'Cervical-Mandibular Coordination Exercise',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Perform a gentle chin tuck and then open the mouth, maintaining the chin tuck position throughout. This coordinates cervical posture and jaw opening together. Forward head posture increases jaw muscle activity, and improving cervical posture can directly reduce TMJ loading.'},
{id:'j22',cat:'TMJ',name:'Masseter Self-Release',pos:'Seated or supine',sets:1,reps:'3-5 min',hold:'—',freq:'Daily',instr:'Using the pads of your fingers, apply sustained, gentle pressure into the masseters (cheek muscles) on both sides simultaneously. Hold until you feel the muscle soften or release. An effective self-treatment for jaw muscle tension and headaches of muscular origin.'},
{id:'j23',cat:'TMJ',name:'Pterygoid Stretching (Lateral)',pos:'Seated',sets:3,reps:'3',hold:'20 sec',freq:'Daily',instr:'Open the mouth wide. Use the flat of your thumb inside the back of the lower teeth on one side to apply a gentle outward lateral stretch of the jaw. Hold, then relax. Stretches the lateral pterygoid, a key muscle in TMJ dysfunction. Perform gently with light pressure only.'},
{id:'j24',cat:'TMJ',name:'Jaw Opening with Tongue on Palate and Mirror',pos:'Seated in front of mirror',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Place your tongue firmly on the roof of your mouth. While maintaining tongue contact, open your mouth as far as possible without the tongue lifting off. Use a mirror to ensure the jaw moves straight down without deviation. A coordinated jaw opening exercise targeting both control and range.'},
{id:'j25',cat:'TMJ',name:'Bite Guard Use and Jaw Position Awareness',pos:'Seated or sleeping',sets:1,reps:'—',hold:'As directed',freq:'As prescribed by dentist or therapist',instr:'Wear your prescribed oral splint or bite guard during the times directed (often at night, sometimes during high-stress daytime activities). Be mindful of jaw clenching habits throughout the day. Keep teeth slightly apart with lips closed at rest. Note which activities or emotions correlate with increased clenching habits.'},
// CERVICAL (c59-c65, 7)
{id:'c59',cat:'Cervical',name:'Axial Extension Exercise',pos:'Seated or standing',sets:3,reps:'10',hold:'5 sec',freq:'2x/day',instr:'Sit or stand tall. Imagine a string pulling the crown of your head straight up toward the ceiling, elongating the entire spine. Simultaneously tuck the chin slightly without flexing the neck. Hold this lengthened, upright position. A fundamental postural awareness exercise used across many neck pain conditions.'},
{id:'c60',cat:'Cervical',name:'Neck Stretches - Ear to Shoulder Combined with Arm Reach',pos:'Seated',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Tilt your right ear toward your right shoulder. Simultaneously reach your left arm downward toward the floor, as if trying to touch the floor. This increases the stretch through the left scalene, upper trap, and levator scapula. Hold, then repeat on the other side.'},
{id:'c61',cat:'Cervical',name:'Cervical Stabilization with Arm Loading',pos:'Seated',sets:3,reps:'10 each arm',hold:'5 sec',freq:'Daily',instr:'Sit tall with neutral cervical posture. While maintaining this posture, slowly raise one arm overhead. The goal is that the cervical spine does not move during the arm raise. Lower and repeat with the other arm. Trains cervical stabilizers to maintain head position during arm loading.'},
{id:'c62',cat:'Cervical',name:'Seated Row for Cervical Posture',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit tall and perform a seated row with a band while simultaneously performing a chin tuck. The combination of a row pulling the shoulders back with a chin tuck directly counters the forward head and rounded shoulder posture pattern associated with chronic neck pain.'},
{id:'c63',cat:'Cervical',name:'Cervical Rotation with Shoulder Fixation',pos:'Seated',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Sit on your hands to fix the shoulder girdle in place. Now rotate your head to one side without allowing the shoulder to compensate by elevating or rotating. This isolates true cervical rotation from compensatory shoulder movement, often revealing actual range of motion limitations.'},
{id:'c64',cat:'Cervical',name:'Chin Tuck with Resistance Band',pos:'Seated',sets:3,reps:'12',hold:'5 sec',freq:'Daily',instr:'Loop a band around the back of your head and hold both ends in front of you, providing resistance to the chin tuck motion. Perform a chin tuck against the forward pull of the band. Directly strengthens the deep cervical flexors under load.'},
{id:'c65',cat:'Cervical',name:'Prone Head Lift Endurance Hold',pos:'Prone on forearms',sets:3,reps:'—',hold:'10-30 sec',freq:'Daily',instr:'Lie face down on your forearms. Lift your head off the surface until it is level with your body, maintaining a chin tuck throughout. Hold for the prescribed time, then lower slowly. An endurance exercise for the cervical and upper thoracic extensors.'},
// SHOULDER (s93-s105, 13)
{id:'s93',cat:'Shoulder',name:'Theraband Sword Draw',pos:'Standing',sets:3,reps:'15 each side',hold:'2 sec',freq:'Daily',instr:'Anchor a band to the opposite hip. Hold the handle near the opposite hip and pull upward and across the body diagonally to finish with the arm overhead on the same side, like drawing a sword. Returns along the same path. Combines shoulder flexion, abduction, and external rotation in a functional diagonal pattern.'},
{id:'s94',cat:'Shoulder',name:'Theraband Reverse Sword Draw',pos:'Standing',sets:3,reps:'15 each side',hold:'2 sec',freq:'Daily',instr:'Anchor a band overhead on the same side. Hold the handle overhead and pull downward across the body to the opposite hip, reversing the sword draw motion. A complementary diagonal strengthening pattern to the sword draw.'},
{id:'s95',cat:'Shoulder',name:'Sidelying External Rotation to Full Arc',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on the non-affected side with a light weight. Starting at 0 degrees ER (arm resting at side, elbow bent, forearm across abdomen), rotate fully to 90 degrees of ER (forearm pointing toward ceiling). Return slowly. A full arc ER strengthening exercise requiring no equipment beyond a light weight.'},
{id:'s96',cat:'Shoulder',name:'Posterior Shoulder Strengthening (Prone Reverse Fly)',pos:'Prone on bench or bed',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down with arms hanging off the edge of a bench or bed. Hold light weights. Raise both arms out to the sides (like wings), squeezing the shoulder blades together at the top. Lower slowly. Strengthens the posterior deltoid and middle trapezius.'},
{id:'s97',cat:'Shoulder',name:'ER with Abduction Progression (Side Lying to Standing)',pos:'Side-lying progressing to standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Begin with side-lying ER. As strength improves, progress to standing ER with the arm abducted to 45 degrees, then 90 degrees. This progression mirrors the range of motion demands of reaching overhead and is used in systematic rotator cuff strengthening programs.'},
{id:'s98',cat:'Shoulder',name:'Shoulder ROM in Warm Pool or Shower',pos:'Standing in warm water or shower',sets:1,reps:'5 min',hold:'—',freq:'Daily',instr:'Under warm water (shower or pool), gently move the shoulder through all available ranges of motion before more formal exercises. Warmth reduces pain, improves tissue extensibility, and allows more effective range of motion gains. Recommended for adhesive capsulitis and early post-surgical patients.'},
{id:'s99',cat:'Shoulder',name:'Shoulder Abduction ROM Measurement Self-Tracking',pos:'Standing facing wall',sets:1,reps:'1 measurement',hold:'—',freq:'Weekly',instr:'Stand facing a wall and raise your arm to the side as high as possible, marking where your middle finger touches on the wall with a sticker. Compare weekly. Self-tracking ROM provides motivation, goal-setting ability, and early identification of plateaus in mobility-focused shoulder programs.'},
{id:'s100',cat:'Shoulder',name:'Low-Level Scapular Stabilization (Drawing Circles)',pos:'Seated or standing',sets:3,reps:'10 circles each direction',hold:'—',freq:'Daily',instr:'Sit or stand tall. Perform slow, large circles with the shoulder blades, moving them in a controlled sequence: up, out, down, and in. Repeat in the other direction. A gentle, active scapular mobility and control exercise appropriate for very early-stage shoulder rehabilitation.'},
{id:'s101',cat:'Shoulder',name:'Proprioceptive Neuromuscular Facilitation (PNF) D1 Flexion',pos:'Supine',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Starting with the arm by your side, palm down, rotate outward and bring the arm upward and across the body, finishing with the arm across the face, palm toward the ceiling. Return along the same path with the pattern reversed. A classic PNF diagonal pattern combining flexion, abduction, and external rotation.'},
{id:'s102',cat:'Shoulder',name:'Shoulder ER/IR ROM Measurement (Goniometer)',pos:'Supine, arm at 90 abduction',sets:1,reps:'1 measure each direction',hold:'—',freq:'Weekly',instr:'Lie on your back with the arm abducted to 90 degrees and elbow bent 90 degrees, resting on the surface. Rotate the forearm from the ceiling toward the bed in each direction. Measure the end range with a goniometer or estimate against the vertical. A standard clinical measurement for monitoring shoulder ROM progress.'},
{id:'s103',cat:'Shoulder',name:'Band External Rotation with Trunk Rotation',pos:'Standing',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Stand sideways to a band anchor at waist height. Rotate your trunk away from the anchor while simultaneously externally rotating the near shoulder, combining two movements. Return slowly. Integrates shoulder ER with trunk rotation, important for throwing and racket sport mechanics.'},
{id:'s104',cat:'Shoulder',name:'Shoulder Depression Exercise',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with hands resting on the seat on each side. Press down through both hands, lifting the body slightly off the seat using the shoulder depressors (lower trapezius and pecs). Hold briefly, then lower. Builds the shoulder depression strength needed for crutch walking and upper extremity weight bearing.'},
{id:'s105',cat:'Shoulder',name:'Posterior Capsule Moist Heat Before Stretching',pos:'Supine or seated',sets:1,reps:'—',hold:'10-15 min pre-stretch',freq:'Before stretching sessions',instr:'Apply a moist heat pack to the posterior shoulder for 10-15 minutes before performing posterior capsule stretching. Heat increases tissue extensibility and allows greater gains in range of motion during subsequent stretching. Commonly used in the treatment of adhesive capsulitis.'},
// ELBOW & WRIST (e69-e77, 9)
{id:'e69',cat:'Elbow & Wrist',name:'Elbow Active ROM - Full Flexion to Extension',pos:'Seated',sets:3,reps:'10',hold:'2 sec each end',freq:'Daily',instr:'Actively move the elbow through its full available range from complete extension to maximum flexion, holding briefly at each end. A general elbow ROM exercise used after immobilization, fracture, or surgery to maintain or regain elbow motion.'},
{id:'e70',cat:'Elbow & Wrist',name:'Wrist Tenodesis Exercise',pos:'Seated, forearm supported',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Actively extend the wrist (fingers will passively close) then actively flex the wrist (fingers will passively open). Uses the tenodesis effect of the wrist to simulate functional hand opening and closing. Used in high-level spinal cord injury rehabilitation when active finger function is absent.'},
{id:'e71',cat:'Elbow & Wrist',name:'Progressive Grip Strengthening with Dynamometer',pos:'Seated',sets:3,reps:'5',hold:'3 sec',freq:'Daily',instr:'Squeeze a hand dynamometer at maximum effort. Record the measurement. Perform progressive submaximal squeezes as prescribed. Grip strength measurement is both a key outcome measure and a training stimulus in hand therapy and general upper extremity rehabilitation.'},
{id:'e72',cat:'Elbow & Wrist',name:'Ulnar Nerve Decompression Exercises (Cubital Tunnel)',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Start with the elbow straight and wrist neutral. Slowly bend the elbow fully while simultaneously flexing the wrist and extending the fingers, then hold. Slowly reverse the sequence. A neural mobilization technique for the ulnar nerve at the elbow. Stop if symptoms increase beyond a mild awareness in the ring and pinky fingers.'},
{id:'e73',cat:'Elbow & Wrist',name:'Thumb CMC Joint Strengthening',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stabilize the wrist. Move the thumb into abduction (away from the palm), then opposition (toward the pinky), performing each motion against light resistance. The CMC joint is the most common site of thumb arthritis, and strengthening the surrounding musculature reduces pain and improves hand function.'},
{id:'e74',cat:'Elbow & Wrist',name:'Wrist Strengthening with Bucket of Rice',pos:'Seated',sets:1,reps:'3-5 min',hold:'—',freq:'Daily',instr:'Place your hand and forearm in a bucket of dry rice and perform various motions: opening and closing the hand, rotating the forearm, moving the wrist in all directions. The rice provides light, variable resistance in all directions simultaneously. A classic hand therapy home exercise technique.'},
{id:'e75',cat:'Elbow & Wrist',name:'Elbow Immobilizer Weaning',pos:'Seated or standing',sets:1,reps:'Progressive time',hold:'—',freq:'Daily',instr:'Follow your prescribed schedule for removing the elbow immobilizer or splint for increasing periods of time, allowing more movement and loading each day. Never remove ahead of the surgical or therapy schedule without clearance.'},
{id:'e76',cat:'Elbow & Wrist',name:'FCR and FCU Isolated Stretching',pos:'Seated, forearm supinated',sets:3,reps:'3 each',hold:'20-30 sec',freq:'2x/day',instr:'For FCR: extend the wrist with slight radial deviation to stretch the flexor carpi radialis. For FCU: extend the wrist with slight radial deviation and forearm pronation to stretch the flexor carpi ulnaris. Hold each stretch with the elbow straight for maximum effect.'},
{id:'e77',cat:'Elbow & Wrist',name:'Mallet Finger Splinting and Exercise Protocol',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'With the DIP joint splinted in extension as prescribed, perform active PIP joint flexion and extension exercises to prevent stiffness in the uninvolved joints. After the splinting phase is complete, perform graded active DIP extension exercises as directed by your therapist.'},
// CORE & LUMBAR (l85-l96, 12)
{id:'l85',cat:'Core & Lumbar',name:'Standing Cable Core Rotation with Lunge',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Stand sideways to a cable or band anchor. Step into a lunge on the far side as you rotate and pull the cable through a chopping motion. Return. Combines lower extremity power with trunk rotation in an integrated functional movement used in sport and occupational rehabilitation.'},
{id:'l86',cat:'Core & Lumbar',name:'TRX or Ring Core Exercises',pos:'Suspended in TRX or rings',sets:3,reps:'8-12',hold:'—',freq:'2-3x/week',instr:'Perform your prescribed TRX exercises such as fallouts, pikes, or suspended planks. The instability of suspension training provides significant additional core demand compared to floor exercises. Used in mid- to late-stage core rehabilitation programs.'},
{id:'l87',cat:'Core & Lumbar',name:'Thoracolumbar Fascia Self-Release',pos:'Supine with foam roller',sets:1,reps:'3-5 min',hold:'—',freq:'Daily',instr:'Lie on your back with a foam roller placed horizontally under your lumbar or thoracolumbar region. Apply gentle body weight pressure over the roller, breathing and allowing tension to release. May also roll slowly up and down through the lumbar region. A myofascial release technique for low back tightness.'},
{id:'l88',cat:'Core & Lumbar',name:'Standing Back Extension (Hyperextension Machine)',pos:'Prone on back extension machine',sets:3,reps:'12-15',hold:'2 sec',freq:'2-3x/week',instr:'Position yourself on a back extension machine with the pads below the hip bones. Lower the trunk downward, then extend back up to horizontal or slightly above. Keep the motion controlled in both directions. A gym-based lumbar extensor and glute strengthening exercise commonly used in chronic low back pain rehabilitation.'},
{id:'l89',cat:'Core & Lumbar',name:'Intra-Abdominal Pressure Control (IAP)',pos:'Various positions',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Practice generating controlled intra-abdominal pressure by bracing the core 360 degrees around (not just pulling the belly in), as if preparing to absorb a punch from any direction. This Valsalva-free bracing technique is the foundation of safe lifting and heavy loading during rehabilitation.'},
{id:'l90',cat:'Core & Lumbar',name:'Hip-Spine Dissociation (Forward Lean)',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand and hold a support. Practice bending forward by moving only at the hips (posterior pelvic tilt) while keeping the spine in neutral, like a door hinge at the hip. Prevents rounding the spine during forward bending. A fundamental movement pattern used throughout lower extremity and lumbar rehabilitation.'},
{id:'l91',cat:'Core & Lumbar',name:'Piriformis and Gluteal Massage (Foam Roll)',pos:'Seated on foam roll',sets:1,reps:'2-3 min each side',hold:'—',freq:'Daily',instr:'Sit on a foam roller with the affected hip crossed over the opposite knee, shifting the weight onto the roller targeting the piriformis and deep gluteal muscles. Slowly roll through the region, pausing on tender spots until they release. Used for piriformis syndrome and hip-related low back pain.'},
{id:'l92',cat:'Core & Lumbar',name:'Lumbar Flexion AROM in Standing (McKenzie)',pos:'Standing',sets:1,reps:'10',hold:'—',freq:'Every 2 hrs',instr:'Stand with feet shoulder-width apart. Bend forward at the waist reaching hands toward the floor and return to standing. A McKenzie repeated movement exercise used for patients with flexion-direction preference or to determine directional preference through symptom response.'},
{id:'l93',cat:'Core & Lumbar',name:'Supine Hamstring Stretch with Dorsiflexion (Neural Tension)',pos:'Supine',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on your back. Lift one leg with the knee straight as far as comfortable. Add ankle dorsiflexion (pull toes toward you) to add neural tension to the sciatic nerve. Stop if this dramatically increases leg symptoms. Used to distinguish hamstring flexibility from sciatic nerve restriction, and as a neural mobilization technique.'},
{id:'l94',cat:'Core & Lumbar',name:'Seated Slump Stretch',pos:'Seated',sets:3,reps:'3',hold:'30 sec',freq:'Daily',instr:'Sit at the edge of a chair without back support. Slouch fully (rounding the whole spine and dropping the chin), then straighten the knee of the affected leg and dorsiflex the ankle. Hold if comfortable. Gently extend the neck to modify the neurodynamic tension. A sitting neural mobilization technique for sciatic nerve and lumbar disc pathology.'},
{id:'l95',cat:'Core & Lumbar',name:'Quadruped Fire Hydrant',pos:'Quadruped',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'On hands and knees with a neutral spine, lift one knee outward to the side keeping it bent at 90 degrees, rotating from the hip like a dog at a fire hydrant. Hold, then lower. Targets the hip abductors and external rotators in a quadruped position that also challenges core stability.'},
{id:'l96',cat:'Core & Lumbar',name:'McGill Big Three - Full Program',pos:'Supine, side-lying, quadruped',sets:1,reps:'As per protocol',hold:'—',freq:'Daily',instr:'Perform all three McGill spine stability exercises in sequence: modified curl-up, side bridge, and bird dog. Use the 6-4-2 repetition scheme within each set (6 reps, 4 reps, 2 reps with decreasing hold time per set). This combination specifically targets the stabilizers shown most important for lumbar spine health in Dr. McGill\'s research.'},
// HIP (h74-h83, 10)
{id:'h74',cat:'Hip',name:'Hip Flexor Activation Against Gravity (Supine)',pos:'Supine',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Lie on your back. Lift one knee to 90 degrees of hip flexion against gravity without using momentum. Hold briefly, then lower slowly. An early hip flexor strengthening exercise that uses gravity as the only resistance and can be performed immediately post-surgically when more loaded exercises are restricted.'},
{id:'h75',cat:'Hip',name:'Standing Hip Circles - Full Range',pos:'Standing, holding support',sets:2,reps:'10 circles each direction',hold:'—',freq:'Daily',instr:'Stand on one leg near a support. Lift the opposite leg slightly and draw the largest comfortable circles possible in each direction, moving from the hip. An active hip mobility warm-up exercise used across hip conditions.'},
{id:'h76',cat:'Hip',name:'Hip Abductor Strengthening - Sidestep on Stairs',pos:'Standing at bottom of stairs',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Stand at the bottom of a staircase. With a band around the ankles, step sideways up one step and back down, leading with the same leg for the prescribed repetitions, then switch. The step height adds an additional load to the hip abductors compared to floor lateral walks.'},
{id:'h77',cat:'Hip',name:'Hip Precaution-Compliant Bridge',pos:'Supine, knees bent',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'For patients following total hip arthroplasty (THA) with standard precautions: perform a bridge while ensuring hip flexion does not exceed 90 degrees and neither hip crosses the midline. Keep feet wider than hip-width if instructed. Follow your specific surgeon\'s precautions at all times.'},
{id:'h78',cat:'Hip',name:'Hip IR Strengthening in Standing with Band',pos:'Standing',sets:3,reps:'15 each leg',hold:'2 sec',freq:'Daily',instr:'Stand with a band anchored outside the ankle. Keeping the knee slightly bent and stable, rotate the leg inward against the resistance of the band. Slowly return. An isolated standing hip internal rotator exercise used in FAI and hip impingement rehabilitation.'},
{id:'h79',cat:'Hip',name:'Deep Hip External Rotator Stretch (Pigeon Pose Variation)',pos:'Seated on floor',sets:3,reps:'3',hold:'30-60 sec',freq:'Daily',instr:'Sit on the floor and position the front leg with knee bent at 90 degrees in front of you (like the yoga pigeon pose). Keep the back leg extended behind you. Lean the trunk forward over the front leg. Feel a deep stretch through the outer hip and deep rotators of the front leg. Use a yoga block or folded blanket under the hip if needed.'},
{id:'h80',cat:'Hip',name:'Hip Strength - Cable Pull-Through',pos:'Standing facing away from cable',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Face away from a low cable or band anchor. Hold the handle between your legs with both hands. Hinge at the hips, letting the cable pull the hands back between the legs, then drive the hips forward to standing and squeeze the glutes at the top. A hip-dominant pulling exercise that trains the hip hinge pattern under load.'},
{id:'h81',cat:'Hip',name:'Single-Leg Squat onto Box (Eccentric Focus)',pos:'Standing on box',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on a low box on the affected leg. Slowly lower yourself into a single-leg squat until you lightly touch a lower box or the floor with the opposite foot, then press back up. Focus on the slow eccentric phase (lowering). Used for gluteal and quad strengthening in hip and knee rehab.'},
{id:'h82',cat:'Hip',name:'Resisted Hip Adduction in Side Lying (Bilateral)',pos:'Side-lying, bottom leg',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your side. Raise the bottom leg up to meet the top leg against gravity, adducting the hip. Hold, then lower slowly. The bottom leg often has weaker hip adductors and this position targets them specifically. Used in groin and adductor strain rehabilitation.'},
{id:'h83',cat:'Hip',name:'Hip Snapping Prevention Exercise (Iliotibial Band Stretch with Hinge)',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand and cross the affected leg behind the other. Lean the trunk away from the affected side while also hinging slightly at the hip to create both an IT band and lateral hip stretch. Slowly rotate the trunk back through neutral. Used for external snapping hip syndrome caused by IT band snapping over the greater trochanter.'},
// KNEE (k73-k82, 10)
{id:'k73',cat:'Knee',name:'Knee Effusion Management - Cryotherapy',pos:'Supine, elevated',sets:1,reps:'—',hold:'15-20 min',freq:'Several times daily or after activity',instr:'Apply a cold pack or ice in a damp cloth to the knee joint, ensuring the ice does not contact skin directly. Elevate the limb above heart level during the application. Used to manage knee effusion and inflammation after injury, surgery, or increased activity. Never apply heat to an acutely swollen joint.'},
{id:'k74',cat:'Knee',name:'Patellofemoral Pain - Vastus Medialis Oblique (VMO) Isolation',pos:'Seated',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Sit with the knee bent slightly. Place your hand on the inner aspect of the quadriceps just above the kneecap (VMO location). Perform a quad set while trying to feel the VMO specifically activating beneath your fingers. Tilt the foot slightly outward to bias VMO activation. Used for VMO weakness in patellofemoral pain syndrome.'},
{id:'k75',cat:'Knee',name:'Knee Flex AROM in Prone (with Strap)',pos:'Prone',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down. Loop a strap around the ankle and hold the other end in your hand. Actively bend the knee toward the buttock, using the strap to assist through the final few degrees. A self-assisted knee flexion ROM exercise for regaining flexion after surgery or immobilization.'},
{id:'k76',cat:'Knee',name:'Knee OA Quad Strengthening (ESCAPE-Pain Style)',pos:'Seated progressing to standing',sets:3,reps:'12-15',hold:'—',freq:'Daily',instr:'Following the exercise for people with knee pain format, perform controlled leg extension and sit-to-stand exercises specifically targeting the quadriceps in a progressively challenging manner. The ESCAPE-pain program is a NICE-recommended intervention for knee osteoarthritis in the UK.'},
{id:'k77',cat:'Knee',name:'Knee Flexion Mobilization (Joint Mob Grade I-II)',pos:'Prone or supine',sets:3,reps:'30-60 sec oscillations',hold:'—',freq:'Daily',instr:'In a comfortable position, perform slow oscillatory movements of the knee through a small range within the pain-free zone. Grade I-II Maitland mobilizations are used to reduce pain and maintain joint nutrition in the early stages of knee rehabilitation.'},
{id:'k78',cat:'Knee',name:'Supine Knee ROM - End Range Extension Overpressure',pos:'Supine',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Lie on your back with the knee near full extension. Place a folded towel under the heel and allow gravity to push the knee into full extension. Gently add overpressure with your hand on the thigh if needed. Restoring full knee extension is the highest priority after ACL surgery and total knee replacement.'},
{id:'k79',cat:'Knee',name:'Step Training with Load Progression',pos:'Standing at step',sets:3,reps:'15 each leg',hold:'—',freq:'Daily',instr:'Begin with a 4-inch step and progress to 6, 8, and then 12 inches as strength and control improve. Lead the step-up with the affected leg each time. Progressively higher steps increase the functional demand on the knee extensors, gluteus maximus, and single-leg stabilizers.'},
{id:'k80',cat:'Knee',name:'Knee Balance Reach with Eyes Closed',pos:'Standing on one leg',sets:3,reps:'8 reaches',hold:'2 sec each',freq:'Daily',instr:'Stand on the affected leg with eyes closed. Reach the free foot to different positions on the floor around you (forward, to each side, backward) and tap lightly, then return. The lack of visual input significantly challenges the proprioceptive system of the knee and ankle.'},
{id:'k81',cat:'Knee',name:'Kinesio Taping for Patellar Tracking',pos:'Knee in 30 degrees flexion',sets:1,reps:'—',hold:'3-5 days of wear',freq:'Applied by therapist as needed',instr:'Have your therapist apply kinesiology tape (or McConnell tape) to the patella in a pattern designed to correct your specific patellar tracking direction. The tape provides tactile feedback and may alter muscle activation timing around the patella, used for patellofemoral pain syndrome and patellar tracking disorders.'},
{id:'k82',cat:'Knee',name:'Knee Arthritis Water Aerobics',pos:'In pool, chest depth',sets:1,reps:'20-30 min',hold:'—',freq:'2-3x/week',instr:'Perform gentle water aerobics including water walking, gentle kicks, and range of motion exercises in a warm pool. The warmth reduces pain, and the buoyancy reduces joint loading significantly while providing resistance for strengthening. A highly effective and low-impact option for severe knee arthritis.'},
// ANKLE & FOOT (a65-a73, 9)
{id:'a65',cat:'Ankle & Foot',name:'Ankle Stability Progression - Unstable Surface Training',pos:'Standing on varied surfaces',sets:3,reps:'—',hold:'30 sec each progression',freq:'Daily',instr:'Progress ankle stability training through this surface hierarchy: firm ground, foam pad, half-foam roll, BOSU flat side up, BOSU dome side up. At each level, progress from double leg to single leg and from eyes open to eyes closed. Systematically challenges the ankle proprioceptive system.'},
{id:'a66',cat:'Ankle & Foot',name:'Tibialis Posterior Tendon Dysfunction Exercise',pos:'Standing, heel raise progression',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Begin with seated inversion against resistance. Progress to standing bilateral heel raises with emphasis on supination (rolling to the outer edge of the foot at the top). Then progress to single-leg heel raises on an inverted surface. Specifically targets the tibialis posterior in its primary function of heel inversion during push-off.'},
{id:'a67',cat:'Ankle & Foot',name:'Gait Retraining - Cadence Increase',pos:'Walking or treadmill',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Walk with a slightly increased step cadence (steps per minute) from your natural pace, guided by a metronome or music. Increasing cadence by 5-10% reduces the loading on the foot, ankle, and knee per step, and is an evidence-based approach for reducing impact-related pain in plantar fasciitis, shin splints, and knee pain.'},
{id:'a68',cat:'Ankle & Foot',name:'Ankle Dorsiflexion Joint Mobilization (Self)',pos:'Standing at wall',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Stand with the affected foot forward, toes touching a wall. Loop a band around the ankle, anchored behind you. Perform a knee-to-wall exercise while the band provides a posterior-to-anterior glide of the talus, mobilizing the talocrural joint. Based on the Mulligan concept MWM technique for dorsiflexion restriction.'},
{id:'a69',cat:'Ankle & Foot',name:'Plantar Intrinsic Strengthening Program (Full)',pos:'Seated and standing',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Perform the full intrinsic strengthening circuit in sequence: toe spreading, toe curls, towel scrunching, marble pickups, and the short foot exercise (foot doming). A comprehensive program targeting the intrinsic foot muscles from multiple angles, used for flat foot, plantar fasciitis, and general foot rehabilitation.'},
{id:'a70',cat:'Ankle & Foot',name:'Hallux Valgus Correction Exercise',pos:'Seated',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Use a rubber band looped around the big toe and anchor it medially. Move the big toe away from the other toes (abduction) against the resistance of the band. Also practice using the abductor hallucis to spread the toes. Used for hallux valgus management to strengthen the medial stabilizers of the first ray.'},
{id:'a71',cat:'Ankle & Foot',name:'Ankle Sprain Return to Sport Progression',pos:'Walking progressing to running and cutting',sets:1,reps:'Per sport return schedule',hold:'—',freq:'As prescribed',instr:'Follow your ankle sprain return-to-sport schedule: walking, then jogging straight lines, then jogging curves, then lateral shuffles, then cutting drills, then sport-specific drills, and finally full practice. Advance only when each stage is symptom-free and strength symmetry is restored.'},
{id:'a72',cat:'Ankle & Foot',name:'Navicular Drop Test Improvement Exercise',pos:'Seated and standing',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Measure your navicular drop (the distance the navicular bone drops from sitting to standing) as directed by your therapist. Perform short foot exercises, tibialis posterior strengthening, and calf raises to improve navicular height over time. A functionally important outcome measure for flat foot and overpronation.'},
{id:'a73',cat:'Ankle & Foot',name:'Bunion Spacer Exercise with Toe Strengthening',pos:'Seated',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Place a bunion spacer between the first and second toes. Perform toe abduction (spreading the big toe away from the others) and toe curls while the spacer maintains the corrected position. Combines the passive correction of the spacer with active strengthening in the corrected alignment.'},
// BALANCE & FUNCTIONAL (b53-b59, 7)
{id:'b53',cat:'Balance & Functional',name:'Nordic Pole Walking',pos:'Walking with two poles',sets:1,reps:'20-40 min',hold:'—',freq:'Daily',instr:'Walk with two trekking poles using a heel-toe gait pattern, planting each pole behind you and pushing backward as you stride forward. Nordic pole walking increases upper body involvement, improves balance in older adults and neurological patients, and increases caloric expenditure compared to regular walking.'},
{id:'b54',cat:'Balance & Functional',name:'Virtual Reality Balance Training',pos:'Standing with VR headset (supervised)',sets:1,reps:'20-30 min',hold:'—',freq:'Daily',instr:'Perform the prescribed balance and weight-shifting exercises using a VR system as directed by your therapist. VR-based balance training provides engaging, repetitive, and task-specific balance challenges with real-time visual feedback. Used increasingly in neurorehabilitation and fall prevention programs.'},
{id:'b55',cat:'Balance & Functional',name:'Anterior Reach Test and Training',pos:'Standing on one leg',sets:3,reps:'5 each leg',hold:'—',freq:'Daily',instr:'Stand on one leg. With a meter stick on the floor in front of you, reach the opposite foot as far as possible along the meter stick without touching it down or losing balance. Record the distance. Practice to improve anterior reach, a key measure of ankle and hip control used in return-to-sport testing.'},
{id:'b56',cat:'Balance & Functional',name:'Standing Weight Acceptance (Force Plate or Scale)',pos:'Standing',sets:3,reps:'10 transitions',hold:'3 sec each side',freq:'Daily',instr:'Stand with each foot on a bathroom scale or force plate. Practice transferring your weight smoothly from one foot to the other in a controlled manner, targeting specific percentage goals on each scale as directed. Used for weight-bearing symmetry training after lower extremity surgery.'},
{id:'b57',cat:'Balance & Functional',name:'Balance Training on Incline Board',pos:'Standing on inclined surface',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Stand on a wedge or inclined surface (front of foot lower, dorsiflexed position). Balance for the prescribed time with eyes open then progressing to eyes closed. The inclined position specifically challenges the anterior tibialis and promotes a dorsiflexion balance strategy different from level-ground training.'},
{id:'b58',cat:'Balance & Functional',name:'Rapid Alternate Stepping (Stair Stepping)',pos:'Standing at step',sets:3,reps:'30 sec',hold:'—',freq:'Daily',instr:'Stand in front of a single step. Alternately tap each foot on the step as quickly as possible while maintaining good alignment and control. Count the number of steps in 30 seconds and track improvement. A standard assessment and training drill for functional stepping speed used in aging and neurology.'},
{id:'b59',cat:'Balance & Functional',name:'Community Stair Negotiation (Variable Height)',pos:'Standing at stairs of varied heights',sets:1,reps:'Multiple flights',hold:'—',freq:'Daily',instr:'Practice navigating stairs of different heights, depths, and configurations (with and without handrails, with and without carpet) to build the adaptive skill needed for real community stair navigation. Many patients manage well on a standard staircase but struggle on non-standard stairs encountered in the community.'},
// POST-OP & GENERAL (p47-p52, 6)
{id:'p47',cat:'Post-Op & General',name:'Bike Ergometer Low Resistance (Cardio Rehab)',pos:'Seated on ergometer',sets:1,reps:'20-40 min',hold:'—',freq:'Daily',instr:'Maintain your target heart rate zone as directed by your therapist. Use rate of perceived exertion (RPE) of 11-13 on the Borg scale as a general guideline for moderate intensity. Aerobic conditioning is an important and often undertreated component of musculoskeletal rehabilitation.'},
{id:'p48',cat:'Post-Op & General',name:'Isometric Exercise in Cast or Immobilizer',pos:'As allowed by immobilization',sets:3,reps:'10',hold:'5-10 sec',freq:'Every 1-2 hrs',instr:'While the limb is immobilized, perform isometric contractions of the muscles within the cast or immobilizer as allowed, pressing against the inner surface without any joint movement. Prevents disuse atrophy during the immobilization phase of fracture healing.'},
{id:'p49',cat:'Post-Op & General',name:'Crutch Donning and Doffing - Stairs Safety',pos:'Standing at stairs',sets:3,reps:'1-2 flights',hold:'—',freq:'Daily',instr:'Practice stair negotiation with crutches following the standard technique: going up, move the crutches then the unaffected leg, then the affected leg. Going down, move the crutches and the affected leg first, then the unaffected leg. Mastering stair negotiation with crutches is essential for safe discharge.'},
{id:'p50',cat:'Post-Op & General',name:'Desensitization Program for Hypersensitive Scar',pos:'Seated or supine',sets:1,reps:'5-10 min per texture',hold:'—',freq:'Daily',instr:'Using a series of progressively firmer and coarser materials (cotton wool, velvet, denim, paper towel, terry cloth), apply each texture to the hypersensitive scar area for several minutes, starting with the softest tolerable texture. Gradually progress to firmer textures as sensitivity reduces. Used for post-surgical or post-traumatic scar hypersensitivity.'},
{id:'p51',cat:'Post-Op & General',name:'Graded Return to Lifting Program',pos:'Standing',sets:3,reps:'As per program',hold:'—',freq:'Progressive',instr:'Follow a structured lifting progression starting from ground level, waist, and shoulder height. Begin with very light weights and progress systematically, mastering proper body mechanics, intra-abdominal pressure, and bracing technique at each load level before advancing. Used in back pain, post-surgical, and occupational rehabilitation.'},
{id:'p52',cat:'Post-Op & General',name:'Global Postural Re-Education (GPR)',pos:'Supine, seated, or standing',sets:1,reps:'45-60 min session',hold:'—',freq:'Weekly with daily home practice',instr:'Under therapist guidance, maintain a corrected posture and perform gentle stretching while breathing in a series of GPR positions designed to release the global muscle chains. A comprehensive approach used in Europe for postural dysfunction and chronic musculoskeletal pain.'},
// NEURO & VESTIBULAR (n39-n44, 6)
{id:'n39',cat:'Neuro & Vestibular',name:'Bilateral Coordination Training',pos:'Seated at table',sets:3,reps:'10 min',hold:'—',freq:'Daily',instr:'Perform activities requiring simultaneous use of both hands in different patterns, such as rhythmic tapping tasks or bimanual pegboard activities. Bilateral coordination exercises address the inter-hemispheric communication often disrupted after stroke or neurological injury.'},
{id:'n40',cat:'Neuro & Vestibular',name:'Treadmill Training Post-Stroke',pos:'Supported on treadmill',sets:1,reps:'20-30 min',hold:'—',freq:'Daily',instr:'Walk on a treadmill (with body weight support if needed) at a challenging speed with therapist assistance and monitoring. High-intensity treadmill training is now one of the most evidence-supported interventions for improving walking speed and endurance after stroke.'},
{id:'n41',cat:'Neuro & Vestibular',name:'Locomotor Retraining (LSVT BIG Walking)',pos:'Walking',sets:1,reps:'30-45 min',hold:'—',freq:'Daily',instr:'Perform walking exercises using the LSVT BIG protocol principles: take big steps, swing the arms widely, and speak loudly. An evidence-based treatment for Parkinson\'s disease focused on large-amplitude movements to overcome the movement reduction that characterizes the condition.'},
{id:'n42',cat:'Neuro & Vestibular',name:'Gait Aid Weaning Program',pos:'Walking',sets:1,reps:'Progressive',hold:'—',freq:'Daily',instr:'Follow your therapist\'s prescribed schedule for reducing reliance on walking aids, progressing from standard walker to rolling walker to forearm crutches to single cane to no device as neurological recovery and balance allow. Never discontinue a walking aid without your therapist\'s clearance.'},
{id:'n43',cat:'Neuro & Vestibular',name:'Multisensory Balance Testing and Training (Computerized)',pos:'Standing on force plate',sets:1,reps:'20-30 min',hold:'—',freq:'2-3x/week',instr:'Perform balance testing and training using a computerized dynamic posturography platform (such as a Biodex Balance System or NeuroCom) under your therapist\'s guidance. These systems provide objective quantification of balance deficits and targeted training programs using visual biofeedback.'},
{id:'n44',cat:'Neuro & Vestibular',name:'Music-Assisted Gait Training - RAS (Rhythmic Auditory Stimulation)',pos:'Walking',sets:1,reps:'20 min',hold:'—',freq:'Daily',instr:'Walk to music set at a slightly faster tempo than your natural walking pace. Rhythmic auditory stimulation (RAS) uses the auditory-motor coupling of the nervous system to entrain and improve gait parameters including stride length, velocity, and symmetry. Used in Parkinson\'s, stroke, and TBI rehabilitation.'},
// PEDIATRIC (peds30-peds33, 4)
{id:'peds30',cat:'Pediatric',name:'Pediatric Balance Beam Walking',pos:'Standing on low balance beam or taped line',sets:3,reps:'2-3 lengths',hold:'—',freq:'Daily',instr:'Have the child walk forward, backward, and sideways along a low balance beam or a line of tape on the floor, placing one foot in front of the other. A classic pediatric balance and coordination activity that can be made more challenging by carrying an object or closing the eyes.'},
{id:'peds31',cat:'Pediatric',name:'Toe Walking Correction Exercise',pos:'Standing and walking',sets:3,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Perform calf stretching, Achilles tendon stretching, and strengthening of the tibialis anterior as directed. Practice walking with flat feet using a heel-toe pattern consciously, with tape markers on the floor or visual feedback. Habitual toe walking can have biomechanical, neurological, or sensory processing origins.'},
{id:'peds32',cat:'Pediatric',name:'Developmental Hip Dysplasia Exercise Program',pos:'Supine and prone',sets:3,reps:'10',hold:'10 sec',freq:'2-3x/day',instr:'Following guidance from your pediatric therapist, perform gentle range of motion activities for the hip in the position of abduction and external rotation as directed. Specific positions and exercises are highly individualized based on the type and degree of dysplasia and the treatment approach selected by the orthopedic surgeon.'},
{id:'peds33',cat:'Pediatric',name:'Pediatric Cerebral Palsy Home Program',pos:'Varies by function level',sets:1,reps:'Per individual program',hold:'—',freq:'Throughout day',instr:'Perform your child\'s individualized CP home program as designed by their physical therapist, incorporating stretching, strengthening, and functional activities into daily routines. Caregiver education and integration of therapy activities into daily life is the cornerstone of effective pediatric CP rehabilitation.'},
// SPORT-SPECIFIC (sp36-sp40, 5)
{id:'sp36',cat:'Sport-Specific & Plyometric',name:'Sport-Specific Movement Screen',pos:'Open space',sets:1,reps:'Full screen',hold:'—',freq:'At return-to-sport clearance',instr:'Perform a sport-specific movement screen including jumping and landing tasks, cutting, deceleration, and sport-relevant positions. Used to identify persistent movement quality deficits before full return to play. Screen is performed alongside strength symmetry and hop test assessments for comprehensive return-to-sport decision making.'},
{id:'sp37',cat:'Sport-Specific & Plyometric',name:'Nordic Hamstring Program - NHC (Prevention)',pos:'Kneeling',sets:3,reps:'6-10',hold:'—',freq:'2x/week in-season',instr:'Perform Nordic hamstring curls as part of a prevention program for hamstring strains in running and field sports. Begin in the preseason with lower volumes (3x5) and progress to higher volumes and faster movement as the season progresses. This is one of the most strongly evidence-supported injury prevention exercises in all of sports medicine.'},
{id:'sp38',cat:'Sport-Specific & Plyometric',name:'FIFA 11+ Injury Prevention Warm-Up',pos:'Open field',sets:1,reps:'Full program',hold:'—',freq:'Before each training session',instr:'Perform the FIFA 11+ warm-up program in its entirety before each soccer training session, including running, strength, and plyometric components. The FIFA 11+ has been shown to reduce overall injury rates by approximately 30-50% in soccer populations and is recommended as standard of care in competitive soccer.'},
{id:'sp39',cat:'Sport-Specific & Plyometric',name:'Overhead Athlete Plyometric Ball Program',pos:'Standing',sets:3,reps:'10 each type',hold:'—',freq:'2-3x/week',instr:'Perform your prescribed upper extremity plyometric program with a rebounder or partner including chest throws, overhead throws, side throws, and underhand throws with a light medicine ball. This program is used in the late stages of shoulder rehabilitation for throwers, swimmers, and overhead sport athletes.'},
{id:'sp40',cat:'Sport-Specific & Plyometric',name:'Deceleration and Change of Direction with Randomized Target',pos:'Open space',sets:3,reps:'10 randomized reps',hold:'—',freq:'2-3x/week',instr:'Set up multiple directional targets. A partner randomly points to a direction and you sprint toward it, decelerate, plant, and change direction to the next called target. The randomized element prevents anticipation and develops the true reactive agility needed in competition, rather than pre-planned drill patterns.'},
// FINAL EXTRAS to hit target (mix of commonly used PT exercises)
{id:'c66',cat:'Cervical',name:'SNAG Cervical Rotation (With Therapist)',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'During PT visits',instr:'Your therapist applies a sustained anterosuperior glide on the articular pillar of the restricted cervical segment while you perform the painful or restricted rotation. The combination of sustained glide and active rotation allows pain-free movement and can provide lasting improvements in range. A Mulligan Concept technique applied directly by the therapist.'},
{id:'s106',cat:'Shoulder',name:'MRI-Guided Shoulder Exercise Prescription',pos:'Varies',sets:3,reps:'As prescribed',hold:'—',freq:'Daily',instr:'Perform exercises specifically chosen based on your MRI findings and surgical report, as directed by your therapist. For example, full-thickness supraspinatus tears require different loading progressions than subscapularis tears or labral repairs. Exercise selection is always based on your specific diagnosis and irritability level.'},
{id:'k83',cat:'Knee',name:'Functional Hop Test Training (Crossover)',pos:'Standing',sets:3,reps:'5 each leg',hold:'—',freq:'2-3x/week',instr:'Mark a line on the floor. Hop on one leg forward, then sideways across the line, then forward again in a crossover hop pattern for three consecutive hops. Compare the total distance to the other leg to calculate limb symmetry index. Used as both training and a return-to-sport assessment.'},
{id:'h84',cat:'Hip',name:'Hip Flexor Endurance Hold in Chair',pos:'Seated at edge of chair',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Sit at the edge of a chair with both legs hanging freely. Hold both knees in a raised position against gravity for the prescribed time. Builds hip flexor endurance in a functional seated position, important for activities like climbing stairs, getting in and out of cars, and prolonged walking.'},
{id:'a74',cat:'Ankle & Foot',name:'Running Gait Analysis Corrective Exercise',pos:'Treadmill or track',sets:1,reps:'As per analysis findings',hold:'—',freq:'During runs',instr:'Based on your running gait analysis findings, implement the specific corrections identified by your therapist (such as increasing cadence, reducing overstriding, improving arm swing, or correcting foot strike pattern). Gait retraining interventions are evidence-based treatments for running-related injuries.'},
{id:'b60',cat:'Balance & Functional',name:'Reaction Time Training (Drop Ruler Test)',pos:'Seated or standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Your therapist or partner holds a ruler vertically between your open fingers, then drops it without warning. Catch the ruler as quickly as possible. Record the distance caught to measure and track reaction time improvement. Used in concussion recovery, neurological rehabilitation, and fall prevention programs.'},
{id:'l97',cat:'Core & Lumbar',name:'Kettlebell Swing (Hip Hinge Pattern)',pos:'Standing',sets:3,reps:'10-15',hold:'—',freq:'2-3x/week',instr:'Stand with feet shoulder-width and a kettlebell between your feet. Hinge at the hips, grasp the bell, then drive the hips forward explosively to swing the bell to shoulder height. Let the bell fall and hinge into the next rep. A ballistic hip hinge exercise building posterior chain power used in late-stage lumbar and hip rehabilitation.'},
{id:'sp41',cat:'Sport-Specific & Plyometric',name:'Eccentric Quad Loading (Spanish Squat)',pos:'Standing, band around post at knee height',sets:3,reps:'8-12',hold:'3 sec eccentric',freq:'2-3x/week',instr:'Loop a band around a post at knee height and around the back of both knees. Squat slowly with the shins vertical (band keeps shins upright), loading the quads eccentrically. Used as an alternative to leg extension machines for patellar tendinopathy and ACL rehabilitation.'},
{id:'n45',cat:'Neuro & Vestibular',name:'Constraint-Induced Movement Therapy (CIMT) - Lower Extremity',pos:'Walking',sets:1,reps:'3-6 hrs/day intensive practice',hold:'—',freq:'Daily for 2 weeks',instr:'Under intensive therapist guidance, practice forced use of the affected lower extremity through massed practice of functional tasks. Lower extremity CI therapy is an emerging application of the CIMT principles developed for the arm, used in post-stroke patients with mild to moderate lower extremity impairment.'},
{id:'pf28',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor and Hip Integration (Abductor with Pelvic Floor)',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Perform a hip abduction exercise while simultaneously maintaining a pelvic floor contraction throughout the movement. Coordination of the pelvic floor with extremity movement is important for managing continence during physical activity.'},
{id:'peds34',cat:'Pediatric',name:'Pediatric Strengthening Through Climbing',pos:'Playground climbing structure',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Encourage the child to climb age-appropriate structures under close supervision. Climbing is one of the most effective and naturally motivating ways to build upper and lower extremity strength, grip strength, and bilateral coordination in pediatric populations, providing progressive resistance through varying heights and grips.'},
// CERVICAL c67-c85 (19)
{id:'c67',cat:'Cervical',name:'Cervical Retraction in Supine with Towel Roll',pos:'Supine',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Lie on your back with a small rolled towel under your neck for support. Gently glide your chin backward without tilting the head up or down. The towel provides tactile feedback for neutral position. A gentler version of the seated chin tuck often better tolerated in acute neck pain.'},
{id:'c68',cat:'Cervical',name:'Cervical Rotation AROM Standing',pos:'Standing',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Stand tall with shoulders relaxed. Slowly rotate your head to one side as far as comfortably possible, hold briefly, then return to center. Repeat to the other side. A basic active range of motion exercise tracking cervical rotation progress throughout rehabilitation.'},
{id:'c69',cat:'Cervical',name:'Upper Trap Stretch with Ipsilateral Arm Hold',pos:'Seated',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Sit on your right hand to anchor the right shoulder. Tilt your left ear toward the left shoulder, adding a gentle overpressure with the left hand on the right side of your head. Feel the stretch along the right upper trapezius. Hold, then switch sides.'},
{id:'c70',cat:'Cervical',name:'Levator Scapulae Stretch',pos:'Seated',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Sit on your right hand to fix the right shoulder. Rotate your head 45 degrees to the left, then tilt your nose toward your left armpit. Hold. Feel the stretch in the right levator scapulae running from the upper neck to the shoulder blade. Switch sides and repeat.'},
{id:'c71',cat:'Cervical',name:'Scalene Stretch (Anterior)',pos:'Seated',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Sit tall. Tilt your head away from the side being stretched and slightly extend your neck while rotating slightly toward the stretch side. Feel the stretch along the front and side of the neck into the upper chest. Hold. Targets the anterior scalene, a common contributor to neck pain and thoracic outlet symptoms.'},
{id:'c72',cat:'Cervical',name:'Sternocleidomastoid Stretch',pos:'Seated',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Sit on your right hand. Rotate your head to the right and tilt your chin upward, feeling a stretch along the left sternocleidomastoid muscle running from behind the ear to the collarbone. Hold, then switch. The SCM is commonly tight in forward head posture.'},
{id:'c73',cat:'Cervical',name:'Suboccipital Release (Self)',pos:'Supine',sets:1,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Lie on your back and interlace your fingers, placing the bony ridge at the base of your skull (occiput) on the knuckles. Allow the weight of your head to create gentle pressure into the suboccipital muscles. Hold and breathe, allowing the muscles to release slowly. Targets the suboccipitals, a common source of tension headaches.'},
{id:'c74',cat:'Cervical',name:'Cervical Rotation Active Assisted (Stick)',pos:'Supine',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'Lie on your back. Hold a short stick or dowel and place one end lightly on your chin. Use the stick to assist the rotation of your head to each side, adding a small additional range at end range. Reduces active muscle demand allowing more range to be accessed comfortably.'},
{id:'c75',cat:'Cervical',name:'Head and Neck Relaxation in Gravity Eliminated Position',pos:'Supine',sets:1,reps:'—',hold:'5-10 min',freq:'Daily',instr:'Lie on your back without a pillow. Allow your head to rest heavily on the surface, consciously releasing all neck muscle tension with each exhale. A rest position prescription used in acute cervical pain to offload compressed cervical structures and allow protective muscle guarding to reduce.'},
{id:'c76',cat:'Cervical',name:'Cervical AROM Full Sequence',pos:'Seated',sets:2,reps:'5 each direction',hold:'2 sec',freq:'Daily',instr:'Perform all six cervical motions in sequence: flexion, extension, left rotation, right rotation, left side bend, right side bend. Move slowly and only as far as comfortable. Used as a daily mobility warm-up routine and to monitor range of motion changes throughout the rehab program.'},
{id:'c77',cat:'Cervical',name:'Cervical Traction with Towel (Supine Self)',pos:'Supine',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Roll a bath towel and place it under the base of your skull. Hold each end and gently pull both ends forward and slightly upward, creating a gentle longitudinal traction force through the cervical spine. Used for facet joint compression pain and cervical radiculopathy where traction provides relief.'},
{id:'c78',cat:'Cervical',name:'Neural Mobilization - Median Nerve Cervical',pos:'Supine',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Lie on your back. Depress the shoulder and bend the elbow, then slowly straighten the elbow while simultaneously wrist extending and side bending your head away. This sequences the median nerve through its cervical and upper extremity course. Used for cervical radiculopathy with C6-C7 nerve root involvement.'},
{id:'c79',cat:'Cervical',name:'Cervical Segmental Self-Mobilization (Rotation with Towel)',pos:'Seated',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Place a folded towel around the back of the neck, holding one end in each hand. Pull forward on one side to create a rotational force at a specific cervical level. Rotate your head in the same direction the towel is pulling while maintaining the towel tension. A self-mobilization technique for restricted cervical rotation.'},
{id:'c80',cat:'Cervical',name:'Wall Angel with Chin Tuck',pos:'Standing against wall',sets:3,reps:'10',hold:'2 sec at top',freq:'Daily',instr:'Stand with your back flat against a wall, heels 2 inches from the base. Perform a chin tuck. Then raise both arms up along the wall in a Y shape while keeping the back of the head, back, and arms in contact with the wall throughout. Combines cervical and scapular postural correction.'},
{id:'c81',cat:'Cervical',name:'Cervical Flexion Strengthening (Band Resisted Nod)',pos:'Seated',sets:3,reps:'12',hold:'3 sec',freq:'Daily',instr:'Loop a band around your head at forehead level, anchored behind you. Perform a chin tuck and nod motion against the resistance pulling your head backward. Directly strengthens the deep and superficial cervical flexors against functional resistance.'},
{id:'c82',cat:'Cervical',name:'Cervical Extension Isometric (Manual Resistance)',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Place both hands on the back of your head. Gently push the head forward while resisting with the neck extensors, creating an isometric contraction without movement. Hold, then relax. A safe, low-load isometric for cervical extensor activation without joint compression.'},
{id:'c83',cat:'Cervical',name:'Cervical Side Bend AROM with Feedback',pos:'Seated against wall',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Sit with your back against a wall. Side bend your head so the ear approaches the shoulder, feeling the wall to ensure you do not rotate or lean forward during the motion. The wall provides proprioceptive feedback for pure lateral flexion movement quality.'},
{id:'c84',cat:'Cervical',name:'Cervical Stabilization with Ball Toss',pos:'Seated',sets:3,reps:'20 catches',hold:'—',freq:'Daily',instr:'Sit tall with a chin tuck. Have a partner toss a ball to you from different directions. Catch the ball while maintaining the cervical neutral position without losing the chin tuck or letting the head move forward. A functional dual-task cervical stabilization exercise.'},
{id:'c85',cat:'Cervical',name:'Pillow Positioning for Sleep',pos:'Side-lying or supine',sets:1,reps:'—',hold:'During sleep',freq:'Nightly',instr:'Position a cervical pillow or rolled towel to maintain neutral cervical spine alignment during sleep. Side lying: the pillow height should fill the space between the ear and shoulder. Supine: a cervical contour pillow or a roll in the pillow case to support the natural curve. Poor sleep posture is a major perpetuating factor in cervical pain.'},
// SHOULDER s107-s125 (19)
{id:'s107',cat:'Shoulder',name:'Shoulder Abduction AROM in Scapular Plane',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand and raise the arm out to the side and slightly forward (30 degrees forward from the coronal plane). Keep the thumb pointing upward. Raise to shoulder height initially and progress to overhead as tolerated. Movement in the scapular plane is the most natural and least impingement-provoking direction for shoulder elevation.'},
{id:'s108',cat:'Shoulder',name:'Active-Assisted Shoulder Flexion (Pulleys)',pos:'Seated under pulleys',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit under an overhead pulley system. Hold one handle in each hand. Use the non-affected arm to pull the rope, raising the affected arm passively overhead. Lower the affected arm under its own control, using the pulley as a brake. A classic early post-surgical overhead shoulder mobility exercise.'},
{id:'s109',cat:'Shoulder',name:'Shoulder Shrug Resisted',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a dumbbell or resistance band in each hand. Elevate both shoulders straight up toward the ears against resistance. Hold briefly, then lower slowly. Strengthens the upper trapezius, used in patients with shoulder elevation weakness or upper trap inhibition following neck or shoulder injury.'},
{id:'s110',cat:'Shoulder',name:'Diagonal Proprioceptive Neuromuscular Facilitation (PNF) D2 Flexion',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Starting with the arm across the body at hip level with the palm down, sweep the arm upward and outward to finish overhead with the palm facing behind you. Reverse for D2 extension. A functional diagonal strengthening pattern combining shoulder flexion, abduction, and external rotation used throughout shoulder rehabilitation.'},
{id:'s111',cat:'Shoulder',name:'Prone Shoulder Extension (Kickback)',pos:'Prone on bench',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down with the affected arm hanging off the edge of a bench. Hold a light weight. Extend the arm backward past the hip, keeping the elbow straight. Lower slowly. A gravity-resisted shoulder extension exercise targeting the posterior deltoid and teres major.'},
{id:'s112',cat:'Shoulder',name:'Push-Up Progression (Wall to Floor)',pos:'Standing to prone, varies',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Progress push-ups through this hierarchy: wall push-up, countertop push-up, incline push-up (hands on step), standard floor push-up, push-up with feet elevated. Each progression increases body weight percentage and demand on the shoulder stabilizers. Only advance when the current level is clean and pain-free.'},
{id:'s113',cat:'Shoulder',name:'Shoulder IR Strengthening (Band)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band to the side at elbow height. With the elbow bent 90 degrees and held against the body, rotate the forearm inward toward the belly against the resistance. Slowly return. Strengthens the subscapularis and anterior deltoid. Important to balance with ER strengthening in a 2:3 ratio for shoulder health.'},
{id:'s114',cat:'Shoulder',name:'Shoulder Adduction Strengthening (Band)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band overhead on the same side. With the arm raised at 90 degrees abduction, pull the arm downward toward the side against the resistance of the overhead band. Strengthens the latissimus dorsi and teres major in a functional adduction pattern.'},
{id:'s115',cat:'Shoulder',name:'Posterior Cuff Strengthening (Prone ER at 90)',pos:'Prone on table, arm at 90 abduction',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down with the arm hanging off the table at 90 degrees abduction, elbow bent 90 degrees. Rotate the forearm toward the ceiling (external rotation). Hold, then lower. A highly specific exercise for the infraspinatus and teres minor in the position most relevant to overhead activities.'},
{id:'s116',cat:'Shoulder',name:'Side-Lying Shoulder Flexion (Gravity Eliminated)',pos:'Side-lying on affected side',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on the affected side. Raise the arm forward (flexion) along the floor, eliminating gravity from the movement. Used in very early or acutely painful shoulder conditions when gravity-loaded exercises are not yet appropriate. A true gravity-eliminated position for shoulder flexion.'},
{id:'s117',cat:'Shoulder',name:'Overhead Reach in Standing (Wall Slide)',pos:'Standing facing wall',sets:3,reps:'15',hold:'2 sec at top',freq:'Daily',instr:'Stand with both forearms on the wall at shoulder height. Slide both arms upward along the wall toward full overhead reach while keeping the forearms in contact with the surface. Return. The wall guides the motion and reduces compensation, making it a safe and effective overhead mobility exercise.'},
{id:'s118',cat:'Shoulder',name:'Shoulder Flexion Isometric at Multiple Angles',pos:'Standing near wall',sets:3,reps:'5 per angle',hold:'10 sec',freq:'Daily',instr:'Press the forearm or palm into a wall at 30, 60, 90, and 120 degrees of shoulder flexion. Hold an isometric contraction at each angle. Builds shoulder flexor strength through the range in a joint-friendly manner appropriate early in rehabilitation.'},
{id:'s119',cat:'Shoulder',name:'Shoulder Extension Isometric',pos:'Standing',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Stand with your back against a wall. Press the backs of your hands or forearms backward into the wall behind you. Hold an isometric extension contraction. A safe early exercise for shoulder extension strength when dynamic exercises are restricted.'},
{id:'s120',cat:'Shoulder',name:'Horizontal Abduction with Band (Prone)',pos:'Prone on bench or bed',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down with both arms hanging. Hold a band in each hand anchored under the bench. Raise both arms outward to horizontal (T position) against the resistance, squeezing the shoulder blades together. A combined posterior deltoid and middle trap exercise.'},
{id:'s121',cat:'Shoulder',name:'Shoulder AROM - Hand Behind Head',pos:'Seated or supine',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Place the hand of the affected arm behind your head and touch the back of your neck. Hold, then lower. Combines shoulder abduction, external rotation, and flexion. This functional end-range position is often one of the last to recover and is the position needed for hair care, dressing, and neck scratching.'},
{id:'s122',cat:'Shoulder',name:'Shoulder Compression Strengthening (Quadruped)',pos:'Quadruped',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Hold a hands-and-knees position with hands directly under shoulders. Maintain stable shoulder blades (neither winging nor over-depressed). This weight-bearing position builds co-contraction stability at the glenohumeral and scapulothoracic joints simultaneously in a closed kinetic chain.'},
{id:'s123',cat:'Shoulder',name:'Capsular Stretching Program (All Three Planes)',pos:'Supine',sets:3,reps:'3 each direction',hold:'30 sec',freq:'2x/day',instr:'Systematically stretch the three capsular directions in sequence: posterior capsule (horizontal adduction), inferior capsule (side-lying ER stretch), and anterior capsule (doorway stretch). Addressing all three components is necessary for complete capsular mobilization in adhesive capsulitis.'},
{id:'s124',cat:'Shoulder',name:'Functional Shoulder Reach Training (ADL Simulation)',pos:'Standing',sets:3,reps:'10 each task',hold:'—',freq:'Daily',instr:'Practice reaching overhead to simulate retrieving items from shelves, reaching behind to simulate dressing, and reaching across to simulate seatbelt use. Functional simulation makes rehabilitation specific to the activities patients report losing due to shoulder pain.'},
{id:'s125',cat:'Shoulder',name:'Rotator Cuff Progressive Resistance Program',pos:'Standing',sets:3,reps:'12-15',hold:'—',freq:'Daily',instr:'Perform your complete rotator cuff program in sequence: IR, ER, scaption, and prone Y/T/W, progressing resistance by one band color or 1 lb every two weeks when 3 sets of 15 can be performed with good form. Systematic progressive overload is the mechanism of strength gain in rotator cuff rehabilitation.'},
// ELBOW & WRIST e78-e95 (18)
{id:'e78',cat:'Elbow & Wrist',name:'Elbow Flexion AROM with Forearm Supination',pos:'Seated, forearm starting pronated',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Begin with the elbow straight and forearm pronated (palm down). As you flex the elbow, simultaneously supinate the forearm (turn palm up). This biceps-specific motion simultaneously recruits both the flexion and supination functions of the biceps brachii.'},
{id:'e79',cat:'Elbow & Wrist',name:'Triceps Strengthening - Overhead Extension',pos:'Standing or seated',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Hold a dumbbell with both hands and raise it overhead. Bend the elbows to lower the weight behind your head, then straighten the elbows to raise it back overhead. Keeps the elbows pointing toward the ceiling throughout. Strengthens the long head of the triceps in its lengthened position.'},
{id:'e80',cat:'Elbow & Wrist',name:'Triceps Kickback',pos:'Standing, hinged forward',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a dumbbell and hinge forward at the hips. Fix the upper arm parallel to the floor. Extend the elbow, straightening the arm behind you. Hold, then bend slowly. Isolates the lateral head of the triceps in a range of motion typical of pushing and reaching activities.'},
{id:'e81',cat:'Elbow & Wrist',name:'Biceps Eccentric Curl (Slow Lower)',pos:'Seated or standing',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Curl the weight up in 1 second using both arms if needed. Transfer the weight to the affected arm. Lower the weight slowly over 4-5 seconds against gravity (eccentric phase). Eccentric biceps loading is used for distal biceps tendinopathy and post-surgical strengthening.'},
{id:'e82',cat:'Elbow & Wrist',name:'Wrist Radial Deviation Strengthening',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest the forearm on the table with the thumb pointing up (neutral position). Hold a hammer or weight at the end of the handle. Move the wrist toward the thumb side (radial deviation) against gravity. Slowly return. Strengthens the flexor and extensor carpi radialis together.'},
{id:'e83',cat:'Elbow & Wrist',name:'Wrist Ulnar Deviation Strengthening',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest the forearm on the table with the thumb pointing up. Hold a hammer at the end of the handle. Move the wrist toward the pinky side (ulnar deviation) against gravity. Slowly return. Strengthens the flexor and extensor carpi ulnaris.'},
{id:'e84',cat:'Elbow & Wrist',name:'Forearm Pronation Eccentric',pos:'Seated, elbow at 90',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Hold a hammer with the head down (pronated position). Slowly supinate as far as possible using both hands, then control the return to pronation using the affected arm only over a 4-second eccentric count. Eccentric loading for pronator teres tendinopathy or post-surgical conditioning.'},
{id:'e85',cat:'Elbow & Wrist',name:'Finger Abduction and Adduction (Band)',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Place a rubber band around all five fingers. Spread the fingers apart against the resistance of the band, then bring them back together. Then place the band around adjacent pairs of fingers and work them against each other. Builds intrinsic hand muscle strength, important for grip control and fine motor tasks.'},
{id:'e86',cat:'Elbow & Wrist',name:'Grip and Release (Putty)',pos:'Seated',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Squeeze therapy putty into a full fist grip, hold, then fully extend all fingers to release. Use progressively firmer putty as strength improves. The opening phase works the extensors while the squeeze works the flexors, making this a complete hand strengthening exercise.'},
{id:'e87',cat:'Elbow & Wrist',name:'Putty Finger Extension (Individual Fingers)',pos:'Seated',sets:3,reps:'10 per finger',hold:'2 sec',freq:'Daily',instr:'Embed one finger in a ball of putty. Extend that finger against the resistance of the putty while keeping other fingers relaxed. Work each finger individually. Isolates finger extensor strengthening, important after extensor tendon repair, boutonniere deformity, or mallet finger.'},
{id:'e88',cat:'Elbow & Wrist',name:'Carpal Tunnel Syndrome (CTS) Tendon and Nerve Glide',pos:'Seated',sets:3,reps:'10 each position',hold:'3 sec',freq:'Daily',instr:'Move through five hand positions in sequence: straight (fingers and wrist extended), hook (MCP extended, IP flexed), full fist, tabletop (MCP flexed, IP extended), and straight wrist with thumb abducted. Each position glides the median nerve and flexor tendons through the carpal tunnel in a different configuration.'},
{id:'e89',cat:'Elbow & Wrist',name:'Wrist Cock-Up Splint Wearing Schedule',pos:'Varies',sets:1,reps:'—',hold:'As prescribed',freq:'As directed',instr:'Wear the wrist cock-up (extension) splint during the activities and sleep hours prescribed by your therapist. The splint maintains the wrist in a neutral or slightly extended position to reduce median nerve pressure in the carpal tunnel. Never increase wear time beyond prescribed without guidance.'},
{id:'e90',cat:'Elbow & Wrist',name:'Scaphoid Shift Test Position Strengthening',pos:'Seated, forearm supported',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Hold the wrist in slight ulnar deviation and perform controlled wrist flexion and extension while stabilizing the scaphoid with thumb pressure as directed. Used in chronic scapholunate ligament instability to strengthen the dynamic stabilizers that compensate for ligamentous laxity.'},
{id:'e91',cat:'Elbow & Wrist',name:'Epicondyle Stretching (Lateral) - Wrist Flexion with Elbow Straight',pos:'Standing or seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Extend the affected arm in front of you with the elbow straight. Use the other hand to bend the wrist downward (flexion) and toward ulnar deviation. Feel the stretch along the lateral forearm and elbow. The gold standard stretch for lateral epicondylalgia, most effective with the elbow fully extended.'},
{id:'e92',cat:'Elbow & Wrist',name:'Epicondyle Stretching (Medial) - Wrist Extension with Elbow Straight',pos:'Standing or seated',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Extend the affected arm with the elbow straight. Use the other hand to bend the wrist upward (extension). Feel the stretch along the medial forearm and inner elbow. The primary stretch for medial epicondylalgia.'},
{id:'e93',cat:'Elbow & Wrist',name:'Dynamic Wrist Stabilization (Function Board)',pos:'Seated',sets:3,reps:'10 min',hold:'—',freq:'Daily',instr:'Perform functional tasks on a tilting balance board held in both hands, keeping the board level. Challenges wrist co-contraction and dynamic stability in multiple directions simultaneously. Used in later stages of wrist sprain and DRUJ rehabilitation.'},
{id:'e94',cat:'Elbow & Wrist',name:'Elbow Hyperextension Prevention Strengthening',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'With the elbow in slight flexion, press into a band anchored in front at elbow height, working the elbow flexors to prevent hyperextension. Combined with proprioception training. Used in gymnasts, dancers, and hypermobile patients to protect the elbow joint from excessive extension loading.'},
{id:'e95',cat:'Elbow & Wrist',name:'Return to Throwing Elbow Strengthening Circuit',pos:'Standing',sets:3,reps:'15 each',hold:'—',freq:'Daily',instr:'Perform your elbow throwing circuit in sequence: wrist flexion, wrist extension, radial deviation, ulnar deviation, forearm pronation, forearm supination, and elbow flexion. Complete the circuit with light resistance before advancing to interval throwing. Used in baseball, tennis, and javelin throwing rehabilitation.'},
// CORE & LUMBAR l98-l117 (20)
{id:'l98',cat:'Core & Lumbar',name:'Abdominal Isometric (Bracing Against Band)',pos:'Standing',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Stand with a band looped around the waist and anchored behind you, creating a forward pull on the abdomen. Brace the core 360 degrees to resist the forward pull without allowing the spine to extend or the belly to push forward. A functional standing anti-extension core exercise.'},
{id:'l99',cat:'Core & Lumbar',name:'Pallof Press (Anti-Rotation)',pos:'Standing',sets:3,reps:'10 each side',hold:'2 sec extended',freq:'Daily',instr:'Stand sideways to a cable or band anchor at chest height. Hold the handle with both hands at your chest. Press the handle straight out in front of you and hold, resisting the rotational pull of the cable. Return. The Pallof press is a fundamental anti-rotation core exercise that mirrors the demands of many daily and sporting activities.'},
{id:'l100',cat:'Core & Lumbar',name:'Suitcase Carry',pos:'Standing, walking',sets:3,reps:'20-30 meters each side',hold:'—',freq:'Daily',instr:'Hold a heavy dumbbell or kettlebell in one hand at your side. Walk for the prescribed distance while maintaining a perfectly upright posture and level pelvis, resisting the lateral lean caused by the asymmetric load. An anti-lateral-flexion core exercise that directly mimics carrying bags, groceries, or luggage.'},
{id:'l101',cat:'Core & Lumbar',name:'Farmer Carry (Bilateral)',pos:'Standing, walking',sets:3,reps:'20-30 meters',hold:'—',freq:'Daily',instr:'Hold a heavy weight in each hand at your sides. Walk for the prescribed distance while maintaining upright posture. A foundational functional strength exercise building grip, core, and total body postural endurance, commonly used in late-stage rehabilitation and work hardening programs.'},
{id:'l102',cat:'Core & Lumbar',name:'Dead Bug (Contralateral)',pos:'Supine, arms and knees at 90',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Lie on your back with arms pointing to the ceiling and hips and knees at 90 degrees. Brace your core and slowly lower the opposite arm and leg toward the floor simultaneously while keeping the low back pressed flat. Return to start. The dead bug specifically trains anti-extension core stability while the limbs act as levers.'},
{id:'l103',cat:'Core & Lumbar',name:'Dead Bug (Ipsilateral Progression)',pos:'Supine',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'From the dead bug starting position, lower the same-side arm and leg together (ipsilateral). This is more demanding on rotational control than the contralateral version. A progression of the dead bug series for intermediate core rehabilitation.'},
{id:'l104',cat:'Core & Lumbar',name:'Copenhagen Hip Adductor Exercise',pos:'Side-lying on elbow, top leg on bench',sets:3,reps:'10',hold:'2 sec',freq:'2-3x/week',instr:'Lie on your side with the top foot resting on a bench or chair at hip height. Lift your body off the floor using the top leg, creating a side plank position supported through the inner thigh. Hold, then lower. The Copenhagen exercise is the most evidence-supported exercise for adductor strengthening and groin injury prevention.'},
{id:'l105',cat:'Core & Lumbar',name:'Lunge Matrix (Multi-Directional)',pos:'Standing',sets:2,reps:'5 in each direction',hold:'2 sec',freq:'Daily',instr:'Perform a complete lunge matrix: forward lunge, 45-degree forward diagonal lunge, lateral lunge, 45-degree backward diagonal lunge, and reverse lunge — alternating legs. This addresses hip mobility and single-leg strength in multiple planes, used as a warm-up and therapeutic exercise in late rehabilitation.'},
{id:'l106',cat:'Core & Lumbar',name:'Standing Cable Row with Hip Hinge',pos:'Standing',sets:3,reps:'12',hold:'2 sec',freq:'Daily',instr:'Stand facing a low cable anchor. Hold the handle and hinge the hips back as you let the cable pull the arms forward, then drive the hips forward to standing while simultaneously rowing the handle to the hip. Combines hip extension with back rowing in a functional loaded movement.'},
{id:'l107',cat:'Core & Lumbar',name:'Split Stance Anti-Rotation Press',pos:'Standing in split stance',sets:3,reps:'10 each side',hold:'2 sec extended',freq:'Daily',instr:'Assume a split stance (one foot forward, one back). Perform a Pallof press from this position. The split stance increases the rotational challenge compared to parallel stance and mimics common sport and daily-activity positions.'},
{id:'l108',cat:'Core & Lumbar',name:'Single-Leg Deadlift (Romanian)',pos:'Standing',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on one leg. Hinge forward at the hip, extending the free leg behind you as the trunk lowers. Keep the spine neutral and the standing knee slightly bent. Return by driving through the standing heel. A single-leg posterior chain and core stability exercise used in hip, knee, and lumbar rehabilitation.'},
{id:'l109',cat:'Core & Lumbar',name:'Bear Crawl',pos:'Quadruped, knees hovering',sets:3,reps:'15-20 meters',hold:'—',freq:'Daily',instr:'Begin on hands and knees with knees hovering just off the ground. Crawl forward by moving the opposite hand and foot simultaneously, maintaining a neutral spine. A demanding core stability and shoulder girdle exercise that integrates the limb movements with trunk control in a developmental movement pattern.'},
{id:'l110',cat:'Core & Lumbar',name:'Inchworm',pos:'Standing to floor and back',sets:3,reps:'8',hold:'—',freq:'Daily',instr:'Stand tall. Walk your hands out to a plank position, hold briefly, then walk your feet in toward your hands and stand. A dynamic mobility and core stability warm-up exercise integrating hamstring flexibility, hip flexor mobility, and shoulder stability in a single movement.'},
{id:'l111',cat:'Core & Lumbar',name:'Lateral Band Walk with Trunk Stability',pos:'Standing',sets:3,reps:'15 steps each way',hold:'—',freq:'Daily',instr:'Place a band around both ankles. Hold a light weight at chest height or a medicine ball overhead to add core demand. Walk laterally, maintaining the trunk upright and the weight steady. The overhead or chest load increases anti-lateral-flexion demand during the lateral steps.'},
{id:'l112',cat:'Core & Lumbar',name:'Lumbar Stabilization in Sitting (No Back Rest)',pos:'Seated on stool or edge of chair',sets:3,reps:'—',hold:'1-5 min',freq:'Several times daily',instr:'Sit on a backless stool or perch on the edge of a chair. Maintain a neutral lumbar lordosis without resting against any support. Progress the duration and add arm movements or light work tasks. A functional endurance exercise for the lumbar stabilizers performed in a position most patients spend significant time in.'},
{id:'l113',cat:'Core & Lumbar',name:'Supine Pelvic Tilt Clock',pos:'Supine, knees bent',sets:3,reps:'10 complete circuits',hold:'—',freq:'Daily',instr:'Lie on your back with knees bent. Imagine a clock face on your pelvis. Tilt the pelvis to the 12 (anterior tilt), then 3, then 6 (posterior tilt), then 9, moving through all clock positions in a smooth circle. Develops lumbopelvic motor control and coordination in multiple directions.'},
{id:'l114',cat:'Core & Lumbar',name:'Thoracolumbar Rotation with Arms Extended (Standing)',pos:'Standing',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Stand with arms extended forward at shoulder height. Rotate the entire trunk to one side as far as comfortable, following the hands with your eyes. Return to center and rotate the other way. A full thoracolumbar rotation mobility exercise used for stiffness, post-surgical rehabilitation, and general mobility.'},
{id:'l115',cat:'Core & Lumbar',name:'Posterior Pelvic Tilt in Standing Against Wall',pos:'Standing against wall',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Stand with your back against a wall, heels about 2 inches out. Flatten your low back against the wall by tilting the pelvis posteriorly. Hold, then release. A fundamental posture and pelvic control exercise that also activates the deep abdominals and reduces lumbar lordosis, used in low back pain management.'},
{id:'l116',cat:'Core & Lumbar',name:'Hip Extension in Standing (Glute Kickback) with Band',pos:'Standing',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand with a band around the ankle, anchored in front. Keeping the knee straight and the trunk upright, extend the hip backward against the band resistance. Hold at the end range, then return slowly. Targets the gluteus maximus while requiring the contralateral core to stabilize the pelvis.'},
{id:'l117',cat:'Core & Lumbar',name:'TRX Single-Leg Squat',pos:'Standing holding TRX handles',sets:3,reps:'10 each leg',hold:'2 sec at bottom',freq:'Daily',instr:'Hold TRX handles for balance assistance. Stand on one leg and lower into a single-leg squat to the prescribed depth, using the TRX handles to offload as needed. The TRX allows patients to train single-leg squat mechanics before they have the strength or balance to perform it independently.'},
// HIP h85-h103 (19)
{id:'h85',cat:'Hip',name:'Hip Flexor Strengthening in Supine (Straight Leg Raise)',pos:'Supine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with one knee bent and the other leg straight. Tighten the quad of the straight leg and raise it to the height of the bent knee. Hold briefly, then lower slowly. A fundamental hip flexor exercise that also recruits the quad, used throughout knee and hip rehabilitation.'},
{id:'h86',cat:'Hip',name:'Hip Adductor Strengthening (Squeeze in Bridge)',pos:'Supine in bridge',sets:3,reps:'15',hold:'5 sec',freq:'Daily',instr:'Place a soft ball between the knees and perform a bridge. Squeeze the ball throughout the entire bridge hold. Simultaneously activates the hip adductors and the glutes, improving coordination between these two muscle groups that share pelvic control.'},
{id:'h87',cat:'Hip',name:'Hip Extension Strengthening - Donkey Kick',pos:'Quadruped',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'On hands and knees, kick one leg backward and upward with the knee bent to 90 degrees, pressing the sole of the foot toward the ceiling. Hold at the top, then lower. Targets the gluteus maximus in a position that limits hamstring contribution due to knee flexion.'},
{id:'h88',cat:'Hip',name:'Hip Flexion Stretch (Kneeling Psoas)',pos:'Half-kneeling',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Kneel on the affected knee with the other foot forward. Maintain an upright trunk and tuck the pelvis slightly under (posterior tilt). Shift your weight forward until you feel a stretch at the front of the kneeling hip. This is the most specific stretch for the iliopsoas and is the standard hip flexor stretch used in PT.'},
{id:'h89',cat:'Hip',name:'Adductor Stretching (Long Sitting)',pos:'Long sit on floor',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Sit on the floor with legs spread wide apart. Lean your trunk forward between the legs, keeping the back as straight as possible. Hold. A standard adductor flexibility exercise. Progress by increasing the leg spread width and the forward lean over time.'},
{id:'h90',cat:'Hip',name:'Seated Hip ER Stretch (Figure 4 in Chair)',pos:'Seated',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Sit in a chair. Cross the ankle of the affected leg over the opposite knee. Gently press the crossed knee downward while keeping the back straight. Feel the stretch in the outer hip. Can be deepened by leaning the trunk forward. A universally prescribed deep hip rotator stretch accessible to all patients.'},
{id:'h91',cat:'Hip',name:'Hip Abduction Standing (Unloaded)',pos:'Standing near support',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand holding a support with one hand. Lift the opposite leg directly out to the side without hiking the hip. Keep the knee straight and toes pointing forward. Lower slowly. A foundational hip abductor strengthening exercise used early in hip and knee rehabilitation.'},
{id:'h92',cat:'Hip',name:'Hip Extension in Prone (Straight Leg)',pos:'Prone',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Lie face down with legs straight. Tighten the glute and lift one leg off the surface a few inches, keeping the knee straight. Hold briefly, then lower. A low-level glute max exercise appropriate for early hip rehabilitation when loaded exercises are not yet tolerated.'},
{id:'h93',cat:'Hip',name:'Seated Hip Flexion Resisted (Chair)',pos:'Seated',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Sit in a chair with a resistance band around the thigh just above the knee, anchored under the chair. Lift the knee against the resistance. Hold, then lower. A seated, low-demand hip flexor exercise appropriate for patients who cannot tolerate standing exercises.'},
{id:'h94',cat:'Hip',name:'Standing Hip Circles (Controlled)',pos:'Standing on one leg',sets:2,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Stand on one leg with a hand on a support. Draw controlled circles with the lifted knee, first small and then larger. The standing leg builds single-leg stability while the moving leg works on hip mobility in all directions. A dynamic hip warm-up exercise.'},
{id:'h95',cat:'Hip',name:'Hip Mobility Flow (CARs)',pos:'Standing',sets:2,reps:'5 each side',hold:'—',freq:'Daily',instr:'Perform a controlled articular rotation (CAR) at the hip: slowly move the hip through its complete active range of motion in a large circle, using maximum active muscle control at every point. A joint health and active mobility exercise used in sports medicine and hip rehabilitation to maintain and develop joint range.'},
{id:'h96',cat:'Hip',name:'Resisted Hip Flexion in Standing (High Knee)',pos:'Standing',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand with a band anchored below and looped around the thigh. Drive the knee upward to 90 degrees against resistance. Hold at the top, then lower. Functional standing hip flexor strengthening in the position most relevant to walking, stair climbing, and running.'},
{id:'h97',cat:'Hip',name:'Hip Abductor Isometric in Standing (Lateral Wall Press)',pos:'Standing sideways to wall',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Stand sideways next to a wall with the outer leg against it. Press the outer leg into the wall without moving. Hold the isometric contraction. A zero-pain-risk isometric for the hip abductors useful when dynamic loading provokes symptoms.'},
{id:'h98',cat:'Hip',name:'Supine Hip ER Strengthening (Clamshell with Resistance)',pos:'Side-lying with resistance band',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your side with a resistance band around both thighs above the knees. Perform clamshells against the resistance of the band. A standard progression of the body-weight clamshell used extensively in hip and knee rehabilitation.'},
{id:'h99',cat:'Hip',name:'Hip Flexor Eccentric (Forward Step Down)',pos:'Standing on step',sets:3,reps:'12 each',hold:'—',freq:'Daily',instr:'Stand on a step on the affected leg. Use the hip flexor of the stance leg to control the lowering of the opposite leg toward the floor. Slowly lower and then raise again. Focuses on eccentric hip flexor loading on the step-standing leg, used for hip flexor tendinopathy and FAI rehabilitation.'},
{id:'h100',cat:'Hip',name:'Prone Hip Abduction (Gravity Eliminated)',pos:'Prone',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Lie face down. Move one leg out to the side along the surface (abduction in a gravity-eliminated position). Return. Used early in hip abductor rehabilitation when weakness is severe and gravity-loaded exercises are not yet appropriate.'},
{id:'h101',cat:'Hip',name:'Hip Internal Rotator Stretch in Prone',pos:'Prone, knee bent 90',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Lie face down with the knee bent to 90 degrees. Allow the foot to fall inward (toward the other foot), moving the hip into internal rotation. Gently press the foot toward the floor for a deeper stretch. Used when hip IR range is limited due to posterior capsule tightness or external rotator shortening.'},
{id:'h102',cat:'Hip',name:'Groin Progressive Strengthening (Standing Adduction with Band)',pos:'Standing',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand with a band anchored to the outside of the affected leg at ankle level. Bring the leg across the midline against the resistance (adduction). Return slowly. A progressive loading exercise for the adductors used in groin strain rehabilitation.'},
{id:'h103',cat:'Hip',name:'Hip Strength Endurance Circuit',pos:'Standing',sets:2,reps:'15 each exercise',hold:'—',freq:'Daily',instr:'Perform a hip strengthening circuit without rest between exercises: hip abduction, hip extension, hip flexion, and hip IR in sequence on one leg, then switch sides. Building hip muscle endurance alongside maximal strength is important for sustaining correct lower limb mechanics through prolonged activity.'},
// KNEE k84-k102 (19)
{id:'k84',cat:'Knee',name:'Quad Set',pos:'Supine or seated, leg straight',sets:3,reps:'10',hold:'10 sec',freq:'Every 1-2 hrs',instr:'Lie on your back or sit with the leg straight. Tighten the front of the thigh (quadriceps) by pushing the back of the knee gently toward the floor. Hold, then relax completely. The most foundational quad activation exercise, used immediately after knee surgery or injury to prevent quad atrophy.'},
{id:'k85',cat:'Knee',name:'Terminal Knee Extension (TKE)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band behind the knee. Stand with the knee slightly bent. Fully straighten the knee against the forward pull of the band. Hold briefly at full extension. Works the VMO and terminal quad control, critical for normal gait push-off mechanics and patellar tracking.'},
{id:'k86',cat:'Knee',name:'Seated Knee Extension Machine (Light)',pos:'Seated on knee extension machine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in the knee extension machine set to a light resistance. Extend the knee fully and hold briefly. Lower slowly. Only use through the range cleared by your therapist, as some post-surgical protocols restrict ranges temporarily. A direct quad strengthening exercise commonly used in knee rehabilitation programs.'},
{id:'k87',cat:'Knee',name:'Step-Up (Forward)',pos:'Standing at step',sets:3,reps:'15 each leg',hold:'2 sec at top',freq:'Daily',instr:'Stand facing a step. Place the affected foot on the step. Press through the step foot to raise your body fully upright on the step, bringing the other foot to step level. Step back down with control. Start with a low step (4 inches) and progress height as strength improves. A fundamental lower extremity functional strengthening exercise.'},
{id:'k88',cat:'Knee',name:'Step-Up (Lateral)',pos:'Standing beside step',sets:3,reps:'15 each leg',hold:'2 sec at top',freq:'Daily',instr:'Stand beside a step with the affected leg closer to it. Step laterally up onto the step with the affected foot, bring the other foot up, then step back down. Addresses the hip abductors and VMO in a different plane than the forward step-up.'},
{id:'k89',cat:'Knee',name:'Leg Press (Bilateral, Light to Moderate)',pos:'Leg press machine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Position yourself in the leg press machine with feet shoulder-width apart and toes slightly turned out. Press through both heels to fully extend the knees (stop just short of lockout). Lower slowly to the prescribed angle. A controlled, supported quad and glute strengthening exercise.'},
{id:'k90',cat:'Knee',name:'Calf Raise with Knee Bend (Soleus Focus)',pos:'Standing on step',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on a step with knees bent to 30 degrees throughout the movement. Rise onto the toes and lower below step height. The bent knee position slackens the gastrocnemius, isolating the soleus. Used for soleus strengthening, insertional Achilles rehabilitation, and knee flexion contracture management.'},
{id:'k91',cat:'Knee',name:'Seated Hamstring Curl',pos:'Seated, leg straight at start',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in a chair or on a table. Hook a resistance band around the ankle and anchor it in front. Curl the heel backward under the chair against the resistance. The seated position maintains a more functional hip angle than the prone curl. Used in hamstring rehabilitation and ACL programs.'},
{id:'k92',cat:'Knee',name:'Hamstring Bridge (Double Leg with Feet Elevated)',pos:'Supine, heels on chair',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Lie on your back with heels resting on a chair or bench. Drive through the heels to lift the hips into a bridge. With heels elevated, the hamstrings take on more of the hip extension load compared to a floor bridge. A progression of the standard bridge that bridges the gap to more demanding hamstring exercises.'},
{id:'k93',cat:'Knee',name:'Hamstring Bridge (Single Leg with Feet Elevated)',pos:'Supine, one heel on chair',sets:3,reps:'12 each',hold:'3 sec',freq:'Daily',instr:'From the elevated double-leg bridge position, straighten one knee and hold the bridge on the single leg. A significant hamstring strengthening progression used in the mid stages of hamstring strain and ACL rehabilitation.'},
{id:'k94',cat:'Knee',name:'Reverse Lunge',pos:'Standing',sets:3,reps:'12 each leg',hold:'2 sec at bottom',freq:'Daily',instr:'Step backward with one leg, lowering the back knee toward the floor. The front knee stays stacked over the front ankle. Return by pushing through the front foot. A lunge variation that loads the front leg more effectively than the forward lunge and is often better tolerated with knee conditions due to reduced forward shear forces.'},
{id:'k95',cat:'Knee',name:'Wall Squat with Ball Between Knees',pos:'Standing against wall',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Stand with your back against a wall, feet 18 inches out. Hold a ball between the knees and slide down to the prescribed angle (often 60-90 degrees). Squeeze the ball gently and hold. Activates the adductors alongside the quads, improving overall knee stability during sustained loading.'},
{id:'k96',cat:'Knee',name:'Resisted Knee Flexion in Standing (Hamstring)',pos:'Standing, band at ankle',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand with a resistance band around the ankle, anchored in front. Curl the heel toward the buttock against the resistance of the band. Hold at end range, then lower slowly. A standing hamstring curl providing more functional loading than a prone curl.'},
{id:'k97',cat:'Knee',name:'Agility Ladder Drills (Basic)',pos:'Standing at ladder',sets:3,reps:'3 lengths',hold:'—',freq:'2-3x/week',instr:'Perform basic agility ladder drills: single-leg hops in each square, two-feet-in, lateral shuffles, and in-in-out-out. A mid to late-stage return-to-sport exercise building foot speed, coordination, and lower extremity neuromuscular control.'},
{id:'k98',cat:'Knee',name:'Plyometric Box Jump',pos:'Standing in front of box',sets:3,reps:'8',hold:'2 sec land',freq:'2-3x/week',instr:'Stand in front of a low to moderate box. Swing arms and bend knees, then jump upward and forward onto the box. Land softly with both feet and hold the landing position before stepping down. A fundamental plyometric exercise building explosive knee extension power and controlled landing mechanics.'},
{id:'k99',cat:'Knee',name:'Plyometric Broad Jump',pos:'Standing',sets:3,reps:'6',hold:'2 sec land',freq:'2-3x/week',instr:'Stand with feet shoulder-width. Bend the knees and swing the arms, then jump forward as far as possible. Land softly on both feet with the knees bent and hold the landing. One of the four standard hop tests used in ACL return-to-sport testing, and also an effective plyometric training exercise.'},
{id:'k100',cat:'Knee',name:'Plyometric Lateral Box Jump',pos:'Standing beside box',sets:3,reps:'8 each direction',hold:'—',freq:'2-3x/week',instr:'Stand beside a low box. Jump laterally onto the box, land softly, then immediately jump laterally off the other side to the floor. Continue jumping back and forth. Builds lateral explosive power and reactive landing mechanics used in court and field sports.'},
{id:'k101',cat:'Knee',name:'Knee Proprioception - Single-Leg Squat with Eyes Closed',pos:'Standing',sets:3,reps:'10 each leg',hold:'2 sec at bottom',freq:'Daily',instr:'Perform a shallow single-leg squat to approximately 30-45 degrees with eyes closed. The absence of visual input requires the knee and ankle proprioceptive systems to work harder to maintain balance. A demanding proprioception exercise used in the later stages of knee rehabilitation.'},
{id:'k102',cat:'Knee',name:'Functional Movement Screen Squat Correction',pos:'Standing, overhead squat',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Hold a dowel overhead with arms straight. Perform a deep squat while maintaining the dowel directly above the feet. Address any limitations identified in the FMS squat screen: ankle dorsiflexion, thoracic extension, hip flexion, or shoulder mobility restrictions. A corrective exercise based on functional movement screening findings.'},
// ANKLE & FOOT a75-a90 (16)
{id:'a75',cat:'Ankle & Foot',name:'Ankle Pumps',pos:'Supine, elevated',sets:3,reps:'20',hold:'—',freq:'Every hr',instr:'While lying with the leg elevated, flex and extend the ankle repeatedly, pumping the foot up and down. Ankle pumps activate the calf muscle pump, reducing swelling, improving circulation, and maintaining basic ankle mobility. Used immediately after ankle surgery, fracture, or injury.'},
{id:'a76',cat:'Ankle & Foot',name:'Ankle Alphabet',pos:'Supine or seated, leg elevated',sets:2,reps:'Once through A-Z',hold:'—',freq:'2-3x/day',instr:'Trace all 26 letters of the alphabet in the air with your toes, making the movements as large as comfortable. Ankle alphabet exercises move the ankle through all planes of motion and are universally prescribed early after ankle sprain, fracture, or surgery.'},
{id:'a77',cat:'Ankle & Foot',name:'Calf Raise (Bilateral)',pos:'Standing, flat surface',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Stand with feet hip-width apart. Rise onto both tiptoes as high as possible. Lower slowly below the starting position if on a step, or to flat if on the floor. The most fundamental calf and ankle plantarflexor strengthening exercise, used at all stages of ankle and Achilles rehabilitation.'},
{id:'a78',cat:'Ankle & Foot',name:'Single-Leg Calf Raise',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on one foot. Rise onto the tiptoe of the standing foot as high as possible. Lower slowly. The most important progression from bilateral calf raise for developing sufficient single-leg push-off strength for walking, stair climbing, and running.'},
{id:'a79',cat:'Ankle & Foot',name:'Ankle Inversion Strengthening (Band)',pos:'Seated',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Sit with a band looped around the inside of the foot, anchored to the opposite side. Invert the foot (sole turning inward) against the resistance. Slowly return. Strengthens the tibialis posterior, tibialis anterior, and other invertor muscles used for medial ankle stability.'},
{id:'a80',cat:'Ankle & Foot',name:'Ankle Eversion Strengthening (Band)',pos:'Seated',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Sit with a band looped around the outside of the foot, anchored to the same side. Evert the foot (sole turning outward) against the resistance. Slowly return. Strengthens the fibularis (peroneal) muscles, the primary lateral ankle stabilizers. Essential in all lateral ankle sprain rehabilitation programs.'},
{id:'a81',cat:'Ankle & Foot',name:'Ankle Dorsiflexion Strengthening (Resistance)',pos:'Seated',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Sit with a band around the top of the foot, anchored below. Dorsiflex (pull the toes toward the shin) against the resistance. Slowly return. Strengthens the tibialis anterior and toe extensors. Used for foot drop, shin splints, and ankle sprain rehabilitation.'},
{id:'a82',cat:'Ankle & Foot',name:'Standing Balance on One Leg (Eyes Open)',pos:'Standing',sets:3,reps:'—',hold:'30-60 sec each',freq:'Daily',instr:'Stand on one leg without holding anything. Keep the standing knee slightly bent. Maintain balance for the prescribed time. The most fundamental single-leg balance exercise prescribed across all ankle, knee, hip, and neurological conditions requiring proprioceptive training.'},
{id:'a83',cat:'Ankle & Foot',name:'Standing Balance on One Leg (Eyes Closed)',pos:'Standing',sets:3,reps:'—',hold:'15-30 sec',freq:'Daily',instr:'Stand on one leg and close your eyes. The absence of visual input forces reliance on vestibular and somatosensory inputs, significantly increasing the proprioceptive challenge. A standard progression from the eyes-open single-leg balance.'},
{id:'a84',cat:'Ankle & Foot',name:'Wobble Board Balance (Bilateral)',pos:'Standing on wobble board',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Stand on a wobble board with both feet. Work to keep the edges from touching the floor by making continuous ankle and hip adjustments. Bilateral wobble board training is an effective early proprioceptive exercise after ankle sprain.'},
{id:'a85',cat:'Ankle & Foot',name:'Wobble Board Balance (Unilateral)',pos:'Standing on wobble board, one leg',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Stand on one leg on the wobble board. Maintain balance while preventing the edges from touching the floor. A more advanced proprioceptive challenge used in mid to late stages of ankle and lower extremity rehabilitation.'},
{id:'a86',cat:'Ankle & Foot',name:'Towel Toe Curls',pos:'Seated, foot on towel on smooth floor',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Place your bare foot on a hand towel on a smooth floor. Curl the toes to scrunch the towel under the foot. Release and repeat. Strengthens the toe flexors and plantar intrinsic muscles. A classic home exercise for plantar fasciitis and intrinsic foot weakness.'},
{id:'a87',cat:'Ankle & Foot',name:'Marble Pickup',pos:'Seated, foot on floor',sets:3,reps:'10-20 marbles',hold:'—',freq:'Daily',instr:'Place marbles on the floor next to a cup. Pick up each marble using only the toes and foot, placing them in the cup one at a time. Strengthens the intrinsic foot muscles and improves toe dexterity. A functional fine motor exercise for foot strengthening used in plantar fasciitis and general foot rehabilitation.'},
{id:'a88',cat:'Ankle & Foot',name:'Heel Walking',pos:'Standing, walking',sets:3,reps:'20 meters',hold:'—',freq:'Daily',instr:'Raise the toes and forefoot off the floor and walk forward on the heels only. Strengthens the anterior compartment muscles (tibialis anterior, toe extensors) and challenges ankle dorsiflexor endurance. Used for shin splints, foot drop, and anterior ankle rehabilitation.'},
{id:'a89',cat:'Ankle & Foot',name:'Toe Walking',pos:'Standing, walking',sets:3,reps:'20 meters',hold:'—',freq:'Daily',instr:'Rise onto both tiptoes and walk forward while remaining up on the toes. Strengthens the calf complex in a dynamic, functional endurance manner. Used for Achilles and calf strengthening rehabilitation and as a heel cord flexibility assessment.'},
{id:'a90',cat:'Ankle & Foot',name:'Single-Leg Stance with Reach - SEBT (Star Excursion)',pos:'Standing on one leg',sets:3,reps:'8 each direction',hold:'—',freq:'Daily',instr:'Stand on one leg. Reach the free foot as far as possible in the anterior, posterolateral, and posteromedial directions, touching lightly and returning without losing balance. The Star Excursion Balance Test is both a clinical assessment tool and a training exercise with strong evidence for reducing lower extremity injury recurrence.'},
// BALANCE & FUNCTIONAL b61-b75 (15)
{id:'b61',cat:'Balance & Functional',name:'Tandem Stance (Semi-Tandem)',pos:'Standing',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Stand with one foot directly beside the other, with the big toe of the back foot touching the heel of the front foot (semi-tandem position). Maintain this position without losing balance. An intermediate stance between parallel feet and full tandem, used in fall prevention programs and vestibular rehabilitation.'},
{id:'b62',cat:'Balance & Functional',name:'Tandem Stance (Full)',pos:'Standing',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Stand with one foot directly in front of the other, heel-to-toe. Maintain this position without holding on. Full tandem is a component of the Short Physical Performance Battery (SPPB) and is a standard fall risk assessment and training position.'},
{id:'b63',cat:'Balance & Functional',name:'Single-Leg Stance Progression (1 sec to 30 sec)',pos:'Standing',sets:3,reps:'—',hold:'As long as possible',freq:'Daily',instr:'Stand on one leg for as long as possible without losing balance. Track time and record progress weekly. Research shows that inability to maintain single-leg stance for 10 seconds in midlife is associated with significantly increased mortality risk and fall risk.'},
{id:'b64',cat:'Balance & Functional',name:'Functional Reach Test Practice',pos:'Standing near wall',sets:3,reps:'3 trials',hold:'—',freq:'Weekly to track',instr:'Stand with one shoulder near a wall, arm raised to 90 degrees. Reach forward as far as possible without stepping or losing balance. Measure the distance reached. The Functional Reach Test is a validated fall risk measure with norms by age and sex. Less than 6 inches indicates high fall risk.'},
{id:'b65',cat:'Balance & Functional',name:'30-Second Chair Stand Practice',pos:'Seated in standard chair',sets:1,reps:'Max repetitions in 30 sec',hold:'—',freq:'Daily',instr:'Sit in a standard armless chair. Stand up fully and sit back down as many times as possible in 30 seconds, using arms only if absolutely necessary. Count the total number. The 30-Second Chair Stand Test is a key measure of lower extremity functional strength and endurance, with established age and sex norms.'},
{id:'b66',cat:'Balance & Functional',name:'Stair Climbing with Handrail (Weaning)',pos:'Standing at staircase with rail',sets:3,reps:'1-3 flights',hold:'—',freq:'Daily',instr:'Practice climbing stairs using the handrail only as needed, working to reduce reliance on the rail over time. Track progress from two-hand rail hold to one-hand to no rail for single steps. Weaning from handrail dependence is an important functional goal in lower extremity and fall prevention rehabilitation.'},
{id:'b67',cat:'Balance & Functional',name:'Stair Descent with Control (Eccentric Focus)',pos:'Standing at top of stairs',sets:3,reps:'2-3 flights',hold:'—',freq:'Daily',instr:'Descend stairs in a slow, controlled manner, focusing on the eccentric quad and glute control of each step down. Use a hand rail for safety as needed. Stair descent is more demanding than ascent and is often the last functional task to recover fully after knee surgery.'},
{id:'b68',cat:'Balance & Functional',name:'Single-Leg Squat (Bodyweight, Shallow)',pos:'Standing on one leg',sets:3,reps:'10 each',hold:'2 sec',freq:'Daily',instr:'Stand on one leg with a slight forward lean. Lower into a shallow squat (30-40 degrees of knee flexion). Return to standing. A fundamental single-leg strength and proprioception exercise. The quality of the movement (knee alignment, trunk position, hip stability) is more important than depth.'},
{id:'b69',cat:'Balance & Functional',name:'Sit to Stand (Standard)',pos:'Seated in chair',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Sit in a standard chair with feet flat. Lean slightly forward, then drive through the feet to stand fully upright. Sit back with control. One of the most functional daily activities, and a primary strengthening exercise for the quads, glutes, and hip extensors in all phases of lower extremity rehabilitation.'},
{id:'b70',cat:'Balance & Functional',name:'Sit to Stand (Armless, No Hands)',pos:'Seated in armless chair',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Perform sit-to-stand without using the armrests. Lean the trunk slightly forward, drive through both feet, and rise to standing using only the legs. Lower back to sitting with control. A progression requiring more leg strength than the standard assisted version.'},
{id:'b71',cat:'Balance & Functional',name:'Walking with Eyes Closed (Supported)',pos:'Walking in corridor with rail nearby',sets:3,reps:'10 meters',hold:'—',freq:'Daily',instr:'Walk forward with eyes closed along a corridor, with the rail or wall within reach for safety. The absence of vision significantly increases the vestibular and somatosensory demand during walking. Used in vestibular rehabilitation and fall prevention programs for older adults.'},
{id:'b72',cat:'Balance & Functional',name:'Ball Toss while Walking',pos:'Walking',sets:3,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Walk at a comfortable pace while tossing and catching a ball with a partner. The dual-task demands of catching and walking challenge the ability to walk safely while doing something else with the hands, a common scenario in daily life that can increase fall risk.'},
{id:'b73',cat:'Balance & Functional',name:'Walking with Cognitive Task (Counting)',pos:'Walking',sets:3,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Walk while simultaneously counting backward by threes from 100, naming animals, or performing another cognitive task assigned by your therapist. Dual-task cognitive-motor training improves the automatic control of walking, reducing the fall risk associated with doing two things at once.'},
{id:'b74',cat:'Balance & Functional',name:'Incline and Decline Walking',pos:'Walking on incline',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Walk on an inclined surface or treadmill both uphill and downhill. Uphill walking increases hip and calf demand while downhill walking increases eccentric quad and proprioceptive demands. A functional progression from level-ground walking used in rehabilitation of lower extremity conditions.'},
{id:'b75',cat:'Balance & Functional',name:'Outdoor Walking on Varied Terrain',pos:'Walking outdoors',sets:1,reps:'20-40 min',hold:'—',freq:'Daily',instr:'Walk outside on varied terrain including grass, gravel, slight slopes, and curbs. Adapting to unpredictable surface changes is a key functional skill that indoor and treadmill training cannot fully replicate. Outdoor walking is an important component of community reintegration for all patient populations.'},
// THORACIC t36-t45 (10)
{id:'t36',cat:'Thoracic',name:'Thoracic Foam Roll Extension (Segmental)',pos:'Supine over foam roll',sets:3,reps:'5 segments',hold:'30 sec each',freq:'Daily',instr:'Lie over a foam roll placed horizontally under the thoracic spine. Support the head with the hands. Allow the thoracic spine to extend over the roll. Slowly move the roll to a new position by scooting the body, working from the mid-thoracic to upper thoracic region. The most commonly prescribed thoracic self-mobilization technique in PT.'},
{id:'t37',cat:'Thoracic',name:'Thoracic Rotation in Quadruped (Open Book Variant)',pos:'Quadruped',sets:3,reps:'10 each side',hold:'3 sec',freq:'Daily',instr:'On hands and knees, place one hand behind the head. Rotate the elbow of that arm upward toward the ceiling, opening the thoracic spine into rotation. Follow the elbow with your eyes. Return slowly. Combines thoracic rotation with appropriate shoulder positioning for effective mid-back mobility.'},
{id:'t38',cat:'Thoracic',name:'Chest Opener Stretch (Clasped Hands Behind Back)',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'Daily',instr:'Stand tall. Clasp both hands behind your back. Straighten the elbows and squeeze the shoulder blades together, lifting the clasped hands slightly away from the body. Hold. Feel the stretch across the chest, front of the shoulders, and thoracic extension. A comprehensive anterior chest and thoracic extension stretch.'},
{id:'t39',cat:'Thoracic',name:'Doorway Pectoral Stretch (90-90)',pos:'Standing in doorway',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand in a doorway with the forearms on the door frame at 90 degrees of shoulder abduction and 90 degrees of elbow flexion. Step one foot through the doorway and lean forward, feeling a stretch across the chest and anterior shoulder. The most commonly prescribed chest stretch used in PT for forward head and rounded shoulder posture.'},
{id:'t40',cat:'Thoracic',name:'Thoracic Extension in Child\'s Pose',pos:'Kneeling',sets:3,reps:'3',hold:'30-60 sec',freq:'Daily',instr:'Kneel and reach both arms forward on the floor as far as possible. Let the chest sink toward the floor while the arms remain outstretched. Feel the stretch through the thoracic spine and lats. A gentle thoracic and lat stretch often used as a cool-down or daily mobility exercise.'},
{id:'t41',cat:'Thoracic',name:'Thoracic Kyphosis Posture Correction Awareness',pos:'Seated or standing',sets:1,reps:'—',hold:'Ongoing awareness',freq:'Throughout day',instr:'Throughout the day, perform periodic posture checks: ears over shoulders, shoulders back and down, thoracic spine tall. Set a timer for every 30-45 minutes as a reminder. Postural awareness and correction is a foundational component of thoracic kyphosis and neck pain management.'},
{id:'t42',cat:'Thoracic',name:'Mid-Trapezius Strengthening (Band Pull Apart)',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a resistance band in front of you at shoulder height, hands slightly wider than shoulder width. Pull the band apart by moving both hands simultaneously outward until the band touches your chest. Squeeze the shoulder blades together. One of the most effective exercises for the middle trapezius and rhomboids.'},
{id:'t43',cat:'Thoracic',name:'Lower Trapezius Strengthening (Y Raise)',pos:'Prone',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down with arms extended overhead in a Y shape (thumbs pointing up). Raise both arms off the surface by depressing and retracting the shoulder blades without shrugging. Hold briefly, then lower. Specifically targets the lower trapezius, a key scapular stabilizer often weak in shoulder pain and thoracic kyphosis.'},
{id:'t44',cat:'Thoracic',name:'Thoracic Rotation in Standing with Dowel',pos:'Standing',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Hold a dowel or broomstick across the back of the shoulders. Stand with feet shoulder-width. Rotate the entire trunk to one side as far as possible, following the dowel with your eyes. Return to center and rotate the other way. The dowel maintains arm position, ensuring the movement comes purely from the thoracic spine.'},
{id:'t45',cat:'Thoracic',name:'Wall Chest Stretch (One Arm)',pos:'Standing beside wall',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Stand beside a wall and place one hand flat on the surface at shoulder height. Gently rotate your body away from the wall, feeling a stretch across the chest and front of the shoulder on the arm-against-wall side. Adjust the arm height to stretch different portions of the pectoral muscles.'},
// POST-OP & GENERAL p53-p62 (10)
{id:'p53',cat:'Post-Op & General',name:'Ice vs. Heat Decision Guide',pos:'Supine or seated',sets:1,reps:'—',hold:'15-20 min',freq:'As needed',instr:'Use ice (cold pack) for acute injuries (first 48-72 hours), after exercise when there is increased swelling, or when there is heat or redness in the joint. Use heat (moist heat pack or heating pad) for chronic stiffness, before stretching, and for muscle tension without swelling. When in doubt, use ice after activity and heat before stretching.'},
{id:'p54',cat:'Post-Op & General',name:'Activity Pacing Program',pos:'All positions',sets:1,reps:'Per schedule',hold:'—',freq:'Throughout day',instr:'Follow your prescribed activity pacing schedule, alternating periods of activity with planned rest breaks before pain or fatigue limits you. Pacing prevents the boom-and-bust pattern common in chronic pain conditions where patients overdo on good days and crash the next. Use a timer to stick to the schedule regardless of symptom level.'},
{id:'p55',cat:'Post-Op & General',name:'Pain Neuroscience Education Home Practice',pos:'Seated',sets:1,reps:'—',hold:'—',freq:'Daily',instr:'Review the pain education concepts taught by your therapist, including the role of central sensitization, the nervous system\'s protective function, and the difference between pain and tissue damage. Apply these concepts when interpreting your symptoms during exercise. Therapeutic neuroscience education combined with exercise is more effective than either alone for chronic pain.'},
{id:'p56',cat:'Post-Op & General',name:'Functional Independence Training (ADL Practice)',pos:'Various',sets:1,reps:'Daily tasks',hold:'—',freq:'Daily',instr:'Practice the specific activities of daily living you have lost due to injury or surgery, such as dressing, bathing, cooking, driving, or returning to work tasks. Systematic practice of the actual activities you need to perform, rather than generic exercises alone, accelerates functional recovery.'},
{id:'p57',cat:'Post-Op & General',name:'Sleep Position Optimization',pos:'Side-lying or supine',sets:1,reps:'—',hold:'During sleep',freq:'Nightly',instr:'Follow your therapist\'s specific guidance for optimal sleep positioning based on your diagnosis. Common guidelines: shoulder patients should sleep on the unaffected side with a pillow under the affected arm; lumbar patients often do best with a pillow between the knees in side-lying; cervical patients benefit from a cervical contour pillow. Poor sleep position significantly perpetuates musculoskeletal pain.'},
{id:'p58',cat:'Post-Op & General',name:'Walking Program Progression',pos:'Walking',sets:1,reps:'Per schedule',hold:'—',freq:'Daily',instr:'Follow your prescribed walking program schedule, beginning with short distances on flat ground and progressively increasing duration, distance, and terrain difficulty over weeks. Walking is one of the most universally beneficial therapeutic exercises across all musculoskeletal conditions and should be consistently progressed throughout rehabilitation.'},
{id:'p59',cat:'Post-Op & General',name:'Energy Conservation Techniques (ECT)',pos:'All positions',sets:1,reps:'—',hold:'—',freq:'Throughout day',instr:'Apply your energy conservation principles: prioritize activities, plan the day to alternate demanding and easy tasks, rest before becoming fatigued rather than after, use assistive devices to reduce effort, and modify the environment to reduce unnecessary energy expenditure. Used in fatigue management for inflammatory arthritis, fibromyalgia, MS, and post-surgical recovery.'},
{id:'p60',cat:'Post-Op & General',name:'Joint Protection Techniques for Arthritis',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Throughout day',instr:'Apply your taught joint protection principles: use larger joints for heavy tasks, avoid positions of deformity, use tools and assistive devices, distribute loads across multiple joints, and respect pain as a signal to modify activity. A cornerstone of occupational and physical therapy management of inflammatory and degenerative arthritis.'},
{id:'p61',cat:'Post-Op & General',name:'Home Exercise Program Review',pos:'Various',sets:1,reps:'Full program',hold:'—',freq:'Daily',instr:'Perform your complete home exercise program as prescribed, in the order listed, at the prescribed frequency. If any exercise causes new or significantly worsened pain, skip it and report to your therapist at the next visit. Consistent home program adherence accounts for the majority of rehabilitation outcomes between clinic visits.'},
{id:'p62',cat:'Post-Op & General',name:'Hydrotherapy Warm Water Pool Program',pos:'In warm pool',sets:1,reps:'30-45 min',hold:'—',freq:'2-3x/week',instr:'Perform your prescribed warm water exercise program including walking, range of motion, and strengthening activities. Warm water (33-36°C) provides pain relief through heat, reduces joint loading through buoyancy, and offers resistance through drag. Particularly beneficial for inflammatory arthritis, fibromyalgia, and severe joint degeneration.'},
// NEURO & VESTIBULAR n46-n55 (10)
{id:'n46',cat:'Neuro & Vestibular',name:'Visual Acuity During Head Movement (DVA Test Training)',pos:'Seated or standing',sets:3,reps:'2 min',hold:'—',freq:'Daily',instr:'Fixate on a stationary target while oscillating the head back and forth horizontally at approximately 1-2 Hz. Maintain the target in clear focus throughout. If the target blurs during head movement, it indicates vestibulo-ocular reflex (VOR) dysfunction. This exercise trains VOR gain in patients with hypofunction.'},
{id:'n47',cat:'Neuro & Vestibular',name:'Habituation Exercises (Dizziness Provocation)',pos:'Various prescribed positions',sets:3,reps:'5-10 per position',hold:'—',freq:'2x/day',instr:'Deliberately move into the positions that provoke your dizziness as prescribed by your therapist. Hold until the dizziness subsides. Repeat the movement. Habituation exercises work by repeatedly exposing the brain to the provoking stimulus until the adaptive response reduces symptom severity. Dizziness during the exercise is expected and necessary for progress.'},
{id:'n48',cat:'Neuro & Vestibular',name:'Brandt-Daroff Exercises',pos:'Seated on edge of bed',sets:3,reps:'5 each side',hold:'30 sec each position',freq:'3x/day',instr:'Sit on the edge of the bed. Quickly lie to one side with the head tilted 45 degrees upward. Hold 30 seconds, then sit upright. Then quickly lie to the other side with the head again tilted 45 degrees upward. Hold 30 seconds and sit up. Used for BPPV when the Epley maneuver is not fully effective or as a follow-up habituation exercise.'},
{id:'n49',cat:'Neuro & Vestibular',name:'Arm and Hand Function Practice Post-Stroke',pos:'Seated at table',sets:1,reps:'30-60 min total',hold:'—',freq:'Daily',instr:'Practice intensive, high-repetition reaching, grasping, and manipulation tasks with the affected arm using objects of varying size, shape, and weight. Task-specific, massed practice is the strongest evidence-based approach for arm recovery after stroke. Aim for hundreds of meaningful repetitions per day.'},
{id:'n50',cat:'Neuro & Vestibular',name:'Sit to Stand Post-Neurological Injury',pos:'Seated in chair',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Practice sit-to-stand transfers with the prescribed level of assistance and equipment. Focus on weight-shifting forward and driving through both feet symmetrically. Sit-to-stand is a critical functional milestone after neurological injury and requires specific attention to symmetrical weight bearing which may be compromised by hemiplegia or paraplegia.'},
{id:'n51',cat:'Neuro & Vestibular',name:'Postural Control in Sitting (Without Support)',pos:'Seated on edge of table',sets:3,reps:'—',hold:'1-5 min',freq:'Daily',instr:'Sit unsupported on the edge of a treatment table without using hands for support. Progress from still sitting to reaching in different directions, to catching objects. Builds seated trunk control used in transfers, ADLs, and as a prerequisite for standing rehabilitation after neurological injury.'},
{id:'n52',cat:'Neuro & Vestibular',name:'Progressive Ambulation Program (Post-Neurological)',pos:'Walking',sets:1,reps:'Progressive distance',hold:'—',freq:'Daily',instr:'Walk the prescribed distance with the prescribed assistive device and level of assistance. Track walking distance and speed weekly. Ambulation practice should be a daily priority in neurological rehabilitation as the intensity and volume of walking practice directly correlates with functional walking outcomes.'},
{id:'n53',cat:'Neuro & Vestibular',name:'Vestibular Migraine Balance Exercises',pos:'Standing',sets:3,reps:'—',hold:'30 sec each',freq:'Daily',instr:'Perform gentle balance and gaze exercises as prescribed, avoiding rapid head movements that trigger migraines during acute phases. Progress the exercises in synchrony with your migraine management plan. Vestibular rehabilitation adapted for vestibular migraine uses a more gradual progression than standard vestibular hypofunction protocols.'},
{id:'n54',cat:'Neuro & Vestibular',name:'Post-Concussion Exertional Threshold Training',pos:'Stationary bike or walking',sets:1,reps:'As per protocol',hold:'—',freq:'Daily',instr:'Exercise at the prescribed intensity level just below the threshold that provokes concussion symptoms, determined by a graded exercise test (Buffalo Concussion Protocol). Gradually increase the intensity by 10% each session. Sub-threshold aerobic exercise is now first-line treatment for persistent post-concussion symptoms.'},
{id:'n55',cat:'Neuro & Vestibular',name:'Sensory Retraining (Peripheral Nerve Injury)',pos:'Seated at table',sets:3,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Using your therapist\'s prescribed progression of textures and objects, practice identifying and discriminating sensations in the area of sensory loss. Begin with moving touch then static touch, large surfaces then small, and familiar objects then unfamiliar shapes. Sensory retraining after peripheral nerve injury accelerates cortical remapping of the recovered nerve.'},
// SPORT-SPECIFIC sp42-sp52 (11)
{id:'sp42',cat:'Sport-Specific & Plyometric',name:'Sprint Mechanics - Acceleration Drills',pos:'Open track',sets:3,reps:'20-30 meters',hold:'—',freq:'2-3x/week',instr:'Practice the acceleration phase of sprinting with 3-point start or falling start technique. Focus on pushing the ground backward with the rear foot and driving with a forward body lean. The acceleration phase is mechanically distinct from top-end speed and is where many hamstring strains occur.'},
{id:'sp43',cat:'Sport-Specific & Plyometric',name:'Maximal Velocity Running Mechanics',pos:'Open track',sets:3,reps:'30-40 meters at 85-95% speed',hold:'—',freq:'2-3x/week',instr:'Run at near-maximal speed over the prescribed distance. Focus on high knee drive, quick toe-off, and full hip extension. Top-end speed requires proper mechanics to minimize injury risk. Only perform after completing a full warm-up and sprint preparation program.'},
{id:'sp44',cat:'Sport-Specific & Plyometric',name:'Plyometric Jump and Stick Bilateral',pos:'Standing',sets:3,reps:'10',hold:'3 sec land',freq:'2-3x/week',instr:'Jump upward or forward and land on both feet in an athletic position with hips and knees bent. Hold the landing position for 3 seconds to demonstrate motor control before the next jump. The land-and-hold component is critical for training safe landing mechanics before reactive training is introduced.'},
{id:'sp45',cat:'Sport-Specific & Plyometric',name:'Medicine Ball Rotational Slam',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Hold a medicine ball and raise it to one side overhead. Slam it into the floor diagonally, following through with the entire body in a rotational pattern. Builds rotational power through the core and hips in a ballistic movement used in combat sports, golf, baseball, and racket sports.'},
{id:'sp46',cat:'Sport-Specific & Plyometric',name:'Depth Jump (Box)',pos:'Standing on box',sets:3,reps:'6',hold:'—',freq:'2-3x/week',instr:'Stand on a box (typically 12-30 inches). Step off (not jump off) and immediately upon landing, jump upward as high as possible. The brief ground contact activates the stretch-shortening cycle. The depth jump is an advanced plyometric with the highest power output demands and should only be used in late-stage rehabilitation with fit, trained athletes.'},
{id:'sp47',cat:'Sport-Specific & Plyometric',name:'Sport-Specific Footwork Patterns',pos:'Standing, open space',sets:3,reps:'5 each pattern',hold:'—',freq:'2-3x/week',instr:'Perform footwork patterns specific to your sport: basketball defensive slides and drop steps, soccer jockeying and directional turns, tennis split-step and lateral sprint starts, or volleyball approach footwork. Sport-specific footwork bridges the gap between general agility training and the actual movement demands of competition.'},
{id:'sp48',cat:'Sport-Specific & Plyometric',name:'Functional Power Test - Standing Vertical Jump',pos:'Standing near wall',sets:1,reps:'3 trials',hold:'—',freq:'Monthly to assess',instr:'Stand beside a wall. Chalk or wet your fingertips. Reach as high as possible and mark the wall, then jump and mark again. The difference is your vertical jump height. Compare to the non-affected side and to baseline. Vertical jump height is a standard return-to-sport power assessment for basketball, volleyball, and jumping athletes.'},
{id:'sp49',cat:'Sport-Specific & Plyometric',name:'Upper Extremity Closed Chain Plyometrics (Ball Drop)',pos:'Push-up position',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'Assume a push-up position with both hands on the floor. A partner drops a ball from overhead and you catch it with one hand, decelerate, then push it back up. Builds reactive shoulder stability and upper extremity plyometric power in a closed chain position. Used in late-stage shoulder rehabilitation for contact sport athletes.'},
{id:'sp50',cat:'Sport-Specific & Plyometric',name:'Agility Hexagon Drill',pos:'Standing in center of hexagon',sets:3,reps:'2 trials each direction',hold:'—',freq:'2-3x/week',instr:'Stand in the center of a hexagon marked on the floor. Jump over each side and back to center continuously, working around the hexagon both clockwise and counterclockwise. Time the total completion. A multidirectional plyometric assessment and training drill used in return-to-sport programs.'},
{id:'sp51',cat:'Sport-Specific & Plyometric',name:'Plyometric Bounding',pos:'Running track or turf',sets:3,reps:'20-30 meters',hold:'—',freq:'2-3x/week',instr:'Run forward with exaggerated, powerful strides, driving off each foot with maximum force and achieving maximum height and distance with each bound. Bounding develops unilateral explosive power in the hip extensors and calf complex and is used in sprinting and jumping sport return-to-performance programs.'},
{id:'sp52',cat:'Sport-Specific & Plyometric',name:'Return to Sport Clearance Criteria Check',pos:'Various',sets:1,reps:'Full assessment battery',hold:'—',freq:'At final discharge clearance',instr:'Perform the complete return-to-sport battery as directed by your therapist and physician: strength testing (limb symmetry index greater than 90%), hop tests, psychological readiness questionnaire (ACL-RSI or similar), movement quality screen, and sport-specific task performance. Return-to-sport decisions should be based on this composite assessment rather than time alone.'},
// PELVIC FLOOR pf29-pf38 (10)
{id:'pf29',cat:'Pelvic Floor & Womens Health',name:'Kegel Exercises (Basic)',pos:'Supine, seated, or standing',sets:3,reps:'10',hold:'5-10 sec',freq:'3x/day',instr:'Tighten the pelvic floor muscles as if trying to stop the flow of urine and prevent passing gas simultaneously. Hold for the prescribed time, then fully relax for an equal amount of time. The pelvic floor must fully release between contractions. Do not hold your breath or contract the abdomen, buttocks, or inner thighs during the exercise.'},
{id:'pf30',cat:'Pelvic Floor & Womens Health',name:'Kegel Exercises (Quick Flick)',pos:'Supine, seated, or standing',sets:3,reps:'10-20',hold:'1 sec',freq:'3x/day',instr:'Rapidly contract and release the pelvic floor muscles in quick, 1-second bursts. This trains the fast-twitch fibers that provide the reflexive closure needed to prevent leakage during sudden increases in intra-abdominal pressure (coughing, sneezing, jumping).'},
{id:'pf31',cat:'Pelvic Floor & Womens Health',name:'Elevator Kegel (Graded Contraction)',pos:'Seated',sets:3,reps:'5',hold:'—',freq:'Daily',instr:'Visualize an elevator with your pelvic floor. Lift the floor to the first floor (25%), hold, then to the second floor (50%), hold, third floor (75%), hold, then top floor (maximum contraction). Hold at the top, then gradually lower back through each floor, fully releasing at ground level. Builds graded pelvic floor control.'},
{id:'pf32',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Strengthening in Squat',pos:'Standing in squat position',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Perform a pelvic floor contraction while in a partial squat position. The squat position is more challenging for the pelvic floor than supine because the muscles must work against gravity and increased intra-abdominal pressure simultaneously. A functional progression toward pelvic floor activation during sport and exercise.'},
{id:'pf33',cat:'Pelvic Floor & Womens Health',name:'Bladder Training Diary and Schedule',pos:'Any',sets:1,reps:'—',hold:'—',freq:'Ongoing',instr:'Keep a voiding diary recording the time, volume, and circumstances of each void and any leakage episodes. Follow your prescribed voiding schedule, gradually increasing the interval between voids by 15-30 minutes every 1-2 weeks. Bladder training is a first-line treatment for urgency and urge urinary incontinence.'},
{id:'pf34',cat:'Pelvic Floor & Womens Health',name:'Prenatal Pelvic Floor Exercise Program',pos:'Seated or side-lying',sets:3,reps:'10',hold:'5-8 sec',freq:'3x/day',instr:'Perform pelvic floor contractions throughout pregnancy, adapting position as pregnancy progresses. Side-lying becomes more comfortable in the third trimester. Prenatal pelvic floor training reduces the risk of incontinence during and after pregnancy and may improve labor outcomes. Always clear with your OB or midwife before starting.'},
{id:'pf35',cat:'Pelvic Floor & Womens Health',name:'Pelvic Organ Prolapse Prevention Exercise',pos:'Standing',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Perform a pelvic floor contraction and hold before and during any activity that increases intra-abdominal pressure: lifting, coughing, sneezing, or exercise. This protective technique (the knack maneuver) should become automatic. Also perform after each void.'},
{id:'pf36',cat:'Pelvic Floor & Womens Health',name:'Hip Flexor Stretch and Pelvic Floor Release',pos:'Half-kneeling',sets:3,reps:'3',hold:'30 sec',freq:'Daily',instr:'In a half-kneeling position, allow the hip flexors to lengthen while simultaneously practicing pelvic floor drop and release. Hip flexor tightness and pelvic floor hypertonicity often co-exist, and combined stretching of both together can be more effective than treating each in isolation.'},
{id:'pf37',cat:'Pelvic Floor & Womens Health',name:'Diastasis Recti Core Restoration',pos:'Supine, knees bent',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Lie on your back with knees bent. Exhale and gently draw the lower abdominals inward while simultaneously contracting the pelvic floor, creating a gentle tensioning across the linea alba. Avoid any exercise that causes the midline to dome or bulge. Progress from supine to seated to standing to functional loading as the gap closes and tension improves.'},
{id:'pf38',cat:'Pelvic Floor & Womens Health',name:'Scar Tissue Mobilization (Cesarean or Perineal)',pos:'Supine',sets:1,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Once the incision or perineal scar is fully healed (typically 6-8 weeks), begin gentle scar massage as directed by your therapist: first around the scar, then along the edges, then slowly mobilizing the scar itself in all directions. Scar adhesions after cesarean or episiotomy can cause pelvic pain, bladder dysfunction, and back pain if not addressed.'},
// AMPUTEE amp22-amp28 (7)
{id:'amp22',cat:'Amputee & Prosthetic',name:'Residual Limb Desensitization',pos:'Seated',sets:3,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Progressively touch and massage the residual limb using varied textures and pressures, beginning with soft fabrics and advancing to firm pressure. Desensitization reduces hypersensitivity of the residual limb to prosthetic socket contact, which is a major barrier to prosthetic wear tolerance.'},
{id:'amp23',cat:'Amputee & Prosthetic',name:'Transtibial Residual Limb Strengthening - Knee Extension',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'For a below-knee amputation, sit in a chair and extend the residual limb against gravity or light resistance. The quadriceps are essential for controlling the prosthetic knee during loading and need to be specifically strengthened.'},
{id:'amp24',cat:'Amputee & Prosthetic',name:'Socket Donning and Doffing Practice',pos:'Seated',sets:3,reps:'—',hold:'—',freq:'Daily',instr:'Practice putting on and removing the prosthetic socket using the correct technique taught by your prosthetist and therapist. Proper donning technique affects fit, comfort, and function. Practice until the process becomes reliable and independent.'},
{id:'amp25',cat:'Amputee & Prosthetic',name:'Prosthetic Weight Bearing Progression',pos:'Standing with parallel bars',sets:3,reps:'—',hold:'Progressive',freq:'Daily',instr:'Begin weight bearing on the prosthesis within parallel bars, starting with partial weight through the device and progressing toward full weight bearing as tolerance and residual limb health allow. Weight bearing progression is monitored by the therapist and prosthetist together.'},
{id:'amp26',cat:'Amputee & Prosthetic',name:'Prosthetic Balance Training (Parallel Bars)',pos:'Standing in parallel bars',sets:3,reps:'—',hold:'1-3 min',freq:'Daily',instr:'Practice standing and weight shifting between the prosthetic and intact limbs within the parallel bars. Progress from two-hand support to one-hand to fingertip contact to hands-off balance within the bars before progressing to open space with a cane or walker.'},
{id:'amp27',cat:'Amputee & Prosthetic',name:'Transfemoral Hip Adductor Strengthening',pos:'Side-lying',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'For above-knee amputation, lie on the affected side and adduct the residual limb downward against gravity. Hip adductors help control the medial-lateral stability of the prosthetic socket and contribute to a smooth gait pattern.'},
{id:'amp28',cat:'Amputee & Prosthetic',name:'Bilateral Upper Extremity Amputee ADL Retraining',pos:'Seated at table',sets:1,reps:'30-60 min',hold:'—',freq:'Daily',instr:'Under therapist guidance, systematically practice daily living tasks with the bilateral prostheses, beginning with simple tasks (picking up large objects) and progressing to complex bimanual tasks (opening containers, using tools, preparing food). Independence in ADLs is the primary goal of bilateral upper extremity prosthetic rehabilitation.'},
// PEDIATRIC peds35-peds41 (7)
{id:'peds35',cat:'Pediatric',name:'Developmental Tummy Time Progression',pos:'Prone',sets:5,reps:'—',hold:'3-5 min',freq:'Throughout day',instr:'For infants and toddlers with delayed motor development: begin with tummy time on the caregiver\'s chest, progressing to a wedge, then flat surface. Tummy time builds the cervical and thoracic extensors needed for head control, rolling, and crawling. Aim for a total of 30 minutes or more of tummy time per day by 3 months.'},
{id:'peds36',cat:'Pediatric',name:'Pediatric Core Strengthening (Crab Walk)',pos:'Seated on floor',sets:3,reps:'3-5 meters',hold:'—',freq:'Daily',instr:'Have the child sit on the floor with hands behind them, lift their bottom off the floor, and walk on hands and feet with the tummy facing up. Crab walking builds shoulder, core, and hip extensor strength in an engaging movement that children typically enjoy and find challenging.'},
{id:'peds37',cat:'Pediatric',name:'Pediatric Coordination - Catching and Throwing',pos:'Standing',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Practice catching and throwing balls of progressively smaller sizes and lighter weights at increasing distances. Begin with a large soft ball at close range and progress to smaller balls. Bilateral hand-eye coordination and anticipatory postural control are developed through ball play.'},
{id:'peds38',cat:'Pediatric',name:'Pediatric Strengthening Through Animal Walks',pos:'Floor, open space',sets:3,reps:'10-15 meters each',hold:'—',freq:'Daily',instr:'Have the child perform animal walks: bear crawl (hands and feet, belly down), crab walk (hands and feet, belly up), bunny hop (jump forward with both feet), frog jump (squat jump forward), and inchworm. Each animal walk builds specific strength and coordination in a motivating, playful format.'},
{id:'peds39',cat:'Pediatric',name:'Pediatric Handwriting Preparation Exercises',pos:'Seated at table',sets:3,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Perform fine motor warm-up exercises before handwriting: finger taps (each finger to thumb in sequence), putty rolling, pinching and releasing clothespins, and drawing large shapes on a vertical surface. Preparing the hand and finger musculature before handwriting improves grip control and letter formation.'},
{id:'peds40',cat:'Pediatric',name:'Pediatric Neurological Developmental Exercise (NDT)',pos:'Various',sets:1,reps:'30-60 min session',hold:'—',freq:'Daily with therapist, home program daily',instr:'Perform your child\'s individualized neurodevelopmental treatment program under therapist guidance. NDT focuses on facilitation of normal movement patterns, inhibition of abnormal patterns, and functional task practice. Caregiver training in the handling and facilitation techniques is a critical component of the NDT approach.'},
{id:'peds41',cat:'Pediatric',name:'Pediatric Kinesio Taping for Posture',pos:'Varies by application',sets:1,reps:'—',hold:'3-5 days wear',freq:'Applied by therapist',instr:'Kinesio tape is applied by your therapist to facilitate specific muscles or inhibit overactive muscles to promote better postural alignment in the pediatric patient. Application sites vary widely depending on the diagnosis. The tape provides 24-hour sensory feedback to encourage corrected postures between therapy sessions.'},
// TMJ j26-j30 (5)
{id:'j26',cat:'TMJ',name:'Jaw Rest Position Awareness',pos:'Seated or standing',sets:1,reps:'Throughout day',hold:'Ongoing awareness',freq:'Continuously',instr:'The jaw resting position is: lips together, teeth apart (1-2mm space between upper and lower teeth), tongue resting lightly on the palate. Maintain this position as the default throughout the day. Many TMJ patients habitually clench, creating constant muscle overload. This rest position awareness is foundational to all TMJ rehabilitation.'},
{id:'j27',cat:'TMJ',name:'Mandibular Resistance Exercises (Stabilization)',pos:'Seated in front of mirror',sets:3,reps:'10 each direction',hold:'5 sec',freq:'Daily',instr:'Using one or both hands, gently resist jaw opening, closing, protrusion, and lateral movements while watching in a mirror to ensure straight movement without deviation. Builds the coordinated muscle strength around the TMJ while training movement quality simultaneously.'},
{id:'j28',cat:'TMJ',name:'Cervical and Jaw Coordination Exercise',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Perform a gentle chin tuck. While maintaining the chin tuck, practice controlled jaw opening and closing. Then release the chin tuck. This exercise links cervical alignment with jaw function, addressing the common clinical finding that forward head posture alters mandibular position and increases TMJ loading.'},
{id:'j29',cat:'TMJ',name:'TMJ Heat Application Before Exercise',pos:'Seated',sets:1,reps:'—',hold:'10-15 min before exercise',freq:'Before TMJ exercise sessions',instr:'Apply a warm moist pack or warm damp cloth to the masseter and temporal regions before performing TMJ stretching or mobilization exercises. Heat reduces muscle guarding, increases tissue extensibility, and allows more effective range of motion gains during subsequent jaw exercises.'},
{id:'j30',cat:'TMJ',name:'Stress and Bruxism Management Behavioral Program',pos:'Any',sets:1,reps:'—',hold:'—',freq:'Daily and ongoing',instr:'Implement your prescribed behavioral strategies for bruxism management: identify and modify stress triggers, practice relaxation techniques before bed, perform the jaw rest position check every time you notice a specific trigger (such as stopping at a red light), and use bite guard consistently at night. Behavioral modification combined with PT exercise is more effective than either alone for bruxism-related TMJ disorder.'},
// CERVICAL c86-c100 (15)
{id:'c86',cat:'Cervical',name:'Cervical Deep Flexor Training Stage 2 (Moderate Load)',pos:'Supine',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Progress from the basic nodding exercise to holding the chin tuck position for longer periods against gravity. The goal is sustained deep cervical flexor activation without recruiting the superficial muscles (SCM and scalenes). Place your fingers lightly on the front of the throat to monitor for superficial muscle over-recruitment.'},
{id:'c87',cat:'Cervical',name:'Cervical Deep Flexor Training Stage 3 (Functional Load)',pos:'Sitting upright',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Maintain a chin tuck while performing a task with the arms such as a light shoulder exercise or reaching. Adding arm load to the chin-tuck position progresses the deep cervical flexors into a functional stability role, mimicking the demands placed on the neck during computer work, driving, and lifting.'},
{id:'c88',cat:'Cervical',name:'Cervical Rotation with Gaze Stabilization (Horizontal)',pos:'Seated',sets:3,reps:'20',hold:'—',freq:'2x/day',instr:'Fix your gaze on a stationary target directly in front of you. Slowly rotate the head to the side and then back to center, keeping the target in clear focus throughout. The gaze stabilization component adds vestibulo-ocular reflex training to the cervical rotation exercise.'},
{id:'c89',cat:'Cervical',name:'Cervical Side Bend Stretch with Arm Down',pos:'Seated',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Tilt your right ear toward the right shoulder. Simultaneously reach your left hand downward toward the floor as if reaching for something below the seat, adding a gentle neural stretch to the side bend. Hold. A combined upper trapezius stretch with neural mobilization component.'},
{id:'c90',cat:'Cervical',name:'Cervical Retraction-Protraction Exercise',pos:'Seated',sets:3,reps:'10',hold:'2 sec each end',freq:'Daily',instr:'Move your head straight backward (retraction/chin tuck) as far as possible, hold briefly. Then slide it straight forward (protraction) as far as possible, hold briefly. This rhythmic movement mobilizes the cervical facet joints in a gliding motion and is used for general cervical stiffness and mobility maintenance.'},
{id:'c91',cat:'Cervical',name:'Cervical Flexion with Resistance (Head Harness)',pos:'Seated',sets:3,reps:'12',hold:'—',freq:'2-3x/week',instr:'Using a cervical harness with weight attached, flex the neck forward against the resistance of the hanging weight. Return slowly. A progressive resistance exercise for the cervical flexors used in athletes and workers with high cervical loading demands such as contact sport players or construction workers.'},
{id:'c92',cat:'Cervical',name:'Cervical Extension with Resistance (Head Harness)',pos:'Seated',sets:3,reps:'12',hold:'—',freq:'2-3x/week',instr:'Using a cervical harness with weight attached, extend the neck backward against the resistance of the hanging weight. Return slowly. Used to build cervical extensor strength in athletes who require a strong neck for contact sports or workers who sustain prolonged forward head positions.'},
{id:'c93',cat:'Cervical',name:'Cervical Joint Position Sense Retraining (Laser)',pos:'Seated',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Attach a small laser pointer or headlamp to your head with a headband. Mark a center target on the wall. Close your eyes, rotate your head in a prescribed direction, then attempt to return to center. Open your eyes to check your accuracy against the target. Trains the cervical proprioceptive system disrupted by neck pain and whiplash.'},
{id:'c94',cat:'Cervical',name:'Cervical Stabilization During Arm Loading (Overhead)',pos:'Seated',sets:3,reps:'10 each arm',hold:'5 sec',freq:'Daily',instr:'Perform a chin tuck and hold it. Slowly raise one arm fully overhead while maintaining the chin-tuck position. Hold with the arm overhead, then lower. The goal is that the head does not extend or the chin protrude during the arm elevation. Trains the neck stabilizers to maintain head position during overhead reaching.'},
{id:'c95',cat:'Cervical',name:'Cervical Myofascial Release (Towel Traction and Rotation)',pos:'Supine',sets:3,reps:'5 each side',hold:'30 sec',freq:'Daily',instr:'Lie on your back and place a rolled towel under the neck at the level of restriction. Apply gentle traction by pulling the towel ends forward, then add a slow rotation to the side while maintaining the traction. Combines longitudinal traction with rotation to mobilize a specific cervical segment in a gravity-assisted position.'},
{id:'c96',cat:'Cervical',name:'Neck Strengthening with Head Band (Lateral)',pos:'Seated',sets:3,reps:'12 each side',hold:'2 sec',freq:'Daily',instr:'Loop a resistance band around your head at ear level, anchored to the same side. Perform a lateral flexion against the resistance. Return slowly. A direct resistance exercise for the lateral cervical flexors including the scalenes and lateral sub-occipitals.'},
{id:'c97',cat:'Cervical',name:'Cervical Range of Motion Self-Measurement',pos:'Seated',sets:1,reps:'All 6 directions',hold:'—',freq:'Weekly to track',instr:'Use a simple inclinometer app on your phone held against the head, or a cervical range of motion device provided by your therapist, to measure and track all six cervical motions each week. Self-monitoring of ROM provides objective feedback about progress and helps identify when progress has plateaued.'},
{id:'c98',cat:'Cervical',name:'Night Guard and Cervical Pillow Combined Protocol',pos:'Side-lying or supine for sleep',sets:1,reps:'—',hold:'During sleep',freq:'Nightly',instr:'Use the prescribed night guard (for bruxism if co-existing with cervical dysfunction) and the optimal cervical pillow simultaneously. Both reduce nocturnal loading on the cervical spine through different mechanisms: the guard reduces jaw muscle tension that transmits to the neck, while the pillow maintains neutral cervical alignment.'},
{id:'c99',cat:'Cervical',name:'Progressive Cervical Endurance Test',pos:'Supine',sets:1,reps:'—',hold:'Maximum time',freq:'Weekly to track',instr:'Lie on your back. Perform a chin tuck and hold it as long as possible while maintaining the correct position. Stop when you can no longer maintain the position. Track the time weekly. Cervical flexor endurance is closely correlated with neck pain and headache frequency, and is a primary outcome measure in cervical rehabilitation research.'},
{id:'c100',cat:'Cervical',name:'Cervical Return to Sport Protocol (Contact)',pos:'Various',sets:1,reps:'Progressive',hold:'—',freq:'As per protocol',instr:'Follow your sport and position-specific return-to-contact protocol, progressing from controlled contact to full contact practice. Cervical strength, range of motion, and clearance from a physician are all required before return to contact sports after cervical injury. Never rush this process.'},
// SHOULDER s126-s140 (15)
{id:'s126',cat:'Shoulder',name:'Scapular PNF (Diagonal Patterns)',pos:'Seated or sidelying',sets:3,reps:'10 each pattern',hold:'—',freq:'Daily',instr:'Perform scapular PNF diagonal patterns as directed by your therapist: anterior elevation to posterior depression (one diagonal), and posterior elevation to anterior depression (the other diagonal). Scapular PNF restores coordinated scapular movement independent of the arm and is used when scapular dyskinesis is the primary impairment.'},
{id:'s127',cat:'Shoulder',name:'Rhythmic Stabilization at Side (Low Position)',pos:'Seated, arm at side with elbow bent',sets:3,reps:'30 sec',hold:'—',freq:'Daily',instr:'Sit with the elbow bent to 90 degrees and the arm held at the side. A partner applies alternating perturbations (pushing up, down, forward, backward) while you maintain the position without moving. A low-demand neuromuscular shoulder exercise appropriate early in rehabilitation before higher position training.'},
{id:'s128',cat:'Shoulder',name:'Rhythmic Stabilization in 90-90 (Horizontal)',pos:'Seated or supine, arm at 90-90',sets:3,reps:'30 sec',hold:'—',freq:'Daily',instr:'Maintain the arm at 90 degrees abduction and 90 degrees elbow flexion. A partner applies multi-directional perturbations while you resist. This is the throwing position and is a critical training position for overhead athletes in shoulder rehabilitation.'},
{id:'s129',cat:'Shoulder',name:'Shoulder Stabilization on Unstable Surface',pos:'Quadruped on foam or half roll',sets:3,reps:'—',hold:'30 sec',freq:'Daily',instr:'Assume a quadruped position with the hands on a foam pad or half-foam roll. Maintain stable shoulder blades and a neutral spine on the unstable surface. The instability adds proprioceptive demand to the shoulder stabilizers compared to a firm floor.'},
{id:'s130',cat:'Shoulder',name:'Band Diagonal Chop (High to Low)',pos:'Standing',sets:3,reps:'12 each side',hold:'—',freq:'Daily',instr:'Anchor a band overhead on one side. Hold with both hands and pull diagonally downward across the body to the opposite hip, rotating the trunk. Return slowly along the same path. Trains the shoulder, core, and hip together in a chopping diagonal pattern used in sport and daily activity.'},
{id:'s131',cat:'Shoulder',name:'Band Diagonal Lift (Low to High)',pos:'Standing',sets:3,reps:'12 each side',hold:'—',freq:'Daily',instr:'Anchor a band low on one side. Hold with both hands and lift diagonally upward across the body to the opposite overhead position, rotating the trunk. Return slowly. The lifting diagonal complements the chopping pattern and is used in throwing, serving, and overhead lifting activities.'},
{id:'s132',cat:'Shoulder',name:'Resisted Shoulder Abduction at 90 Degrees',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor a band below and hold it in the affected hand. With the arm at 90 degrees abduction, press further outward and upward toward 120 degrees against the resistance. Return slowly. Specifically loads the deltoid and supraspinatus in the mid-range of abduction where they are most active.'},
{id:'s133',cat:'Shoulder',name:'Glenohumeral Compression Exercise',pos:'Supine',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Lie on your back with the arm at 90 degrees of flexion, elbow straight. A partner applies gentle longitudinal compression along the arm into the shoulder joint while you co-contract the rotator cuff muscles. Compression with co-contraction provides joint stabilization stimulus similar to weight bearing through the shoulder.'},
{id:'s134',cat:'Shoulder',name:'Shoulder Horizontal Abduction (Reverse Fly)',pos:'Standing, hinged forward',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hinge forward at the hips with arms hanging. Hold light weights or band handles. Raise both arms out to the sides (horizontal abduction), squeezing the shoulder blades at the top. Lower slowly. Strengthens the posterior deltoid, middle and lower trapezius simultaneously in a functional position.'},
{id:'s135',cat:'Shoulder',name:'Scapular Stabilization Plank',pos:'Prone on forearms',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Assume a forearm plank position. Focus on maintaining active scapular depression and slight retraction throughout the hold, preventing the shoulder blades from winging upward or rounding forward. A core and shoulder stabilization exercise combined in a functional position.'},
{id:'s136',cat:'Shoulder',name:'Shoulder Muscle Energy Technique (Self)',pos:'Supine',sets:3,reps:'5',hold:'10 sec contract, 20 sec stretch',freq:'Daily',instr:'Position the shoulder at the restrictive barrier (end of available range). Contract the antagonist muscles gently against your own hand for 10 seconds. Relax, then move further into the restricted direction. The post-isometric relaxation of the muscle allows additional range to be gained with each repetition.'},
{id:'s137',cat:'Shoulder',name:'Upper Extremity Ergometer (UBE)',pos:'Seated in front of ergometer',sets:1,reps:'10-20 min',hold:'—',freq:'Daily',instr:'Crank the upper body ergometer at a light to moderate resistance for the prescribed duration. The UBE provides aerobic conditioning of the upper extremities, builds rotator cuff and shoulder girdle endurance, and is used throughout shoulder rehabilitation as an adjunct to specific exercises.'},
{id:'s138',cat:'Shoulder',name:'Shoulder Impingement Prevention Program',pos:'Standing',sets:3,reps:'15 each',hold:'—',freq:'Daily',instr:'Perform the shoulder impingement prevention circuit: scapular retraction, lower trapezius Y-raise, ER side-lying, serratus punch. Address all four components to balance the force couples acting on the shoulder and maintain adequate subacromial space during overhead movement.'},
{id:'s139',cat:'Shoulder',name:'Adhesive Capsulitis Specific Protocol',pos:'Supine',sets:3,reps:'3 each direction',hold:'30-45 sec',freq:'2-3x/day',instr:'For frozen shoulder: perform the complete capsular stretch program (inferior capsule, posterior capsule, anterior capsule) followed by pendulum exercises and active range of motion within the pain-free range. Consistency and frequency of stretching is the key to capsular mobility restoration in adhesive capsulitis.'},
{id:'s140',cat:'Shoulder',name:'Shoulder External Rotation at 90 Abduction (Supine)',pos:'Supine, arm at 90 abduction',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with the arm out to the side at 90 degrees and elbow bent 90 degrees, resting the upper arm on the surface. Holding a light weight, rotate the forearm toward the floor (IR) and then back toward the ceiling (ER). This position provides a gravity-resisted ER exercise in a supported overhead-relevant position.'},
// ELBOW & WRIST e96-e108 (13)
{id:'e96',cat:'Elbow & Wrist',name:'Active Wrist Circumduction',pos:'Seated, forearm supported',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'With the forearm supported, move the wrist through the largest comfortable circles in both directions, combining flexion, extension, radial deviation, and ulnar deviation in a smooth arc. Maintains wrist joint mobility and synovial fluid distribution. Used throughout wrist rehabilitation as a mobility warm-up.'},
{id:'e97',cat:'Elbow & Wrist',name:'Elbow Active Range of Motion Program',pos:'Seated',sets:3,reps:'10 each motion',hold:'2 sec',freq:'Daily',instr:'Perform a complete elbow ROM sequence: full flexion, full extension, full supination, and full pronation. Track the range at each check-in. A systematic daily ROM program for restoring elbow motion after fracture, surgery, or prolonged immobilization.'},
{id:'e98',cat:'Elbow & Wrist',name:'Grip Strengthening with Hand Exerciser',pos:'Seated',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Use a hand grip strengthener set to an appropriate resistance. Squeeze fully and release fully. Ensures complete opening of the hand between squeezes which works the extrinsics in both directions. Progress resistance level every two weeks when 3 sets of 20 are easy.'},
{id:'e99',cat:'Elbow & Wrist',name:'Wrist Strengthening Program (Full Circuit)',pos:'Seated, forearm on table',sets:3,reps:'12 each direction',hold:'2 sec',freq:'Daily',instr:'Perform the complete wrist strengthening circuit: wrist flexion, wrist extension, radial deviation, ulnar deviation, pronation, and supination, each with light resistance. Completing the full circuit ensures balanced wrist strength development, important after any wrist pathology or immobilization.'},
{id:'e100',cat:'Elbow & Wrist',name:'Trigger Finger Flexion and Extension Exercise',pos:'Seated',sets:3,reps:'15 each finger',hold:'—',freq:'Daily',instr:'Actively flex and extend each finger fully and smoothly, focusing on any finger with a triggering or clicking sensation. Gentle active ROM helps move the flexor tendon nodule through the A1 pulley during rehabilitation of trigger finger. Stop if a painful lock occurs and contact your therapist.'},
{id:'e101',cat:'Elbow & Wrist',name:'DeQuervain Tendinopathy Strengthening',pos:'Seated, forearm neutral',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Perform thumb extension and radial deviation against light resistance using a band looped around the thumb. Move through a pain-free range. After the acute phase, progressive loading of the first dorsal compartment tendons (abductor pollicis longus and extensor pollicis brevis) is essential for full recovery from DeQuervain tendinopathy.'},
{id:'e102',cat:'Elbow & Wrist',name:'Ulnar Collateral Ligament Valgus Stress Control',pos:'Seated',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'With the elbow at 30 degrees flexion, activate the flexor-pronator mass muscles with light resisted wrist flexion and forearm pronation. These muscles dynamically stabilize the medial elbow and protect the UCL from valgus stress. Used in UCL sprain and throwing athlete rehabilitation.'},
{id:'e103',cat:'Elbow & Wrist',name:'Finger Tendon Repair Passive ROM (Duran Protocol)',pos:'Supine or seated, supported arm',sets:6,reps:'10',hold:'—',freq:'Every waking hour',instr:'Following flexor tendon repair, perform gentle passive flexion and extension of the repaired finger using the other hand, within the protected range prescribed by your therapist. The Duran protocol prevents tendon adhesion formation while protecting the repair. Never perform active flexion until specifically cleared.'},
{id:'e104',cat:'Elbow & Wrist',name:'Thumb Opposition Strengthening',pos:'Seated',sets:3,reps:'15 each finger pair',hold:'3 sec',freq:'Daily',instr:'Touch the tip of the thumb to the tip of each finger in sequence (index, middle, ring, pinky), forming a complete circle each time. Resist with the other hand if prescribed. Strengthens the opponens pollicis and thenar musculature needed for virtually all pinch and precision grip activities.'},
{id:'e105',cat:'Elbow & Wrist',name:'Wrist Proprioception Training (Eyes Closed Matching)',pos:'Seated, both forearms on table',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'With eyes open, move the affected wrist to a target position shown on a goniometer or set by the therapist. Hold the position, close your eyes, relax, then try to reproduce the exact position. Open eyes to check accuracy. Trains wrist joint position sense, disrupted after sprains, fractures, and carpal instability.'},
{id:'e106',cat:'Elbow & Wrist',name:'Forearm Strengthening Circuit',pos:'Seated, forearm on table',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Perform the complete forearm circuit without rest between: wrist curls (flexion), reverse wrist curls (extension), hammer pronation, hammer supination. A time-efficient comprehensive forearm strengthening routine used in racket sport, throwing, and grip-intensive occupation rehabilitation.'},
{id:'e107',cat:'Elbow & Wrist',name:'Functional Hand Strengthening (Jar Lids and Keys)',pos:'Seated',sets:3,reps:'10 each task',hold:'—',freq:'Daily',instr:'Practice opening and closing jars of varied tightness, turning keys in locks, and other common household gripping and torque tasks. Functional hand strengthening using real-life objects is more motivating and directly transfers to the activities patients need to perform than isolated putty or dumbbell exercises alone.'},
{id:'e108',cat:'Elbow & Wrist',name:'Dynamic Splint for Elbow Extension',pos:'Wearing dynamic splint',sets:1,reps:'—',hold:'As prescribed',freq:'As directed',instr:'Wear the dynamic extension splint for the duration prescribed by your therapist. Dynamic splints use spring or elastic tension to apply a continuous low-load stretch at the end of the range, gradually restoring elbow extension range over time through creep of the capsular and connective tissue structures.'},
// CORE & LUMBAR l118-l135 (18)
{id:'l118',cat:'Core & Lumbar',name:'Wall Sit',pos:'Standing against wall',sets:3,reps:'—',hold:'30-60 sec',freq:'Daily',instr:'Stand with your back against a smooth wall, feet about 18 inches out. Slide down until the knees are at approximately 90 degrees, as if sitting in a chair. Hold the position. An isometric quad and hip strengthening exercise that also requires lumbar and core control to maintain the back against the wall.'},
{id:'l119',cat:'Core & Lumbar',name:'Glute Bridge with Band Abduction',pos:'Supine, knees bent',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Place a band around both thighs just above the knees. Perform a bridge while simultaneously pressing the knees outward against the resistance of the band. The combined glute activation (bridge) with hip abductor co-activation (band) more closely matches the multi-directional demand placed on the glutes during functional activities.'},
{id:'l120',cat:'Core & Lumbar',name:'Supine Core Endurance (Hollow Body Hold)',pos:'Supine',sets:3,reps:'—',hold:'15-30 sec',freq:'Daily',instr:'Lie on your back. Flatten the low back to the floor and raise the legs to approximately 45 degrees with arms extended alongside the head. Hold this position while breathing normally. A gymnastic-derived core endurance exercise that challenges the anterior core through the full lever of both the legs and arms.'},
{id:'l121',cat:'Core & Lumbar',name:'Stability Ball Plank',pos:'Prone, forearms on stability ball',sets:3,reps:'—',hold:'20-30 sec',freq:'Daily',instr:'Assume a forearm plank position with the forearms resting on a stability ball rather than the floor. Maintain a rigid body position while preventing the ball from rolling. The instability of the ball significantly increases the activation demand on the deep spinal stabilizers compared to a floor plank.'},
{id:'l122',cat:'Core & Lumbar',name:'Stability Ball Prone Rollout',pos:'Prone with hands on ball',sets:3,reps:'10',hold:'2 sec extended',freq:'Daily',instr:'Begin on hands and knees with hands on a stability ball. Roll the ball forward by straightening the elbows, extending the body, then pull it back. An anti-extension core exercise on an unstable surface, used in mid to late stage core rehabilitation.'},
{id:'l123',cat:'Core & Lumbar',name:'Stability Ball Bridge',pos:'Supine, feet on ball',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Lie on your back with both feet resting on top of a stability ball. Drive through the heels to lift the hips into a bridge. The instability of the ball adds significant gluteal and core demand compared to a floor bridge. Progress to single-leg variation by straightening one knee.'},
{id:'l124',cat:'Core & Lumbar',name:'Stability Ball Seated Balance',pos:'Seated on ball',sets:3,reps:'—',hold:'1-3 min',freq:'Daily',instr:'Sit on a stability ball with feet flat on the floor and arms crossed over the chest. Maintain balance without resting the feet for counterbalance. Progress by closing the eyes, lifting one foot, or adding arm movements. Used for lumbar and pelvic stability training in a functional seated position.'},
{id:'l125',cat:'Core & Lumbar',name:'Ab Wheel Rollout',pos:'Kneeling on mat',sets:3,reps:'8-10',hold:'2 sec extended',freq:'2-3x/week',instr:'Kneel on a mat holding an ab wheel in front of you. Roll the wheel forward as far as possible while maintaining a rigid trunk, then pull it back. The ab wheel requires the anti-extension core stabilizers to prevent lumbar hyperextension throughout the motion. One of the most demanding anti-extension core exercises.'},
{id:'l126',cat:'Core & Lumbar',name:'Reverse Crunch',pos:'Supine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with hips and knees at 90 degrees. Contract the lower abdominals to curl the hips off the floor toward the chest, moving the knees toward the face. Lower slowly. The reverse crunch emphasizes the lower fibers of the rectus abdominis and the lower abdominals more than standard crunches.'},
{id:'l127',cat:'Core & Lumbar',name:'Prone Hip Extension Progression (Weight)',pos:'Prone, ankle weight',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Add an ankle weight to the prone hip extension exercise. Maintaining a neutral spine, lift one straight leg off the surface against the added resistance. A natural progression of the bodyweight version used when basic prone extension becomes easy.'},
{id:'l128',cat:'Core & Lumbar',name:'Standing Rotational Reach (Thoracolumbar Integration)',pos:'Standing',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Stand with both arms extended forward. Rotate the trunk to one side while simultaneously reaching both arms further in the rotation direction. Feel the rotation come from the thoracic and lumbar spine together. Return to center and rotate the other way. A dynamic integrated trunk rotation mobility and control exercise.'},
{id:'l129',cat:'Core & Lumbar',name:'Hip Hinge with Dowel Check',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Hold a dowel along the spine with three contact points: back of head, between shoulder blades, and sacrum. Hinge forward at the hips while maintaining all three contact points with the dowel. Loss of any contact indicates a deviation from the neutral-spine hip hinge. A biofeedback technique for learning proper hip hinge mechanics.'},
{id:'l130',cat:'Core & Lumbar',name:'Standing Anti-Lateral Flexion (Band from Above)',pos:'Standing',sets:3,reps:'10 each side',hold:'5 sec',freq:'Daily',instr:'Anchor a band above on one side. Hold the handle with the same-side hand, arm down. Resist the lateral pull of the band by keeping the trunk perfectly upright. A standing anti-lateral-flexion exercise that builds quadratus lumborum and lateral core endurance in a functional position.'},
{id:'l131',cat:'Core & Lumbar',name:'Step-Up with Hip Hinge Forward',pos:'Standing at step',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Place one foot on a step. Hinge forward slightly at the hip as you push through the step foot to stand up. The forward lean increases the hip extensor demand compared to an upright step-up. Used in late-stage lumbar and hip rehabilitation for functional strength.'},
{id:'l132',cat:'Core & Lumbar',name:'Goblet Squat',pos:'Standing',sets:3,reps:'12',hold:'2 sec at bottom',freq:'Daily',instr:'Hold a dumbbell or kettlebell at chest height with both hands. Squat downward while keeping the weight close to the chest and the trunk upright. The anterior load counterbalances the tendency to lean forward, making the goblet squat an excellent squat teaching tool and a functional strength exercise.'},
{id:'l133',cat:'Core & Lumbar',name:'Lumbar Multifidus and Transversus Abdominis Co-Activation',pos:'Quadruped',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'On hands and knees in neutral spine, simultaneously contract the pelvic floor upward, draw the lower abdomen slightly inward, and gently firm the muscles along the sides of the spine (multifidus). Hold while breathing normally. This co-activation of the deep spinal stabilizers is the foundation of lumbar segmental stabilization programs.'},
{id:'l134',cat:'Core & Lumbar',name:'Hip Extension Endurance in Prone (Alternating)',pos:'Prone',sets:3,reps:'20 alternating',hold:'2 sec each',freq:'Daily',instr:'Lie face down and alternately lift each straight leg a few inches off the floor, in a slow reciprocal alternating pattern like flutter kicks. Builds gluteal and lumbar extensor endurance simultaneously. Keep the movement controlled and the pelvis in contact with the floor throughout.'},
{id:'l135',cat:'Core & Lumbar',name:'Trunk Rotation Stretch (Seated)',pos:'Seated in chair',sets:3,reps:'3 each side',hold:'20-30 sec',freq:'Daily',instr:'Sit upright in a chair. Rotate the trunk to one side and place the opposite hand on the outside of the knee to add gentle overpressure. Look over the shoulder in the direction of rotation. Hold, then return to center. A gentle daily thoracolumbar rotation stretch appropriate for all fitness levels.'},
// HIP h104-h118 (15)
{id:'h104',cat:'Hip',name:'Piriformis Stretch (Supine Figure 4)',pos:'Supine',sets:3,reps:'3 each side',hold:'30-60 sec',freq:'2x/day',instr:'Lie on your back with knees bent. Cross one ankle over the opposite knee. Reach through the crossed leg and pull the lower thigh toward your chest. Feel a deep stretch in the outer hip of the crossed leg. The most commonly prescribed stretch for the piriformis and deep hip external rotators.'},
{id:'h105',cat:'Hip',name:'IT Band Stretch (Standing)',pos:'Standing beside wall',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'Stand with the affected leg furthest from the wall. Cross the affected leg behind the other leg and lean the hip toward the wall, feeling a stretch along the outer thigh. The further you lean and cross, the deeper the IT band stretch. Used for IT band syndrome and lateral knee or hip pain.'},
{id:'h106',cat:'Hip',name:'IT Band Foam Rolling',pos:'Side-lying on foam roll',sets:1,reps:'2-3 min each side',hold:'—',freq:'Daily',instr:'Lie on your side with the foam roll under the outer thigh. Roll slowly from just below the hip to just above the knee. Pause on particularly tender spots for 30-60 seconds. IT band foam rolling addresses the lateral fascial stiffness contributing to IT band syndrome and lateral hip pain.'},
{id:'h107',cat:'Hip',name:'Hip Flexor Kneeling Stretch (With Rotation)',pos:'Half-kneeling',sets:3,reps:'3 each side',hold:'30 sec',freq:'2x/day',instr:'In a half-kneeling position with the affected knee down, shift your weight forward into the hip flexor stretch. Then rotate the trunk toward the front leg while maintaining the stretch. The rotation adds a component of iliopsoas stretch that the straight hip flexor stretch misses.'},
{id:'h108',cat:'Hip',name:'Hip Strengthening in Functional Positions (Squat to Chair)',pos:'Standing in front of chair',sets:3,reps:'15',hold:'2 sec hover',freq:'Daily',instr:'Stand in front of a chair. Lower toward the seat slowly, hovering above it for 2 seconds before either sitting fully or returning to standing. The controlled lowering without sitting builds eccentric hip and quad control in the most universally functional movement in daily life.'},
{id:'h109',cat:'Hip',name:'Lateral Hip and Glute Strengthening (Fire Hydrant to Kickback)',pos:'Quadruped',sets:3,reps:'12 each',hold:'2 sec',freq:'Daily',instr:'From hands and knees, perform a fire hydrant (knee up and out) then transition directly to a kickback (extend the leg back). Return the knee to the fire hydrant position and down. Combining these two movements builds both hip abductor and extensor strength in a flowing pattern without stopping between repetitions.'},
{id:'h110',cat:'Hip',name:'Standing Hip CARs with Band Resistance',pos:'Standing',sets:2,reps:'5 each side',hold:'—',freq:'Daily',instr:'Stand on one leg. Perform a controlled articular rotation at the hip (large circles in both directions) while fighting against a light resistance band attached to the moving ankle. The band increases the controlled active muscle demand through every point of the rotation.'},
{id:'h111',cat:'Hip',name:'Resisted Hip Flexion in Supine (Leg Lowering)',pos:'Supine',sets:3,reps:'10 each',hold:'—',freq:'Daily',instr:'Lie on your back with one leg raised to 90 degrees. Lower the leg slowly toward the floor against gravity over 4-5 seconds, stopping just before the low back arches. Return to 90 degrees. A demanding eccentric hip flexor and core exercise that simultaneously builds hip flexor strength and lumbar stability.'},
{id:'h112',cat:'Hip',name:'Hip Impingement Avoidance Training',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Practice the prescribed movement modifications to avoid provocative hip positions while still performing functional tasks. For FAI: avoid combined hip flexion, adduction, and internal rotation simultaneously. Practice sit-to-stand, squatting, and stair patterns using modified hip positioning to reduce impingement during daily activities.'},
{id:'h113',cat:'Hip',name:'Hip Precaution Training Post-THA (Standard)',pos:'Various functional positions',sets:1,reps:'Daily tasks',hold:'—',freq:'Daily',instr:'Practice all daily activities using total hip arthroplasty precautions: do not flex the hip past 90 degrees, do not cross the legs, and do not turn the foot of the operated leg inward (posterior approach precautions). Practice getting in and out of chairs, bed, cars, and toilets while following these precautions.'},
{id:'h114',cat:'Hip',name:'Hip Abductor Strengthening - Resisted Side Kick',pos:'Standing',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand with a band around the ankles. Kick the leg out to the side to approximately 30-45 degrees against the resistance, keeping the toes forward and the trunk upright. Return slowly. A functional standing hip abductor exercise in the position most relevant to walking and stair mechanics.'},
{id:'h115',cat:'Hip',name:'Hip Adductor Foam Rolling',pos:'Prone, inner thigh on foam roll',sets:1,reps:'2 min each side',hold:'—',freq:'Daily',instr:'Lie face down with the foam roll placed along the inner thigh of one leg. Roll slowly from the groin to just above the knee along the adductors. Pause on tender spots. Used for adductor tightness contributing to groin pain, medial knee pain, and hip rotation restriction.'},
{id:'h116',cat:'Hip',name:'Glute Foam Rolling',pos:'Seated on foam roll',sets:1,reps:'2 min each side',hold:'—',freq:'Daily',instr:'Sit on the foam roll with the affected hip. Cross the ankle over the opposite knee to target the deep gluteals and piriformis. Slowly roll through the gluteal region, pausing on tender spots. Address the entire posterior hip from the sacrum to the greater trochanter.'},
{id:'h117',cat:'Hip',name:'Hip External Rotation Strengthening in Standing (Band)',pos:'Standing',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand with a band anchored medially at ankle level. Keeping the knee straight, rotate the entire leg outward against the resistance. Return slowly. A direct hip external rotator strengthening exercise used in FAI, posterior hip instability, and patellar tracking rehabilitation.'},
{id:'h118',cat:'Hip',name:'Hip Posterior Chain Integration (Deadlift Pattern Progression)',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Progress the hip hinge pattern through bodyweight, then resistance band, then light barbell or dumbbell Romanian deadlift as tolerated. The hip-dominant deadlift pattern is the single most comprehensive posterior chain strengthening exercise and is a key functional goal across all hip and lumbar rehabilitation programs.'},
// KNEE k103-k116 (14)
{id:'k103',cat:'Knee',name:'Quad and Hamstring Co-Contraction',pos:'Seated, leg straight',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Sit with the leg straight. Simultaneously contract both the quadriceps (pushing the knee down) and the hamstrings (pulling the heel back) at the same time. The co-contraction creates dynamic joint stability without any movement. Used after ACL injury to re-establish protective co-contraction patterns before more dynamic exercise.'},
{id:'k104',cat:'Knee',name:'Hamstring Stretching (Standing)',pos:'Standing',sets:3,reps:'3 each',hold:'30 sec',freq:'2x/day',instr:'Stand and place the heel of one leg on a slightly elevated surface (a step or chair). Keep the knee straight and lean the trunk forward from the hips (not rounding the back). Hold the hamstring stretch. The standing position allows a more functional and often better-tolerated hamstring stretch than the supine version.'},
{id:'k105',cat:'Knee',name:'Hamstring Stretching (Supine)',pos:'Supine',sets:3,reps:'3 each',hold:'30 sec',freq:'2x/day',instr:'Lie on your back and raise one leg with the knee straight, holding the thigh with both hands. Hold the stretch in the hamstrings at the limit of comfortable range. The most commonly prescribed hamstring flexibility exercise across all knee, hip, and lumbar conditions where hamstring tightness is a contributing factor.'},
{id:'k106',cat:'Knee',name:'Quad Stretching (Standing)',pos:'Standing',sets:3,reps:'3 each',hold:'30 sec',freq:'2x/day',instr:'Stand on one leg. Bend the other knee, grasping the ankle behind you and holding the foot toward the buttock. Keep the knees together and the trunk upright. A standard quad flexibility exercise used across all knee conditions and as a standard athletic warm-down stretch.'},
{id:'k107',cat:'Knee',name:'Calf Stretching (Gastrocnemius)',pos:'Standing at wall',sets:3,reps:'3 each',hold:'30 sec',freq:'2x/day',instr:'Stand facing a wall, hands on the surface. Step one foot back. Keep the back heel on the floor and the back knee straight. Lean toward the wall until you feel the stretch in the upper calf of the back leg. A standard gastrocnemius stretch used across all lower extremity conditions.'},
{id:'k108',cat:'Knee',name:'Calf Stretching (Soleus)',pos:'Standing at wall, knee bent',sets:3,reps:'3 each',hold:'30 sec',freq:'2x/day',instr:'Perform the standard calf stretch but bend the back knee slightly while keeping the heel on the floor. The bent knee slackens the gastrocnemius, allowing the stretch to target the deeper soleus muscle. Used alongside gastrocnemius stretching for complete Achilles and calf flexibility restoration.'},
{id:'k109',cat:'Knee',name:'Knee Flexion Passive Stretch (Prone)',pos:'Prone',sets:3,reps:'3',hold:'30-60 sec',freq:'2x/day',instr:'Lie face down. Bend one knee and hold the ankle, pulling the heel toward the buttock. Hold. A passive stretch for knee flexion range of motion used when active range is limited, such as after total knee replacement or prolonged immobilization.'},
{id:'k110',cat:'Knee',name:'IT Band Foam Rolling (Lateral Thigh)',pos:'Side-lying on foam roll',sets:1,reps:'2 min each side',hold:'—',freq:'Daily',instr:'Lie on your side with the foam roll under the outer thigh. Support your weight on the forearm. Roll slowly from the hip to the knee. Pause on tender areas. Used for IT band syndrome and lateral knee pain. Note that many physiotherapists believe the IT band itself cannot be stretched but that the surrounding tissue and lateral quad contribute to tightness.'},
{id:'k111',cat:'Knee',name:'Patellar Mobilization (Self)',pos:'Supine or seated, knee straight',sets:3,reps:'10 each direction',hold:'3 sec',freq:'Daily',instr:'Relax the quad completely. Using the fingertips, gently glide the kneecap upward, downward, and to each side, and then tilt it by pressing one edge inward. Hold each glide briefly. Patellar self-mobilization maintains or restores patellar mobility and is particularly important after knee surgery to prevent infrapatellar fat pad fibrosis or patellar entrapment.'},
{id:'k112',cat:'Knee',name:'Knee OA Exercise Class Participation',pos:'Group fitness setting',sets:1,reps:'45-60 min class',hold:'—',freq:'2-3x/week',instr:'Attend your prescribed exercise class for knee osteoarthritis (such as ESCAPE-pain or a hydrotherapy class). Group exercise for knee OA has additional benefits beyond the physical exercises including peer support, adherence, and the social environment. Regular class attendance is associated with better long-term outcomes than home exercise alone.'},
{id:'k113',cat:'Knee',name:'Quad Foam Rolling',pos:'Prone on foam roll',sets:1,reps:'2 min each',hold:'—',freq:'Daily',instr:'Lie face down with the foam roll under the front of one thigh. Roll slowly from just above the knee to the hip crease. Pause on tender spots. Quad foam rolling addresses anterior compartment tightness contributing to patellar tracking issues, knee pain, and hip flexor tightness.'},
{id:'k114',cat:'Knee',name:'Knee Active Assisted Extension (AAROM)',pos:'Supine',sets:3,reps:'10',hold:'2 sec',freq:'Daily',instr:'Lie on your back. Using a strap around the ankle or the other foot under the heel, assist the affected leg into full extension. Hold at full extension, then slowly lower. Primarily used after total knee replacement when active extension is limited by quad weakness, to achieve full extension range without full quad activation.'},
{id:'k115',cat:'Knee',name:'Knee Brace Weaning Program',pos:'Standing and walking',sets:1,reps:'Progressive time',hold:'—',freq:'Daily',instr:'Follow your prescribed knee brace weaning schedule, gradually increasing time without the brace during activities as strength and confidence improve. Brace weaning progresses from straight-line walking, then cutting, then sport-specific activities. Never discontinue brace use during high-risk activities without your therapist\'s and surgeon\'s clearance.'},
{id:'k116',cat:'Knee',name:'Return to Kneeling Tolerance',pos:'Kneeling on soft surface',sets:3,reps:'—',hold:'1-5 min progressive',freq:'Daily',instr:'Practice kneeling on a soft surface for gradually increasing durations. Begin with a cushioned mat and progress to firmer surfaces as tolerance improves. Return to comfortable kneeling is an important functional goal after total knee replacement, particularly for religious practice, gardening, and floor-based activities.'},
// ANKLE & FOOT a91-a103 (13)
{id:'a91',cat:'Ankle & Foot',name:'Ankle Dorsiflexion AROM (Towel Slide)',pos:'Supine, heel on towel on smooth floor',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with the heel on a small towel on a smooth floor. Slide the foot toward the buttock by bending the ankle and knee, then slide it back out. The towel reduces friction allowing easy motion. Used early after ankle injury or surgery to restore dorsiflexion ROM without weight bearing.'},
{id:'a92',cat:'Ankle & Foot',name:'Ankle Strengthening Circuit (Complete)',pos:'Seated',sets:3,reps:'15 each direction',hold:'2 sec',freq:'Daily',instr:'Perform the complete ankle circuit: dorsiflexion, plantarflexion, inversion, and eversion each with light band resistance. Completing all four directions ensures balanced ankle musculature development, important after ankle sprain where selective weakness in eversion is common.'},
{id:'a93',cat:'Ankle & Foot',name:'Calf Foam Rolling',pos:'Seated on floor, calf on foam roll',sets:1,reps:'2 min each',hold:'—',freq:'Daily',instr:'Sit on the floor with the foam roll under one calf. Cross the other leg over for added pressure. Roll slowly from just above the ankle to the back of the knee. Pause on tender spots. Calf foam rolling addresses the tissue restrictions contributing to ankle dorsiflexion limitation, calf tightness, and Achilles dysfunction.'},
{id:'a94',cat:'Ankle & Foot',name:'Plantar Fascia Self-Massage with Ball',pos:'Seated or standing',sets:1,reps:'2-3 min each foot',hold:'—',freq:'Daily (before first steps)',instr:'Place a tennis ball or frozen water bottle on the floor. Roll the arch of the foot over it with moderate pressure. Begin with the heel, moving to the arch and ball of the foot. Perform before taking your first steps in the morning. Regular plantar fascia self-massage reduces morning pain and improves fascia mobility in plantar fasciitis.'},
{id:'a95',cat:'Ankle & Foot',name:'Standing Ankle Eversion Strengthening',pos:'Standing',sets:3,reps:'15 each',hold:'2 sec',freq:'Daily',instr:'Stand with a band anchored on the same side at ankle height, looped around the outside of the foot. Lift the foot and evert it against the resistance while standing on the other leg. A more functional position for peroneal strengthening than seated exercises, used in later stages of ankle sprain rehabilitation.'},
{id:'a96',cat:'Ankle & Foot',name:'Ankle ROM in Seated Gravity-Eliminated',pos:'Seated, foot unsupported',sets:3,reps:'10 each direction',hold:'2 sec',freq:'Daily',instr:'Sit with the foot hanging free, not touching the floor. Move through full ankle dorsiflexion, plantarflexion, inversion, and eversion actively against gravity eliminated. Used in early post-fracture or post-surgical ankle rehabilitation when weight bearing is restricted but active motion is cleared.'},
{id:'a97',cat:'Ankle & Foot',name:'Balance and Reach with Ball Kick',pos:'Standing on one leg',sets:3,reps:'10 each direction',hold:'—',freq:'Daily',instr:'Stand on one leg. Kick a ball (or reach a foot to tap a target) in the anterior, lateral, and posterior directions with the free leg, returning to single-leg balance between each reach. Combines dynamic balance training with a sport-relevant and motivating activity.'},
{id:'a98',cat:'Ankle & Foot',name:'Ankle and Foot Intrinsic Strengthening (Towel Grab)',pos:'Seated, foot flat on towel',sets:3,reps:'20',hold:'2 sec',freq:'Daily',instr:'Sit with your bare foot flat on a hand towel on the floor. Bunch the towel toward you by gripping with the toes. Smooth it out and repeat. A classic intrinsic foot strengthening exercise that requires no equipment and can be performed anywhere.'},
{id:'a99',cat:'Ankle & Foot',name:'Heel-to-Toe Walking (Tandem Gait)',pos:'Walking in corridor',sets:3,reps:'20 steps',hold:'—',freq:'Daily',instr:'Walk forward placing each foot directly in front of the other in a heel-to-toe pattern, creating a straight line of steps. Arms can be held out for balance. Used in vestibular, neurological, and ankle rehabilitation programs to build dynamic balance and controlled weight transfer in narrow base of support.'},
{id:'a100',cat:'Ankle & Foot',name:'Running on Uneven Terrain Progression',pos:'Grass or trail',sets:1,reps:'10-30 min',hold:'—',freq:'2-3x/week',instr:'Progress outdoor running from flat even surfaces to grass, then gentle trail terrain, then more uneven or hilly terrain as ankle stability and confidence improve. Running on varied terrain develops the reactive ankle stability needed for community and sport activity that treadmill running cannot replicate.'},
{id:'a101',cat:'Ankle & Foot',name:'Ankle and Foot Taping (Prophylactic)',pos:'Seated, foot in slight plantarflexion',sets:1,reps:'—',hold:'During high-risk activity',freq:'As prescribed for activity',instr:'Apply the prescribed ankle taping technique before high-risk activities as taught by your therapist, or request it be applied by your athletic trainer. Prophylactic ankle taping reduces recurrence of lateral ankle sprain in athletes with a prior history of sprain by limiting excessive inversion range.'},
{id:'a102',cat:'Ankle & Foot',name:'Barefoot Balance Training Progression',pos:'Standing barefoot on varied surfaces',sets:3,reps:'—',hold:'30 sec each surface',freq:'Daily',instr:'Progress barefoot balance training through: firm floor, grass, sand, gravel, and foam pad. Barefoot training on varied surfaces stimulates the plantar mechanoreceptors, builds intrinsic foot strength, and improves proprioceptive input from the foot and ankle, all of which are typically diminished in patients who wear orthotics or supportive footwear exclusively.'},
{id:'a103',cat:'Ankle & Foot',name:'Plyometric Ankle Stiffness Drills (Pogos)',pos:'Standing',sets:3,reps:'20 sec',hold:'—',freq:'2-3x/week',instr:'Bounce rapidly on both feet with minimal knee bend, staying tall and stiff through the ankle and calf, like bouncing on a pogo stick. Minimizes ground contact time. Builds ankle stiffness and the reactive spring quality needed for running economy and sport performance. A fundamental plyometric drill used in late-stage ankle and Achilles rehabilitation.'},
// BALANCE b76-b85 (10)
{id:'b76',cat:'Balance & Functional',name:'Modified Clinical Test of Sensory Interaction (mCTSIB)',pos:'Standing on firm and foam surfaces',sets:3,reps:'—',hold:'30 sec each condition',freq:'Daily',instr:'Stand under four conditions in order: firm surface eyes open, firm surface eyes closed, foam surface eyes open, foam surface eyes closed. Time each condition. A standardized balance assessment and training paradigm used clinically to identify which sensory system is most impaired and to design targeted balance training.'},
{id:'b77',cat:'Balance & Functional',name:'Single-Leg Stance with Arm Movements',pos:'Standing on one leg',sets:3,reps:'10 arm movements per set',hold:'—',freq:'Daily',instr:'Stand on one leg. Perform shoulder-level arm movements (forward, to side, across body, overhead) in sequence while maintaining single-leg balance. The arm movements create reactive perturbations that challenge the hip, knee, and ankle stabilizers of the stance leg.'},
{id:'b78',cat:'Balance & Functional',name:'Stepping Response Training (Protective Stepping)',pos:'Standing near support',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Stand with a support within reach. A partner gently and unexpectedly tips your body beyond the limits of stability, requiring a protective step to prevent a fall. Practice stepping with both legs and in multiple directions. Trains the protective stepping response that prevents falls when balance is lost, used in fall prevention programs.'},
{id:'b79',cat:'Balance & Functional',name:'Foam Pad Single-Leg Balance',pos:'Standing on foam',sets:3,reps:'—',hold:'20-30 sec each leg',freq:'Daily',instr:'Stand on one leg on a 4-inch foam pad. The compressible foam reduces the quality of somatosensory information from the foot and ankle, forcing greater reliance on vestibular and visual inputs. Used to progress balance training beyond what is achievable on a firm surface.'},
{id:'b80',cat:'Balance & Functional',name:'Reaching to Pick Up Object from Floor (Single-Leg)',pos:'Standing',sets:3,reps:'10 each side',hold:'—',freq:'Daily',instr:'Stand on one leg. Bend forward and reach down to pick up a small object from the floor, maintaining single-leg balance. Stand back upright. Directly mimics the functional challenge of picking things up from the floor that many patients find difficult and fear after lower extremity injury or surgery.'},
{id:'b81',cat:'Balance & Functional',name:'Functional Mobility - Car Transfer Practice',pos:'Seated in chair beside car',sets:3,reps:'3 trials',hold:'—',freq:'Daily',instr:'Practice getting in and out of a car seat using the prescribed technique, adapting for hip, knee, or back restrictions as directed. Specifically rehearse: positioning, lowering onto the seat, swinging the legs in, and reversing the sequence. Car transfers are one of the most commonly identified difficult functional tasks after lower extremity surgery.'},
{id:'b82',cat:'Balance & Functional',name:'Ascending and Descending Curbs',pos:'Standing at curb',sets:3,reps:'5 each direction',hold:'—',freq:'Daily',instr:'Practice stepping up and down from curbs in a controlled manner, leading with the stronger leg going up and the weaker leg going down (following the stair rule). Curb negotiation is a fundamental community mobility skill that is frequently impaired after lower extremity injury or surgery.'},
{id:'b83',cat:'Balance & Functional',name:'Grocery Shopping Simulation (Carry and Navigate)',pos:'Walking with weighted bag',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Walk around an open space or through corridors carrying a grocery bag of graduated weight, practicing stopping, turning, and navigating around obstacles while holding the bag. This simulation directly addresses one of the most commonly reported functional activity limitations in lower extremity and balance rehabilitation patients.'},
{id:'b84',cat:'Balance & Functional',name:'Pool Balance and Gait Training',pos:'In pool, chest or waist depth',sets:1,reps:'20-30 min',hold:'—',freq:'Daily',instr:'Perform balance and walking activities in chest or waist-deep water: tandem walking, single-leg balance, lateral stepping, backward walking, and step-overs. The buoyancy reduces fall risk and joint loading while the water resistance and instability challenge balance. Often the first environment in which patients with severe balance impairment can practice walking without constant fall risk.'},
{id:'b85',cat:'Balance & Functional',name:'Obstacle Course Navigation',pos:'Walking through course',sets:3,reps:'2-3 runs through course',hold:'—',freq:'Daily',instr:'Walk through a course set up with cones, steps, floor targets, and narrow passages. Each run focuses on different challenges: speed, accuracy, avoiding touching cones, or carrying an object. A functional and engaging balance training format that closely mimics the demands of real community environments.'},
// THORACIC t46-t50 (5)
{id:'t46',cat:'Thoracic',name:'Pectoral Minor Stretching (Corner Stretch Progression)',pos:'Standing in corner',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand in a corner with forearms on each wall at 90 degrees of shoulder abduction. Lean into the corner. Progress by raising the arm height incrementally (from 70 to 90 to 110 degrees of abduction) in subsequent sets to target different portions of the pec minor and anterior deltoid fascia.'},
{id:'t47',cat:'Thoracic',name:'Thoracic Segmental Extension (Supine Towel Roll)',pos:'Supine',sets:3,reps:'5 positions',hold:'1-2 min each',freq:'Daily',instr:'Roll a bath towel and place it horizontally under the thoracic spine. Begin at mid-thoracic (T6-8) and allow the spine to extend over the roll. Hold for 1-2 minutes before moving the roll one vertebral level up and repeating. A gentle, prolonged thoracic extension mobilization requiring no equipment beyond a towel.'},
{id:'t48',cat:'Thoracic',name:'Seated Thoracic Rotation with Band Pull',pos:'Seated on stool',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Sit on a backless stool. Hold a resistance band in both hands anchored to one side at shoulder height. Rotate the trunk to the other side while simultaneously pulling the band. Combines thoracic rotation with a rowing pattern that also activates the thoracic extensors during the rotation.'},
{id:'t49',cat:'Thoracic',name:'Standing Thoracic Extension Against Wall (Thoracic Widget)',pos:'Standing with hands clasped behind head',sets:3,reps:'5',hold:'5 sec',freq:'Daily',instr:'Stand with your back to a wall. Clasp your hands behind your head. Press the mid-thoracic region into the wall as you extend backward, allowing the thoracic spine to curve over the edge of the doorframe or a rolled towel placed vertically on the wall. A targeted thoracic extension self-mobilization for the upper and mid-thoracic segments.'},
{id:'t50',cat:'Thoracic',name:'W-Exercise for Shoulder Blade Retraction',pos:'Prone or standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie face down or stand and raise the elbows to shoulder height with forearms hanging down, forming a W shape with the arms. Squeeze the shoulder blades together and retract the elbows backward, keeping the W shape. Hold briefly. Combines middle and lower trapezius activation with thoracic extension in a functional strengthening position.'},
// POST-OP p63-p70 (8)
{id:'p63',cat:'Post-Op & General',name:'Therapeutic Heat Modality (Moist Hot Pack)',pos:'Prone or supine',sets:1,reps:'—',hold:'15-20 min',freq:'Before stretching or exercise as prescribed',instr:'Apply a moist heat pack wrapped in a protective towel to the target area. The heat penetrates superficial tissues, increases blood flow, reduces muscle guarding, and improves tissue extensibility. Used before stretching to gain greater range of motion, and for chronic muscle tension, arthritis, and subacute injury management.'},
{id:'p64',cat:'Post-Op & General',name:'Cryotherapy (Ice Massage)',pos:'Seated or prone',sets:1,reps:'5-7 min',hold:'—',freq:'After exercise or as needed for pain',instr:'Use a large piece of ice frozen in a foam cup (peel back the top to expose the ice). Apply directly to the skin in slow circular or linear strokes over the painful area. Ice massage produces a rapid local cooling effect with four stages: cold, burning, aching, and numbness. Stop when numbness is achieved (5-7 min). More effective than a static ice pack for superficial tissue such as tendons.'},
{id:'p65',cat:'Post-Op & General',name:'Functional Capacity Building (Progressive Activity)',pos:'All functional positions',sets:1,reps:'As per program',hold:'—',freq:'Daily',instr:'Systematically increase the intensity, duration, and complexity of functional activities each week, tracking objective measures such as distance walked, weight lifted, or time performed. A structured functional capacity building program bridges the gap between clinic discharge and full return to work, sport, or leisure activities.'},
{id:'p66',cat:'Post-Op & General',name:'Manual Lymphatic Drainage Exercise',pos:'Supine, limb elevated',sets:3,reps:'10 min',hold:'—',freq:'Daily',instr:'Perform the prescribed diaphragmatic breathing and gentle circular lymphatic drainage massage strokes as taught by your therapist, working from the proximal lymph nodes distally. Used for post-surgical lymphedema management, particularly after axillary lymph node dissection, to reduce swelling and prevent progression.'},
{id:'p67',cat:'Post-Op & General',name:'Compression Garment Use and Skin Care',pos:'Varies',sets:1,reps:'—',hold:'As prescribed hours per day',freq:'Daily',instr:'Wear your compression garment for the prescribed number of hours daily. Inspect the skin under the garment daily for irritation or breakdown. Follow your therapist\'s skin care protocol, including moisturizing and protecting the affected limb. Compression garment compliance is the most important factor in long-term lymphedema management.'},
{id:'p68',cat:'Post-Op & General',name:'Graded Exposure for Fear-Avoidance',pos:'Varies',sets:1,reps:'Per hierarchical list',hold:'—',freq:'Daily',instr:'Follow your individually created graded exposure hierarchy, beginning with the least feared movement or activity on your list and progressing systematically. Graded exposure is an evidence-based psychological and physical intervention for fear-avoidance behavior in chronic musculoskeletal pain, helping patients re-engage with movements they have been avoiding due to pain fears.'},
{id:'p69',cat:'Post-Op & General',name:'Acceptance and Commitment Therapy Movement Practice',pos:'Various',sets:1,reps:'Throughout day',hold:'—',freq:'Daily',instr:'Practice mindful engagement with your prescribed exercises and daily movements, noticing thoughts and feelings about pain without allowing them to dictate avoidance behavior. Committed action toward valued activities despite pain is the core principle of ACT applied to chronic pain and disability rehabilitation.'},
{id:'p70',cat:'Post-Op & General',name:'Reassessment and Goal Update Session',pos:'Clinic',sets:1,reps:'—',hold:'—',freq:'Every 4-6 weeks',instr:'At your scheduled reassessment, work with your therapist to measure objective outcomes (strength, range of motion, functional tests) and compare to your initial and previous values. Update short and long-term goals based on your progress. Regular structured reassessment is the clinical standard for monitoring rehabilitation effectiveness and adjusting the program accordingly.'},
// NEURO n56-n63 (8)
{id:'n56',cat:'Neuro & Vestibular',name:'Disequilibrium Management Exercise',pos:'Standing near support',sets:3,reps:'—',hold:'30 sec each surface',freq:'Daily',instr:'Systematically practice balance on progressively challenging surfaces: firm with eyes open, firm with eyes closed, foam with eyes open, foam with eyes closed. Disequilibrium (a sense of imbalance without spinning vertigo) is treated with sensory reweighting exercises targeting the somatosensory, visual, and vestibular systems progressively.'},
{id:'n57',cat:'Neuro & Vestibular',name:'Post-Concussion Return to Learn Protocol',pos:'Desk or seated',sets:1,reps:'Progressive duration',hold:'—',freq:'Daily',instr:'Begin with 5-10 minutes of cognitive activity (reading, screen use) and track whether symptoms are provoked. Increase duration by 5-10 minute increments daily as tolerated. The return-to-learn protocol parallels the return-to-sport protocol and should be managed alongside your physician and school administration.'},
{id:'n58',cat:'Neuro & Vestibular',name:'Parkinson\'s Gait Training (LSVT BIG Stepping)',pos:'Standing, walking',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Practice taking exaggerated big steps with high knee lift and full heel-to-toe pattern. Use a metronome to maintain target cadence. Large-amplitude stepping specifically targets the hypokinesia (reduced movement amplitude) that characterizes Parkinson\'s gait and is a core component of the LSVT BIG approach.'},
{id:'n59',cat:'Neuro & Vestibular',name:'Multiple Sclerosis Fatigue Management Exercise',pos:'Seated or standing',sets:1,reps:'Short frequent bouts',hold:'—',freq:'Multiple short sessions daily',instr:'Perform brief 5-10 minute exercise bouts with rest periods in between rather than single long sessions. Exercise in a cool environment and at cooler times of day to prevent heat-induced symptom exacerbation (Uhthoff\'s phenomenon). Paced, cool-environment exercise is the most effective approach for building fitness in MS without worsening fatigue.'},
{id:'n60',cat:'Neuro & Vestibular',name:'Cognitive Dual-Task Balance Training',pos:'Standing on varied surfaces',sets:3,reps:'2-3 min each',hold:'—',freq:'Daily',instr:'Perform balance exercises (single-leg stance, foam pad standing, tandem) simultaneously with cognitive tasks of increasing difficulty (counting backward by 2, naming categories, answering questions). Cognitive-motor dual-task training improves the automated control of balance and reduces fall risk during real-world situations that require simultaneous thinking and walking.'},
{id:'n61',cat:'Neuro & Vestibular',name:'Head Impulse Test Training Feedback',pos:'Seated',sets:3,reps:'20 each direction',hold:'—',freq:'Daily',instr:'A partner rapidly rotates your head 10-15 degrees to the affected side. Focus on a target directly in front of you. If the target moves from view and a corrective saccade is needed to re-fixate, it indicates VOR deficit on that side. Repeated head impulses to the affected side drive vestibular compensation when combined with gaze stabilization exercises.'},
{id:'n62',cat:'Neuro & Vestibular',name:'Gait Retraining Post-TBI (Traumatic Brain Injury)',pos:'Walking',sets:1,reps:'20-30 min',hold:'—',freq:'Daily',instr:'Walk in progressively complex environments from quiet corridor to busy hallways to outdoor community settings. Address gait speed, step symmetry, and head movement tolerance simultaneously. TBI gait rehabilitation must account for both the physical and cognitive processing demands of walking in complex environments.'},
{id:'n63',cat:'Neuro & Vestibular',name:'Neuropathic Pain Desensitization Program',pos:'Seated at table',sets:3,reps:'10 min per area',hold:'—',freq:'Daily',instr:'Apply progressively varied tactile stimuli (soft fabric, gel, textured glove, firm pressure) to the area of neuropathic hypersensitivity in a systematic desensitization sequence, working from outside the most sensitive area inward. Used for allodynia and hyperalgesia following nerve injury, CRPS, or post-surgical neuropathic pain.'},
// SPORT sp53-sp58 (6)
{id:'sp53',cat:'Sport-Specific & Plyometric',name:'Jump Landing Mechanics Coaching',pos:'Standing',sets:3,reps:'10 landings',hold:'3 sec each',freq:'Daily',instr:'Practice jumping and landing with coaching cues for optimal mechanics: land with hips and knees bent, knees tracking over the second toe, quiet landing with equal weight on both feet, and no valgus collapse. Filmed and reviewed with your therapist if possible. Landing mechanics training has the strongest evidence for ACL injury prevention in female athletes.'},
{id:'sp54',cat:'Sport-Specific & Plyometric',name:'Multi-Direction Change of Direction with Decision',pos:'Open space with colored cones',sets:3,reps:'10 decision points',hold:'—',freq:'2-3x/week',instr:'Set up colored cones in different directions. Your therapist or partner points to a cone color at the last second and you change direction to it. The reactive decision-making element prevents the movement from becoming planned and prepares the athlete for the unpredictable demands of actual sport competition.'},
{id:'sp55',cat:'Sport-Specific & Plyometric',name:'Force Plate Jump Analysis and Training',pos:'Standing on force plate',sets:1,reps:'Per assessment',hold:'—',freq:'Every 4 weeks to assess',instr:'Perform jump and landing tasks on a force plate as directed by your therapist. The force plate measures peak force, loading rate, asymmetry, and reactive strength index. These objective data guide return-to-sport decisions and identify persistent deficits not visible to the naked eye.'},
{id:'sp56',cat:'Sport-Specific & Plyometric',name:'Hip and Knee Control During Overhead Throw',pos:'Standing, throwing motion',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'During throwing or serving practice, focus on the lower extremity drive: pushing off the back foot, hip rotation, and transferring power through the trunk and into the throwing arm. Many shoulder injuries in overhead athletes originate from inadequate lower extremity and trunk power generation, overloading the arm.'},
{id:'sp57',cat:'Sport-Specific & Plyometric',name:'Reactive Balance Board Training (Sport Specific)',pos:'Standing on balance board with perturbations',sets:3,reps:'1-2 min bouts',hold:'—',freq:'Daily',instr:'Stand on a balance board while a partner provides unexpected perturbations simulating sport contact or ball reception forces. React to maintain balance. A sport-specific reactive balance training tool used in soccer, basketball, and contact sport return-to-play programs.'},
{id:'sp58',cat:'Sport-Specific & Plyometric',name:'Interval Training (Sport-Specific Conditioning)',pos:'Track, field, or court',sets:1,reps:'Per conditioning program',hold:'—',freq:'2-3x/week',instr:'Perform your sport-specific conditioning intervals as prescribed, matching the work-to-rest ratios of your sport. Restoring sport-specific cardiovascular conditioning alongside strength and power is essential for safe return to sport, as fatigue is a major injury risk factor in the late stages of competition.'},
// PELVIC FLOOR pf39-pf43 (5)
{id:'pf39',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor and Diaphragm Coordination',pos:'Supine',sets:3,reps:'10 breaths',hold:'—',freq:'Daily',instr:'Inhale slowly, allowing the belly and pelvic floor to descend and expand. Exhale slowly, allowing the pelvic floor to gently lift and the abdomen to draw in. The pelvic floor and diaphragm should move in coordination with breathing. Dysfunction of this pressure system is a major contributor to both incontinence and low back pain.'},
{id:'pf40',cat:'Pelvic Floor & Womens Health',name:'Return to High-Impact Exercise Post-Partum',pos:'Standing and running',sets:1,reps:'Per progressive program',hold:'—',freq:'As prescribed',instr:'Follow your individually designed return-to-running or return-to-exercise program beginning at a minimum of 12 weeks postpartum (or as cleared by your OB and pelvic PT). The program systematically builds tissue tolerance, pelvic floor strength, and running load using a symptom-monitoring approach.'},
{id:'pf41',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Strengthening for Stress Incontinence',pos:'Seated, standing, and during exercise',sets:3,reps:'10-15',hold:'8-10 sec',freq:'3x/day',instr:'Perform long-hold pelvic floor contractions (slow twitch fiber focus) in multiple positions, with the goal of maintaining the contraction for 10 seconds by 12 weeks. Combine with quick-flick exercises. This is the evidence-based first-line treatment for stress urinary incontinence with studies showing 40-80% improvement or cure rates with proper technique.'},
{id:'pf42',cat:'Pelvic Floor & Womens Health',name:'Pelvic Organ Prolapse Symptom Management',pos:'Supine and standing',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Perform pelvic floor strengthening in the positions that minimize prolapse symptoms (often supine before building to standing). Learn and use the knack maneuver before any increase in intra-abdominal pressure. Pelvic floor physiotherapy is the first-line treatment for pelvic organ prolapse, with evidence supporting reduction in symptom severity and prolapse stage.'},
{id:'pf43',cat:'Pelvic Floor & Womens Health',name:'Sexual Health Rehabilitation Exercise',pos:'Supine',sets:3,reps:'10',hold:'5 sec relax, 5 sec contract',freq:'Daily',instr:'Practice alternating pelvic floor contractions and deliberate relaxation holds. Address any painful scar tissue mobilization at the vaginal opening or perineum as directed. Pelvic PT for sexual pain (dyspareunia, vaginismus) uses specific relaxation, desensitization, and graded exposure approaches tailored to the individual presentation.'},
// AMPUTEE amp29-amp32 (4)
{id:'amp29',cat:'Amputee & Prosthetic',name:'Residual Limb Shaping and Wrapping',pos:'Seated or supine',sets:1,reps:'—',hold:'23 hrs/day when not wearing prosthesis',freq:'Daily',instr:'Apply the elastic bandage or shrinker sock to the residual limb using the prescribed figure-8 or spiral wrapping technique, starting at the distal end and working proximally. Proper shaping reduces residual limb volume, prepares the limb for prosthetic fitting, and prevents the dependent edema that delays prosthetic use.'},
{id:'amp30',cat:'Amputee & Prosthetic',name:'Prosthetic Community Ambulation Practice',pos:'Outdoors and in community settings',sets:1,reps:'Progressive distance',hold:'—',freq:'Daily',instr:'Practice walking in community environments: uneven terrain, ramps, crowded spaces, stores, and restaurants. Community ambulation practice exposes the amputee to the full range of challenges encountered in real-world environments that controlled clinic and home practice cannot replicate.'},
{id:'amp31',cat:'Amputee & Prosthetic',name:'Upper Limb Phantom Pain Management Exercise',pos:'Seated',sets:3,reps:'15 min',hold:'—',freq:'Daily',instr:'Perform your prescribed combination of phantom limb pain management techniques: mirror therapy, mental imagery of the phantom limb moving, TENS application, or prosthetic use for phantom management. Multiple approaches used in combination are more effective than any single intervention for phantom limb pain.'},
{id:'amp32',cat:'Amputee & Prosthetic',name:'Prosthetic Running (Advanced)',pos:'Open track with running prosthesis',sets:1,reps:'As per running program',hold:'—',freq:'2-3x/week',instr:'Follow your progressive running program with the carbon-fiber running prosthesis, beginning with short walk-jog intervals and progressing to continuous running. Work with both your therapist and prosthetist to optimize running prosthetic socket fit, blade stiffness, and height. Return to running after lower limb amputation is an achievable goal for motivated patients of all ages.'},
// PEDIATRIC peds42-peds46 (5)
{id:'peds42',cat:'Pediatric',name:'Pediatric Handwriting Grip Exercises',pos:'Seated at table',sets:3,reps:'5-10 min',hold:'—',freq:'Daily',instr:'Practice the correct dynamic tripod grip on a weighted pen or textured grip adapter. Progress through pre-writing strokes (vertical lines, horizontal lines, circles, diagonals) before letters. Grip strength, wrist stability, and visual-motor integration are all addressed in pediatric handwriting rehabilitation.'},
{id:'peds43',cat:'Pediatric',name:'Pediatric Sitting Posture and Core Activation',pos:'Seated in school chair',sets:3,reps:'—',hold:'5-10 min progressive',freq:'During school and homework',instr:'Practice maintaining an active, upright sitting posture at a desk: feet flat, hips at 90 degrees, and back tall without slouching. Use a wobble seat cushion if prescribed. Brief active sitting exercises at the desk (subtle core bracing, shoulder rolls) during school day help children with hypotonia or trunk weakness sustain attention and posture.'},
{id:'peds44',cat:'Pediatric',name:'Pediatric Sensory Processing Proprioceptive Activities',pos:'Floor and equipment',sets:1,reps:'30-45 min',hold:'—',freq:'Daily',instr:'Perform heavy work activities designed to provide proprioceptive input: pushing a weighted cart, carrying a backpack with appropriate weight, jumping on a trampoline, animal walks, and wall push-ups. Proprioceptive input is organizing and calming for children with sensory processing disorder and is a primary tool in sensory integration therapy.'},
{id:'peds45',cat:'Pediatric',name:'Pediatric Sports Readiness Conditioning',pos:'Open space',sets:1,reps:'30-45 min',hold:'—',freq:'3-5x/week',instr:'Perform the age and sport-appropriate conditioning program prescribed to prepare the child athlete for return to sport after injury or to build sufficient fitness to participate safely. Include fundamental movement skill practice (running, jumping, throwing, catching) alongside sport-specific conditioning appropriate to the child\'s developmental stage.'},
{id:'peds46',cat:'Pediatric',name:'Pediatric Genu Valgum Correction (Knock Knees)',pos:'Standing and walking',sets:3,reps:'10-15',hold:'5 sec',freq:'Daily',instr:'Perform hip external rotation strengthening (clamshells, side-lying abduction), hip abductor strengthening, and single-leg balance exercises. Practice single-leg squat with focus on maintaining knee alignment over the second toe. Functional genu valgum in children and adolescents often responds well to hip strengthening and movement re-education without surgery.'},
// TMJ j31-j33 (3) - complete the 500
{id:'j31',cat:'TMJ',name:'Oral Motor Strengthening (Tongue Exercises)',pos:'Seated',sets:3,reps:'10 each',hold:'3 sec',freq:'Daily',instr:'Perform: tongue press to palate (press tip firmly into the roof of the mouth and hold), lateral tongue press (press to each cheek wall), and tongue protrusion (push tongue directly forward against resistance from a tongue depressor held by a therapist). Tongue muscle strength and coordination affects jaw mechanics, swallowing, and speech.'},
{id:'j32',cat:'TMJ',name:'TMJ Disc Recapture Exercise',pos:'Seated, in front of mirror',sets:3,reps:'5',hold:'—',freq:'Daily',instr:'Open the mouth just past the point of clicking. Place the tongue on the palate to retract the mandible slightly. While maintaining this position, open further. If this sequence reduces or eliminates the click, it may represent disc recapture. Only perform as specifically directed by your therapist after imaging has characterized your disc position.'},
{id:'j33',cat:'TMJ',name:'Cervical Flexion for TMJ (Chin Tuck Effect on Jaw)',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Perform a chin tuck and notice how this cervical retraction also slightly repositions the mandible. Some patients with TMJ anterior disc displacement find that the chin tuck position reduces jaw pain and clicking by altering the spatial relationship between the condyle and the disc. Use as directed if your therapist has identified this as a beneficial position for your presentation.'},
// CERVICAL c101-c108 (8)
{id:'c101',cat:'Cervical',name:'Cervical Flexion-Rotation Test Position Stretch',pos:'Supine',sets:3,reps:'3 each side',hold:'20-30 sec',freq:'Daily',instr:'Lie on your back. Flex the neck fully forward (chin to chest) then rotate the head to each side as far as comfortable while maintaining the flexed position. This isolates upper cervical (C1-C2) rotation, often restricted in cervicogenic headache. Hold gently at end range.'},
{id:'c102',cat:'Cervical',name:'Cervicogenic Headache Self-Management Routine',pos:'Seated',sets:1,reps:'Full routine',hold:'—',freq:'Daily and at headache onset',instr:'At the first sign of headache, perform your prescribed sequence: suboccipital release, upper trapezius stretch, chin tuck holds, and gentle cervical rotation. Consistent early intervention at symptom onset is more effective than waiting until the headache is fully established.'},
{id:'c103',cat:'Cervical',name:'Cervical Spine Stability Ball Wall Exercise',pos:'Standing against wall with ball',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Place a small ball between the back of your head and a wall. Press your head gently into the ball, holding the contact while performing a chin tuck. This combines cervical extensor isometric activation with deep flexor engagement against a stable surface.'},
{id:'c104',cat:'Cervical',name:'Cervical Spine Stenosis Safe Movement Program',pos:'Seated or standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Perform gentle cervical range of motion within the pain-free and symptom-free range only, avoiding sustained extreme extension which can narrow the spinal canal further in cervical stenosis. Favor flexion and neutral-range movements. Always follow your specific physician and therapist guidance for your stenosis severity.'},
{id:'c105',cat:'Cervical',name:'Cervical Radiculopathy Symptom Centralization Tracking',pos:'Various as directed',sets:1,reps:'Per assessment',hold:'—',freq:'Each visit',instr:'Track whether your prescribed movements cause symptoms to centralize (move from the arm/hand back toward the neck) or peripheralize (move further into the arm/hand). Centralizing movements are generally favorable and should be continued; peripheralizing movements should be avoided. Report your symptom response pattern to your therapist at each visit.'},
{id:'c106',cat:'Cervical',name:'Cervical Extension with Hands Support (Modified)',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Sit tall and place both hands behind the head for light support. Gently extend the neck backward into the support of the hands rather than the hands pushing the head. A modified, lower-demand cervical extension exercise appropriate for patients who find unsupported extension provoking.'},
{id:'c107',cat:'Cervical',name:'Forward Head Posture Self-Correction with Mirror Feedback',pos:'Standing in front of mirror',sets:3,reps:'10',hold:'5 sec',freq:'Several times daily',instr:'Stand sideways to a mirror. Practice aligning the ear directly over the shoulder by performing a chin tuck while watching your profile in the mirror. Visual feedback accelerates the relearning of correct postural alignment, which often feels unusual or exaggerated initially to patients with long-standing forward head posture.'},
{id:'c108',cat:'Cervical',name:'Cervical Spine Self-Assessment Symptom Diary',pos:'Any',sets:1,reps:'—',hold:'—',freq:'Daily',instr:'Record your neck pain intensity, headache frequency, and any arm symptoms each day along with any notable activities or postures that seemed to provoke or relieve symptoms. A symptom diary helps identify patterns and triggers that may not be obvious without systematic daily tracking, and provides objective data for treatment planning.'},
// SHOULDER s141-s148 (8)
{id:'s141',cat:'Shoulder',name:'Shoulder External Rotation Lag Sign Strengthening',pos:'Supine',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Lie on your back with the arm at the side, elbow bent 90 degrees. Have a partner passively rotate the arm to near full external rotation, then ask you to hold the position actively as they release support. If the arm drifts back toward internal rotation (a lag), this indicates infraspinatus weakness or tear. Practice holding the end-range ER position actively for the prescribed time.'},
{id:'s142',cat:'Shoulder',name:'Lift-Off Test Position Strengthening (Subscapularis)',pos:'Standing',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Place the back of your hand against the small of your back. Practice lifting the hand directly off the back without extending the elbow or rotating the trunk. This isolates and strengthens the subscapularis specifically, the primary internal rotator and an important anterior shoulder stabilizer.'},
{id:'s143',cat:'Shoulder',name:'Shoulder Belly Press Strengthening',pos:'Standing',sets:3,reps:'15',hold:'3 sec',freq:'Daily',instr:'Place the palm flat against your stomach with the elbow forward of the trunk. Press the palm into the belly while keeping the wrist straight and the elbow from moving backward. This is an alternative subscapularis isolation exercise for patients who cannot tolerate the lift-off position due to limited internal rotation range.'},
{id:'s144',cat:'Shoulder',name:'Shoulder Impingement Self-Test and Monitoring',pos:'Standing',sets:1,reps:'Periodic check',hold:'—',freq:'Weekly',instr:'Raise the arm slowly overhead in the scapular plane, noting any painful arc (typically between 60-120 degrees of elevation). Track whether the painful arc is narrowing or resolving over the course of treatment as an informal measure of impingement-related progress.'},
{id:'s145',cat:'Shoulder',name:'Active Compression Test Position Strengthening (Labral)',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'With the arm forward at 90 degrees flexion and slightly across the body, rotate the thumb down then up against light manual resistance as directed. Used cautiously in SLAP lesion rehabilitation to build strength in the position that tests labral integrity, only as specifically cleared by your therapist.'},
{id:'s146',cat:'Shoulder',name:'Shoulder External Rotation Strength Symmetry Test',pos:'Standing or seated',sets:1,reps:'3 trials each side',hold:'5 sec',freq:'Every 2-4 weeks',instr:'Using a hand-held dynamometer or a fixed resistance band, measure maximal external rotation force on both the affected and unaffected sides. Calculate a limb symmetry index. Tracking this over time provides an objective marker of rotator cuff strength recovery and informs return-to-sport or return-to-work decisions.'},
{id:'s147',cat:'Shoulder',name:'Overhead Athlete Scapular Dyskinesis Correction',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Perform the scapular assistance test position correction: while raising the arm overhead, a partner manually assists the scapula into proper upward rotation and posterior tilt. Practice replicating this corrected scapular movement actively without manual assistance. Addresses scapular dyskinesis commonly seen in throwing athletes.'},
{id:'s148',cat:'Shoulder',name:'Shoulder Girdle Postural Endurance Test and Training',pos:'Seated',sets:3,reps:'—',hold:'Maximum time, target 30-60 sec',freq:'Weekly to track',instr:'Sit tall with shoulder blades retracted and depressed. Hold this corrected posture as long as possible without fatigue causing the shoulders to round forward. Track the maximum hold time weekly as a measure of scapular postural muscle endurance, which is often deficient in patients with shoulder impingement and rounded shoulder posture.'},
// ELBOW & WRIST e109-e114 (6)
{id:'e109',cat:'Elbow & Wrist',name:'Elbow Extension Lag Monitoring and Exercise',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Actively straighten the elbow as far as possible, then measure or estimate any remaining flexion (the extension lag) compared to full passive extension. Perform active extension holds at end range to close the gap between active and passive extension, common after elbow fracture or prolonged immobilization.'},
{id:'e110',cat:'Elbow & Wrist',name:'Wrist Flexor Tendinopathy Eccentric Loading',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'—',freq:'2x/day',instr:'Rest the forearm on a table with the palm up, holding a light weight. Use the other hand to assist lifting into wrist flexion, then slowly lower the weight against gravity over a 3-4 second count using only the affected wrist. Eccentric loading is the primary evidence-based intervention for flexor tendinopathy at the elbow.'},
{id:'e111',cat:'Elbow & Wrist',name:'Forearm Rotation Strength Symmetry Check',pos:'Seated',sets:1,reps:'3 trials each direction',hold:'5 sec',freq:'Every 2-4 weeks',instr:'Using a hand-held dynamometer or graded resistance, measure pronation and supination strength on both the affected and unaffected sides. Compare to track recovery progress, particularly important in racquet sport athletes and after distal radius fracture where forearm rotation strength often lags behind grip strength recovery.'},
{id:'e112',cat:'Elbow & Wrist',name:'Wrist and Hand Functional Task Battery',pos:'Seated at table',sets:1,reps:'Full battery',hold:'—',freq:'Weekly to track',instr:'Perform a standardized set of functional tasks (turning a key, opening a jar, buttoning, writing, lifting a full cup) and rate the difficulty or pain of each. A functional task battery provides a real-world measure of hand and wrist recovery beyond isolated strength and range of motion testing.'},
{id:'e113',cat:'Elbow & Wrist',name:'Wartenberg Syndrome Nerve Glide (Superficial Radial)',pos:'Seated',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Pronate the forearm, flex the wrist, and ulnar deviate while extending the elbow, then add cervical lateral flexion away from the arm. This glides the superficial radial nerve, used for Wartenberg syndrome (superficial radial nerve entrapment) causing dorsal forearm and thumb numbness.'},
{id:'e114',cat:'Elbow & Wrist',name:'Hand Therapy Functional Outcome Measure Tracking (DASH/QuickDASH)',pos:'Seated',sets:1,reps:'Questionnaire',hold:'—',freq:'Every 4-6 weeks',instr:'Complete the DASH or QuickDASH self-report questionnaire about your arm, shoulder, and hand function at the prescribed intervals. This standardized outcome measure tracks your perceived functional improvement over the course of treatment and is widely used in upper extremity rehabilitation research and clinical practice.'},
// CORE & LUMBAR l136-l145 (10)
{id:'l136',cat:'Core & Lumbar',name:'Modified Curl-Up (McGill)',pos:'Supine, one knee bent',sets:3,reps:'8',hold:'8-10 sec',freq:'Daily',instr:'Lie on your back with one knee bent and the other leg straight. Place both hands under the low back to maintain its natural curve. Lift only the head and shoulders slightly off the floor, keeping the neck in line with the trunk. Hold, then lower. Part of the McGill Big Three, this minimizes lumbar flexion compared to a standard crunch while still training the rectus abdominis.'},
{id:'l137',cat:'Core & Lumbar',name:'Lumbar Spine Self-Assessment (Repeated Movement Testing)',pos:'Standing and supine as directed',sets:1,reps:'10 reps per direction tested',hold:'—',freq:'Initial assessment, then as directed',instr:'Under your therapist\'s guidance, perform repeated lumbar flexion and extension movements to identify your directional preference (which direction centralizes or reduces symptoms). This McKenzie-based assessment determines which repeated movement exercises will be most beneficial for your specific presentation.'},
{id:'l138',cat:'Core & Lumbar',name:'Sciatic Nerve Flossing (Seated Slump with Ankle Pumps)',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Sit with a mild slump posture. Extend the knee while simultaneously plantarflexing the ankle, then flex the knee while dorsiflexing the ankle, creating a flossing motion that moves the sciatic nerve through its pathway without adding excessive tension at any one point. Gentler than a sustained slump stretch and often better tolerated for irritable nerve presentations.'},
{id:'l139',cat:'Core & Lumbar',name:'Lumbar Spondylolisthesis Stabilization Program',pos:'Supine and quadruped',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'Focus on neutral spine core stabilization exercises (transverse abdominis activation, multifidus co-contraction) while specifically avoiding repeated lumbar extension, which can increase shear forces at the level of the slip. Follow your therapist\'s specific movement restrictions for your grade of spondylolisthesis.'},
{id:'l140',cat:'Core & Lumbar',name:'Lumbar Disc Herniation Movement Modification Training',pos:'Various',sets:1,reps:'Throughout day',hold:'—',freq:'Daily',instr:'Practice modified techniques for daily activities that typically load the disc in flexion and rotation simultaneously (the most provocative combination for disc herniation): bending with a neutral spine using the hip hinge, avoiding twisting while lifting, and using a log-roll technique for getting out of bed.'},
{id:'l141',cat:'Core & Lumbar',name:'Core Strength Endurance Ratio Testing (McGill Test Battery)',pos:'Various',sets:1,reps:'Full battery',hold:'Maximum time each',freq:'Every 4-6 weeks',instr:'Perform the McGill torso muscular endurance test battery: trunk flexor endurance (modified curl-up hold), trunk extensor endurance (Biering-Sorensen test), and side bridge endurance bilaterally. Compare the ratios between these tests, as an imbalance (particularly weak extensors relative to flexors) is associated with increased low back pain risk.'},
{id:'l142',cat:'Core & Lumbar',name:'Functional Lifting Mechanics Assessment and Training',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Practice lifting a box from the floor using proper mechanics: feet shoulder-width apart, hip hinge with neutral spine, box close to the body, and driving up through the legs. Progress the weight gradually as proper mechanics are demonstrated consistently. Used in occupational rehabilitation and injury prevention programs.'},
{id:'l143',cat:'Core & Lumbar',name:'Seated Posture Endurance with Lumbar Support',pos:'Seated with lumbar roll',sets:1,reps:'—',hold:'As long as comfortable, building duration',freq:'Throughout work day',instr:'Use a lumbar support roll or cushion positioned at the natural curve of the low back while seated for prolonged periods. Practice maintaining contact with the support without slouching forward away from it. Gradually building tolerance for sustained, well-supported sitting is an important functional goal for desk workers with low back pain.'},
{id:'l144',cat:'Core & Lumbar',name:'Lumbar Extension Pattern with Hip Drive (Glute Bridge to Standing)',pos:'Supine progressing to standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Perform a glute bridge, then progress directly into standing by rolling to the side and using the legs to stand up while maintaining the hip-dominant extension pattern learned in the bridge. Teaches patients to extend through the hips rather than the lumbar spine during functional transitions.'},
{id:'l145',cat:'Core & Lumbar',name:'Trunk Rotation Strength Test and Asymmetry Correction',pos:'Standing',sets:3,reps:'10 each side',hold:'2 sec',freq:'Daily',instr:'Using a cable or band, test and compare rotational strength to each side. Many patients, particularly rotational sport athletes, show significant side-to-side asymmetry. Specifically strengthen the weaker rotational direction to address the imbalance, which is associated with increased low back and oblique injury risk in rotational sports.'},
// HIP h119-h128 (10)
{id:'h119',cat:'Hip',name:'Trendelenburg Sign Correction Exercise',pos:'Standing on one leg',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Stand on the affected leg in front of a mirror. Practice maintaining a level pelvis (no drop on the unsupported side) while lifting the opposite knee. If a Trendelenburg drop is visible, focus on actively engaging the standing-side hip abductor to correct it. Directly addresses hip abductor weakness commonly identified during gait observation.'},
{id:'h120',cat:'Hip',name:'Hip Joint Distraction Self-Mobilization',pos:'Standing in doorway',sets:3,reps:'5',hold:'30 sec',freq:'Daily',instr:'Stand in a doorway with one foot braced against the frame at hip height. Lean your body weight away to create a gentle distraction force through the hip joint of the braced leg. Used for hip joint stiffness and as an adjunct to capsular stretching in hip osteoarthritis or post-surgical hip stiffness.'},
{id:'h121',cat:'Hip',name:'Hip Internal Rotation Range Measurement and Tracking',pos:'Seated at edge of table',sets:1,reps:'1 measure each side',hold:'—',freq:'Weekly',instr:'Sit at the edge of a table with knees bent over the edge. Rotate the lower leg outward (which moves the hip into internal rotation) as far as comfortable. Measure or estimate the angle and compare to the other side and to previous measurements. A standard clinical measure for tracking hip IR range, often limited in FAI and hip osteoarthritis.'},
{id:'h122',cat:'Hip',name:'Adductor Strain Return to Sport Testing (Squeeze Test)',pos:'Supine, knees bent',sets:1,reps:'3 trials',hold:'5 sec',freq:'Weekly to track',instr:'Lie on your back with knees bent at 45 degrees. Squeeze a sphygmomanometer cuff or your therapist\'s hands between your knees as hard as possible. Compare the force generated and any pain provoked to baseline measurements. The adductor squeeze test is a standard return-to-sport readiness measure following groin strain injury.'},
{id:'h123',cat:'Hip',name:'Femoroacetabular Impingement Activity Modification Training',pos:'Various functional positions',sets:1,reps:'Throughout day',hold:'—',freq:'Daily',instr:'Practice modified squatting, sitting, and stair-climbing techniques that avoid the combined deep flexion, adduction, and internal rotation positions that provoke FAI symptoms. Widen your stance during squats and avoid sitting in low, soft chairs that force excessive hip flexion.'},
{id:'h124',cat:'Hip',name:'Hip Labral Tear Functional Progression Program',pos:'Various',sets:3,reps:'Per phase',hold:'—',freq:'Daily',instr:'Follow your structured hip labral rehabilitation phases: Phase 1 (protect and reduce inflammation), Phase 2 (restore range and basic strength), Phase 3 (progressive loading and single-leg control), Phase 4 (return to sport-specific movement). Progress only when criteria for each phase are met rather than by time alone.'},
{id:'h125',cat:'Hip',name:'Greater Trochanteric Pain Syndrome Loading Program',pos:'Side-lying and standing',sets:3,reps:'15',hold:'45 sec isometric',freq:'Daily',instr:'Begin with isometric hip abduction holds (45 second holds, similar to tendinopathy protocols elsewhere in the body) before progressing to dynamic strengthening. Avoid positions of excessive hip adduction (crossing legs, lying directly on the affected side) which compress the gluteal tendons against the greater trochanter.'},
{id:'h126',cat:'Hip',name:'Hip Extensor Strength Symmetry Testing',pos:'Prone',sets:1,reps:'3 trials each side',hold:'5 sec',freq:'Every 2-4 weeks',instr:'Using a hand-held dynamometer or fixed resistance, measure hip extension strength on both legs in the prone position. Calculate the limb symmetry index. Hip extensor (gluteal) strength symmetry is an important component of return-to-sport testing batteries for hip, knee, and lumbar conditions.'},
{id:'h127',cat:'Hip',name:'Hip Osteoarthritis Joint Protection Education and Exercise',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Throughout day',instr:'Apply joint protection principles for hip osteoarthritis: pace activities, use a cane on the unaffected side if recommended, avoid prolonged standing on hard surfaces, and maintain regular gentle movement rather than complete rest. Combine with your prescribed hip strengthening and range of motion program for comprehensive OA management.'},
{id:'h128',cat:'Hip',name:'Hip Flexor Strain Return to Running Progression',pos:'Walking to running',sets:1,reps:'Per progressive schedule',hold:'—',freq:'As prescribed',instr:'Follow your structured return-to-running progression after hip flexor strain: pain-free walking, then light jogging, then progressive sprint and high-knee drill introduction, then full-speed running and cutting. The hip flexors are loaded eccentrically during the deceleration phase of sprinting, making a gradual speed progression essential to avoid re-injury.'},
// KNEE k117-k126 (10)
{id:'k117',cat:'Knee',name:'Knee Extensor Lag Correction Exercise',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Sit with the knee at full extension passively achieved (using a towel under the heel if needed). Practice actively holding this fully extended position without the knee drifting back into flexion. An extensor lag (inability to actively match passive extension) is common after knee surgery and indicates quad weakness specifically at terminal extension.'},
{id:'k118',cat:'Knee',name:'Knee Range of Motion Tracking and Goal Setting',pos:'Supine or seated',sets:1,reps:'1 measure flexion and extension',hold:'—',freq:'Weekly',instr:'Using a goniometer or your therapist\'s measurement, track active and passive knee flexion and extension range weekly. Compare progress against the expected timeline for your specific surgery or injury, and discuss with your therapist if progress appears to be plateauing earlier than expected.'},
{id:'k119',cat:'Knee',name:'Patellar Tendinopathy Load Management Education',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Ongoing',instr:'Apply load management principles: avoid sudden increases in jumping or deep squatting volume, monitor next-day pain as a guide for appropriate loading (some discomfort during exercise is acceptable if it resolves by the next day), and maintain the isometric and heavy-slow resistance program consistently even when pain improves.'},
{id:'k120',cat:'Knee',name:'ACL Reconstruction Graft-Specific Precaution Exercise',pos:'Various',sets:3,reps:'Per protocol',hold:'—',freq:'As prescribed',instr:'Follow the specific exercise restrictions for your graft type: hamstring autograft patients should avoid aggressive isolated hamstring curls early in rehabilitation, while patellar tendon autograft patients should be cautious with early kneeling and resisted knee extension near the harvest site. Always follow your individual surgeon\'s protocol.'},
{id:'k121',cat:'Knee',name:'Meniscus Repair Weight-Bearing Progression',pos:'Standing with crutches',sets:1,reps:'Per protocol',hold:'—',freq:'Daily',instr:'Follow your surgeon\'s specific weight-bearing protocol for your meniscus repair, which varies based on tear location and repair type. Posterior horn repairs often have more restricted flexion and weight-bearing limits than anterior repairs. Never increase weight-bearing status without surgeon clearance.'},
{id:'k122',cat:'Knee',name:'Total Knee Replacement Functional Milestone Tracking',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Weekly',instr:'Track your progress against standard TKR milestones: independent transfers (week 1-2), stairs with rail (week 2-3), walking without device (week 4-6), driving (when cleared by surgeon), and return to low-impact recreational activity (8-12 weeks). Discuss any significant delays from expected timelines with your surgical team.'},
{id:'k123',cat:'Knee',name:'Knee Effusion Self-Monitoring (Sweep Test)',pos:'Supine, leg extended',sets:1,reps:'1 check',hold:'—',freq:'Daily during active rehab',instr:'With the knee fully extended, sweep your hand upward along the inner side of the knee to move fluid, then press on the outer side and watch for a bulge or wave on the inner side, indicating effusion. Monitoring effusion helps guide exercise intensity, as significant swelling indicates the tissue needs relative rest from aggressive loading.'},
{id:'k124',cat:'Knee',name:'Knee Osteoarthritis Weight Management Exercise Integration',pos:'Various',sets:1,reps:'Per program',hold:'—',freq:'Daily',instr:'Combine your prescribed knee strengthening program with the aerobic and dietary components of your weight management plan as recommended by your care team. Weight loss of even 5-10% of body weight is associated with significant reductions in knee osteoarthritis pain and improved function, multiplying the benefit of the exercise program alone.'},
{id:'k125',cat:'Knee',name:'PCL Injury Specific Strengthening Considerations',pos:'Standing and closed chain positions',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Emphasize closed-chain quadriceps strengthening (squats, leg press, step-ups) over isolated open-chain hamstring exercises in early PCL rehabilitation, since the hamstrings can increase posterior tibial translation stress on a healing PCL. Always follow your surgeon\'s specific protocol, which differs meaningfully from standard ACL guidelines.'},
{id:'k126',cat:'Knee',name:'Knee Multi-Ligament Injury Comprehensive Stability Program',pos:'Various as cleared',sets:3,reps:'Per individualized protocol',hold:'—',freq:'As directed',instr:'Follow your highly individualized rehabilitation protocol for multi-ligament knee injury, which requires careful sequencing of range of motion, strengthening, and weight-bearing progression to protect multiple healing structures simultaneously. This complex injury pattern requires close coordination between you, your surgeon, and your therapist throughout an extended recovery timeline.'},
// ANKLE & FOOT a104-a110 (7)
{id:'a104',cat:'Ankle & Foot',name:'Chronic Ankle Instability Comprehensive Program',pos:'Various',sets:3,reps:'Per circuit',hold:'—',freq:'Daily',instr:'Perform the comprehensive chronic ankle instability circuit: strengthening (all four directions), balance progression (firm to foam to wobble board), and functional/sport-specific drills. Chronic ankle instability requires addressing strength, proprioceptive, and biomechanical factors together rather than any single intervention alone for lasting improvement.'},
{id:'a105',cat:'Ankle & Foot',name:'Ankle Sprain Grading and Expected Timeline Education',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Ongoing',instr:'Understand your specific ankle sprain grade (I, II, or III) and the expected healing timeline associated with it. Grade I sprains typically return to activity in 1-2 weeks, Grade II in 2-6 weeks, and Grade III in 6-12+ weeks. Setting realistic expectations based on your grade helps with appropriate activity pacing during recovery.'},
{id:'a106',cat:'Ankle & Foot',name:'Achilles Tendon Rupture Post-Surgical Protocol',pos:'Various as directed',sets:1,reps:'Per protocol phase',hold:'—',freq:'As prescribed',instr:'Follow your surgeon\'s specific post-operative protocol for Achilles tendon repair, which typically progresses through phases of protected weight-bearing in a boot with heel wedges, gradual wedge removal, transition to normal footwear, and finally progressive strengthening. Never rush the early protective phases, as re-rupture risk is highest in the first 8-12 weeks.'},
{id:'a107',cat:'Ankle & Foot',name:'Charcot-Marie-Tooth Foot Drop Management Exercise',pos:'Seated and standing',sets:3,reps:'15',hold:'—',freq:'Daily',instr:'Perform tibialis anterior strengthening within available range, ankle-foot orthosis fitting and gait training, and balance exercises adapted for progressive peripheral neuropathy. Exercise programs for hereditary neuropathies focus on maintaining function and preventing secondary complications rather than reversing the underlying progressive condition.'},
{id:'a108',cat:'Ankle & Foot',name:'Diabetic Foot Care and Protective Exercise',pos:'Seated',sets:1,reps:'Daily inspection plus exercise',hold:'—',freq:'Daily',instr:'Perform daily foot inspection for any cuts, blisters, or pressure areas before beginning gentle range of motion and circulation-promoting exercises. Avoid high-impact activities if peripheral neuropathy or vascular compromise is present. Diabetic foot exercise programs prioritize protection from injury alongside the standard rehabilitation goals.'},
{id:'a109',cat:'Ankle & Foot',name:'Lisfranc Injury Specific Rehabilitation Protocol',pos:'Various as directed',sets:1,reps:'Per protocol phase',hold:'—',freq:'As prescribed',instr:'Follow your surgeon\'s specific protocol for Lisfranc (midfoot) injury, which typically requires a longer period of non-weight-bearing than ankle sprains due to the structural importance of the midfoot arch in weight transmission. Midfoot mobility and strengthening exercises are introduced cautiously and later than in standard ankle rehabilitation.'},
{id:'a110',cat:'Ankle & Foot',name:'Return to Cleated Footwear Progression',pos:'Standing and walking on field',sets:1,reps:'Progressive time',hold:'—',freq:'As tolerated',instr:'Gradually introduce cleated athletic footwear after ankle or foot injury, beginning with brief periods of standing and walking before progressing to running and cutting. Cleats create a fixed point of ground contact that increases rotational stress on the ankle and foot compared to standard athletic shoes, requiring a careful introduction period.'},
// BALANCE & FUNCTIONAL b86-b90 (5)
{id:'b86',cat:'Balance & Functional',name:'Fall Risk Comprehensive Assessment and Home Program',pos:'Various assessment positions',sets:1,reps:'Full battery',hold:'—',freq:'At intake and reassessment',instr:'Complete the comprehensive fall risk assessment including the Berg Balance Scale, Timed Up and Go, 30-second chair stand, and gait speed measurement. Use the results to guide an individualized home exercise program targeting your specific identified deficits rather than a generic balance routine.'},
{id:'b87',cat:'Balance & Functional',name:'Fear of Falling Cognitive-Behavioral Exercise Integration',pos:'Various',sets:1,reps:'Progressive exposure',hold:'—',freq:'Daily',instr:'Combine graded physical balance exercise with cognitive strategies addressing fear of falling, such as challenging catastrophic thoughts about falling and gradually re-engaging with previously avoided activities. Fear of falling itself is an independent risk factor for future falls, separate from actual balance ability, and must be addressed concurrently with physical training.'},
{id:'b88',cat:'Balance & Functional',name:'Home Hazard Modification Walkthrough',pos:'Home environment',sets:1,reps:'—',hold:'—',freq:'Once, with periodic review',instr:'Work with your therapist or occupational therapist to identify and address home fall hazards: loose rugs, poor lighting, lack of grab bars, and cluttered walkways. Environmental modification is one of the most effective fall prevention interventions and should be implemented alongside your exercise program.'},
{id:'b89',cat:'Balance & Functional',name:'Multi-Component Fall Prevention Exercise Class',pos:'Group setting',sets:1,reps:'45-60 min class',hold:'—',freq:'2-3x/week',instr:'Attend a structured, evidence-based fall prevention exercise class (such as Otago, Tai Chi for Arthritis, or a similar validated program) that combines balance, strength, and functional mobility training. Multi-component group exercise programs have the strongest evidence base for reducing fall rates in community-dwelling older adults.'},
{id:'b90',cat:'Balance & Functional',name:'Post-Fall Recovery and Confidence Rebuilding Program',pos:'Various',sets:1,reps:'Progressive',hold:'—',freq:'Daily',instr:'Following a fall, work through a structured program addressing the physical deficits identified, practice the floor-to-standing recovery sequence, and gradually rebuild confidence through graded activity exposure. A fall, even without injury, often triggers significant activity avoidance that itself becomes a major contributor to functional decline if not specifically addressed.'},
// THORACIC t51-t52 (2)
{id:'t51',cat:'Thoracic',name:'Thoracic Spine Rib Mobilization (Self with Strap)',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Loop a strap around the affected rib at the level of restriction, anchored to a fixed point. Lean away from the anchor while breathing deeply to mobilize the costovertebral joint. Used for rib hypomobility contributing to thoracic pain or breathing restriction, performed only at the level specifically identified by your therapist.'},
{id:'t52',cat:'Thoracic',name:'Ankylosing Spondylitis Thoracic Mobility Program',pos:'Various',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Perform your prescribed daily mobility program emphasizing thoracic extension, rib expansion breathing, and postural exercises to counteract the progressive kyphotic and restrictive changes associated with ankylosing spondylitis. Daily consistency is critical, as this is a progressive condition where maintaining mobility is the primary achievable goal.'},
// POST-OP & GENERAL p71-p75 (5)
{id:'p71',cat:'Post-Op & General',name:'Surgical Site Infection Monitoring Education',pos:'Various',sets:1,reps:'Daily check',hold:'—',freq:'Daily through healing',instr:'Inspect your surgical incision daily for signs of infection: increasing redness, warmth, swelling, drainage (especially pus or foul odor), increasing pain, or fever above 101°F. Contact your surgeon promptly if any of these signs appear, as early identification and treatment of surgical site infection significantly improves outcomes.'},
{id:'p72',cat:'Post-Op & General',name:'Deep Vein Thrombosis Prevention Exercise',pos:'Supine or seated',sets:5,reps:'10',hold:'—',freq:'Every hour while awake',instr:'Perform frequent ankle pumps, calf contractions, and if cleared, short walks throughout the day following surgery, particularly lower extremity surgery. Wear prescribed compression stockings. DVT prevention exercises and early mobilization are critical safety components of post-surgical rehabilitation, especially in the first two weeks.'},
{id:'p73',cat:'Post-Op & General',name:'Post-Surgical Pain Medication Tapering Coordination',pos:'Various',sets:1,reps:'—',hold:'—',freq:'As prescribed by physician',instr:'Follow your physician\'s prescribed pain medication tapering schedule, coordinating your exercise intensity with your pain management plan. Communicate openly with your healthcare team about pain levels during exercise, as this information guides both your rehabilitation progression and medication management decisions.'},
{id:'p74',cat:'Post-Op & General',name:'Nutritional Support for Tissue Healing Education',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Ongoing',instr:'Maintain adequate protein intake and overall nutrition to support tissue healing during the post-surgical recovery period, as directed by your physician or a registered dietitian. Adequate nutrition, particularly protein intake, is increasingly recognized as an important modifiable factor in surgical recovery and muscle preservation during periods of reduced activity.'},
{id:'p75',cat:'Post-Op & General',name:'Discharge Planning and Long-Term Maintenance Program',pos:'Various',sets:1,reps:'Full maintenance routine',hold:'—',freq:'Ongoing after discharge',instr:'Establish your long-term maintenance exercise program to be continued independently after formal physical therapy discharge. This typically includes a condensed version of your strengthening program, continued activity modification awareness, and clear guidance on when to seek follow-up care if symptoms recur.'},
// NEURO & VESTIBULAR n64-n66 (3)
{id:'n64',cat:'Neuro & Vestibular',name:'Guillain-Barre Syndrome Progressive Strengthening',pos:'Various as tolerated',sets:3,reps:'10-15',hold:'—',freq:'Daily, carefully monitored',instr:'Perform very gradual, low-intensity strengthening exercises with careful monitoring for overwork weakness, a phenomenon where excessive exercise intensity can cause temporary or lasting weakness in recovering nerves. Progress slowly and conservatively, particularly during the recovery phase of Guillain-Barre syndrome.'},
{id:'n65',cat:'Neuro & Vestibular',name:'Functional Electrical Stimulation (FES) Cycling',pos:'Seated in FES cycle',sets:1,reps:'20-30 min',hold:'—',freq:'2-3x/week',instr:'Pedal using an FES cycling system that electrically stimulates the leg muscles in a coordinated pattern to assist cycling motion. Used in spinal cord injury rehabilitation to provide cardiovascular conditioning, prevent muscle atrophy, and improve bone density in paralyzed limbs.'},
{id:'n66',cat:'Neuro & Vestibular',name:'Wheelchair Skills Training Program',pos:'Seated in wheelchair',sets:1,reps:'30-45 min session',hold:'—',freq:'2-3x/week',instr:'Practice wheelchair propulsion, transfers, curb negotiation, and other essential wheelchair mobility skills as part of a structured wheelchair skills training program. Comprehensive wheelchair skills training improves both objective performance and confidence in wheelchair users with spinal cord injury or other significant mobility impairments.'},
// SPORT-SPECIFIC sp59-sp60 (2)
{id:'sp59',cat:'Sport-Specific & Plyometric',name:'Concussion Return to Sport Graduated Protocol',pos:'Various',sets:1,reps:'Per stage',hold:'—',freq:'24+ hrs between stages',instr:'Follow the graduated return-to-sport protocol: light aerobic exercise, sport-specific exercise, non-contact training drills, full contact practice, and finally return to competition. Each stage requires at least 24 hours without symptom recurrence before progressing. This evidence-based protocol is the standard of care for safe concussion return to sport.'},
{id:'sp60',cat:'Sport-Specific & Plyometric',name:'In-Season Load Management Monitoring',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Weekly tracking',instr:'Track training load (such as session RPE multiplied by duration) throughout the competitive season and compare week-to-week changes. Sharp spikes in training load (greater than 10-15% week over week) are associated with increased injury risk. Use this data to guide appropriate load progression and recovery planning throughout the season.'},
// PELVIC FLOOR pf44-pf45 (2)
{id:'pf44',cat:'Pelvic Floor & Womens Health',name:'Vulvodynia Management Pelvic Floor Program',pos:'Supine',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Perform the prescribed combination of pelvic floor relaxation techniques, gentle desensitization, and breathing exercises specific to vulvodynia management. Avoid aggressive strengthening exercises, as vulvodynia typically involves pelvic floor hypertonicity rather than weakness, and strengthening can worsen symptoms.'},
{id:'pf45',cat:'Pelvic Floor & Womens Health',name:'Postpartum Diastasis Recti Functional Integration',pos:'Various functional positions',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Progress core restoration exercises into functional movements such as lifting a baby carrier, getting up from the floor, and carrying groceries while maintaining proper intra-abdominal pressure management and avoiding doming of the abdominal wall. Functional integration ensures the core restoration program translates to real-world postpartum demands.'},
// AMPUTEE amp33 (1)
{id:'amp33',cat:'Amputee & Prosthetic',name:'Pediatric Limb Difference Adaptive Sports Introduction',pos:'Varies by sport',sets:1,reps:'30-45 min session',hold:'—',freq:'2-3x/week',instr:'Introduce age-appropriate adaptive sports and recreational activities for children with congenital or acquired limb differences, working with adaptive sports organizations as available. Early introduction to adaptive sports supports both physical development and psychosocial adjustment in pediatric limb difference populations.'},
// PEDIATRIC peds47-peds48 (2)
{id:'peds47',cat:'Pediatric',name:'Pediatric Brachial Plexus Injury Range of Motion Program',pos:'Supine',sets:3,reps:'10',hold:'10 sec',freq:'Multiple times daily',instr:'Perform gentle, full passive range of motion of all joints of the affected arm as taught by your pediatric therapist, focusing especially on shoulder external rotation and elbow extension, which are commonly restricted in brachial plexus birth injury. Consistent daily range of motion is critical to prevent contracture while awaiting nerve recovery or surgical intervention.'},
{id:'peds48',cat:'Pediatric',name:'Pediatric Idiopathic Toe Walking Sensory Integration',pos:'Standing and walking',sets:1,reps:'15-20 min',hold:'—',freq:'Daily',instr:'For children with sensory-based idiopathic toe walking (rather than purely orthopedic), incorporate proprioceptive and tactile input to the feet (textured surfaces, weighted activities) alongside the standard stretching and gait retraining program, addressing the sensory processing component that may underlie the toe walking pattern.'},
// TMJ j34 (1) - final entry to complete 500
{id:'j34',cat:'TMJ',name:'TMJ Post-Surgical Rehabilitation Protocol',pos:'Various as directed',sets:1,reps:'Per protocol phase',hold:'—',freq:'As prescribed',instr:'Follow your oral surgeon\'s specific post-operative protocol following TMJ surgery (arthroscopy, arthroplasty, or joint replacement), which typically progresses through phases of protected jaw rest, gentle passive range of motion, and gradual return to active exercise and normal diet. Close coordination between your surgeon and physical therapist is essential throughout TMJ surgical recovery.'},
{id:'c109',cat:'Cervical',name:'Cervical Lateral Glide Self-Mobilization',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Place the side of your hand against the side of your neck at the restricted level. Gently glide the neck sideways over the stabilizing hand in a smooth, repeated motion. A self-mobilization technique for lateral glide restriction, often used for radicular arm symptoms responsive to lateral glide positioning.'},
{id:'s149',cat:'Shoulder',name:'Shoulder External Rotation with Towel Roll Under Arm',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Place a small rolled towel under the affected armpit to maintain slight shoulder abduction. Hold a band anchored at the side and rotate the forearm outward against resistance. The towel roll provides a small amount of abduction that better targets the infraspinatus compared to a fully adducted starting position.'},
{id:'e115',cat:'Elbow & Wrist',name:'Wrist Extensor Tendon Glide with Resistance',pos:'Seated, forearm on table',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Rest the forearm on a table, palm down, with a light band looped around the hand. Extend the wrist fully against the resistance, then lower slowly. Used progressively in lateral epicondylalgia rehabilitation once isometric loading is well tolerated.'},
{id:'l146',cat:'Core & Lumbar',name:'Standing Trunk Flexion Endurance Hold',pos:'Standing, hinged forward',sets:3,reps:'—',hold:'15-30 sec',freq:'Daily',instr:'Hinge forward at the hips to approximately 45 degrees with a neutral spine, arms hanging. Hold the position, engaging the posterior chain to resist further flexion. Builds isometric endurance in the position commonly sustained during gardening, dish washing, and similar bent-over tasks.'},
{id:'h129',cat:'Hip',name:'Hip Adductor Eccentric Strengthening (Slide)',pos:'Standing on slide board or socks',sets:3,reps:'12 each',hold:'—',freq:'2-3x/week',instr:'Stand on a slide board or smooth floor with socks. Slide one leg outward into abduction, then use the adductors to slowly pull it back in against the sliding resistance. Eccentric adductor loading is increasingly used in groin strain and osteitis pubis rehabilitation.'},
{id:'k127',cat:'Knee',name:'Knee Extension with Hip Flexion Combined (SLR Variant)',pos:'Supine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Lie on your back with one knee bent and the other leg straight. Lift the straight leg while simultaneously flexing slightly at the hip to about 30-45 degrees, holding briefly at the top. Combines quad and hip flexor activity in a single functional motion pattern.'},
{id:'a111',cat:'Ankle & Foot',name:'Ankle Eversion Stretch (Standing)',pos:'Standing',sets:3,reps:'3',hold:'30 sec',freq:'2x/day',instr:'Stand and cross the affected foot behind the other, rolling the outer edge of the foot toward the floor to stretch the peroneal muscles and lateral ankle structures. Hold. Used for peroneal tightness contributing to chronic lateral ankle discomfort.'},
{id:'b91',cat:'Balance & Functional',name:'Single-Leg Stance on Stairs (Static)',pos:'Standing on one step',sets:3,reps:'—',hold:'20-30 sec each leg',freq:'Daily',instr:'Stand on a single step with one foot, holding the railing lightly for safety initially. Maintain balance on the elevated single-leg position. Progresses balance training into a position more similar to functional stair negotiation than flat-ground single-leg stance.'},
{id:'t53',cat:'Thoracic',name:'Thoracic Spine Active Mobility - Cat Cow',pos:'Quadruped',sets:3,reps:'10',hold:'2 sec each end',freq:'Daily',instr:'On hands and knees, alternate between arching the back upward (cat) and dropping it downward while lifting the chest (cow). Move slowly and focus on mobilizing through the thoracic segments specifically rather than only the lumbar spine. A foundational spinal mobility exercise used widely across PT and yoga-informed rehabilitation.'},
{id:'p76',cat:'Post-Op & General',name:'Post-Surgical Scar Tissue Cross-Friction Massage',pos:'Seated or supine',sets:1,reps:'3-5 min',hold:'—',freq:'Daily once healed',instr:'Once the incision is fully closed and cleared by your surgeon, apply firm cross-friction massage perpendicular to the scar line using your fingertips. Helps prevent adhesion formation and improves scar mobility and cosmetic appearance over the following months.'},
{id:'n67',cat:'Neuro & Vestibular',name:'Ataxia Coordination Training (Frenkel Exercises)',pos:'Supine progressing to standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Perform the classic Frenkel exercise progression: heel-to-shin sliding in supine, then progressing to seated and standing coordination tasks with visual feedback. Frenkel exercises are a long-established approach for retraining coordination in ataxia from cerebellar or sensory causes through repetition and visual substitution.'},
{id:'sp61',cat:'Sport-Specific & Plyometric',name:'Single-Leg Landing Stabilization Drill',pos:'Standing on box',sets:3,reps:'10 each leg',hold:'3 sec',freq:'2-3x/week',instr:'Step off a low box and land on a single leg, holding the landing position steady for 3 seconds with good knee alignment. A foundational single-leg landing control exercise used before progressing to single-leg jumping and cutting tasks in return-to-sport programs.'},
{id:'pf46',cat:'Pelvic Floor & Womens Health',name:'Pelvic Floor Activation with Functional Squat',pos:'Standing',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Perform a bodyweight squat while initiating a gentle pelvic floor lift just before and during the most demanding part of the movement (typically the ascent). Trains the pelvic floor to anticipate and respond to functional loading rather than only working in isolation.'},
{id:'amp34',cat:'Amputee & Prosthetic',name:'Prosthetic Sock Ply Management Training',pos:'Seated',sets:1,reps:'—',hold:'—',freq:'As needed throughout day',instr:'Learn to monitor residual limb volume changes throughout the day and adjust the number of prosthetic sock plies accordingly to maintain proper socket fit. Volume fluctuates with activity, temperature, and time of day, and sock ply management is an essential self-care skill for comfortable, safe prosthetic use.'},
{id:'peds49',cat:'Pediatric',name:'Pediatric Visual-Motor Integration Activities',pos:'Seated at table',sets:1,reps:'15-20 min',hold:'—',freq:'Daily',instr:'Practice connect-the-dot drawings, mazes, copying shapes, and puzzle assembly activities designed to integrate visual perception with motor output. Visual-motor integration deficits commonly affect handwriting, ball skills, and other functional tasks in children with coordination difficulties.'},
{id:'j35',cat:'TMJ',name:'TMJ Functional Chewing Retraining',pos:'Seated',sets:1,reps:'Each meal',hold:'—',freq:'Daily',instr:'Practice chewing soft, appropriately-sized food bites slowly and bilaterally (alternating sides) rather than habitually chewing on one side only. Bilateral, controlled chewing helps redistribute joint loading and is an important functional retraining component of comprehensive TMJ rehabilitation.'},
{id:'c110',cat:'Cervical',name:'Cervical Endurance Functional Carry',pos:'Standing, walking',sets:3,reps:'20-30 meters',hold:'—',freq:'Daily',instr:'Walk while carrying a moderately weighted backpack or bag, maintaining a tall cervical posture with a slight chin tuck throughout. Combines functional carrying with cervical postural endurance training relevant to school bag or work bag carrying demands.'},
{id:'s150',cat:'Shoulder',name:'Shoulder Combined Flexion-Abduction-ER Strength Test',pos:'Standing',sets:1,reps:'3 trials',hold:'5 sec',freq:'Every 2-4 weeks',instr:'Using a dynamometer at 90 degrees of combined shoulder elevation and external rotation, measure and compare strength between the affected and unaffected sides. This composite testing position closely mirrors the demands of overhead throwing and serving and is used in advanced return-to-sport assessment for overhead athletes.'},
{id:'e116',cat:'Elbow & Wrist',name:'Combined Elbow and Wrist Functional Strengthening Circuit',pos:'Standing',sets:3,reps:'12 each exercise',hold:'—',freq:'Daily',instr:'Perform a combined circuit addressing elbow flexion, elbow extension, wrist flexion, and wrist extension in sequence using a single resistance band, transitioning smoothly between exercises. An efficient comprehensive upper extremity strengthening session for patients managing both elbow and wrist symptoms simultaneously.'},
{id:'l147',cat:'Core & Lumbar',name:'Standing March with Core Bracing (High Step)',pos:'Standing',sets:3,reps:'20 total',hold:'2 sec',freq:'Daily',instr:'Stand tall and brace the core. March in place lifting each knee to hip height alternately while maintaining a stable trunk without rotation or side-bending. A standing core control exercise that also builds hip flexor endurance, transitional toward gait-specific training.'},
{id:'h130',cat:'Hip',name:'Hip Internal Rotator Eccentric Strengthening',pos:'Seated',sets:3,reps:'12',hold:'—',freq:'Daily',instr:'Sit with a band looped around both ankles, crossing between the legs. Actively rotate the hip outward using both legs together, then slowly control the return into internal rotation using only the affected leg over a 3-4 second eccentric count. Used for deep gluteal syndrome and hip rotator strengthening progressions.'},
{id:'k128',cat:'Knee',name:'Single-Leg Romanian Deadlift to Knee Touch',pos:'Standing',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand on the affected leg. Hinge forward at the hip while extending the free leg behind you, lightly touching the opposite knee to the floor in front if range allows, then return to standing. A demanding single-leg posterior chain and knee stability exercise used in late-stage ACL and patellar tendon rehabilitation.'},
{id:'a112',cat:'Ankle & Foot',name:'Single-Leg Hop and Hold (Multi-Directional)',pos:'Standing',sets:3,reps:'8 each direction',hold:'2 sec',freq:'2-3x/week',instr:'Hop forward, backward, and laterally on one leg, holding a stable landing for 2 seconds after each hop before the next repetition. A foundational single-leg plyometric control exercise bridging basic balance training and more demanding reactive hop testing used in ankle and ACL rehabilitation.'},
{id:'b92',cat:'Balance & Functional',name:'Dynamic Balance with Object Manipulation',pos:'Standing',sets:3,reps:'2-3 min',hold:'—',freq:'Daily',instr:'Stand on a foam pad or single leg while sorting, stacking, or manipulating small objects with the hands. Combines fine motor dual-tasking with balance demand, simulating real-world activities such as putting away dishes or sorting items while standing.'},
{id:'t54',cat:'Thoracic',name:'Thoracic Spine Extension with Foam Roller Walk-Out',pos:'Supine over foam roller',sets:3,reps:'5',hold:'10-15 sec',freq:'Daily',instr:'Lie over a foam roller at the mid-thoracic level with knees bent and hands supporting the head. Slowly walk the feet outward to lower the hips toward the floor, increasing the thoracic extension stretch as the body lengthens over the roller. Hold, then walk back in.'},
{id:'p77',cat:'Post-Op & General',name:'Post-Surgical Range of Motion Goal Tracking Chart',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Weekly',instr:'Maintain a simple chart tracking your range of motion measurements each week against the expected post-surgical timeline provided by your surgeon and therapist. Visual tracking of progress is motivating for patients and helps identify early if additional intervention is needed for a plateauing range.'},
{id:'n68',cat:'Neuro & Vestibular',name:'Hemispatial Neglect Visual Scanning Training',pos:'Seated at table',sets:3,reps:'10 min',hold:'—',freq:'Daily',instr:'Practice systematic visual scanning tasks that deliberately direct attention to the neglected side, such as searching for specific items arranged across a full table or reading exercises with a colored line marking the start of each row on the neglected side. Used in stroke patients with hemispatial neglect, often the left side following right hemisphere stroke.'},
{id:'sp62',cat:'Sport-Specific & Plyometric',name:'Reactive Agility with Visual Cue',pos:'Standing facing partner or screen',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'React to a visual cue (a partner pointing, a colored light, or a screen prompt) by sprinting or changing direction as quickly as possible to the indicated target. Visual reactive agility training more closely simulates the unpredictable decision-making demands of actual competition than pre-planned agility drills.'},
{id:'pf47',cat:'Pelvic Floor & Womens Health',name:'Coccydynia Seated Positioning and Exercise',pos:'Seated on wedge cushion',sets:1,reps:'—',hold:'As needed',freq:'Throughout day',instr:'Use a coccyx cushion or wedge that offloads direct pressure from the tailbone during sitting. Combine with gentle pelvic floor relaxation and posterior pelvic tilt exercises as directed by your therapist to reduce coccygeal loading and associated pelvic floor guarding.'},
{id:'amp35',cat:'Amputee & Prosthetic',name:'Prosthetic Component Adjustment Communication Training',pos:'Standing and walking',sets:1,reps:'—',hold:'—',freq:'As needed',instr:'Learn to identify and clearly communicate specific prosthetic fit or alignment concerns (such as pistoning, rotation, or pressure areas) to your prosthetist using consistent descriptive language. Effective patient-prosthetist communication significantly improves the efficiency of prosthetic adjustments and overall satisfaction with the device.'},
{id:'peds50',cat:'Pediatric',name:'Pediatric Bilateral Integration Midline Crossing Activities',pos:'Seated or standing',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Practice activities that require crossing the body midline with the hands or feet, such as touching the opposite knee, passing objects hand to hand across the body, or figure-8 movements. Midline crossing ability reflects and supports the bilateral integration of brain hemispheres important for many functional and academic tasks.'},
{id:'j36',cat:'TMJ',name:'TMJ Self-Mobilization (Anterior Glide)',pos:'Seated',sets:3,reps:'10',hold:'5 sec',freq:'Daily',instr:'Place your thumb inside your mouth along the lower molars on the affected side, with the other fingers supporting the outside of the jaw. Gently apply a downward and forward glide to the mandible while opening slightly. Used to address anterior capsular restriction in TMJ hypomobility, only as specifically directed by your therapist.'},
{id:'c111',cat:'Cervical',name:'Cervical Postural Exercise with Resistance Tubing Row',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Anchor resistance tubing in front at chest height. Perform a rowing motion while simultaneously holding a chin tuck and a tall cervical posture throughout the pulling motion. Reinforces correct cervical alignment under a functional upper body loading task.'},
{id:'s151',cat:'Shoulder',name:'Shoulder Functional Reach Behind Back (Bra Strap Simulation)',pos:'Standing',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Practice reaching one hand behind your back and upward toward the opposite shoulder blade, simulating the motion needed to fasten a bra or reach a back pocket. A functional combined internal rotation and extension task frequently identified as difficult by patients with shoulder restriction.'},
{id:'s152',cat:'Shoulder',name:'Bilateral ER 90° w/TB',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a resistance band in both hands with your arms straight out in front of you at shoulder height. Keeping your arms straight, pull the band apart by moving your hands out to the sides, squeezing your shoulder blades together. Slowly return to the starting position and repeat.'},
{id:'s153',cat:'Shoulder',name:'Bilateral ER 0° w/TB',pos:'Standing',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Hold a resistance band in both hands with your elbows bent to 90 degrees and tucked into your sides. Keeping your elbows pinned to your body, rotate your forearms outward away from each other, squeezing your shoulder blades together. Slowly return to the starting position and repeat.'},
{id:'s154',cat:'Shoulder',name:'Wall Angels',pos:'Standing against wall',sets:3,reps:'12',hold:'2 sec at top',freq:'Daily',instr:'Stand with your back, head, and arms against a wall, feet a few inches out. Bend your elbows and raise your arms out to the sides like a goalpost, keeping your hands, forearms, and elbows touching the wall the whole time. Slowly slide your arms up overhead as far as you can while keeping contact with the wall, then slide them back down. Keep your low back flat against the wall throughout.'},
{id:'s155',cat:'Shoulder',name:'Ball on the Wall',pos:'Standing facing wall',sets:3,reps:'10 circles each direction',hold:'—',freq:'Daily',instr:'Stand facing a wall and press a small weighted ball against it with your arm fully extended out in front of you at shoulder height. Keeping your arm straight and the ball pressed firmly into the wall, roll the ball in slow, controlled circles, first in one direction and then the other. Keep your shoulder blade engaged and your trunk steady throughout.'},
{id:'e117',cat:'Elbow & Wrist',name:'Wrist and Forearm Stretch Sequence (Complete)',pos:'Standing or seated',sets:3,reps:'Full sequence',hold:'30 sec each',freq:'2x/day',instr:'Perform the complete wrist and forearm stretch sequence in order: flexor stretch (elbow straight, wrist extended), extensor stretch (elbow straight, wrist flexed), pronator stretch, and supinator stretch. A comprehensive daily flexibility routine for the entire forearm musculature.'},
{id:'l148',cat:'Core & Lumbar',name:'Resisted Trunk Flexion (Cable Crunch)',pos:'Kneeling at cable machine',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Kneel facing away from a high cable with the rope attachment held behind the head. Crunch forward by flexing the trunk against the resistance, then return slowly. A progressive resisted abdominal exercise used in later-stage core strengthening once basic stabilization is established.'},
{id:'h131',cat:'Hip',name:'Hip Extensor Power Development (Banded Hip Thrust)',pos:'Supine, band around waist',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'Perform a standard hip thrust with a resistance band anchored behind you around the waist, adding horizontal resistance to the typical vertical hip thrust motion. Builds explosive hip extension power relevant to sprinting and jumping athletes in late-stage rehabilitation.'},
{id:'k129',cat:'Knee',name:'Lateral Step-Down with Knee Control Feedback',pos:'Standing on step',sets:3,reps:'10 each leg',hold:'—',freq:'Daily',instr:'Stand sideways on a low step. Step down sideways with the outside leg while keeping the standing knee from collapsing inward, using a mirror or your therapist for feedback on alignment. Specifically trains frontal-plane knee control during a functional stepping task.'},
{id:'k130',cat:'Knee',name:'Heel Slides on the Wall',pos:'Supine, leg up against wall',sets:3,reps:'15',hold:'3-5 sec',freq:'Daily',instr:'Lie on your back close to a wall with your leg straight up and your heel resting against the wall. Slowly slide your heel down the wall, bending your knee as far as comfortable, then slide it back up to straighten the leg. Bracing against the wall gives you extra control and a deeper stretch than sliding on the floor.'},
{id:'k131',cat:'Knee',name:'Anterior Step-Ups',pos:'Standing facing step',sets:3,reps:'15 each leg',hold:'2 sec at top',freq:'Daily',instr:'Stand facing a step with your affected leg on top of it. Push through that leg to step straight up, fully straightening your hip and knee at the top, then slowly lower your other foot back down to the floor with control. Keep your knee tracking in line with your toes throughout. Start with a low step and increase the height as you get stronger.'},
{id:'k132',cat:'Knee',name:'4-Way SLR',pos:'Supine, side-lying, and prone',sets:3,reps:'15 each direction',hold:'2 sec',freq:'Daily',instr:'Perform straight leg raises in four directions in sequence: lying on your back lift the leg straight up (flexion), lying on your side lift the top leg out to the side (abduction), lying on your side lift the bottom leg up to meet the top one (adduction), and lying on your stomach lift the leg straight back (extension). Keep the knee straight throughout each direction.'},
{id:'k133',cat:'Knee',name:'Squat with TRX',pos:'Standing holding TRX handles',sets:3,reps:'15',hold:'2 sec at bottom',freq:'Daily',instr:'Hold the TRX handles with arms extended in front of you for balance and light support. Lower into a squat, keeping your weight in your heels and your knees tracking over your toes, then push back up to standing. Use the TRX to offload as much weight as needed and reduce assistance as your strength improves.'},
{id:'k134',cat:'Knee',name:'Leg Press - Single Leg or Double Leg',pos:'Seated leg press machine',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit in the leg press machine with your foot or feet on the platform. For double leg, press through both feet evenly to extend the knees, then return with control. For single leg, perform the same motion using only the affected leg, keeping the knee aligned over the foot throughout. Use the load and side prescribed by your therapist.'},
{id:'k135',cat:'Knee',name:'Heel Raises on Step',pos:'Standing on edge of step',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Stand on the edge of a step with your heels hanging off the back. Rise up onto your toes as high as you can, then lower your heels down below the step level for a deeper stretch and a fuller range of motion than raising on flat ground. Hold a rail for balance if needed.'},
{id:'l149',cat:'Core & Lumbar',name:'Physioball Bridges',pos:'Supine, heels on physioball',sets:3,reps:'15',hold:'2-3 sec',freq:'Daily',instr:'Lie on your back with your heels resting on top of a physioball and your knees slightly bent. Press through your heels to lift your hips into a bridge while keeping the ball steady underneath you, then lower back down with control. The instability of the ball adds extra core and hamstring work compared to bridging on the floor.'},
{id:'k136',cat:'Knee',name:'Heel Slides with Towel and Strap',pos:'Supine',sets:3,reps:'15',hold:'3-5 sec',freq:'Daily',instr:'Lie on your back with a strap or folded towel looped around the ball of your foot, holding both ends in your hands. Slide your heel toward your buttock, bending your knee as far as comfortable, then use the strap to gently pull and add a little extra stretch at the end. Slide the heel back down to straighten the leg and repeat.'},
{id:'a113',cat:'Ankle & Foot',name:'Ankle and Foot Strengthening with Resistance Band Circuit (Standing)',pos:'Standing',sets:3,reps:'15 each direction',hold:'—',freq:'Daily',instr:'Perform a complete standing ankle strengthening circuit using a band: dorsiflexion, plantarflexion (calf raise), inversion, and eversion, all performed in weight-bearing or partial weight-bearing standing positions for greater functional carryover than seated exercises alone.'},
{id:'b93',cat:'Balance & Functional',name:'Backward Walking Practice',pos:'Walking',sets:3,reps:'10-15 meters',hold:'—',freq:'Daily',instr:'Walk backward slowly in a clear, supervised space, taking controlled small steps. Backward walking challenges balance and proprioception differently than forward walking and is used in balance training, gait rehabilitation, and as an assessment of dynamic postural control.'},
{id:'t55',cat:'Thoracic',name:'Thoracic Mobility Combined with Breathing (3D Breath and Reach)',pos:'Seated or standing',sets:3,reps:'10',hold:'3 sec',freq:'Daily',instr:'Inhale deeply while reaching one arm overhead and slightly rotating the trunk away, expanding the ribcage on that side. Exhale as you return to center. Combines diaphragmatic breathing mechanics with thoracic mobility in an integrated movement pattern.'},
{id:'t56',cat:'Thoracic',name:'Foam Roller Stretch 1 - Thoracic Extension (Roller Lengthwise)',pos:'Supine over foam roller, lengthwise',sets:1,reps:'—',hold:'1-3 min',freq:'Daily',instr:'Lie on your back with the foam roller positioned lengthwise along your entire spine, supporting your head and tailbone. Let your arms rest out to the sides, palms up, and allow your shoulders to relax and open toward the floor. Breathe deeply and let gravity gently open the chest and upper back.'},
{id:'t57',cat:'Thoracic',name:'Foam Roller Stretch 2 - Mid-Back Extension (Roller Crosswise)',pos:'Supine over foam roller, crosswise at mid-back',sets:3,reps:'5',hold:'15-30 sec',freq:'Daily',instr:'Place the foam roller crosswise under your mid-back (around bra-strap level). Support your head with your hands and bend your knees with feet flat on the floor. Gently arch backward over the roller, letting your upper back extend over it. Hold, then carefully sit up before moving the roller to a new spot if continuing.'},
{id:'t58',cat:'Thoracic',name:'Foam Roller Stretch 3 - Upper Back Extension',pos:'Supine over foam roller, crosswise at upper back',sets:3,reps:'5',hold:'15-30 sec',freq:'Daily',instr:'Move the foam roller crosswise to just below your shoulder blades. Support your head with your hands, knees bent, feet flat. Gently extend backward over the roller to open the upper back and chest. Hold, then sit up carefully before repositioning.'},
{id:'t59',cat:'Thoracic',name:'Foam Roller Stretch 4 - Segmental Walk-Through',pos:'Supine over foam roller, crosswise',sets:1,reps:'1 pass',hold:'15-20 sec each level',freq:'Daily',instr:'With the roller crosswise under your back and knees bent, support your head with your hands. Use your feet to slowly shift your body so the roller moves up the spine one segment at a time, pausing at each level to let that section of the back extend and open before moving to the next.'},
{id:'t60',cat:'Thoracic',name:'Foam Roller Stretch 5 - Open Book Rotation on Roller',pos:'Supine over foam roller, lengthwise',sets:3,reps:'8 each side',hold:'3 sec',freq:'Daily',instr:'Lie lengthwise along the foam roller with your head and tailbone supported, knees bent and feet flat. Bring both arms straight up toward the ceiling, palms together. Let one arm slowly rotate open toward the floor on that side while keeping the other arm reaching upward, then bring it back to center and repeat on the other side.'},
{id:'t61',cat:'Thoracic',name:'Foam Roller Stretch 6 - Chest and Shoulder Opener',pos:'Supine over foam roller, lengthwise',sets:1,reps:'—',hold:'1-2 min',freq:'Daily',instr:'Lie lengthwise on the foam roller with your head and tailbone supported. Bring your arms out into a wide T or goalpost position with elbows bent, letting the backs of your hands relax toward the floor. Stay here and breathe, allowing the chest and front of the shoulders to gradually open and release.'},
{id:'p78',cat:'Post-Op & General',name:'Falls Risk Education Following Surgery',pos:'Various',sets:1,reps:'—',hold:'—',freq:'Throughout recovery',instr:'Receive and apply education on fall risk specific to your post-surgical recovery period, including medication side effects, temporary weakness, altered gait patterns, and home safety modifications needed during the vulnerable early recovery phase. Post-surgical patients, especially older adults, are at meaningfully elevated fall risk during initial recovery.'},
{id:'n69',cat:'Neuro & Vestibular',name:'Apraxia Motor Planning Retraining',pos:'Seated at table',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Practice multi-step functional motor sequences (such as preparing a simple snack) broken down into individual components, with verbal or tactile cueing as needed, gradually reducing assistance as motor planning improves. Used for ideomotor and ideational apraxia commonly seen after left hemisphere stroke.'},
{id:'sp63',cat:'Sport-Specific & Plyometric',name:'Plyometric Skater Jump',pos:'Standing',sets:3,reps:'12 each direction',hold:'2 sec land',freq:'2-3x/week',instr:'Jump laterally from one leg to the other in a skating motion, swinging the trailing leg behind for balance and landing with control before pushing off into the next jump. Builds lateral power and single-leg landing control used in skating, hockey, and multi-directional field sports.'},
{id:'pf48',cat:'Pelvic Floor & Womens Health',name:'Endometriosis Pelvic Floor and Visceral Mobility Program',pos:'Supine',sets:1,reps:'10-15 min',hold:'—',freq:'Daily',instr:'Perform the prescribed combination of gentle visceral mobilization techniques, pelvic floor relaxation, and breathing exercises specific to endometriosis-related pelvic pain management, working alongside your gynecological care team for comprehensive symptom management.'},
{id:'amp36',cat:'Amputee & Prosthetic',name:'Prosthetic Foot Selection Activity Matching Education',pos:'Various',sets:1,reps:'—',hold:'—',freq:'As needed',instr:'Learn about how different prosthetic foot categories (SACH, single-axis, energy-storing, microprocessor-controlled) are matched to different activity levels and goals, supporting informed discussions with your prosthetist about component selection appropriate to your functional level and lifestyle goals.'},
{id:'peds51',cat:'Pediatric',name:'Pediatric Gross Motor Milestone Progression Play',pos:'Floor and open space',sets:1,reps:'30-45 min',hold:'—',freq:'Daily',instr:'Facilitate play activities specifically targeting the next gross motor milestone in sequence (rolling, sitting, crawling, pulling to stand, cruising, walking, running, jumping) appropriate to the child\'s current developmental level, embedding therapeutic goals into naturally engaging play.'},
{id:'j37',cat:'TMJ',name:'TMJ and Cervical Combined Self-Management Protocol',pos:'Seated',sets:1,reps:'Full routine',hold:'—',freq:'Daily',instr:'Perform your combined TMJ and cervical home program addressing both regions together, since they frequently co-exist and influence each other: chin tuck, suboccipital release, masseter self-release, and jaw rest position awareness in sequence. An integrated approach is generally more effective than treating either region in complete isolation.'},
{id:'l150',cat:'Core & Lumbar',name:'Kettlebell Goblet Squat',pos:'Standing',sets:3,reps:'12',hold:'2 sec at bottom',freq:'2-3x/week',instr:'Hold a kettlebell by the horns (sides of the handle) at chest height. Squat down keeping the chest tall and the bell close to your body, then drive back up through your heels. The front-loaded weight helps counterbalance and encourages an upright squat posture.'},
{id:'l151',cat:'Core & Lumbar',name:'Kettlebell Deadlift',pos:'Standing, bell between feet',sets:3,reps:'10-12',hold:'—',freq:'2-3x/week',instr:'Stand with a kettlebell on the floor between your feet. Hinge at the hips with a flat back, grip the handle with both hands, and stand up tall by driving your hips forward. Lower it back down with the same hip hinge. A foundational hip-hinge strengthening exercise with a lower starting position than a barbell.'},
{id:'l152',cat:'Core & Lumbar',name:'Kettlebell Single-Arm Suitcase Deadlift',pos:'Standing, bell beside one foot',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Place a kettlebell beside one foot. Hinge down, grip it with the same-side hand, and stand up tall without leaning or twisting toward the weight. The offset load forces the core to resist side-bending, mimicking picking up a suitcase or grocery bag.'},
{id:'l153',cat:'Core & Lumbar',name:'Kettlebell Racked Carry',pos:'Standing, walking',sets:3,reps:'20-30 meters each side',hold:'—',freq:'2-3x/week',instr:'Clean a kettlebell to the rack position (resting against your forearm at chest height, elbow tucked). Walk with a tall, upright posture. The racked position challenges the core and shoulder stabilizers differently than a suitcase carry at your side.'},
{id:'l154',cat:'Core & Lumbar',name:'Kettlebell Overhead Carry',pos:'Standing, walking',sets:3,reps:'15-20 meters each side',hold:'—',freq:'2-3x/week',instr:'Press a kettlebell overhead with one arm locked out. Walk while keeping the arm vertical and your ribs down, not letting the back arch. A demanding shoulder stability and core exercise used in late-stage overhead athlete rehabilitation.'},
{id:'l155',cat:'Core & Lumbar',name:'Kettlebell Around the World',pos:'Standing',sets:3,reps:'8 each direction',hold:'—',freq:'2-3x/week',instr:'Pass the kettlebell around your body in a circle, switching hands in front and behind. Keep the trunk still and resist rotating or leaning as the bell travels. Builds grip, coordination, and anti-rotation core control in a continuous dynamic pattern.'},
{id:'l156',cat:'Core & Lumbar',name:'Kettlebell Halo',pos:'Standing or tall kneeling',sets:3,reps:'8 each direction',hold:'—',freq:'Daily',instr:'Hold a kettlebell upside down by the horns at chest height. Circle it slowly around your head, keeping it close, then reverse direction. Mobilizes the shoulders and thoracic spine while the core resists the shifting load. A popular warm-up in kettlebell-based rehab programs.'},
{id:'l157',cat:'Core & Lumbar',name:'Kettlebell Windmill',pos:'Standing, wide stance',sets:3,reps:'6 each side',hold:'—',freq:'2-3x/week',instr:'Press a kettlebell overhead with one arm. With feet angled away from that arm, push your hips toward the bell side and slide your free hand down the inside of your leg, keeping your eyes on the bell and the arm vertical. Return to standing. An advanced mobility-plus-stability exercise for the shoulder, hips, and lateral core.'},
{id:'l158',cat:'Core & Lumbar',name:'Kettlebell Turkish Get-Up (Half)',pos:'Supine to seated',sets:3,reps:'5 each side',hold:'—',freq:'2-3x/week',instr:'Lie on your back holding a kettlebell straight up with one arm. Roll onto the opposite elbow, then up to the hand, keeping the bell arm vertical the whole time. Reverse back down with control. The half get-up is the first half of the full Turkish get-up and builds shoulder stability and core strength through transitional movement.'},
{id:'l159',cat:'Core & Lumbar',name:'Kettlebell Turkish Get-Up (Full)',pos:'Supine to standing',sets:2,reps:'3 each side',hold:'—',freq:'2-3x/week',instr:'From lying on your back with the kettlebell pressed up in one arm, move through elbow, hand, bridge, sweep the leg through to half-kneeling, and stand up — keeping the bell locked out overhead the entire time. Reverse each step to return. One of the most complete total-body stability exercises in rehabilitation and strength training.'},
{id:'h132',cat:'Hip',name:'Kettlebell Single-Leg Deadlift',pos:'Standing on one leg',sets:3,reps:'8 each leg',hold:'—',freq:'2-3x/week',instr:'Hold a kettlebell in one hand. Balance on the opposite leg and hinge forward at the hip, extending the free leg behind you as the bell lowers toward the floor. Return to standing by driving the hips forward. Builds single-leg posterior chain strength and balance under load.'},
{id:'h133',cat:'Hip',name:'Kettlebell Sumo Deadlift',pos:'Standing, wide stance',sets:3,reps:'12',hold:'—',freq:'2-3x/week',instr:'Stand with feet wider than shoulder-width, toes angled out, kettlebell between your feet. Hinge and squat down to grip the handle, then stand tall by driving through your heels and squeezing your glutes. The wide stance emphasizes the inner thighs and glutes more than a standard deadlift.'},
{id:'h134',cat:'Hip',name:'Kettlebell Goblet Lateral Lunge',pos:'Standing',sets:3,reps:'8 each side',hold:'—',freq:'2-3x/week',instr:'Hold a kettlebell at your chest. Step out wide to one side, sitting back into that hip while the other leg stays straight, then push back to standing. The goblet hold keeps you upright while the lateral lunge loads the hips and inner thighs in the frontal plane.'},
{id:'h135',cat:'Hip',name:'Kettlebell Reverse Lunge with Rack Hold',pos:'Standing',sets:3,reps:'10 each leg',hold:'—',freq:'2-3x/week',instr:'Hold a kettlebell in the rack position on one side. Step backward into a reverse lunge on the same side, lowering the back knee toward the floor, then drive back up. The offset load adds a core stability challenge to the lunge pattern.'},
{id:'k137',cat:'Knee',name:'Kettlebell Step-Up',pos:'Standing at step',sets:3,reps:'10 each leg',hold:'—',freq:'2-3x/week',instr:'Hold a kettlebell in each hand (or one in a goblet hold). Step up onto a box or step, driving through the lead leg to stand fully tall on top, then lower back down with control. A loaded progression of the bodyweight step-up for building single-leg strength.'},
{id:'k138',cat:'Knee',name:'Kettlebell Split Squat',pos:'Standing in split stance',sets:3,reps:'10 each leg',hold:'2 sec at bottom',freq:'2-3x/week',instr:'Hold a kettlebell at your chest or one in each hand. From a split stance, lower the back knee straight down toward the floor, keeping the front shin fairly vertical, then press back up. Builds single-leg quad and glute strength with less balance demand than a lunge.'},
{id:'s156',cat:'Shoulder',name:'Kettlebell Bottoms-Up Press',pos:'Standing or seated',sets:3,reps:'8 each arm',hold:'—',freq:'2-3x/week',instr:'Hold a light kettlebell upside down by the handle so the bell sits above your fist. Press it overhead slowly while keeping the bell balanced. The unstable bottoms-up position forces the rotator cuff and grip to work overtime, making it a favorite for shoulder stability rehabilitation with light loads.'},
{id:'s157',cat:'Shoulder',name:'Kettlebell Bottoms-Up Carry',pos:'Standing, walking',sets:3,reps:'15-20 meters each side',hold:'—',freq:'2-3x/week',instr:'Hold a light kettlebell upside down by the handle at shoulder height with the elbow bent, keeping the bell balanced above your fist as you walk. Builds rotator cuff endurance, grip, and shoulder stability in a functional carrying pattern.'},
{id:'s158',cat:'Shoulder',name:'Kettlebell Arm Bar',pos:'Side-lying transition',sets:2,reps:'3-5 each side',hold:'20-30 sec',freq:'2-3x/week',instr:'Lie on your back and press a light kettlebell up with one arm. Roll toward your opposite side, letting the bell arm stay vertical while your body turns under it, ending nearly face-down with the arm still pressed up. Breathe and hold. An advanced shoulder stability and pec/anterior capsule mobility exercise.'},
{id:'s159',cat:'Shoulder',name:'Kettlebell Single-Arm Overhead Press',pos:'Standing',sets:3,reps:'10 each arm',hold:'—',freq:'2-3x/week',instr:'Clean a kettlebell to the rack position, then press it overhead until the arm is locked out, keeping your ribs down and core braced. Lower with control. The kettlebell sits behind the wrist, encouraging a more natural pressing path than a dumbbell for many people.'},
{id:'s160',cat:'Shoulder',name:'Kettlebell High Pull',pos:'Standing',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'Start in a hip hinge holding the kettlebell between your knees. Explosively extend the hips while pulling the bell up to chest height, elbow leading out and up, then let it swing back down into the next rep. A power-development exercise bridging the swing and the snatch.'},
{id:'l160',cat:'Core & Lumbar',name:'Kettlebell Single-Arm Swing',pos:'Standing',sets:3,reps:'10 each arm',hold:'—',freq:'2-3x/week',instr:'Perform a kettlebell swing holding the bell with one hand only, keeping your shoulders square and resisting the pull to rotate. Switch arms each set. The one-arm version adds an anti-rotation core demand to the standard hip-hinge swing.'},
{id:'l161',cat:'Core & Lumbar',name:'Kettlebell Dead Bug Pullover',pos:'Supine',sets:3,reps:'10',hold:'—',freq:'2-3x/week',instr:'Lie on your back in the dead bug position holding a light kettlebell over your chest with both hands. Lower the bell overhead toward the floor while keeping your low back flat, then return. Combines the anti-extension dead bug with a lat and shoulder mobility component.'},
{id:'l162',cat:'Core & Lumbar',name:'Kettlebell Plank Pull-Through',pos:'Plank position',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Hold a plank with a kettlebell on the floor just outside one hand. Reach under your body with the opposite hand, drag the bell across to the other side, and repeat back and forth while keeping your hips from rotating or swaying. An anti-rotation plank progression.'},
{id:'h136',cat:'Hip',name:'Kettlebell Glute Bridge Pullover',pos:'Supine, knees bent',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Lie on your back holding a light kettlebell above your chest. Perform a glute bridge and, while holding the bridge, lower the bell overhead and return. Combines hip extension holds with core anti-extension work in a single move.'},
{id:'b94',cat:'Balance & Functional',name:'Kettlebell Farmer Carry with Obstacle Steps',pos:'Standing, walking',sets:3,reps:'20 meters',hold:'—',freq:'2-3x/week',instr:'Carry a kettlebell in each hand while stepping over small obstacles placed along your path. Combines loaded carrying with the stepping precision and balance demands of navigating real-world environments like stairs, curbs, and cluttered floors.'},
{id:'e118',cat:'Elbow & Wrist',name:'Kettlebell Wrist Curl (Handle Grip)',pos:'Seated, forearm on thigh',sets:3,reps:'15',hold:'2 sec',freq:'Daily',instr:'Sit with your forearm resting on your thigh, palm up, holding a light kettlebell handle with the bell hanging below. Curl the wrist upward and lower slowly. The hanging bell adds a stability challenge compared to a dumbbell wrist curl.'},
{id:'e119',cat:'Elbow & Wrist',name:'Kettlebell Bottoms-Up Hold (Grip Endurance)',pos:'Seated or standing, elbow at 90',sets:3,reps:'—',hold:'20-30 sec each',freq:'Daily',instr:'Hold a light kettlebell upside down by the handle with your elbow bent at 90 degrees, balancing the bell above your fist without letting it tip. Builds crushing grip strength and wrist stability, useful in late-stage elbow and wrist rehabilitation.'},
{id:'sp64',cat:'Sport-Specific & Plyometric',name:'Kettlebell Snatch',pos:'Standing',sets:3,reps:'8 each arm',hold:'—',freq:'2-3x/week',instr:'From a hip hinge, explosively drive the hips and pull the kettlebell in one motion overhead to a locked-out position, punching through at the top so the bell lands softly on the forearm. Lower into the next rep. An advanced total-body power exercise for late-stage athletic rehabilitation.'},
{id:'sp65',cat:'Sport-Specific & Plyometric',name:'Kettlebell Clean',pos:'Standing',sets:3,reps:'8 each arm',hold:'—',freq:'2-3x/week',instr:'Swing the kettlebell back between your legs, then drive the hips forward and guide the bell up to the rack position, letting it roll softly around your wrist rather than flipping and banging the forearm. Builds hip power and teaches force absorption at the rack.'},
{id:'sp66',cat:'Sport-Specific & Plyometric',name:'Kettlebell Push Press',pos:'Standing',sets:3,reps:'8 each arm',hold:'—',freq:'2-3x/week',instr:'From the rack position, dip slightly at the knees and drive up through the legs to help press the kettlebell overhead, then lower with control. The leg drive allows heavier loads than a strict press, training total-body power transfer from the ground up.'},
{id:'l163',cat:'Core & Lumbar',name:'Kettlebell Suitcase March',pos:'Standing, marching in place',sets:3,reps:'20 total steps',hold:'—',freq:'Daily',instr:'Hold a kettlebell at your side in one hand. March in place, lifting each knee to hip height, while keeping your trunk perfectly upright against the offset pull of the weight. Switch hands each set. Combines anti-lateral-flexion core work with hip flexor activation.'},
{id:'h137',cat:'Hip',name:'Kettlebell Staggered-Stance Deadlift',pos:'Standing, staggered stance',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Stand with one foot a half-step behind the other, most of your weight on the front leg. Hinge and lower a kettlebell down the front leg, then drive back up. A stepping stone between the two-leg deadlift and the full single-leg version.'},
{id:'b95',cat:'Balance & Functional',name:'Kettlebell Sit-to-Stand (Goblet)',pos:'Seated in chair',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'Hold a kettlebell at your chest in the goblet position. Stand up from a chair without using your hands, then sit back down with control. The added load progresses the basic sit-to-stand and the front weight actually helps many people counterbalance during the movement.'},
{id:'s161',cat:'Shoulder',name:'Cable External Rotation at 0 Degrees',pos:'Standing beside cable column',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Stand sideways to a cable set at elbow height, holding the handle with the far hand, elbow bent 90 degrees and tucked at your side. Rotate the forearm outward away from your body, then return slowly. The cable provides smooth, constant resistance through the full arc, unlike a band which gets harder at the end.'},
{id:'s162',cat:'Shoulder',name:'Cable Internal Rotation at 0 Degrees',pos:'Standing beside cable column',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Stand sideways to a cable at elbow height, holding the handle with the near hand, elbow bent 90 degrees at your side. Rotate the forearm inward across your stomach, then return slowly. Constant cable tension makes this a smooth subscapularis strengthening option.'},
{id:'s163',cat:'Shoulder',name:'Cable Face Pull',pos:'Standing facing cable',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Set a rope attachment at face height. Pull the rope toward your face, spreading the ends apart so your hands finish beside your ears with elbows high, squeezing the shoulder blades together. One of the best all-around exercises for the rear delts, mid traps, and external rotators together.'},
{id:'s164',cat:'Shoulder',name:'Cable Y-Raise',pos:'Standing facing low cable',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'With cables set low, cross the handles so each hand holds the opposite side. Raise both arms up and out into a Y shape with thumbs up, then lower slowly. Targets the lower trapezius with smooth resistance through the whole range.'},
{id:'s165',cat:'Shoulder',name:'Cable Reverse Fly',pos:'Standing, cables at shoulder height',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Stand between two cable columns set at shoulder height, holding the left handle in the right hand and vice versa. Pull both arms out and back like opening a pair of doors, squeezing the shoulder blades. Constant tension makes this superior to dumbbells for rear deltoid isolation at the top of the movement.'},
{id:'s166',cat:'Shoulder',name:'Cable Scaption Raise',pos:'Standing, low cable behind',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'With a low cable behind you, raise the arm forward and slightly out to the side (the scapular plane) with the thumb up, to shoulder height. Lower slowly. The cable resists from behind, loading the raise evenly through the arc.'},
{id:'s167',cat:'Shoulder',name:'Cable Straight-Arm Pulldown (Bilateral)',pos:'Standing facing high cable',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Hold a straight bar attached to a high cable with both hands, arms extended. Keeping the elbows straight, pull the bar down in an arc to your thighs, then return with control. Strengthens the lats and shoulder depressors through a full overhead-to-hip range.'},
{id:'s168',cat:'Shoulder',name:'Cable External Rotation at 90 Degrees Abduction',pos:'Standing facing cable',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Set the cable at shoulder height. With your arm out to the side at 90 degrees and elbow bent 90 degrees, rotate the forearm up and back against the resistance, then return slowly. Trains the rotator cuff in the throwing position with constant, controllable load.'},
{id:'e120',cat:'Elbow & Wrist',name:'Cable Triceps Pushdown',pos:'Standing facing high cable',sets:3,reps:'12-15',hold:'2 sec',freq:'2-3x/week',instr:'Hold a bar or rope attached to a high cable with elbows tucked at your sides. Push the handle down until the elbows are fully straight, then let it rise back up with control without letting the elbows drift forward. A staple triceps strengthening exercise with smooth resistance.'},
{id:'e121',cat:'Elbow & Wrist',name:'Cable Biceps Curl',pos:'Standing facing low cable',sets:3,reps:'12-15',hold:'2 sec',freq:'2-3x/week',instr:'Hold a bar attached to a low cable with palms up, elbows at your sides. Curl the bar up toward your shoulders, then lower slowly. The cable keeps tension on the biceps at the bottom of the movement where a dumbbell curl has almost none.'},
{id:'e122',cat:'Elbow & Wrist',name:'Cable Wrist Curl Over Bench',pos:'Kneeling, forearms on bench',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Kneel with your forearms resting on a bench, palms up, holding a bar attached to a low cable. Curl only the wrists upward, then lower slowly through a full range. Constant cable tension loads the wrist flexors evenly through the entire arc.'},
{id:'l164',cat:'Core & Lumbar',name:'Cable Pallof Press with Overhead Reach',pos:'Standing sideways to cable',sets:3,reps:'10 each side',hold:'2 sec',freq:'2-3x/week',instr:'Perform a standard Pallof press, but after extending the arms, raise them overhead while resisting the cable pull to rotate you, then lower and return. The overhead reach adds an anti-extension demand on top of the anti-rotation challenge.'},
{id:'l165',cat:'Core & Lumbar',name:'Cable Reverse Chop (Low to High) Kneeling',pos:'Half-kneeling beside low cable',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Half-kneel with the inside knee down beside a low cable. Pull the handle up and across your body from the low anchor to above the opposite shoulder, rotating through the trunk. The half-kneeling position locks the hips and forces the rotation to come from the core.'},
{id:'l166',cat:'Core & Lumbar',name:'Cable Chop Kneeling (High to Low)',pos:'Half-kneeling beside high cable',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Half-kneel with the outside knee down beside a high cable. Pull the handle down and across your body to the opposite hip, rotating through the trunk while the hips stay still. The kneeling chop isolates trunk rotation better than the standing version.'},
{id:'l167',cat:'Core & Lumbar',name:'Cable Standing Row (Neutral Grip)',pos:'Standing facing cable',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Stand facing a cable at chest height with a neutral-grip handle. Row the handle to your ribs while keeping a tall posture and stable trunk, squeezing the shoulder blades at the end. A standing row requires the core to resist being pulled forward, unlike a supported machine row.'},
{id:'l168',cat:'Core & Lumbar',name:'Cable Single-Arm Row with Anti-Rotation',pos:'Standing facing cable',sets:3,reps:'12 each arm',hold:'2 sec',freq:'2-3x/week',instr:'Row a single cable handle to your ribs with one arm while keeping your shoulders and hips perfectly square, resisting the twist the one-sided pull creates. Combines back strengthening with anti-rotation core work.'},
{id:'h138',cat:'Hip',name:'Cable Hip Abduction',pos:'Standing beside low cable',sets:3,reps:'15 each leg',hold:'2 sec',freq:'2-3x/week',instr:'Attach an ankle cuff to a low cable and stand sideways with the cuffed leg on the outside. Lift the leg straight out to the side against the resistance, keeping your trunk tall, then return slowly. The cable provides smoother, more adjustable resistance than a band for hip abductor strengthening.'},
{id:'h139',cat:'Hip',name:'Cable Hip Adduction',pos:'Standing beside low cable',sets:3,reps:'15 each leg',hold:'2 sec',freq:'2-3x/week',instr:'With the ankle cuff on the leg closest to the machine, pull that leg across your body toward and past the standing leg, then return with control. Strengthens the inner thigh through a full range with constant tension.'},
{id:'h140',cat:'Hip',name:'Cable Hip Extension (Standing Kickback)',pos:'Standing facing low cable',sets:3,reps:'15 each leg',hold:'2 sec',freq:'2-3x/week',instr:'Face the cable machine with an ankle cuff on one leg. Kick the leg straight back behind you, squeezing the glute at the end, without arching the low back. Return slowly. A direct glute max exercise with adjustable resistance through the full arc.'},
{id:'h141',cat:'Hip',name:'Cable Hip Flexion (Standing March)',pos:'Standing facing away from low cable',sets:3,reps:'15 each leg',hold:'2 sec',freq:'2-3x/week',instr:'Face away from the machine with an ankle cuff on one leg. Drive the knee up toward hip height against the cable backward pull, then lower with control. Loads the hip flexors in the pattern used for stairs, running, and stepping over obstacles.'},
{id:'k139',cat:'Knee',name:'Cable Terminal Knee Extension',pos:'Standing facing away from cable',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Loop the cable strap behind the back of your knee, facing away from the machine with the knee slightly bent. Straighten the knee fully against the cable pull, squeezing the quad, then bend slightly and repeat. The cable version of the band TKE with finer load control.'},
{id:'k140',cat:'Knee',name:'Cable Squat to Row',pos:'Standing facing cable',sets:3,reps:'12',hold:'—',freq:'2-3x/week',instr:'Hold a cable handle in each hand at a low setting. Squat down letting your arms extend forward, then as you stand, row the handles to your ribs in one flowing motion. Pairs the squat pattern with a pull, useful for time-efficient total-body strengthening in a rehab circuit.'},
{id:'a114',cat:'Ankle & Foot',name:'Cable Ankle Eversion',pos:'Seated, cuff around forefoot',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Sit with an ankle cuff or strap around the forefoot connected to a low cable anchored on the inside. Turn the sole of the foot outward against the resistance, then return slowly. Smooth, adjustable loading for the peroneal muscles after ankle sprain.'},
{id:'a115',cat:'Ankle & Foot',name:'Cable Ankle Inversion',pos:'Seated, cuff around forefoot',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Sit with the cable anchored on the outside of the foot. Turn the sole inward against the resistance, then return slowly. Strengthens the tibialis posterior with constant tension through the full range.'},
{id:'a116',cat:'Ankle & Foot',name:'Cable Ankle Dorsiflexion',pos:'Seated, strap over top of foot',sets:3,reps:'15',hold:'2 sec',freq:'2-3x/week',instr:'Sit facing the low cable with a strap over the top of your foot. Pull the toes and foot up toward your shin against the resistance, then lower slowly. A smooth-resistance alternative to band dorsiflexion for shin and foot-drop strengthening.'},
{id:'c112',cat:'Cervical',name:'Cable Row with Chin Tuck Hold',pos:'Standing facing cable',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Perform a cable row at chest height while holding a chin tuck the entire set, keeping your head from poking forward as you pull. Trains the deep neck flexors to hold correct head position during upper body pulling, the pattern needed at a desk and in daily lifting.'},
{id:'t62',cat:'Thoracic',name:'Cable High Row (Thoracic Extension Focus)',pos:'Standing facing high cable',sets:3,reps:'12',hold:'2 sec',freq:'2-3x/week',instr:'Hold a rope attached above head height. Row it down and back toward your upper chest while lifting your chest and extending the mid-back, squeezing the shoulder blades down and together. Combines rowing with active thoracic extension against gravity slump.'},
{id:'sp67',cat:'Sport-Specific & Plyometric',name:'Cable Rotational Punch',pos:'Standing sideways to cable',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Hold the cable handle at chest height with the arm cocked. Rotate through the hips and trunk while punching the handle straight forward, transferring force from the ground up through the arm. Trains rotational power for throwing, boxing, and racket sports with adjustable load.'},
{id:'sp68',cat:'Sport-Specific & Plyometric',name:'Cable Lateral Bound with Resistance',pos:'Standing, belt around waist attached to cable',sets:3,reps:'8 each direction',hold:'2 sec land',freq:'2-3x/week',instr:'With a waist belt attached to a cable pulling you sideways, bound laterally away from the machine and stick the landing on the outside leg. The cable adds resistance to the push-off and challenges the landing, building lateral power for cutting sports.'},
{id:'b96',cat:'Balance & Functional',name:'Cable-Resisted Gait (Forward Walking)',pos:'Walking away from cable, belt at waist',sets:3,reps:'10-15 meters',hold:'—',freq:'2-3x/week',instr:'Wear a waist belt attached to a cable behind you. Walk forward against the backward pull, focusing on strong push-off and upright posture. Resisted walking strengthens the gait pattern itself rather than isolated muscles, useful in later-stage gait rehabilitation.'},
{id:'b97',cat:'Balance & Functional',name:'Cable Perturbation Stance Training',pos:'Standing, holding taut cable',sets:3,reps:'30 sec',hold:'—',freq:'2-3x/week',instr:'Stand on one or both legs holding a lightly loaded cable handle at your chest. A partner or the therapist varies the pull direction or you shift your own grip, forcing your balance system to respond to the changing load. A graded, measurable way to add perturbations to balance training.'},
{id:'l169',cat:'Core & Lumbar',name:'Cable Dead Bug Press',pos:'Supine, head toward low cable',sets:3,reps:'10 each side',hold:'—',freq:'2-3x/week',instr:'Lie on your back with your head toward the machine, holding a low cable handle with both arms extended above your chest. Perform dead bug leg lowers while the cable constantly tries to pull your arms overhead, forcing the core to resist extension the entire time.'},
{id:'h142',cat:'Hip',name:'Cable Glute Kickback (Bent-Over)',pos:'Standing hinged forward, holding frame',sets:3,reps:'12 each leg',hold:'2 sec',freq:'2-3x/week',instr:'Hinge forward holding the machine frame with an ankle cuff on one leg. Drive the leg back and slightly up, squeezing the glute hard at the top without arching the low back. The bent-over angle lets the glute work through a longer range than the upright kickback.'},
{id:'p79',cat:'Post-Op & General',name:'TKA Protocol Week 1-2: Early Motion Priorities',pos:'Supine and seated',sets:3,reps:'10 each exercise',hold:'—',freq:'3-4x/day',instr:'In the first two weeks after total knee replacement, prioritize: ankle pumps hourly, quad sets, heel slides toward 90 degrees of bend, and passive knee extension with a towel under the heel. Getting the knee fully straight is the single most important early goal — spend time daily letting it hang into extension.'},
{id:'p80',cat:'Post-Op & General',name:'TKA Protocol Week 3-6: Strength and Gait Phase',pos:'Standing and seated',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Weeks 3-6 after knee replacement: progress to standing exercises (mini squats, heel raises, standing knee bends), wean from the walker to a cane as your surgeon allows, and work toward 110-120 degrees of knee bend. Continue extension stretching daily — do not let full straightening slip while chasing bend.'},
{id:'p81',cat:'Post-Op & General',name:'TKA Protocol Week 6-12: Functional Return Phase',pos:'Standing, stairs, community',sets:3,reps:'Per exercise',hold:'—',freq:'Daily',instr:'Weeks 6-12 after knee replacement: progress step-ups and step-downs, stationary cycling with increasing resistance, single-leg balance, and community walking distance. Most surgeons clear driving around 4-6 weeks (right knee, off narcotics) and low-impact recreation by 3 months.'},
{id:'p82',cat:'Post-Op & General',name:'THA Posterior Approach Protocol Phase 1 (Weeks 0-6)',pos:'Supine and standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'After posterior-approach hip replacement, weeks 0-6: follow precautions strictly (no bending past 90 degrees, no crossing legs, no turning the toes inward), while performing ankle pumps, glute sets, quad sets, standing hip abduction, and short walks that progressively lengthen. Sleep with a pillow between the knees.'},
{id:'p83',cat:'Post-Op & General',name:'THA Protocol Phase 2 (Weeks 6-12): Strengthening',pos:'Standing and side-lying',sets:3,reps:'12-15',hold:'—',freq:'Daily',instr:'Weeks 6-12 after hip replacement, once cleared from strict precautions: progress side-lying hip abduction, bridges, sit-to-stands, step-ups, and stationary cycling. Focus especially on the hip abductors — a lingering limp after hip replacement almost always traces back to abductor weakness.'},
{id:'p84',cat:'Post-Op & General',name:'Rotator Cuff Repair Protocol Phase 1 (Weeks 0-6): Passive Only',pos:'Supine and standing',sets:3,reps:'10',hold:'—',freq:'2-3x/day',instr:'For the first six weeks after rotator cuff repair, the repaired tendon must not actively contract: wear the sling as directed, and perform only pendulums, passive external rotation with a stick (within the surgeon range limit), and elbow/wrist/hand motion. Someone else or your other arm moves the shoulder — never the surgical side itself.'},
{id:'p85',cat:'Post-Op & General',name:'Rotator Cuff Repair Protocol Phase 2 (Weeks 6-12): Active Motion',pos:'Supine progressing upright',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Weeks 6-12 after cuff repair: transition from passive to active-assisted to active motion — supine flexion with the other arm assisting, then wand exercises, then unassisted reaching. No resistance or strengthening yet. Full overhead active motion should be comfortable before any banded work begins.'},
{id:'p86',cat:'Post-Op & General',name:'Rotator Cuff Repair Protocol Phase 3 (Months 3-6): Strengthening',pos:'Standing',sets:3,reps:'12-15',hold:'—',freq:'Daily to every other day',instr:'From about 12 weeks after cuff repair: begin isometrics, then light band work for internal rotation, external rotation, and scaption, progressing load slowly over months. The repaired tendon continues remodeling for a year — pain-free today does not mean ready for heavy load tomorrow.'},
{id:'p87',cat:'Post-Op & General',name:'ACL Reconstruction Protocol Phase 1 (Weeks 0-2)',pos:'Supine and standing',sets:3,reps:'10-20',hold:'—',freq:'3-4x/day',instr:'The first two weeks after ACL reconstruction center on three things: full knee extension (prone hangs, towel-under-heel), quad reactivation (quad sets, straight leg raises once quad control returns), and swelling control (ice, elevation, ankle pumps). Weight bearing progresses per your surgeon based on graft and any meniscus work.'},
{id:'p88',cat:'Post-Op & General',name:'ACL Reconstruction Protocol Phase 2 (Weeks 2-12)',pos:'Standing, closed chain',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Weeks 2-12 after ACL reconstruction: build with closed-chain work — leg press, squats to 90 degrees, step-ups, stationary cycling, balance training — while restoring full bend. Normal walking without a limp, full motion, and good quad control are the gateway criteria to begin jogging, typically around 3 months.'},
{id:'p89',cat:'Post-Op & General',name:'ACL Reconstruction Protocol Phase 3 (Months 3-9): Running to Sport',pos:'Track, gym, field',sets:1,reps:'Per stage',hold:'—',freq:'3-5x/week',instr:'From month 3 onward: progress straight-line jogging, then acceleration and deceleration, then plyometrics and cutting, then sport drills. Return to competition should be criteria-based — quad strength at least 90% of the other side, passing hop tests, and confidence — and rarely occurs before 9 months, as re-tear risk drops meaningfully with each month waited.'},
{id:'p90',cat:'Post-Op & General',name:'Meniscectomy (Partial) Rapid Recovery Protocol',pos:'Supine to standing',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'After partial meniscectomy (removal, not repair), recovery is comparatively fast: weight bearing as tolerated immediately, quad sets and straight leg raises from day one, stationary bike as soon as the knee bends enough, and return to most activities in 4-6 weeks as swelling and strength allow. Persistent swelling is the main signal to slow down.'},
{id:'p91',cat:'Post-Op & General',name:'Achilles Repair Protocol: Early Functional Rehab (Weeks 0-8)',pos:'Seated and standing in boot',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'Modern Achilles repair protocols use early protected motion: boot with heel wedges from around week 2, protected weight bearing progressing to full in the boot, gentle active ankle motion above neutral, and wedge removal one at a time every 1-2 weeks. Never stretch the tendon into dorsiflexion during this window — the repair lengthens all too easily and cannot be shortened back.'},
{id:'p92',cat:'Post-Op & General',name:'Lumbar Fusion Protocol Phase 1 (Weeks 0-6): Protection',pos:'Standing and walking',sets:1,reps:'Walking program',hold:'—',freq:'Multiple short walks daily',instr:'The first six weeks after lumbar fusion follow the BLT rule — no bending, lifting over 5-10 pounds, or twisting. Walking is the primary exercise: several short walks daily, progressively longer. Log-roll in and out of bed. No formal core exercise yet; the fusion needs quiet time to begin knitting.'},
{id:'p93',cat:'Post-Op & General',name:'Lumbar Fusion Protocol Phase 2 (Months 2-6): Progressive Loading',pos:'Various',sets:3,reps:'10',hold:'10 sec',freq:'Daily',instr:'From about 6-8 weeks after fusion, as cleared: begin gentle core activation (abdominal bracing, marching, bird dog progressions), hip strengthening, and gradual return to daily tasks with hip-hinge mechanics. Loaded and rotational exercise typically waits until imaging confirms the fusion is consolidating, often 3-6 months.'},
{id:'p94',cat:'Post-Op & General',name:'Microdiscectomy Protocol: Early Recovery (Weeks 0-6)',pos:'Walking, supine',sets:1,reps:'Walking plus gentle motion',hold:'—',freq:'Daily',instr:'After lumbar microdiscectomy: walk early and often, limit sitting to 20-30 minutes at a stretch initially, and perform gentle nerve glides if prescribed. Avoid bending and lifting for the first several weeks. Most patients return to desk work in 2-4 weeks; recurrence risk is highest in the first 6-12 weeks, so respect the lifting limits even when pain is gone.'},
{id:'p95',cat:'Post-Op & General',name:'Total Shoulder Replacement Protocol Phase 1 (Weeks 0-6)',pos:'Supine and standing',sets:3,reps:'10',hold:'—',freq:'2-3x/day',instr:'After anatomic total shoulder replacement: sling per surgeon, pendulums, passive and active-assisted flexion and external rotation within the surgeon stated limits, plus elbow and hand motion. For reverse total shoulders the limits differ — often no combined extension and internal rotation behind the back early — so confirm which prosthesis you have and follow its specific limits.'},
{id:'p96',cat:'Post-Op & General',name:'Distal Radius Fracture Protocol (Post-Cast or ORIF)',pos:'Seated',sets:3,reps:'10 each motion',hold:'3 sec',freq:'3-4x/day',instr:'Once cleared after wrist fracture (cast removal or plate fixation): begin active wrist flexion, extension, radial and ulnar deviation, and forearm rotation, plus tendon glides and full finger motion. Grip strengthening starts gently a few weeks later. Forearm rotation (turning palm up) is commonly the slowest motion to return — prioritize it daily.'},
{id:'p97',cat:'Post-Op & General',name:'Ankle ORIF Protocol: Post-Immobilization Phase',pos:'Seated and standing',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'After ankle fracture fixation, once weight bearing is cleared: restore dorsiflexion first (knee-to-wall stretching), then progress the four-direction ankle strengthening, calf raises, balance work from double to single leg, and gait normalization. A stiff ankle that lacks dorsiflexion will limp for months — motion before strength.'},
{id:'p98',cat:'Post-Op & General',name:'Bankart Repair Protocol (Anterior Labral Repair)',pos:'Supine and standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'After anterior labral (Bankart) repair, external rotation range is deliberately restricted early — typically no ER beyond neutral-to-30 degrees for the first six weeks — to protect the repair. Follow the staged ER limits exactly, progress strengthening from 6-12 weeks, and expect return to contact sport or throwing no earlier than 5-6 months with surgeon clearance.'},
{id:'p99',cat:'Post-Op & General',name:'SLAP Repair Protocol: Biceps Protection Phase',pos:'Supine and standing',sets:3,reps:'10',hold:'—',freq:'Daily',instr:'After SLAP repair, the biceps anchor must be protected: no active biceps contraction (no resisted elbow flexion or supination) for approximately six weeks, alongside standard passive shoulder motion. Aggressive early biceps work is the classic way this repair fails — treat the arm as a no-curl zone until cleared.'},
{id:'p100',cat:'Post-Op & General',name:'Hamstring Strain Protocol: Criteria-Based Progression',pos:'Various',sets:3,reps:'Per stage',hold:'—',freq:'Daily',instr:'Hamstring strain rehab progresses through stages by criteria, not dates: pain-free walking, then pain-free jogging and isometrics, then eccentric loading (Nordic progressions, single-leg deadlifts), then sprinting progressions. Return to sport requires pain-free maximum-effort sprinting — the eccentric and sprint stages are where skipping ahead causes the notorious re-injury.'},
{id:'p101',cat:'Post-Op & General',name:'Lateral Ankle Sprain Functional Protocol (Grades I-II)',pos:'Seated to standing',sets:3,reps:'Per phase',hold:'—',freq:'Daily',instr:'Evidence-based ankle sprain care is functional, not immobilized: brief protection and swelling control (days 0-3), early motion and weight bearing as tolerated (first week), four-direction strengthening and balance work (weeks 1-4), then hopping and sport drills. Balance training is the piece most often skipped and the piece most protective against the next sprain.'},
{id:'p102',cat:'Post-Op & General',name:'Proximal Humerus Fracture Conservative Protocol',pos:'Standing and supine',sets:3,reps:'10-15',hold:'—',freq:'3-4x/day',instr:'For non-operative proximal humerus fracture: sling for comfort, pendulums beginning around 1-2 weeks per the physician, passive and active-assisted elevation from 2-4 weeks as callus forms, active motion around 6 weeks, and strengthening from 8-12 weeks. Early pendulums prevent the frozen shoulder that is this fracture most common complication.'},
{id:'p103',cat:'Post-Op & General',name:'Patellar Dislocation First-Time Conservative Protocol',pos:'Supine to standing',sets:3,reps:'10-15',hold:'—',freq:'Daily',instr:'After a first-time kneecap dislocation managed without surgery: brief immobilization for comfort only, early quad activation (quad sets, straight leg raises), progressive knee motion, then a strengthening program emphasizing the inner quad and — critically — the hip abductors and external rotators, since hip weakness lets the knee collapse inward and the kneecap drift out.'},
{id:'p104',cat:'Post-Op & General',name:'Frozen Shoulder Staged Protocol (Freezing/Frozen/Thawing)',pos:'Supine and standing',sets:3,reps:'3-5 stretches',hold:'20-30 sec',freq:'2-3x/day',instr:'Match the intensity to the stage: in the painful freezing stage, gentle pain-free motion and pendulums only — aggressive stretching makes this stage worse. In the frozen stage, progressive sustained stretching in all directions. In the thawing stage, push range harder and add strengthening. The condition resolves over 1-2 years; the exercises shorten and smooth that arc.'},
{id:'p105',cat:'Post-Op & General',name:'Lateral Epicondylalgia Loading Protocol (Isometric to Eccentric)',pos:'Seated',sets:3,reps:'Per stage',hold:'45 sec isometric',freq:'Daily',instr:'Tennis elbow responds to a staged loading sequence: heavy isometric wrist extension holds for pain relief first, then slow heavy concentric-eccentric wrist extension with a dumbbell, then the Tyler Twist eccentric bar work, then grip-intensive function. Complete rest deconditions the tendon — the treatment is the right dose of load, not the absence of it.'},
{id:'p106',cat:'Post-Op & General',name:'Greater Trochanteric Pain (Gluteal Tendinopathy) LEAP Protocol',pos:'Standing and side-lying',sets:3,reps:'Per program',hold:'45 sec isometric',freq:'Daily',instr:'Based on the LEAP trial: education plus progressive gluteal loading beats injections long-term for lateral hip pain. Begin with hip abductor isometrics and positional education (no leg crossing, no lying on the painful side without padding, no hanging on one hip), then progress bridging, abduction against resistance, and functional single-leg loading over 8-12 weeks.'},
{id:'p107',cat:'Post-Op & General',name:'Patellofemoral Pain Combined Hip-Knee Protocol',pos:'Standing and side-lying',sets:3,reps:'12-15',hold:'—',freq:'Daily',instr:'Best-evidence care for kneecap pain trains both ends of the chain: hip abductor and external rotator strengthening (clamshells, side-lying abduction, banded squats) plus quad strengthening in ranges that do not provoke pain, with movement retraining to stop the knee diving inward during squats, stairs, and landing. Hip work alone outperforms quad work alone in most trials.'},
{id:'p108',cat:'Post-Op & General',name:'Cervical Radiculopathy Conservative Protocol',pos:'Supine and seated',sets:3,reps:'10',hold:'—',freq:'2-3x/day',instr:'For a pinched nerve in the neck: begin with positions that ease arm symptoms (often supine with the arm supported), add median nerve glides and gentle cervical retraction if they centralize symptoms toward the neck, then progress deep neck flexor and scapular strengthening as the arm quiets. Most cases resolve without surgery over 6-12 weeks.'},
{id:'p109',cat:'Post-Op & General',name:'Carpal Tunnel Conservative Protocol',pos:'Seated',sets:3,reps:'10',hold:'—',freq:'2-3x/day',instr:'Conservative carpal tunnel care combines: night splinting in neutral wrist position (the single best-supported piece), tendon and median nerve gliding exercises, activity modification for sustained gripping and wrist-bent postures, and workstation adjustments. Worsening numbness, constant symptoms, or thumb weakness are the signals to escalate to the physician.'},
{id:'p110',cat:'Post-Op & General',name:'Plantar Fasciitis Comprehensive Protocol',pos:'Seated and standing',sets:3,reps:'Per component',hold:'30 sec stretches',freq:'Daily',instr:'The best-supported combination for plantar heel pain: plantar fascia-specific stretching before the first steps each morning, calf stretching twice daily, high-load slow calf raises with the toes propped up on a towel, and short-term taping or heel cups for symptom relief. Improvement is measured in weeks to months — consistency beats intensity.'},
{id:'p111',cat:'Post-Op & General',name:'Nonspecific Low Back Pain First-Line Protocol',pos:'Various',sets:1,reps:'Per program',hold:'—',freq:'Daily',instr:'Guideline-based first-line care for common low back pain: stay active and avoid bed rest, walk daily, use whichever movement direction eases symptoms, add progressive core and hip strengthening as the acute pain settles, and return to normal activity as quickly as tolerable. Reassurance matters — most episodes improve substantially within 4-6 weeks regardless of imaging findings.'},
];
